function registerChatTargetIdentity(identity) {
    if (!identity || identity.role_type !== 'doctor_agent' || !identity.id) return null;
    const normalized = {...identity, id: String(identity.id)};
    chatTargetIdentityStore.set(normalized.id, normalized);
    if (normalized.target_id) chatTargetIdentityStore.set(String(normalized.target_id), normalized);
    if (normalized.actor_id) chatTargetIdentityStore.set(String(normalized.actor_id), normalized);
    return normalized;
}

function getChatTargetIdentity(targetId) {
    return chatTargetIdentityStore.get(String(targetId || '')) || null;
}

window.registerChatTargetIdentity = registerChatTargetIdentity;
window.getChatTargetIdentity = getChatTargetIdentity;

