// 临时隐藏的聊天列表；新消息到达后会自动恢复。
const HIDDEN_CHAT_ACTIVITY_STORAGE_KEY = 'hiddenChatActivityV2';

function readHiddenChatList() {
    try {
        const value = JSON.parse(localStorage.getItem('hiddenChats') || '[]');
        return Array.isArray(value) ? value.map(String) : [];
    } catch (error) {
        console.warn('[聊天列表] 隐藏项数据损坏，已忽略', error);
        return [];
    }
}

function readHiddenChatActivity() {
    try {
        const value = JSON.parse(localStorage.getItem(HIDDEN_CHAT_ACTIVITY_STORAGE_KEY) || '{}');
        return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
    } catch (error) {
        console.warn('[聊天列表] 隐藏项活动游标损坏，已忽略', error);
        return {};
    }
}

let hiddenChats = readHiddenChatList();
let hiddenChatActivity = readHiddenChatActivity();
const cachedChatActivity = new Map();

function chatVisibilityKey(chatId, chatType) {
    return String(chatType) + ':' + String(chatId);
}

function normalizeChatActivity(chat = {}) {
    return {
        last_time: Number(chat.lastTime ?? chat.last_time ?? 0) || 0,
        message_count: Number(chat.messageCount ?? chat.message_count ?? 0) || 0
    };
}

function persistHiddenChatState() {
    localStorage.setItem('hiddenChats', JSON.stringify(hiddenChats));
    localStorage.setItem(HIDDEN_CHAT_ACTIVITY_STORAGE_KEY, JSON.stringify(hiddenChatActivity));
}

function markChatHidden(chatId, chatType, chat = {}) {
    const key = chatVisibilityKey(chatId, chatType);
    if (!hiddenChats.includes(key)) hiddenChats.push(key);
    hiddenChatActivity[key] = {
        ...normalizeChatActivity(chat),
        hidden_at: Date.now()
    };
    persistHiddenChatState();
}

function reactivateHiddenChat(chatId, chatType, activity = {}, force = false) {
    const key = chatVisibilityKey(chatId, chatType);
    if (!hiddenChats.includes(key)) return false;
    const baseline = hiddenChatActivity[key] || {};
    const current = normalizeChatActivity(activity);
    const hasLaterMessage = current.last_time > (Number(baseline.last_time) || 0);
    if (!force && !hasLaterMessage) return false;
    hiddenChats = hiddenChats.filter(item => item !== key);
    delete hiddenChatActivity[key];
    persistHiddenChatState();
    return true;
}

function shouldKeepChatHidden(chat) {
    const key = chatVisibilityKey(chat.id, chat.type);
    if (!hiddenChats.includes(key)) return false;
    if (!hiddenChatActivity[key]) {
        const cached = cachedChatActivity.get(key);
        hiddenChatActivity[key] = {
            ...normalizeChatActivity(cached || chat),
            hidden_at: Date.now()
        };
        persistHiddenChatState();
    }
    if (reactivateHiddenChat(chat.id, chat.type, chat)) return false;
    delete unreadCount[key];
    return true;
}

