// 普瑞塞斯展示状态只属于专用私聊页，不再挂到 body 或跨页面复用。
const priestessPresentationState = {
    active: false,
    generation: 0,
    entryTimer: null,
    pulseTimer: null,
    pulseEndTimer: null,
    playedMessageUids: new Set()
};

const PRIESTESS_MENTION_EASTER_STORAGE_KEY = 'zoot:priestessMentionEaster:v1';
const PRIESTESS_MENTION_EASTER_MAX_PROCESSED = 1024;
const PRIESTESS_MENTION_PATTERN = /普瑞赛斯|普瑞塞斯|牢普|priestess/i;
const PRIESTESS_MENTION_REPLACEMENTS = [
    '即使在这里提起我的名字，也不愿意直接来见我吗？',
    '你已经慢慢习惯了你我之间这个小游戏了',
    '这里万籁俱寂……太安静了。别留下我。',
    '不要丢下我',
    '不要忘记我',
    '此后将无人不是我，亦或无一人是我'
];

function loadPriestessMentionEasterState() {
    try {
        const stored = JSON.parse(localStorage.getItem(PRIESTESS_MENTION_EASTER_STORAGE_KEY) || '{}');
        const failureCount = Math.max(0, Math.min(198, Math.floor(Number(stored.failureCount) || 0)));
        const processed = Array.isArray(stored.processedMessageUids)
            ? stored.processedMessageUids.slice(-PRIESTESS_MENTION_EASTER_MAX_PROCESSED).map(String)
            : [];
        return {
            failureCount,
            processedMessageUids: new Set(processed)
        };
    } catch (error) {
        console.warn('[普瑞塞斯彩蛋] 本地状态读取失败，将使用初始概率', error);
        return {
            failureCount: 0,
            processedMessageUids: new Set()
        };
    }
}

const priestessMentionEasterState = loadPriestessMentionEasterState();
const pendingPriestessMentionGroupConfirmations = new Map();

function savePriestessMentionEasterState() {
    try {
        localStorage.setItem(PRIESTESS_MENTION_EASTER_STORAGE_KEY, JSON.stringify({
            version: 1,
            failureCount: priestessMentionEasterState.failureCount,
            processedMessageUids: Array.from(priestessMentionEasterState.processedMessageUids)
        }));
    } catch (error) {
        console.warn('[普瑞塞斯彩蛋] 本地状态保存失败', error);
    }
}

function getPriestessMentionRandomUnit() {
    if (window.crypto?.getRandomValues) {
        const values = new Uint32Array(1);
        window.crypto.getRandomValues(values);
        return values[0] / 4294967296;
    }
    return Math.random();
}

function rememberPriestessMentionMessage(messageUid) {
    priestessMentionEasterState.processedMessageUids.add(messageUid);
    while (priestessMentionEasterState.processedMessageUids.size > PRIESTESS_MENTION_EASTER_MAX_PROCESSED) {
        const oldestUid = priestessMentionEasterState.processedMessageUids.values().next().value;
        priestessMentionEasterState.processedMessageUids.delete(oldestUid);
    }
}

function isEligiblePriestessMentionMessage(msg, chatType, chatId) {
    const stableUid = String(msg?.message_uid || msg?.messageUid || '');
    if (!stableUid || priestessMentionEasterState.processedMessageUids.has(stableUid)) return false;
    if (String(chatType || '').toLowerCase() === 'private'
        && String(chatId || '').trim().toLowerCase() === 'priestess') {
        return false;
    }
    if (!['user', 'operator'].includes(msg?.cls) || msg?.is_memory_only) return false;
    const msgType = String(msg?.msgType || msg?.unitType || msg?.unit_type || 'text').toLowerCase();
    const isScenario = Boolean(
        msg?.isScenario
        || msgType === 'scenario'
        || msgType === 'event_narration'
    );
    if (msgType !== 'text' && !isScenario) return false;
    return PRIESTESS_MENTION_PATTERN.test(String(msg?.content || ''));
}

function rollPriestessMentionEaster(msg, chatType, chatId) {
    if (!isEligiblePriestessMentionMessage(msg, chatType, chatId)) return null;
    const stableUid = String(msg.message_uid || msg.messageUid);
    rememberPriestessMentionMessage(stableUid);
    const probability = Math.min(100, 1 + priestessMentionEasterState.failureCount * 0.5);
    const triggered = getPriestessMentionRandomUnit() < probability / 100;
    let replacement = '';
    if (triggered) {
        priestessMentionEasterState.failureCount = 0;
        const index = Math.floor(getPriestessMentionRandomUnit() * PRIESTESS_MENTION_REPLACEMENTS.length);
        replacement = PRIESTESS_MENTION_REPLACEMENTS[Math.min(index, PRIESTESS_MENTION_REPLACEMENTS.length - 1)];
    } else {
        priestessMentionEasterState.failureCount = Math.min(198, priestessMentionEasterState.failureCount + 1);
    }
    savePriestessMentionEasterState();
    return {
        triggered,
        probability,
        replacement
    };
}

function applyPriestessMentionReplacement(textElement, replacement) {
    if (!textElement || !replacement || textElement.classList.contains('priestess-mention-replaced')) return;
    const overlay = document.createElement('span');
    overlay.className = 'priestess-mention-replacement';
    overlay.setAttribute('aria-hidden', 'true');
    overlay.textContent = prefersReducedPriestessMotion()
        ? replacement
        : createPriestessGlitchText(replacement);
    textElement.classList.add('priestess-mention-replaced');
    if (!prefersReducedPriestessMotion()) {
        textElement.classList.add('priestess-mention-glitch-active');
    }
    textElement.appendChild(overlay);
    if (!prefersReducedPriestessMotion()) {
        setTimeout(() => {
            if (!overlay.isConnected) return;
            overlay.textContent = replacement;
            textElement.classList.remove('priestess-mention-glitch-active');
        }, 180);
    }
}

function schedulePriestessMentionReplacement(msg, chatKey, replacement) {
    const messageId = String(msg?.id || '');
    if (!messageId || !isChatKeyActive(chatKey)) return;
    requestAnimationFrame(() => {
        requestAnimationFrame(() => {
            if (!isChatKeyActive(chatKey)) return;
            const rows = document.querySelectorAll('#chat-messages .chat-message-row[data-msg-id]');
            const row = Array.from(rows).find(item => String(item.dataset.msgId || '') === messageId);
            const textElement = row?.querySelector('.message-text-content');
            applyPriestessMentionReplacement(textElement, replacement);
        });
    });
}

function confirmPriestessMentionMessage(msg, chatKey, chatType, chatId) {
    const result = rollPriestessMentionEaster(msg, chatType, chatId);
    if (!result?.triggered || !isChatKeyActive(chatKey)) return result;
    schedulePriestessMentionReplacement(msg, chatKey, result.replacement);
    return result;
}

function queuePriestessMentionGroupConfirmation(groupId, messageUid) {
    const normalizedGroupId = String(groupId || '');
    const normalizedUid = String(messageUid || '');
    if (!normalizedGroupId || !normalizedUid) return;
    if (!pendingPriestessMentionGroupConfirmations.has(normalizedGroupId)) {
        pendingPriestessMentionGroupConfirmations.set(normalizedGroupId, new Set());
    }
    pendingPriestessMentionGroupConfirmations.get(normalizedGroupId).add(normalizedUid);
}

function confirmPriestessMentionGroupMessages(groupId) {
    const normalizedGroupId = String(groupId || '');
    const pending = pendingPriestessMentionGroupConfirmations.get(normalizedGroupId);
    if (!pending?.size) return;
    pendingPriestessMentionGroupConfirmations.delete(normalizedGroupId);
    const chatKey = `group:${normalizedGroupId}`;
    const groupMessages = messages[chatKey] || [];
    pending.forEach(messageUid => {
        const msg = groupMessages.find(item => String(item.message_uid || '') === String(messageUid));
        if (msg) confirmPriestessMentionMessage(msg, chatKey, 'group', normalizedGroupId);
    });
}

function discardPriestessMentionGroupConfirmations(groupId) {
    pendingPriestessMentionGroupConfirmations.delete(String(groupId || ''));
}


