// ========== 1.1 DOMContentLoaded 事件监听 ==========
document.addEventListener('DOMContentLoaded', function() {
    console.log('[DOMContentLoaded] 开始绑定静态事件');

    // ====================================================================
    // 1. 通用工具
    // ====================================================================
    document.getElementById('batch-select-all')?.addEventListener('click', toggleSelectAll);
    document.getElementById('batch-complete')?.addEventListener('click', batchComplete);
    document.getElementById('batch-delete')?.addEventListener('click', batchDelete);
    document.getElementById('batch-cancel')?.addEventListener('click', exitBatchMode);

    console.log('[DOMContentLoaded] 通用工具绑定完成');

    // ====================================================================
    // 2. API 设置（旧的单独API密钥模态框）
    // ====================================================================
    const apiKeySave = document.getElementById('api-key-save');
    const apiKeyCancel = document.getElementById('api-key-cancel');
    const apiKeyModal = document.getElementById('apiKeyModal');
    if (apiKeySave && apiKeyCancel && apiKeyModal) {
        apiKeySave.onclick = () => {
            const key = document.getElementById('api-key-input').value.trim();
            if (key) {
                fetch('/set_api_key', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ api_key: key })
                }).then(res => {
                    if (res.ok) {
                        alert('API密钥保存成功');
                        hideModal('apiKeyModal');
                    } else {
                        alert('保存失败');
                    }
                }).catch(err => alert('保存出错'));
            } else {
                alert('请输入API密钥');
            }
        };
        apiKeyCancel.onclick = () => {
            hideModal('apiKeyModal');
        };
    }

    // 思考模式切换按钮
    document.getElementById('think-mode-toggle')?.addEventListener('change', async (e) => {
        const provider = document.getElementById('provider-select').value;
        const mode = e.target.value || 'auto';
        await saveThinkMode(provider, mode);
        updateThinkModeHint(provider, mode);
    });

    console.log('[DOMContentLoaded] API 设置绑定完成');

    // ====================================================================
    // 3. 首次启动向导窗
    // ====================================================================
    const wizardSave = document.getElementById('wizard-save');
    const wizardSkip = document.getElementById('wizard-skip');
    if (wizardSave && wizardSkip) {
        wizardSave.onclick = async () => {
            if (window._wizardSavePending || window.firstRunCoordinator?.state === 'saving') return;
            window._wizardSavePending = true;
            wizardSave.disabled = true;
            wizardSkip.disabled = true;
            try {
                await saveWizardSettings();
            } catch (error) {
                console.error('[首次运行] 保存失败', error);
                alert('设置保存失败，请检查当前配置后重试');
            } finally {
                window._wizardSavePending = false;
                if (window.firstRunCoordinator?.state !== 'completed') {
                    wizardSave.disabled = false;
                    wizardSkip.disabled = false;
                }
            }
        };
        wizardSkip.onclick = async () => {
            if (window._wizardSavePending || window.firstRunCoordinator?.state === 'saving') return;
            await window.firstRunCoordinator.complete({ skipped: true });
        };
    }

    // 向导窗服务商切换
    const wizardProviderSelect = document.getElementById('wizard-provider-select');
    if (wizardProviderSelect) {
        wizardProviderSelect.addEventListener('change', async () => {
            const provider = wizardProviderSelect.value;
            const apiBaseInput = document.getElementById('wizard-api-base');
            const apiKeyInput = document.getElementById('wizard-api-key');
            const customModelInput = document.getElementById('wizard-custom-model');
            const modelSelect = document.getElementById('wizard-model-select');
            const hintDiv = document.getElementById('wizard-api-base-hint');

            try {
                const [apiBaseRes, apiKeyRes, modelRes] = await Promise.all([
                    fetch(`/get_api_base_for_provider?provider=${provider}`),
                    fetch(`/get_api_key_for_provider?provider=${provider}`),
                    fetch(`/get_model_for_provider?provider=${provider}`)
                ]);
                let apiBase = '', apiKey = '', apiKeyConfigured = false, savedModel = '';
                if (apiBaseRes.ok) { const data = await apiBaseRes.json(); apiBase = data.api_base || ''; }
                if (apiKeyRes.ok) {
                    const data = await apiKeyRes.json();
                    apiKey = '';
                    apiKeyConfigured = Boolean(data.configured);
                    apiKeyInput.dataset.configured = apiKeyConfigured ? '1' : '0';
                    apiKeyInput.placeholder = apiKeyConfigured
                        ? `已保存密钥（${data.masked_value || '已配置'}）；留空保持不变`
                        : '请输入 API 密钥';
                }
                if (modelRes.ok) { const data = await modelRes.json(); savedModel = data.model || ''; }

                if (!apiBase && DEFAULT_API_BASE[provider]) {
                    apiBase = DEFAULT_API_BASE[provider];
                }
                apiBaseInput.value = apiBase;
                apiKeyInput.value = apiKey;
                if (savedModel) {
                    customModelInput.value = savedModel;
                    modelSelect.value = '';
                } else {
                    customModelInput.value = '';
                    modelSelect.value = '';
                }
            } catch (e) {
                console.warn('加载服务商配置失败', e);
            }

            modelSelect.innerHTML = '<option value="">请先填写 API 地址和密钥后刷新</option>';
            if (provider === 'custom') {
                if (hintDiv) hintDiv.innerHTML = '💡 需兼容 OpenAI 协议';
            } else {
                if (hintDiv) hintDiv.innerHTML = '';
            }
        });
    }

    // 向导窗刷新模型列表
    const wizardRefreshModels = document.getElementById('wizard-refresh-models');
    if (wizardRefreshModels) {
        wizardRefreshModels.addEventListener('click', () => {
            prepareWizardModels();
        });
    }

    console.log('[DOMContentLoaded] 向导窗绑定完成');

    // ====================================================================
    // 4. 主题与配色（显示模式页面）
    // ====================================================================
    if (typeof currentColorScheme === 'undefined') {
        window.currentColorScheme = localStorage.getItem('colorScheme') || 'scheme1';
    }
    const savedTheme = localStorage.getItem('theme') || 'light';
    const savedScheme = localStorage.getItem('colorScheme') || 'scheme1';
    if (typeof applyTheme === 'function') {
        applyTheme(savedTheme, savedScheme);
    } else {
        document.documentElement.classList.toggle('dark-mode', savedTheme === 'dark');
    }

    // 个人页快捷切换按钮
    const themeToggleBtn = document.getElementById('theme-quick-toggle');
    if (themeToggleBtn) {
        const updateBtnIcon = () => {
            const isCovenant = localStorage.getItem('colorScheme') === 'scheme4';
            if (isCovenant) {
                themeToggleBtn.innerHTML = '<img src="/static/images/img_theme_sealed.png" alt="">';
                themeToggleBtn.setAttribute('aria-label', '承诺主题');
            } else {
                const isDark = document.documentElement.classList.contains('dark-mode');
                themeToggleBtn.innerHTML = isDark
                    ? '<img src="/static/images/img_theme_day.png" alt="">'
                    : '<img src="/static/images/img_theme_night.png" alt="">';
                themeToggleBtn.setAttribute('aria-label', isDark ? '切换到日间模式' : '切换到夜间模式');
            }
        };
        updateBtnIcon();
        themeToggleBtn.removeEventListener('click', window._themeToggleHandler);
        window._themeToggleHandler = () => {
            const currentScheme = localStorage.getItem('colorScheme') || 'scheme1';
            const isDark = document.documentElement.classList.contains('dark-mode');
            const newTheme = isDark ? 'light' : 'dark';
            const newScheme = currentScheme;
            applyTheme(newTheme, newScheme);
            // 同步显示模式页面的开关和下拉框
            const themeSwitch = document.getElementById('theme-switch');
            if (themeSwitch) themeSwitch.checked = (newTheme === 'dark');
            const colorSelect = document.getElementById('theme-color');
            if (colorSelect) colorSelect.value = newScheme;
            updateBtnIcon();
        };
        themeToggleBtn.addEventListener('click', window._themeToggleHandler);
    }

    // 日夜模式开关（显示模式页面）
    const themeSwitch = document.getElementById('theme-switch');
    if (themeSwitch) {
        // 初始化开关状态
        const currentTheme = localStorage.getItem('theme') || 'light';
        themeSwitch.checked = (currentTheme === 'dark');
        themeSwitch.addEventListener('change', () => {
            const newTheme = themeSwitch.checked ? 'dark' : 'light';
            const currentScheme = localStorage.getItem('colorScheme') || 'scheme1';
            applyTheme(newTheme, currentScheme);
        });
    }

    // 主题色下拉框（显示模式页面）
    const colorSelect = document.getElementById('theme-color');
    if (colorSelect) {
        // 初始化下拉框值
        colorSelect.value = localStorage.getItem('colorScheme') || 'scheme1';
        colorSelect.addEventListener('change', () => {
            const newScheme = colorSelect.value;
            const currentTheme = document.documentElement.classList.contains('dark-mode') ? 'dark' : 'light';
            applyTheme(currentTheme, newScheme);
            // 如果切换到承诺主题，且当前开关为夜间模式，强制切换为日间（承诺主题的日间模式）
            if (newScheme === 'scheme4') {
                const themeSwitch = document.getElementById('theme-switch');
                if (themeSwitch && themeSwitch.checked) {
                    themeSwitch.checked = false;
                    applyTheme('light', 'scheme4');
                }
            }
        });
    }

    // 字体设置实时保存
    const fontSizeSlider = document.getElementById('font-size-slider');
    const fontSizeValue = document.getElementById('font-size-value');
    const fontFamilySelect = document.getElementById('font-family-select');
    if (fontSizeSlider) {
        fontSizeSlider.addEventListener('input', () => {
            const val = fontSizeSlider.value;
            if (fontSizeValue) fontSizeValue.textContent = val + 'px';
            applyFontSize(parseInt(val));
            localStorage.setItem('fontSize', val);
        });
    }
    if (fontFamilySelect) {
        fontFamilySelect.addEventListener('change', () => {
            const val = fontFamilySelect.value;
            applyFontFamily(val);
            localStorage.setItem('fontFamily', val);
        });
    }

    // 统计卡片背景图片切换（承诺主题下使用 sealed 版本）
    const statsCards = document.querySelectorAll('.stats-card');
    if (statsCards.length) {
        const currentScheme = localStorage.getItem('colorScheme') || 'scheme1';
        const isCovenant = (currentScheme === 'scheme4');
        const bgImage = isCovenant ? 'url("/static/images/img_room_bkg_sealed.png")' : 'url("/static/images/img_room_bkg.png")';
        statsCards.forEach(card => {
            card.style.backgroundImage = bgImage;
        });
    }

    console.log('[DOMContentLoaded] 主题与配色绑定完成');

    // ====================================================================
    // 5. 浮动按钮组业务逻辑（创建群聊、成员选择等）
    // ====================================================================
    // 5.1 创建群聊按钮
    const createGroupConfirm = document.querySelector('#create-group-buttons #create-group-confirm');
    if (createGroupConfirm) {
        createGroupConfirm.removeEventListener('click', window._createGroupConfirmHandler);
        window._createGroupConfirmHandler = async () => {
            const checkboxes = document.querySelectorAll('#create-group-members .member-checkbox:not([disabled]):checked');
            let memberIds = Array.from(checkboxes).map(cb => cb.value);
            const preselectedHidden = document.querySelector('#create-group-members .preselected-hidden');
            if (preselectedHidden) {
                const preselectedId = preselectedHidden.value;
                if (!memberIds.includes(preselectedId)) {
                    memberIds.unshift(preselectedId);
                }
            }
            if (memberIds.length === 0) {
                alert('请至少选择一名干员');
                return;
            }
            const tagsInput = document.getElementById('create-group-tags');
            const tags = tagsInput ? tagsInput.value.split(',').map(s => s.trim()).filter(s => s) : [];
            const groupName = document.getElementById('create-group-name').value.trim();
            const res = await fetch('/group/create', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    member_ids: memberIds,
                    tags: tags,
                    group_name: groupName
                })
            });
            if (res.ok) {
                alert('群聊创建成功');
                localStorage.removeItem('preselectedMember');
                goBack();
            } else {
                const err = await res.json();
                alert('创建失败: ' + (err.detail || '未知错误'));
            }
        };
        createGroupConfirm.addEventListener('click', window._createGroupConfirmHandler);
    }

    console.log('[DOMContentLoaded] 浮动按钮组业务逻辑绑定完成');

    // ====================================================================
    // 6. 通用开关与交互（置顶、活跃度、标签等）
    // ====================================================================
    if (pinToggle) {
        pinToggle.addEventListener('change', (e) => {
            if (currentOperatorId) {
                const chat = chats.find(c => c.id === currentOperatorId && c.type === 'private');
                if (chat) {
                    chat.isPinned = e.target.checked;
                    savePinnedState();
                    if (document.getElementById('page-chat-list').classList.contains('active-page')) renderChatList();
                }
            }
        });
    }
    if (groupPinToggle) {
        groupPinToggle.addEventListener('change', (e) => {
            if (currentGroupId) {
                const chat = chats.find(c => c.id === currentGroupId && c.type === 'group');
                if (chat) {
                    chat.isPinned = e.target.checked;
                    savePinnedState();
                    renderChatList();
                }
            }
        });
    }
    if (moodSlider && moodSpan) {
        moodSlider.addEventListener('input', (e) => { moodSpan.textContent = e.target.value; });
    }

    // 标签添加模态框
    if (tagAddCancel) tagAddCancel.addEventListener('click', () => { document.getElementById('tagAddModal').style.display = 'none'; });
    if (tagAddConfirm) {
        tagAddConfirm.addEventListener('click', () => {
            const newTag = newTagInput.value.trim();
            if (newTag && currentTagOperatorId) {
                addTagToCurrentOperator(newTag);
                document.getElementById('tagAddModal').style.display = 'none';
            } else alert('请输入标签');
        });
    }
    if (quickTagBtns.length) {
        quickTagBtns.forEach(btn => {
            btn.addEventListener('click', (e) => { newTagInput.value = e.target.dataset.tag; });
        });
    }

    // 聊天详情页右上角菜单按钮
    const chatMenu = document.getElementById('chat-menu');
    const menuPanel = document.getElementById('chat-menu-panel');
    if (chatMenu && menuPanel) {
        chatMenu.addEventListener('click', () => {
            if (currentGroupId) {
                showPage('group-info');
            } else if (currentOperatorId) {
                const special = getChatTargetIdentity(currentOperatorId);
                if (special?.profile_id && typeof window.openDoctorAgentEditor === 'function') {
                    window.openDoctorAgentEditor(special.profile_id);
                } else {
                    showPage('private-settings');
                }
            }
        });
        menuPanel.addEventListener('click', (e) => {
            if (e.target.classList.contains('menu-overlay')) {
                menuPanel.classList.add('hidden');
            }
        });
    }

    document.addEventListener('click', (e) => {
        // 右滑操作区由专用处理器负责；绝不能继续触发聊天项跳转。
        if (e.target.closest('.chat-item-actions')) return;
        const chatItem = e.target.closest('.chat-item');
        if (!chatItem) return;
        if (chatItem.dataset.justSwiped === 'true' || chatItem.classList.contains('swiped')) {
            chatItem.dataset.justSwiped = '';
            return;
        }
        const chatId = chatItem.dataset.chatId;
        const chatType = chatItem.dataset.chatType;
        if (chatType === 'private') {
            openChat('private', chatId, getChatTargetIdentity(chatId));
        } else if (chatType === 'group') {
            currentGroupId = chatId;
            currentOperatorId = null;
            const group = groups[chatId];
            const titleEl = document.getElementById('chat-title');
            if (titleEl) titleEl.textContent = group ? group.name : chatId;
            loadGroupHistory(chatId);
            saveCurrentChat();
            showPage('chat-detail');
        }
    });

    console.log('[DOMContentLoaded] 通用开关与交互绑定完成');

    // ====================================================================
    // 7. 聊天列表页相关
    // ====================================================================
    // 聊天列表搜索功能（带清除按钮）
    const chatSearchInput = document.getElementById('chat-search');
    const clearSearchBtn = document.getElementById('clear-search-btn');

    if (chatSearchInput) {
        // 输入事件：过滤/高亮，并控制清除按钮显示
        const handleSearchInput = (e) => {
            const keyword = e.target.value;
            if (keyword && keyword.trim() !== '') {
                // 有关键字：筛选并高亮
                chatSearchQuery = keyword;
                renderChatList();
                if (clearSearchBtn) clearSearchBtn.style.display = 'flex';
            } else {
                // 清空：重置搜索状态，显示全部聊天
                chatSearchQuery = '';
                renderChatList();
                if (clearSearchBtn) clearSearchBtn.style.display = 'none';
            }
        };
        chatSearchInput.removeEventListener('input', window._chatSearchHandler);
        window._chatSearchHandler = handleSearchInput;
        chatSearchInput.addEventListener('input', window._chatSearchHandler);
    }

    // 清除按钮点击事件
    if (clearSearchBtn) {
        clearSearchBtn.addEventListener('click', () => {
            if (chatSearchInput) {
                chatSearchInput.value = '';
                chatSearchQuery = '';
                renderChatList();
                clearSearchBtn.style.display = 'none';
                // 可选：让输入框获得焦点
                chatSearchInput.focus();
            }
        });
    }

    // 过滤标签（全部/私聊/群聊）
    document.addEventListener('click', (e) => {
        const tab = e.target.closest('.filter-tab');
        if (tab && tab.closest('.chat-filter-tabs')) {
            const filter = tab.dataset.filter;
            if (filter) {
                console.log('点击过滤标签:', filter);
                chatFilter = filter;
                document.querySelectorAll('.filter-tab').forEach(t => t.classList.remove('active'));
                tab.classList.add('active');
                renderChatList();
            }
        }
    });

    bindHeaderButtons(); // 加号菜单

        // ========== 下拉刷新（聊天列表页） ==========
    const chatScrollWrapper = document.querySelector('#page-chat-list .chat-scroll-wrapper');
    if (chatScrollWrapper) {
        initPullToRefresh(chatScrollWrapper, async (reportProgress) => {
            console.log('[下拉刷新] 开始统一刷新');
            // 获取当前已配对设备
            let pairedDevice = null;
            if (window.Android) {
                const pairedJson = Android.getPairedDevice();
                if (pairedJson && pairedJson !== 'null') {
                    try {
                        pairedDevice = JSON.parse(pairedJson);
                    } catch(e) {}
                }
            }
            if (pairedDevice && pairedDevice.ip && pairedDevice.port) {
                reportProgress('正在同步配对设备…');
                await startFullSync(pairedDevice.ip, pairedDevice.port, pairedDevice.deviceId);
            }
            reportProgress('正在刷新聊天与未读…');
            await loadChats(0, true);
            reportProgress('正在刷新事务与动态提醒…');
            await Promise.allSettled([updateAssistantUnreadCount(), updateTodoUnviewedCount(), fetchUnreadCount()]);
            renderChatList();
        }, { threshold: 80 });
    }

    // 聊天数据在服务器就绪后的 window.onload 中统一加载。这里提前请求会与
    // 启动加载并发，造成重复渲染，也会让仍停留在初始聊天列表的页面错过最终激活。

    console.log('[DOMContentLoaded] 聊天列表页绑定完成');

    // ====================================================================
    // 8. 联系人页相关
    // ====================================================================
    document.addEventListener('input', (e) => {
        if (e.target.id === 'contact-search') {
            performSearchOnContactList(e.target.value.trim());
        }
    });

    // 初始隐藏索引栏和筛选器（showPage 会正确处理，但为了保险）
    const indexBar = document.getElementById('contact-index-bar');
    if (indexBar) indexBar.style.display = 'none';
    document.getElementById('contact-index-bar')?.style.setProperty('display', 'none', 'important');

    console.log('[DOMContentLoaded] 联系人页绑定完成');

    // ====================================================================
    // 9. 成员选择页搜索
    // ====================================================================
    document.addEventListener('input', (e) => {
        if (e.target.id === 'member-search') {
            const searchTerm = e.target.value.trim();
            const memberItems = document.querySelectorAll('#member-list .contact-item');
            if (!memberItems.length) return;

            if (operatorDetailsLoaded.size < operators.length && !operatorDetailsLoading) {
                loadAllOperatorDetails().then(() => {
                    filterMemberList(searchTerm);
                });
                return;
            }
            filterMemberList(searchTerm);
        }
    });

    bindMemberSelectConfirm();

    initSecretOperator();

    console.log('[DOMContentLoaded] 成员选择页搜索绑定完成');

    // ====================================================================
    // 10. 个人页设置&按钮栏事件绑定
    // ====================================================================
    initProfileActionBar();

    const genderSelect = document.getElementById('doctor-gender-select');
    if (genderSelect) {
        genderSelect.addEventListener('change', (e) => {
            localStorage.setItem('doctorGender', e.target.value);
        });
    }

    // 群聊信息页编辑弹窗
    if (groupEditCancel) {
        groupEditCancel.addEventListener('click', () => {
            hideModal('groupEditModal');
            currentEditField = null;
        });
    }
    if (groupEditConfirm) {
        groupEditConfirm.addEventListener('click', () => {
            const inputEl = document.getElementById('groupEditInput');
            const newValue = inputEl.value.trim();
            if (newValue && currentEditField) {
                const maxLen = MAX_LENGTH[currentEditField];
                if (newValue.length > maxLen) {
                    alert(`内容不能超过${maxLen}字`);
                    return;
                }
                const updates = {};
                updates[currentEditField] = newValue;
                updateGroupConfig(updates);
            }
            hideModal('groupEditModal');
            currentEditField = null;
        });
    }

    console.log('[DOMContentLoaded] 个人页设置绑定完成');

    // ====================================================================
    // 11. 数据收集许可面板
    // ====================================================================
    const infoButton = document.getElementById('infoButton');
    const infoPanel = document.getElementById('infoPanel');
    if (infoButton && infoPanel) {
        infoButton.addEventListener('click', (e) => {
            e.stopPropagation();
            if (infoPanel.style.display === 'none' || infoPanel.style.display === '') {
                infoPanel.style.display = 'block';
            } else {
                infoPanel.style.display = 'none';
            }
        });
        document.addEventListener('click', (e) => {
            if (!infoButton.contains(e.target) && !infoPanel.contains(e.target)) {
                infoPanel.style.display = 'none';
            }
        });
    }

    console.log('[DOMContentLoaded] 数据收集许可面板绑定完成');

    // ====================================================================
    // 12. 发送消息与博士扩展设定
    // ====================================================================
    if (sendMessageBtn) {
        sendMessageBtn.onclick = function(e) {
            e.preventDefault();
            e.stopPropagation();
            sendCurrentMessage(false);
        };
    }

    const saveDoctorProfile = document.getElementById('save-doctor-profile');
    if (saveDoctorProfile) {
        saveDoctorProfile.onclick = async () => {
            const extra = document.getElementById('doctor-extra-prompt').value;
            try {
                const res = await fetch('/extra_prompt/doctor', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ extra_prompt: extra })
                });
                if (res.ok) {
                    alert('博士附加设定保存成功');
                } else {
                    alert('保存失败');
                }
            } catch (e) {
                console.error('保存博士扩展设定出错', e);
                alert('保存出错: ' + e.message);
            }
        };
    }

    console.log('[DOMContentLoaded] 发送消息与博士扩展设定绑定完成');

    // ====================================================================
    // 13. 群组活跃度系数
    // ====================================================================
    const activenessFactor = document.getElementById('group-activeness-factor');
    const activenessValue = document.getElementById('group-activeness-value');
    if (activenessFactor && activenessValue) {
        activenessFactor.addEventListener('input', (e) => {
            const val = parseFloat(e.target.value);
            activenessValue.textContent = val.toFixed(1);
            if (currentGroupId) {
                fetch(`/group/config/${currentGroupId}`).then(res => res.json()).then(config => {
                    config.activeness_factor = val;
                    fetch(`/group/config/${currentGroupId}`, {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify(config)
                    });
                });
            }
        });
    }

    console.log('[DOMContentLoaded] 群组活跃度系数绑定完成');

    // ====================================================================
    // 14. 扩展页列表
    // ====================================================================
    // 扩展页列表项点击跳转
    document.addEventListener('click', (e) => {
        const item = e.target.closest('.extension-item');
        if (item && item.closest('#page-moments')) {
            const page = item.dataset.page;
            if (!page) return;
            if (isExtensionFavoriteSelectionActive()) {
                e.preventDefault();
                selectExtensionFavorite(page);
                return;
            }
            showPage(page);
        }
    });

    initExtensionFavorites();
    initExtensionSearch();

    // 点击半页框遮罩关闭
    document.addEventListener('click', (e) => {
        if (e.target.classList.contains('bottom-sheet-overlay')) {
            const sheet = e.target.closest('.bottom-sheet');
            if (sheet?.id) closeBottomSheet(sheet.id);
        }
    });

    // 初始化时加载未读计数
    fetchUnreadCount();

    console.log('[DOMContentLoaded] 扩展页绑定完成');

    // ====================================================================
    // 15. 右滑删除手势（聊天列表）
    // ====================================================================
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initGlobalSwipe);
    } else {
        initGlobalSwipe();
    }

    console.log('[DOMContentLoaded] 右滑删除手势绑定完成');

    // ====================================================================
    // 16. 安全区适配 & 键盘监听
    // ====================================================================
    // 手动安全区
    loadManualSafeAreaSettings();
    initManualSafeAreaControls();
    // 原生视口事件是安全区权威来源；resize 只作为无原生桥时的降级。
    updateSafeArea();
    window.addEventListener('resize', () => {
        if (!nativeViewportState) updateSafeArea();
    }, { passive: true });

    // 键盘弹出处理（仅滚动输入框）
    initKeyboardObserver();

    console.log('[DOMContentLoaded] 安全区适配 & 键盘监听绑定完成');

    // ====================================================================
    // 17. 批量操作复选框 & 调试模式
    // ====================================================================
    document.getElementById('batch-complete')?.addEventListener('click', batchComplete);
    document.getElementById('batch-delete')?.addEventListener('click', batchDelete);
    document.getElementById('batch-cancel')?.addEventListener('click', cancelBatch);

    updateDebugPanelVisibility();

    // 调试边框开关（设置-调试模式）
    const debugBorderToggle = document.getElementById('debug-border-toggle');
    if (debugBorderToggle) {
        debugBorderToggle.addEventListener('change', (e) => {
            if (e.target.checked) {
                enableDebugBorder();
            } else {
                disableDebugBorder();
            }
        });
    }

    console.log('[DOMContentLoaded] 批量操作复选框 & 调试模式绑定完成');

    // ====================================================================
    // 18. 初始化设备发现 & 协同管理器
    // ====================================================================
    // 初始化协同管理器
    if (window.coopManager) {
        window.coopManager.loadConfig();
    } else {
        console.warn('coopManager 未加载，协同加速将不可用');
    }

    initDeviceDiscovery();

    const toggle = document.getElementById('pc-accelerate-toggle');
    const addressInput = document.getElementById('pc-address');
    const testBtn = document.getElementById('test-pc-connection'); // 添加测试按钮引用

    // 隐藏测试连接按钮（协同加速标签页不再需要）
    if (testBtn) {
        testBtn.style.display = 'none';
    }

    // 地址输入框设为只读（配对后自动填充，不允许手动修改）
    if (addressInput) {
        addressInput.readOnly = true;
        addressInput.style.background = 'var(--bg-secondary)';
    }

    // ===== 新增：初始化协同加速开关状态和地址显示 =====
    if (toggle) {
        const savedEnabled = localStorage.getItem('pcAccelerateEnabled') === 'true';
        toggle.checked = savedEnabled;
        const addrItem = document.getElementById('pc-address-item');
        if (addrItem) addrItem.style.display = savedEnabled ? 'flex' : 'none';
    }
    if (addressInput) {
        const savedAddress = localStorage.getItem('pcAddress') || '';
        addressInput.value = savedAddress;
    }
    // ===== 初始化结束 =====

    if (toggle) {
        toggle.addEventListener('change', () => {
            const enabled = toggle.checked;
            const address = addressInput ? addressInput.value.trim() : '';
            localStorage.setItem('pcAccelerateEnabled', enabled);
            localStorage.setItem('pcAddress', address);
            if (window.coopManager) window.coopManager.loadConfig();
            const addrItem = document.getElementById('pc-address-item');
            if (addrItem) addrItem.style.display = enabled ? 'flex' : 'none';
        });
    }
    if (addressInput) {
        addressInput.addEventListener('change', () => {
            const address = addressInput.value.trim();
            localStorage.setItem('pcAddress', address);
            if (window.coopManager) window.coopManager.loadConfig();
        });
    }

    if (window.Android) {
        const pairedJson = Android.getPairedDevice();
        if (pairedJson && pairedJson !== 'null') {
            try {
                const paired = JSON.parse(pairedJson);
                const baseUrl = `http://${paired.ip}:${paired.port}`;
                // 若已有同步管理器，先停止再新建，避免重复运行
                if (window.syncManager) {
                    window.syncManager.stop();
                    window.syncManager = null;
                }
                window.syncManager = new SyncManager(baseUrl);
                window.syncManager.start();
            } catch(e) { console.error(e); }
        }
    }

    saveMessagesToLocalStorage();

    console.log('[DOMContentLoaded] 设备发现 & 协同管理器初始化完成');

    // ====================================================================
    // 19. 初始化设备发现、协同加速、代理推送设置
    // ====================================================================
    // 多端互通页面的标签页切换
    const deviceTabBtn = document.querySelector('#page-settings-multi-device .auto-tab[data-tab="device"]');
    const cooperationTabBtn = document.querySelector('#page-settings-multi-device .auto-tab[data-tab="cooperation"]');
    const proxyTabBtn = document.querySelector('#page-settings-multi-device .auto-tab[data-tab="proxy"]');
    const conflictsTabBtn = document.querySelector('#page-settings-multi-device .auto-tab[data-tab="conflicts"]');
    const deviceContent = document.getElementById('device-tab');
    const cooperationContent = document.getElementById('cooperation-tab');
    const proxyContent = document.getElementById('proxy-tab');
    const conflictsContent = document.getElementById('conflicts-tab');

    function switchMultiDeviceTab(tabId) {
        // 隐藏所有内容
        if (deviceContent) deviceContent.classList.add('hidden');
        if (cooperationContent) cooperationContent.classList.add('hidden');
        if (proxyContent) proxyContent.classList.add('hidden');
        if (conflictsContent) conflictsContent.classList.add('hidden');
        // 显示选中内容
        if (tabId === 'device' && deviceContent) deviceContent.classList.remove('hidden');
        if (tabId === 'cooperation' && cooperationContent) cooperationContent.classList.remove('hidden');
        if (tabId === 'proxy' && proxyContent) proxyContent.classList.remove('hidden');
        if (tabId === 'conflicts' && conflictsContent) { conflictsContent.classList.remove('hidden'); loadSyncConflicts(); }
        // 更新标签样式
        [deviceTabBtn, cooperationTabBtn, proxyTabBtn, conflictsTabBtn].forEach(btn => {
            if (btn) btn.classList.remove('active');
        });
        if (tabId === 'device' && deviceTabBtn) deviceTabBtn.classList.add('active');
        if (tabId === 'cooperation' && cooperationTabBtn) cooperationTabBtn.classList.add('active');
        if (tabId === 'proxy' && proxyTabBtn) proxyTabBtn.classList.add('active');
        if (tabId === 'conflicts' && conflictsTabBtn) conflictsTabBtn.classList.add('active');

        // ===== 新增：当切换到协同加速标签页时，刷新 UI 状态 =====
        if (tabId === 'cooperation') {
            const toggle = document.getElementById('pc-accelerate-toggle');
            const addressInput = document.getElementById('pc-address');
            const addrItem = document.getElementById('pc-address-item');
            if (toggle) {
                const enabled = localStorage.getItem('pcAccelerateEnabled') === 'true';
                toggle.checked = enabled;
                if (addrItem) addrItem.style.display = enabled ? 'flex' : 'none';
            }
            if (addressInput) {
                addressInput.value = localStorage.getItem('pcAddress') || '';
            }
        }
        // ===== 新增结束 =====
    }

    if (deviceTabBtn) deviceTabBtn.addEventListener('click', () => switchMultiDeviceTab('device'));
    if (cooperationTabBtn) cooperationTabBtn.addEventListener('click', () => switchMultiDeviceTab('cooperation'));
    if (proxyTabBtn) proxyTabBtn.addEventListener('click', () => switchMultiDeviceTab('proxy'));
    if (conflictsTabBtn) conflictsTabBtn.addEventListener('click', () => switchMultiDeviceTab('conflicts'));

    console.log('[DOMContentLoaded] 设备发现、协同加速、代理推送设置初始化完成');

    // ====================================================================
    // 20. 初始化时加载时区
    // ====================================================================
    loadGlobalTimezone();
    const saveTzBtn = document.getElementById('save-timezone-btn');
    if (saveTzBtn) saveTzBtn.addEventListener('click', saveGlobalTimezone);

    console.log('[DOMContentLoaded] 设备发现、协同加速、代理推送设置初始化完成');

    // ====================================================================
    // 21. 初始化干员档案页
    // ====================================================================
    // 全局监听：处理干员档案页的“自定义档案”和“发言设置”按钮
    document.addEventListener('click', (e) => {
        const btn = e.target.closest('.operator-extra-btn');
        if (!btn) return;
        const operatorId = btn.dataset.operator;
        const page = btn.dataset.page; // 'operator-extra' 或 'operator-speech'
        if (operatorId && page) {
            sessionStorage.setItem('currentCustomOperatorId', operatorId);
            sessionStorage.setItem('currentCustomRoleType', getCharacterRoleType(operatorId));
            showPage(page);
        }
    });

    console.log('[DOMContentLoaded] 干员档案页初始化完成');

    // ====================================================================
    // 22. 全局点击事件委托（聊天项及右滑按钮）
    // ====================================================================
    document.addEventListener('click', (e) => {
        // 优先处理操作按钮点击
        const actionBtn = e.target.closest('.chat-item-actions .action-btn');
        if (actionBtn) {
            e.stopPropagation();
            e.preventDefault();
            const action = actionBtn.dataset.action;
            const chatId = actionBtn.dataset.chatId;
            const chatType = actionBtn.dataset.chatType;
            // 关闭当前聊天项的滑动状态
            const chatItem = actionBtn.closest('.chat-item');
            if (chatItem && chatItem.classList.contains('swiped')) {
                chatItem.classList.remove('swiped');
                chatItem.style.transform = '';
            }
            if (action === 'unpin') {
                togglePin(chatId, chatType);
            } else if (action === 'mark-unread') {
                markAsUnread(chatId, chatType);
            } else if (action === 'delete') {
                deleteChat(chatId, chatType);
            }
            return;
        }

        // 如果点击的区域在 .chat-item-actions 内部（例如按钮之间的空隙），也阻止聊天项跳转
        if (e.target.closest('.chat-item-actions')) {
            e.stopPropagation();
            return;
        }

        // 聊天项点击
        const chatItem = e.target.closest('.chat-item');
        if (!chatItem) return;
        const chatId = chatItem.dataset.chatId;
        const chatType = chatItem.dataset.chatType;
        if (chatType === 'private') {
            openChat('private', chatId, getChatTargetIdentity(chatId));
        } else {
            currentGroupId = chatId;
            currentOperatorId = null;
            const group = groups[chatId];
            const titleEl = document.getElementById('chat-title');
            if (titleEl) titleEl.textContent = group ? group.name : chatId;
            loadGroupHistory(chatId);
            ensureGroupConfig(chatId).then(() => renderCurrentChat());
            saveCurrentChat();
            showPage('chat-detail');
        }
    });

    console.log('[DOMContentLoaded] 全局点击事件委托绑定完成');

    // ====================================================================
    // 23. 父页面监听器
    // ====================================================================
    window.addEventListener('message', (event) => {
        // 可以添加来源验证，简化处理直接信任
        const data = event.data;
        if (data && data.type === 'navigate_graph') {
            const targetId = data.id;
            if (targetId) {
                // 调用 showPage 切换到新的图谱页
                const graphMode = data.mode || 'static';
                showPage(`embedded-graph?mode=${encodeURIComponent(graphMode)}&id=${encodeURIComponent(targetId)}`, false, false);
            }
        }
        if (data && data.type === 'navigate_character_detail' && data.id) {
            showOperatorDetail(String(data.id));
        }
    });

    console.log('[DOMContentLoaded] 父页面监听器绑定完成');

    console.log('[DOMContentLoaded] 静态事件绑定完成');
    // 全局日记管理翻页导航初始化
    initDiaryNavigation();

});


// ========== 1.1.1. async function ==========
document.addEventListener('DOMContentLoaded', async function() {
    await loadVersionInfo(); // ✅ 正常
});


// ========== 1.2. 首次启动 ==========
// ========== 1.2.1. 首次启动设置向导 ==========
// 永久完成标记不随版本升级失效；开发者 reset ID 只会消费一次。
window.firstRunCoordinator = {
    state: 'unknown',
    promise: null,
    async start() {
        if (this.promise) return this.promise;
        this.promise = this._start();
        return this.promise;
    },
    async _start() {
        this.state = 'loading';
        const legacyCompleted = localStorage.getItem('setupWizardCompletedPermanently') === 'true' ||
            localStorage.getItem('onboarding_completed_v1') === 'true';
        let localData = {};
        let backendState = null;
        try {
            const [versionResponse, stateResponse] = await Promise.all([
                fetch('/api/version/local'), fetch('/first-run/state')
            ]);
            if (versionResponse.ok) localData = await versionResponse.json();
            if (stateResponse.ok) backendState = await stateResponse.json();
        } catch (error) {
            console.warn('[首次运行] 读取后端状态失败，使用本地完成缓存', error);
        }
        currentAppVersion = localData.app_version || currentAppVersion;
        currentPlatform = String(localData.platform || currentPlatform);
        const resetId = String(localData.setup_wizard_reset_id || backendState?.reset_generation || '');
        const consumedResetId = localStorage.getItem('setupWizardConsumedResetId') || '';
        const forcedReset = Boolean(localData.force_setup_wizard_reset && resetId && resetId !== consumedResetId);
        const completed = legacyCompleted || Boolean(backendState?.setup_completed);
        if (completed && !forcedReset) {
            this.state = 'completed';
            window._wizardShown = false;
            if (!backendState?.setup_completed) this.persist().catch(() => {});
            return { shown: false };
        }
        if (forcedReset) localStorage.setItem('setupWizardConsumedResetId', resetId);
        await loadCurrentSettingsToWizard();
        if (this.state !== 'completed') {
            showModal('setupWizardModal');
            this.state = 'shown';
            window._wizardShown = true;
        }
        return { shown: true };
    },
    async persist() {
        const response = await fetch('/first-run/state', {
            method: 'PUT', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ setup_completed: true, onboarding_completed: true })
        });
        if (!response.ok) throw new Error(`first-run persist failed: ${response.status}`);
    },
    async complete() {
        if (this.state === 'saving') return false;
        this.state = 'saving';
        localStorage.setItem('setupWizardShownVersion', currentAppVersion || APP_VERSION);
        localStorage.setItem('setupWizardCompletedPermanently', 'true');
        localStorage.setItem('onboarding_completed_v1', 'true');
        hideModal('setupWizardModal');
        window._wizardShown = false;
        this.state = 'completed';
        try {
            await this.persist();
        } catch (error) {
            console.warn('[首次运行] 后端完成状态将在下次启动补写', error);
        }
        return true;
    }
};

async function checkAndShowSetupWizard() {
    return window.firstRunCoordinator.start();
}

async function loadCurrentSettingsToWizard() {
    // 1. 获取当前服务商
    let currentProvider = 'deepseek';
    try {
        const res = await fetch('/get_current_provider');
        if (res.ok) {
            const data = await res.json();
            currentProvider = data.provider || 'deepseek';
        }
    } catch (e) { console.warn('获取当前服务商失败', e); }

    const providerSelect = document.getElementById('wizard-provider-select');
    if (providerSelect) providerSelect.value = currentProvider;

    const provider = currentProvider;
    let apiBase = '', apiKey = '', apiKeyConfigured = false, savedModel = '';

    // 2. 并行加载该服务商的 API 地址、密钥和模型（逐个捕获错误）
    try {
        const apiBaseRes = await fetch(`/get_api_base_for_provider?provider=${provider}`);
        if (apiBaseRes.ok) apiBase = (await apiBaseRes.json()).api_base || '';
    } catch (e) { console.warn('加载API地址失败', e); }

    try {
        const apiKeyRes = await fetch(`/get_api_key_for_provider?provider=${provider}`);
        if (apiKeyRes.ok) {
            const keyData = await apiKeyRes.json();
            apiKey = '';
            apiKeyConfigured = Boolean(keyData.configured);
            const apiKeyInput = document.getElementById('wizard-api-key');
            if (apiKeyInput) {
                apiKeyInput.dataset.configured = apiKeyConfigured ? '1' : '0';
                apiKeyInput.placeholder = apiKeyConfigured
                    ? `已保存密钥（${keyData.masked_value || '已配置'}）；留空保持不变`
                    : '请输入 API 密钥';
            }
        }
    } catch (e) { console.warn('加载API密钥失败', e); }

    try {
        const modelRes = await fetch(`/get_model_for_provider?provider=${provider}`);
        if (modelRes.ok) savedModel = (await modelRes.json()).model || '';
    } catch (e) { console.warn('加载模型失败', e); }

    // 如果没有默认地址且存在默认映射，则填充默认地址（但不覆盖用户现有的输入）
    if (!apiBase && DEFAULT_API_BASE && DEFAULT_API_BASE[provider]) {
        apiBase = DEFAULT_API_BASE[provider];
    }

    // 填充表单字段
    const apiBaseInput = document.getElementById('wizard-api-base');
    const apiKeyInput = document.getElementById('wizard-api-key');
    const customModelInput = document.getElementById('wizard-custom-model');
    const modelSelect = document.getElementById('wizard-model-select');

    if (apiBaseInput) apiBaseInput.value = apiBase;
    if (apiKeyInput) apiKeyInput.value = apiKey;

    if (savedModel) {
        // 有已保存的模型：优先填入自定义输入框，清空下拉选择
        if (customModelInput) customModelInput.value = savedModel;
        if (modelSelect) modelSelect.value = '';
    } else {
        if (customModelInput) customModelInput.value = '';
        if (modelSelect) modelSelect.value = '';
    }

    // 3. 加载博士姓名
    try {
        const res = await fetch('/doctor/preferences');
        if (res.ok) {
            const data = await res.json();
            const nameInput = document.getElementById('wizard-doctor-name');
            if (nameInput) nameInput.value = data.doctor_name || '';
        }
    } catch (e) {}

    // 4. 加载自主消息开关
    try {
        const res = await fetch('/background_mode');
        if (res.ok) {
            const data = await res.json();
            const autoGenerateCheck = document.getElementById('wizard-auto-generate');
            if (autoGenerateCheck) autoGenerateCheck.checked = data.enabled || false;
        }
    } catch (e) {}

    // 5. 加载随机事件开关
    try {
        const res = await fetch('/event/config');
        if (res.ok) {
            const config = await res.json();
            const anyEnabled = Object.values(config).some(c => c.enabled);
            const autoEventCheck = document.getElementById('wizard-auto-event');
            if (autoEventCheck) autoEventCheck.checked = anyEnabled;
        }
    } catch (e) {}

    // 6. 可选：延迟自动刷新模型列表（但为了避免过多请求，保持手动刷新）
    // 如果希望自动刷新，可以取消注释下面一行，但需要确保密钥已填写
    if (apiBase && apiKey) prepareWizardModels();
}

async function saveWizardSettings() {
    const provider = document.getElementById('wizard-provider-select').value;
    let apiBase = document.getElementById('wizard-api-base').value.trim();
    const model = document.getElementById('wizard-model-select').value || document.getElementById('wizard-custom-model').value.trim();
    const apiKey = document.getElementById('wizard-api-key').value.trim();
    const doctorName = document.getElementById('wizard-doctor-name').value.trim();
    const autoGenerate = document.getElementById('wizard-auto-generate').checked;
    const autoEvent = document.getElementById('wizard-auto-event').checked;

    // 如果未填写 API 地址，尝试使用默认地址（仅对部分已知服务商）
    if (!apiBase) {
        const defaultBase = DEFAULT_API_BASE[provider];
        if (defaultBase) apiBase = defaultBase;
    }
    if (!apiBase) {
        alert('请填写 API 地址');
        return;
    }
    if (!model) {
        alert('请选择或输入模型名称');
        return;
    }
    if (!apiKey && document.getElementById('wizard-api-key')?.dataset.configured !== '1') {
        alert('请填写 API 密钥');
        return false;
    }

    // 保存当前服务商
    await fetch('/set_current_provider', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ provider })
    });

    // 保存该服务商的 API 地址、密钥和模型
    await fetch('/set_api_base_for_provider', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ provider, api_base: apiBase })
    });
    await fetch('/set_api_key_for_provider', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ provider, api_key: apiKey })
    });
    await fetch('/set_model_for_provider', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ provider, model })
    });

    // 保存博士姓名
    if (doctorName) {
        localStorage.setItem('doctorName', doctorName);
        await fetch('/set_doctor_name', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name: doctorName })
        });
    }

    // 保存自主消息开关
    await fetch('/background_mode', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ enabled: autoGenerate, interval: 60 })
    });

    // 保存随机事件开关（全部类别统一开关）
    const eventConfigRes = await fetch('/event/config');
    const eventConfig = await eventConfigRes.json();
    for (let cat in eventConfig) {
        eventConfig[cat].enabled = autoEvent;
    }
    await fetch('/event/config', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(eventConfig)
    });

    const localRes = await fetch('/api/version/local');
    const localData = await localRes.json();
    // 更新全局变量
    currentAppVersion = localData.app_version;
    currentPlatform = String(localData.platform || currentPlatform);
    await window.firstRunCoordinator.complete();
    return true;
}

async function prepareWizardModels() {
    const provider = document.getElementById('wizard-provider-select').value;
    let apiBase = document.getElementById('wizard-api-base').value.trim();
    const apiKey = document.getElementById('wizard-api-key').value.trim();

    // 如果 API 地址为空且当前服务商有默认地址，则自动填充到输入框并继续使用
    if (!apiBase && DEFAULT_API_BASE[provider]) {
        apiBase = DEFAULT_API_BASE[provider];
        document.getElementById('wizard-api-base').value = apiBase;
    }

    // 校验地址和密钥是否齐全
    if (!apiBase) {
        document.getElementById('wizard-model-select').innerHTML = '<option value="">请先填写 API 地址</option>';
        return;
    }
    if (!apiKey) {
        document.getElementById('wizard-model-select').innerHTML = '<option value="">请先填写 API 密钥</option>';
        return;
    }

    const select = document.getElementById('wizard-model-select');
    select.innerHTML = '<option value="">加载中...</option>';
    try {
        const res = await fetch('/api/models', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ provider, api_base: apiBase, api_key: apiKey })
        });
        if (res.ok) {
            const data = await res.json();
            const models = data.models || [];
            if (models.length === 0) {
                select.innerHTML = '<option value="">未获取到模型，请检查地址/密钥</option>';
            } else {
                let options = '<option value="">请选择模型</option>';
                models.forEach(m => options += `<option value="${m}">${m}</option>`);
                select.innerHTML = options;
            }
        } else {
            // 尝试解析错误信息
            let errorMsg = '获取失败';
            try {
                const err = await res.json();
                errorMsg = err.error?.message || err.message || errorMsg;
            } catch(e) {}
            select.innerHTML = `<option value="">${errorMsg}</option>`;
        }
    } catch (e) {
        console.error(e);
        select.innerHTML = '<option value="">网络错误，请检查连接</option>';
    }
}

