// ========== 1.2.3. 自动更新弹窗 ==========
let updateNotificationData = null;          // 缓存当前弹窗数据
let hasShownUpdateNotification = false;     // 防止重复弹出

function showUpdateNotification(data) {
    if (hasShownUpdateNotification) return;
    hasShownUpdateNotification = true;

    const forcedVersionKey = 'shown_force_version';
    if (data.force_update) {
        const shownVersion = localStorage.getItem(forcedVersionKey);
        if (shownVersion === data.version) {
            return;
        }
    }

    updateNotificationData = data;

    const overlay = document.getElementById('update-notification-overlay');
    if (!overlay) return;

    // 版本号
    const verEl = document.getElementById('update-notification-version');
    if (verEl) {
        verEl.textContent = data.version ? `v${data.version}` : '版本信息不可用';
    }

    // 卡片
    const cardsContainer = document.getElementById('update-notification-cards');
    if (cardsContainer) {
        if (data.cards && data.cards.length > 0) {
            cardsContainer.innerHTML = data.cards.map(card => `
                <div class="update-card">
                    <img src="${card.image}" alt="${card.title}" loading="lazy" onerror="this.src='/static/backgrounds/profile_cardbanner_unfold.webp'">
                    <div class="card-title">${card.title}</div>
                    <div class="card-desc">${card.desc}</div>
                </div>
            `).join('');
        } else {
            cardsContainer.innerHTML = `<div style="padding:16px;color:var(--text-secondary);">${data.release_notes || '本次更新优化了性能和稳定性。'}</div>`;
        }
    }

    // 按钮
    const updateBtn = document.getElementById('update-notification-update');
    const laterBtn = document.getElementById('update-notification-later');

    if (updateBtn) {
        // 判断可用性
        const hasFrontend = data.frontend_url && data.frontend_url.trim() !== '';
        const hasFull = data.full_url && data.full_url.trim() !== '';

        if (data.is_full && hasFull) {
            updateBtn.textContent = '📦 下载完整安装包';
            updateBtn.disabled = false;
        } else if (!data.is_full && hasFrontend) {
            updateBtn.textContent = '⚡ 立即更新';
            updateBtn.disabled = false;
        } else if (hasFull) {
            // 有全量包但 is_full 为 false，强制转为全量
            updateBtn.textContent = '📦 下载完整安装包';
            updateBtn.disabled = false;
            data.is_full = true;
        } else {
            updateBtn.textContent = '❌ 更新不可用';
            updateBtn.disabled = true;
        }

        updateBtn.onclick = () => {
            if (data.force_update) {
                localStorage.setItem(forcedVersionKey, data.version);
            }
            hideUpdateNotification();
            performUpdate(data);
        };
    }

    if (laterBtn) {
        if (data.force_update) {
            laterBtn.disabled = true;
            laterBtn.textContent = '此更新为强制更新，请立即更新';
        } else {
            laterBtn.disabled = false;
            laterBtn.textContent = '暂不更新';
            laterBtn.onclick = () => {
                hideUpdateNotification();
            };
        }
    }

    overlay.classList.remove('hidden');
}

function hideUpdateNotification() {
    const overlay = document.getElementById('update-notification-overlay');
    if (overlay) overlay.classList.add('hidden');
    hasShownUpdateNotification = false; // 重置，以便下次启动可再次弹出
}

/**
 * 执行全量更新（PC端或移动端）
 */
async function performFullUpdate(data) {
    try {
        const res = await fetch('/api/version/download_full', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                version: data.version,
                url: data.full_url
            })
        });
        const result = await res.json();
        if (res.ok) {
            if (window.Android && typeof window.Android.installApk === 'function') {
                // 移动端：调用 Java 安装
                window.Android.installApk(result.file_path);
            } else {
                // PC 端：文件已自动打开
                alert('安装包已下载，请运行安装程序完成更新');
            }
        } else {
            alert('全量更新失败：' + (result.message || '未知错误'));
        }
    } catch (e) {
        alert('全量更新出错，请稍后重试');
        console.error(e);
    }
}

