function initGeneralSettingsSections() {
    const root = document.getElementById('page-settings-general');
    if (!root) return;
    const savedTab = localStorage.getItem('settings-tab:settings-general') || 'notif';
    const tabs = root.querySelectorAll('.general-settings-tabs [data-tab]');
    tabs.forEach(tab => {
        const active = tab.dataset.tab === savedTab;
        tab.classList.toggle('active', active);
        const panel = root.querySelector(`#general-tab-${tab.dataset.tab}`);
        panel?.classList.toggle('hidden', !active);
        if (tab.dataset.generalBound !== '1') {
            tab.dataset.generalBound = '1';
            tab.addEventListener('click', () => {
                localStorage.setItem('settings-tab:settings-general', tab.dataset.tab);
            });
        }
    });
    root.querySelectorAll('[data-general-section]').forEach(section => {
        const key = `zoot_general_section:${section.dataset.generalSection}`;
        const saved = localStorage.getItem(key);
        if (saved !== null) section.open = saved === 'open';
        if (section.dataset.generalBound === '1') return;
        section.dataset.generalBound = '1';
        section.addEventListener('toggle', () => {
            localStorage.setItem(key, section.open ? 'open' : 'closed');
        });
    });
}

// ========== 1.4. 历史相关 ==========
// 清除所有历史（聊天记录和待办事项）
async function clearAllHistory() {
    if (!confirm('⚠️ 此操作将清除所有聊天记录和待办事项，不可恢复！确定继续吗？')) return;
    try {
        // 清除所有聊天记录
        await fetch('/history/all', { method: 'DELETE' });
        // 清除所有待办事项
        const todoRes = await fetch('/todo/list');
        const todos = await todoRes.json();
        for (const todo of todos) {
            await fetch('/todo/delete', { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({id: todo.id}) });
        }
        // 清空前端缓存
        messages = {};
        chats = [];
        unreadCount = {};
        stretchMessages = [];
        await loadChats();
        await loadTodoItems();
        alert('所有历史已清除');
    } catch (e) {
        console.error(e);
        alert('清除失败');
    }
}

// 导出历史（聊天记录）
async function exportHistory() {
    try {
        const personaId = window.currentPersonaId || currentPersonaId || 'doctor';
        const res = await fetch(`/chats?persona_id=${encodeURIComponent(personaId)}`);
        const chatsList = await res.json();
        let allMessages = [];
        for (const chat of chatsList) {
            let url = chat.type === 'private' ? `/private/history?operator_id=${chat.id}&limit=1000` : `/group/history?group_id=${chat.id}&limit=1000`;
            const msgsRes = await fetch(url);
            const msgs = await msgsRes.json();
            allMessages.push({ chat: chat, messages: msgs });
        }
        const dataStr = JSON.stringify(allMessages, null, 2);
        const blob = new Blob([dataStr], {type: 'application/json'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `zoot_history_${new Date().toISOString().slice(0,19)}.json`;
        a.click();
        URL.revokeObjectURL(url);
        alert('聊天记录已导出');
    } catch (e) {
        console.error(e);
        alert('导出失败');
    }
}

