// ========== 2.1. 全局函数 ==========
function openChat(targetType, targetId, identity = null) {
    targetId = String(targetId);
    if (targetType === 'private') {
        const special = registerChatTargetIdentity(identity) || getChatTargetIdentity(targetId);
        if (special && (window.currentPersonaId || currentPersonaId || 'doctor') === 'doctor') {
            showTemporaryToast('博士人格不能与 AI 博士或 AI 管理员建立会话', 3200, 'warning');
            return;
        }
        currentSpecialChatTarget = special;
        currentOperatorId = targetId;
        currentGroupId = null;
        saveCurrentChat();
        clearUnread(`private:${targetId}`);
        showPage('chat-detail');
    } else if (targetType === 'group') {
        currentSpecialChatTarget = null;
        currentGroupId = targetId;
        currentOperatorId = null;
        saveCurrentChat();
        clearUnread(`group:${targetId}`);
        showPage('chat-detail');
    }
}
window.openChat = openChat;

const chatHistoryRefreshes = new Map();
function refreshChatHistory(chatType, chatId) {
    const chatKey = `${chatType}:${chatId}`;
    if (chatHistoryRefreshes.has(chatKey)) return chatHistoryRefreshes.get(chatKey);
    const request = loadHistory(chatType, chatId)
        .catch(error => console.error(`[聊天] 刷新 ${chatKey} 失败`, error))
        .finally(() => chatHistoryRefreshes.delete(chatKey));
    chatHistoryRefreshes.set(chatKey, request);
    return request;
}

function adjustChatListHeight() {
    const page = document.getElementById('page-chat-list');
    if (!page || !page.classList.contains('active-page')) return;

    const header = page.querySelector('.page-header');
    const search = page.querySelector('.search-bar');
    const filter = page.querySelector('.chat-filter-tabs');
    const container = page.querySelector('.chat-list-container');

    if (!container) return;

    // 计算固定头部总高度
    let fixedHeight = 0;
    if (header) fixedHeight += header.offsetHeight;
    if (search) fixedHeight += search.offsetHeight;
    if (filter) fixedHeight += filter.offsetHeight;

    // 获取页面可视高度
    const viewportHeight = window.innerHeight;

    // 容器高度 = 视口高度 - 固定头部高度
    const containerHeight = viewportHeight - fixedHeight;

    // 设置容器高度
    container.style.height = Math.max(0, containerHeight) + 'px';
}

async function fetchGlobalYear() {
    if (globalYear !== null) return globalYear;
    try {
        const res = await fetch('/global/year');
        const data = await res.json();
        globalYear = data.year;
        return globalYear;
    } catch (e) {
        console.error('获取全局年份失败', e);
        globalYear = 1099; // 默认泰拉历1099年
        return globalYear;
    }
}

/**
 * 手动构建 datetime-local 输入框需要的本地时间字符串
 * @param {number} year 年份
 * @param {number} month 月份 (1-12)
 * @param {number} day 日期 (1-31)
 * @param {number} hour 小时 (0-23)
 * @param {number} minute 分钟 (0-59)
 * @returns {string} 格式 YYYY-MM-DDTHH:MM
 */
function buildLocalDateTimeString(year, month, day, hour, minute) {
    const pad = (n) => String(n).padStart(2, '0');
    return `${year}-${pad(month)}-${pad(day)}T${pad(hour)}:${pad(minute)}`;
}

/**
 * 将时间戳转换为本地 datetime-local 字符串（纯手动，无 UTC 转换）
 * @param {number} timestamp 秒级时间戳
 * @returns {string}
 */
function timestampToLocalDateTimeString(timestamp) {
    const date = new Date(timestamp * 1000);
    const year = date.getFullYear();
    const month = date.getMonth() + 1;
    const day = date.getDate();
    const hour = date.getHours();
    const minute = date.getMinutes();
    return buildLocalDateTimeString(year, month, day, hour, minute);
}

// 辅助函数：设置日期选择器的默认值为全局年份的当天
function setDefaultDateWithGlobalYear(dateInput, targetDate = null) {
    if (!dateInput) return;
    if (!globalYear) {
        setTimeout(() => setDefaultDateWithGlobalYear(dateInput, targetDate), 100);
        return;
    }

    if (dateInput.type === 'datetime-local') {
        let defaultStr;
        if (targetDate) {
            // targetDate 可能是时间戳、Date 对象或日期字符串
            let date;
            if (typeof targetDate === 'number') {
                date = new Date(targetDate * 1000);
            } else if (targetDate instanceof Date) {
                date = targetDate;
            } else {
                // 尝试解析字符串
                date = new Date(targetDate);
                if (isNaN(date.getTime())) {
                    // 无效日期，使用当前时间
                    date = new Date();
                }
            }
            const year = date.getFullYear();
            const month = date.getMonth() + 1;
            const day = date.getDate();
            const hour = date.getHours();
            const minute = date.getMinutes();
            defaultStr = buildLocalDateTimeString(year, month, day, hour, minute);
        } else {
            // 使用全局年份 + 当前系统月日 + 中午12点
            const now = new Date();
            const year = globalYear;
            const month = now.getMonth() + 1;
            const day = now.getDate();
            const hour = 12;
            const minute = 0;
            defaultStr = buildLocalDateTimeString(year, month, day, hour, minute);
        }
        dateInput.value = defaultStr;
    } else if (dateInput.type === 'date') {
        let defaultStr;
        if (targetDate) {
            let date;
            if (typeof targetDate === 'number') {
                date = new Date(targetDate * 1000);
            } else if (targetDate instanceof Date) {
                date = targetDate;
            } else {
                date = new Date(targetDate);
            }
            const year = date.getFullYear();
            const month = String(date.getMonth() + 1).padStart(2, '0');
            const day = String(date.getDate()).padStart(2, '0');
            defaultStr = `${year}-${month}-${day}`;
        } else {
            const now = new Date();
            const year = globalYear;
            const month = String(now.getMonth() + 1).padStart(2, '0');
            const day = String(now.getDate()).padStart(2, '0');
            defaultStr = `${year}-${month}-${day}`;
        }
        dateInput.value = defaultStr;
    }
}

// ========== 2.2. 通用确认弹窗 ==========
function showConfirmDialog(title, message, onConfirm, onCancel = null) {
    const modal = document.getElementById('confirmModal');
    if (!modal) {
        console.error('confirmModal 元素不存在');
        showToast('确认组件暂不可用，请稍后重试', 2600, 'error');
        return;
    }
    document.getElementById('confirm-title').textContent = title;
    document.getElementById('confirm-message').textContent = message;

    const okBtn = document.getElementById('confirm-ok');
    const cancelBtn = document.getElementById('confirm-cancel');

    // 移除旧监听（通过克隆替换）
    const newOkBtn = okBtn.cloneNode(true);
    okBtn.parentNode.replaceChild(newOkBtn, okBtn);
    const newCancelBtn = cancelBtn.cloneNode(true);
    cancelBtn.parentNode.replaceChild(newCancelBtn, cancelBtn);

    newOkBtn.addEventListener('click', () => {
        hideModal('confirmModal');
        onConfirm();
    });
    newCancelBtn.addEventListener('click', () => {
        hideModal('confirmModal');
        if (typeof onCancel === 'function') onCancel();
    });

    showModal('confirmModal');
}

function requestProjectConfirmation(title, message) {
    return new Promise(resolve => showConfirmDialog(title, message, () => resolve(true), () => resolve(false)));
}

function requestProjectTextInput(title, initialValue = '') {
    return new Promise(resolve => {
        const overlay = document.createElement('div');
        overlay.className = 'app-modal-overlay';
        overlay.innerHTML = `<section class="app-modal-sheet project-text-dialog" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><header><h3>${escapeHtml(title)}</h3></header><textarea class="project-text-input" rows="8" maxlength="6000"></textarea><footer><button type="button" data-dialog-cancel>取消</button><button type="button" data-dialog-submit>保存</button></footer></section>`;
        const input = overlay.querySelector('textarea');
        input.value = String(initialValue || '');
        const close = value => { overlay.remove(); resolve(value); };
        overlay.querySelector('[data-dialog-cancel]').onclick = () => close(null);
        overlay.querySelector('[data-dialog-submit]').onclick = () => close(input.value.trim());
        overlay.addEventListener('click', event => { if (event.target === overlay) close(null); });
        document.body.appendChild(overlay);
        requestAnimationFrame(() => input.focus());
    });
}

function requestProjectSingleLineInput(title, initialValue = '', maxLength = 40) {
    return new Promise(resolve => {
        const overlay = document.createElement('div');
        overlay.className = 'app-modal-overlay';
        overlay.innerHTML = `<section class="app-modal-sheet project-text-dialog project-single-line-dialog" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><header><h3>${escapeHtml(title)}</h3></header><input class="project-text-input" type="text" maxlength="${Number(maxLength) || 40}"><footer><button type="button" data-dialog-cancel>取消</button><button type="button" data-dialog-submit>保存</button></footer></section>`;
        const input = overlay.querySelector('input');
        input.value = String(initialValue || '');
        const close = value => {
            overlay.remove();
            resolve(value);
        };
        const submit = () => close(input.value.trim());
        overlay.querySelector('[data-dialog-cancel]').onclick = () => close(null);
        overlay.querySelector('[data-dialog-submit]').onclick = submit;
        overlay.addEventListener('click', event => {
            if (event.target === overlay) close(null);
        });
        input.addEventListener('keydown', event => {
            if (event.key === 'Enter') {
                event.preventDefault();
                submit();
            }
        });
        document.body.appendChild(overlay);
        requestAnimationFrame(() => {
            input.focus();
            input.select();
        });
    });
}

