// ========== 2.3. 深度合并函数 ==========
/**
 * 深度合并两个对象，递归合并所有层级，返回新对象（不修改原对象）
 * @param {Object} target 目标对象（会被合并到其中，但为了不修改，这里作为基础）
 * @param {Object} source 源对象
 * @returns {Object} 合并后的新对象
 */
function deepMerge(target, source) {
    if (!source || typeof source !== 'object') return target;
    const result = Array.isArray(target) ? [...target] : { ...target };
    for (const key of Object.keys(source)) {
        const sourceVal = source[key];
        if (sourceVal && typeof sourceVal === 'object' && !Array.isArray(sourceVal)) {
            result[key] = deepMerge(target[key] || {}, sourceVal);
        } else {
            result[key] = sourceVal;
        }
    }
    return result;
}

// ========== 2.4. 通用一次性提示组件 ==========
/**
 * 显示一个带"不再提示"按钮的持久化提示
 * @param {string} tipKey - 用于 localStorage 存储的键名（如 'silent_send_tip_dismissed'）
 * @param {string} tipText - 提示文本
 * @param {string|Element} container - 容器选择器或 DOM 元素
 * @param {Object} options - 可选配置
 * @param {string} options.dismissText - "不再提示"按钮文字，默认 "不再提示"
 * @param {number} options.autoHideDelay - 自动隐藏延迟（毫秒），0 表示不自动隐藏
 * @param {string} options.className - 额外 CSS 类名
 */
function showPersistentTip(tipKey, tipText, container, options = {}) {
    // 检查是否已被永久关闭
    if (localStorage.getItem(tipKey) === 'true') {
        return null;
    }

    const {
        dismissText = '不再提示',
        autoHideDelay = 0,
        className = ''
    } = options;

    // 确定容器
    let containerEl;
    if (typeof container === 'string') {
        containerEl = document.querySelector(container);
    } else if (container instanceof Element) {
        containerEl = container;
    } else {
        console.warn('[PersistentTip] 无效的容器');
        return null;
    }
    if (!containerEl) return null;

    // 移除已存在的同 key 提示
    const existing = containerEl.querySelector(`.persistent-tip[data-tip-key="${tipKey}"]`);
    if (existing) existing.remove();

    // 创建提示元素
    const tipEl = document.createElement('div');
    tipEl.className = `persistent-tip ${className}`.trim();
    tipEl.dataset.tipKey = tipKey;

    const textSpan = document.createElement('span');
    textSpan.className = 'tip-text';
    textSpan.textContent = tipText;

    const dismissBtn = document.createElement('button');
    dismissBtn.className = 'tip-dismiss';
    dismissBtn.textContent = dismissText;
    dismissBtn.addEventListener('click', () => {
        localStorage.setItem(tipKey, 'true');
        tipEl.remove();
    });

    tipEl.appendChild(textSpan);
    tipEl.appendChild(dismissBtn);
    containerEl.appendChild(tipEl);

    // 自动隐藏
    if (autoHideDelay > 0) {
        setTimeout(() => {
            if (tipEl.parentNode) {
                tipEl.style.transition = 'opacity 0.3s';
                tipEl.style.opacity = '0';
                setTimeout(() => tipEl.remove(), 300);
            }
        }, autoHideDelay);
    }

    return tipEl;
}

/**
 * 初始化静默发送提示
 */
function initSilentSendTip() {
    const tipContainer = document.querySelector('.sendbar-left');
    if (!tipContainer) return;

    // 检查是否已存在，避免重复创建
    if (tipContainer.querySelector('.persistent-tip[data-tip-key="silent_send_tip_dismissed"]')) {
        return;
    }

    // 使用通用提示组件
    showPersistentTip(
        'silent_send_tip_dismissed',
        '"静默发送"不会直接触发回复，而是等待使用"发送"后一起发送给干员',
        tipContainer,
        {
            dismissText: '不再提示',
            autoHideDelay: 0
        }
    );
}

/**
 * 显示临时提示消息（轻提示）
 * @param {string} text - 提示内容
 * @param {number} duration - 显示时长（毫秒）
 * @param {string} type - 提示类型 ('success', 'error', 'info')，默认为 'info'
 */
function showTemporaryToast(text, duration = 2000, type = 'info') {
    const existing = document.querySelector('.toast-tip');
    if (existing) existing.remove();

    const toast = document.createElement('div');
    toast.className = 'toast-tip';
    const toastIconName = window.ZootIcons?.statusName(type, text) || 'info';
    const toastIcon = window.ZootIcons?.element(toastIconName, {
        className: `zoot-status-icon zoot-status-${toastIconName}`
    });
    const toastText = document.createElement('span');
    toastText.textContent = window.ZootIcons?.cleanText(text) || text;
    if (toastIcon) toast.appendChild(toastIcon);
    toast.appendChild(toastText);

    // 根据类型设置颜色
    const colors = {
        success: 'rgba(40, 167, 69, 0.9)',
        error: 'rgba(220, 53, 69, 0.9)',
        info: 'rgba(0, 0, 0, 0.75)'
    };
    const bgColor = colors[type] || colors.info;

    toast.style.cssText = `
        position: fixed;
        bottom: 120px;
        left: 50%;
        transform: translateX(-50%);
        background: ${bgColor};
        color: #fff;
        padding: 8px 20px;
        border-radius: 20px;
        font-size: 13px;
        z-index: 9999;
        backdrop-filter: blur(8px);
        animation: tipFadeIn 0.3s ease;
        pointer-events: none;
    `;
    document.body.appendChild(toast);

    setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transition = 'opacity 0.3s';
        setTimeout(() => toast.remove(), 300);
    }, duration);
}

// ========== 2.5. 更新缓存大小辅助函数 ==========
async function updateCacheSize() {
    try {
        const res = await fetch('/api/cloud/cache/size');
        const data = await res.json();
        const sizeEl = document.getElementById('cloud-cache-size');
        const statusEl = document.getElementById('cloud-cache-status');
        if (sizeEl) {
            sizeEl.textContent = formatFileSize(data.size || 0);
        }
        if (statusEl) {
            statusEl.textContent = formatFileSize(data.size || 0);
        }
    } catch (e) {
        document.getElementById('cloud-cache-size').textContent = '获取失败';
        document.getElementById('cloud-cache-status').textContent = '获取失败';
    }
}

function formatFileSize(bytes) {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

// ========== 2.6. 云端服务 API 封装（CloudAPI） ==========
const CloudAPI = {
    async request(endpoint, options = {}) {
        const url = `/api/cloud${endpoint}`;
        console.log('[CloudAPI] 请求 URL:', url);
        try {
            const res = await fetch(url, {
                ...options,
                headers: {
                    'Content-Type': 'application/json',
                    ...(options.headers || {})
                }
            });

            // 先读取原始响应体（避免流被重复消费）
            let responseText = '';
            try {
                responseText = await res.text();
            } catch (e) {
                throw new Error('无法读取响应');
            }

            // 手动解析 JSON
            let json;
            try {
                json = JSON.parse(responseText);
            } catch (e) {
                throw new Error(`响应格式错误: ${responseText.substring(0, 100)}`);
            }

            if (!res.ok) {
                throw new Error(json.detail || json.message || `HTTP ${res.status}`);
            }

            console.log('[CloudAPI] 原始响应体:', JSON.stringify(json, null, 2));
            return json;
        } catch (e) {
            console.error(`[CloudAPI] ${endpoint} 失败:`, e);
            throw e;
        }
    },

    // ---------- API Key 管理 ----------
    getApiKeyStatus() {
        return this.request('/api_key_status');
    },
    refreshApiKey() {
        return this.request('/refresh_api_key', { method: 'POST' });
    },

    // ---------- 更新 ----------
    /**
     * 检查更新
     * @param {string} platform - 'pc' 或 'android'
     * @param {string} version - 当前应用版本
     * @param {string} frontendVersion - 当前前端版本
     * @param {string} grayCode - 灰度码（可选）
     */
    checkUpdate(platform = 'pc', version, frontendVersion, grayCode = null) {
        const params = new URLSearchParams({
            platform,
            version: version || '0.0.0',
            frontend_version: frontendVersion || '0.0.0'
        });
        if (grayCode) params.append('gray_code', grayCode);
        return this.request(`/check_update?${params.toString()}`);
    },

    // ---------- 灰度码 ----------
    /**
     * 验证灰度码
     * @param {string} code - 灰度码
     * @returns {Promise<{valid: boolean, expires_at?: number}>}
     */
    verifyGrayCode(code) {
        return this.request('/gray/verify', {
            method: 'POST',
            body: JSON.stringify({ code })
        });
    },
    getGrayStatus() {
        return this.request('/gray/status');
    },

    // ---------- 活动 ----------
    getActivities(since = null) {
        const params = since ? `?since=${since}` : '';
        return this.request(`/activities${params}`, { method: 'POST' });
    },

    // ---------- 反馈 ----------
    submitFeedback(data) {
        return this.request('/feedback', {
            method: 'POST',
            body: JSON.stringify(data)
        });
    },

    // ---------- 实验 ----------
    getExperimentConfig() {
        return this.request('/experiment/config');
    },
    submitExperimentData(data) {
        return this.request('/experiment/data', {
            method: 'POST',
            body: JSON.stringify(data)
        });
    },

    // ---------- 缓存 ----------
    getCacheSize() {
        return this.request('/cache/size');
    },
    clearCache() {
        return this.request('/cache/clear', { method: 'POST' });
    },

    // ---------- 健康检查 ----------
    healthCheck() {
        return this.request('/health');
    }
};

// ========== 2.7. 版本号工具函数 ==========
function parseVersion(version) {
    console.log('[更新调试] parseVersion 输入:', version);
    if (!version) {
        console.log('[更新调试] parseVersion: version 为空');
        return null;
    }
    const match = String(version).match(/^(\d+)\.(\d+)\.(\d+)/);
    console.log('[更新调试] parseVersion 正则匹配结果:', match);
    if (!match) {
        console.log('[更新调试] parseVersion: 匹配失败');
        return null;
    }
    const result = {
        major: parseInt(match[1], 10),
        minor: parseInt(match[2], 10),
        patch: parseInt(match[3], 10)
    };
    console.log('[更新调试] parseVersion 结果:', result);
    return result;
}

function compareVersions(v1, v2) {
    console.log('[更新调试] compareVersions 输入: v1=', v1, 'v2=', v2);
    const p1 = parseVersion(v1);
    const p2 = parseVersion(v2);
    console.log('[更新调试] compareVersions 解析结果: p1=', p1, 'p2=', p2);
    if (!p1 && !p2) return 0;
    if (!p1) return -1;
    if (!p2) return 1;
    const result = p1.major - p2.major || p1.minor - p2.minor || p1.patch - p2.patch;
    console.log('[更新调试] compareVersions 最终结果:', result);
    return result;
}

/**
 * 检查是否有新版本
 * @param {string} local - 本地版本
 * @param {string} remote - 服务端版本
 * @returns {boolean}
 */
function isNewVersionAvailable(local, remote) {
    if (!local || !remote) return false;
    return compareVersions(local, remote) < 0;
}

