// ========== 5. 草稿管理 ==========
function getDraftKey(chatType, chatId) {
    return `draft_${chatType}:${chatId}`;
}

function saveDraft(chatType, chatId, content) {
    console.debug('saveDraft', chatType, chatId, `length=${String(content || '').length}`);
    if (!chatType || !chatId) return;
    const key = getDraftKey(chatType, chatId);
    if (content && content.trim() !== '') {
        localStorage.setItem(key, content);
        ensureChatInList(chatType, chatId);
    } else {
        localStorage.removeItem(key);
    }
    renderChatList();
}

function loadDraft(chatType, chatId) {
    if (!chatType || !chatId) return '';
    const key = getDraftKey(chatType, chatId);
    return localStorage.getItem(key) || '';
}

function clearDraft(chatType, chatId) {
    console.log('clearDraft', chatType, chatId);
    if (!chatType || !chatId) return;
    const key = getDraftKey(chatType, chatId);
    localStorage.removeItem(key);
    const chatIndex = chats.findIndex(c => c.type === chatType && c.id === chatId);
    if (chatIndex !== -1) {
        const chat = chats[chatIndex];
        if (!chat.lastMsg && !localStorage.getItem(key)) {
            chats.splice(chatIndex, 1);
        }
    }
    renderChatList();
}

function ensureChatInList(chatType, chatId) {
    console.log('ensureChatInList', chatType, chatId);
    let exists = chats.some(c => c.type === chatType && c.id === chatId);
    if (!exists) {
        let newChat = {
            id: chatId,
            type: chatType,
            name: '',
            lastMsg: '',
            lastTime: 0,
            isPinned: false
        };
        if (chatType === 'private') {
            const op = operatorMap.get(chatId);
            newChat.name = op ? op.codename : chatId;
        } else {
            const group = groups[chatId];
            newChat.name = group ? group.name : chatId;
        }
        chats.push(newChat);
        renderChatList();
    }
}

// ========== 6. 通用设置页 ==========
// ========== 6.1. 设置子页面标签页初始化 ==========
// 修改后的 initSettingsTabs
function initSettingsTabs(pageId, tabsContainerSelector = '.auto-message-tabs', contentPrefix = null) {
    const page = document.getElementById(`page-${pageId}`);
    if (!page) return;
    // 只选取页面内第一个 .auto-message-tabs 容器（顶层标签）
    const tabsContainer = page.querySelector(tabsContainerSelector);
    if (!tabsContainer) return;
    const tabs = tabsContainer.querySelectorAll(':scope > .auto-tab');
    if (tabs.length === 0) return;

    const prefix = contentPrefix || pageId.replace('settings-', '');
    const contents = {};
    tabs.forEach(tab => {
        const target = tab.dataset.tab;
        const contentId = `${prefix}-tab-${target}`;
        const content = document.getElementById(contentId);
        if (content) contents[target] = content;
    });

    if (Object.keys(contents).length === 0) return;

    const activate = (tab) => {
        const target = tab.dataset.tab;
        tabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        Object.values(contents).forEach(c => c.classList.add('hidden'));
        if (contents[target]) contents[target].classList.remove('hidden');
        localStorage.setItem(`settings-tab:${pageId}`, target);
        if (pageId === 'settings-auto-gen' && typeof activateGeneratedContentSettingsSection === 'function') {
            void activateGeneratedContentSettingsSection(target);
        }
    };
    tabsContainer.onclick = (event) => {
        const clickedElement = event.target instanceof Element ? event.target : null;
        const tab = clickedElement?.closest('.auto-tab');
        if (tab?.parentElement === tabsContainer) activate(tab);
    };
    // 确保默认激活的标签
    let remembered = localStorage.getItem(`settings-tab:${pageId}`);
    if (pageId === 'settings-api' && remembered === 'cloud') {
        remembered = 'routes';
        localStorage.setItem(`settings-tab:${pageId}`, remembered);
    }
    const activeTab = Array.from(tabs).find(tab => tab.dataset.tab === remembered && contents[remembered])
        || tabsContainer.querySelector('.auto-tab.active');
    if (activeTab) {
        const target = activeTab.dataset.tab;
        Object.values(contents).forEach(c => c.classList.add('hidden'));
        if (contents[target]) contents[target].classList.remove('hidden');
    } else if (tabs[0]) {
        tabs[0].classList.add('active');
        const target = tabs[0].dataset.tab;
        Object.values(contents).forEach(c => c.classList.add('hidden'));
        if (contents[target]) contents[target].classList.remove('hidden');
    }
}

