// ========== 6.3. 调试错误日志 ==========
// 错误日志捕获（前端+后端）
let frontendErrors = []; // 存储前端错误 { timestamp, message, stack? }

function captureFrontendError(message, source, lineno, colno, error) {
    frontendErrors.unshift({
        timestamp: Date.now() / 1000,
        type: '前端错误',
        message: message,
        stack: error ? error.stack : null
    });
    if (frontendErrors.length > 200) frontendErrors.pop();
    if (document.getElementById('page-settings-debug').classList.contains('active-page')) {
        refreshErrorDisplay();
    }
}

// 监听全局错误
window.onerror = function(message, source, lineno, colno, error) {
    captureFrontendError(message, source, lineno, colno, error);
    return false;
};

// 监听未捕获的 Promise 拒绝
window.addEventListener('unhandledrejection', function(event) {
    captureFrontendError('未捕获的 Promise 拒绝: ' + (event.reason?.message || event.reason), null, null, null, event.reason);
});

// 刷新错误显示区（根据当前选中的选项卡）
let currentErrorTab = 'backend';

async function refreshErrorDisplay() {
    const textarea = document.getElementById('error-log-display');
    if (!textarea) return;
    if (currentErrorTab === 'backend') {
        try {
            const res = await fetch('/debug/error-logs?limit=100');
            const data = await res.json();
            const logs = data.logs || [];
            const content = logs.map(log => {
                let line = `[${new Date(log.timestamp * 1000).toLocaleString()}] [${log.level}] ${log.logger}: ${log.message}`;
                if (log.exception) line += `\n${log.exception}`;
                return line;
            }).join('\n');
            textarea.value = content || '暂无后端错误记录。';
        } catch (e) {
            textarea.value = '加载后端错误日志失败：' + e.message;
        }
    } else if (currentErrorTab === 'frontend') {
        const content = frontendErrors.map(err => {
            let line = `[${new Date(err.timestamp * 1000).toLocaleString()}] ${err.type}: ${err.message}`;
            if (err.stack) line += `\n${err.stack}`;
            return line;
        }).join('\n');
        textarea.value = content || '暂无前端错误记录。';
    }
}

// 复制错误日志
function copyErrorLogs() {
    const textarea = document.getElementById('error-log-display');
    if (!textarea) return;
    textarea.select();
    document.execCommand('copy');
    alert('已复制到剪贴板');
}

// 清空前端错误记录
function clearFrontendErrors() {
    frontendErrors = [];
    if (currentErrorTab === 'frontend') refreshErrorDisplay();
    alert('前端错误记录已清空');
}

// 选项卡切换
function initErrorLogTabs() {
    const backendTab = document.getElementById('error-log-tab-backend');
    const frontendTab = document.getElementById('error-log-tab-frontend');
    if (backendTab) {
        backendTab.addEventListener('click', () => {
            currentErrorTab = 'backend';
            backendTab.classList.add('active');
            frontendTab.classList.remove('active');
            refreshErrorDisplay();
        });
    }
    if (frontendTab) {
        frontendTab.addEventListener('click', () => {
            currentErrorTab = 'frontend';
            frontendTab.classList.add('active');
            backendTab.classList.remove('active');
            refreshErrorDisplay();
        });
    }
}

// 初始化错误日志区域（在页面加载时调用）
function initErrorLogCapture() {
    initErrorLogTabs();
    const refreshBtn = document.getElementById('refresh-error-logs');
    if (refreshBtn) refreshBtn.addEventListener('click', () => refreshErrorDisplay());
    const copyBtn = document.getElementById('copy-error-logs');
    if (copyBtn) copyBtn.addEventListener('click', copyErrorLogs);
    const clearBtn = document.getElementById('clear-frontend-errors');
    if (clearBtn) clearBtn.addEventListener('click', clearFrontendErrors);
    refreshErrorDisplay();
}

// ========== 6.4. 手动安全区 ==========
// 手动安全区偏移量（覆盖系统值，null 表示未覆盖）
let manualBottomOffset = null; // 单位 px
let manualTopOffset = null;

function loadManualSafeAreaSettings() {
    const savedBottom = localStorage.getItem('manualBottomOffset');
    const savedTop = localStorage.getItem('manualTopOffset');
    const parsedBottom = savedBottom !== null ? parseInt(savedBottom) : 0;
    const parsedTop = savedTop !== null ? parseInt(savedTop) : 0;
    manualBottomOffset = Number.isFinite(parsedBottom) && parsedBottom !== 0 ? parsedBottom : null;
    manualTopOffset = Number.isFinite(parsedTop) && parsedTop !== 0 ? parsedTop : null;
    // 更新 UI 控件（如果当前在调试页面且控件存在）
    const bottomSlider = document.getElementById('manual-bottom-offset');
    const bottomValue = document.getElementById('manual-bottom-offset-value');
    if (bottomSlider) {
        bottomSlider.value = manualBottomOffset !== null ? manualBottomOffset : 0;
        if (bottomValue) bottomValue.innerText = bottomSlider.value;
    }
    const topSlider = document.getElementById('manual-top-offset');
    const topValue = document.getElementById('manual-top-offset-value');
    if (topSlider) {
        topSlider.value = manualTopOffset !== null ? manualTopOffset : 0;
        if (topValue) topValue.innerText = topSlider.value;
    }
}

function saveManualBottomOffset(val) {
    manualBottomOffset = val;
    if (val === null) localStorage.removeItem('manualBottomOffset');
    else localStorage.setItem('manualBottomOffset', val);
    updateSafeArea();
}

function saveManualTopOffset(val) {
    manualTopOffset = val;
    if (val === null) localStorage.removeItem('manualTopOffset');
    else localStorage.setItem('manualTopOffset', val);
    updateSafeArea();
}

function resetManualOffsets() {
    manualBottomOffset = null;
    manualTopOffset = null;
    localStorage.removeItem('manualBottomOffset');
    localStorage.removeItem('manualTopOffset');
    // 重置 UI 滑块
    const bottomSlider = document.getElementById('manual-bottom-offset');
    if (bottomSlider) bottomSlider.value = 0;
    const topSlider = document.getElementById('manual-top-offset');
    if (topSlider) topSlider.value = 0;
    updateSafeArea();
}

function initManualSafeAreaControls() {
    const bottomSlider = document.getElementById('manual-bottom-offset');
    const bottomValue = document.getElementById('manual-bottom-offset-value');
    const topSlider = document.getElementById('manual-top-offset');
    const topValue = document.getElementById('manual-top-offset-value');
    const resetBottomBtn = document.getElementById('reset-bottom-offset');
    const resetTopBtn = document.getElementById('reset-top-offset');
    const resetAllBtn = document.getElementById('reset-all-offsets');

    if (bottomSlider) {
        bottomSlider.addEventListener('input', (e) => {
            const val = parseInt(e.target.value);
            if (bottomValue) bottomValue.innerText = val;
            saveManualBottomOffset(val);
        });
    }
    if (topSlider) {
        topSlider.addEventListener('input', (e) => {
            const val = parseInt(e.target.value);
            if (topValue) topValue.innerText = val;
            saveManualTopOffset(val);
        });
    }
    if (resetBottomBtn) {
        resetBottomBtn.addEventListener('click', () => {
            manualBottomOffset = null;
            localStorage.removeItem('manualBottomOffset');
            if (bottomSlider) bottomSlider.value = 0;
            if (bottomValue) bottomValue.innerText = 0;
            updateSafeArea();
        });
    }
    if (resetTopBtn) {
        resetTopBtn.addEventListener('click', () => {
            manualTopOffset = null;
            localStorage.removeItem('manualTopOffset');
            if (topSlider) topSlider.value = 0;
            if (topValue) topValue.innerText = 0;
            updateSafeArea();
        });
    }
    if (resetAllBtn) {
        resetAllBtn.addEventListener('click', () => {
            manualBottomOffset = null;
            manualTopOffset = null;
            localStorage.removeItem('manualBottomOffset');
            localStorage.removeItem('manualTopOffset');
            if (bottomSlider) bottomSlider.value = 0;
            if (bottomValue) bottomValue.innerText = 0;
            if (topSlider) topSlider.value = 0;
            if (topValue) topValue.innerText = 0;
            updateSafeArea();
        });
    }
}

// ========== 6.5. 多端互通标签页初始化 ==========
/**
 * 初始化多端互通页面内的标签页（设备发现/代理协同加速/代理消息推送）
 * 由于内容ID规则不同，单独处理
 */
function initMultiDeviceTabs() {
    const page = document.getElementById('page-settings-multi-device');
    if (!page) return;
    const tabs = page.querySelectorAll('.auto-message-tabs .auto-tab');
    if (tabs.length === 0) return;

    const contents = {
        device: document.getElementById('device-tab'),
        cooperation: document.getElementById('cooperation-tab'),
        proxy: document.getElementById('proxy-tab')
    };

    tabs.forEach(tab => {
        tab.removeEventListener('click', window._multiDeviceTabHandler);
        const handler = () => {
            const target = tab.dataset.tab;
            tabs.forEach(t => t.classList.remove('active'));
            tab.classList.add('active');
            Object.values(contents).forEach(c => c.classList.add('hidden'));
            if (contents[target]) contents[target].classList.remove('hidden');
        };
        tab.addEventListener('click', handler);
        window._multiDeviceTabHandler = handler;
    });
}

