/**
 * 加载向量库配置信息（维度、模型路径）并显示在记忆设置的“向量库配置”标签页中
 */
async function loadVectorConfig() {
    try {
        // 优先从后端获取实际配置
        const res = await fetch('/vector/config');
        if (res.ok) {
            const data = await res.json();
            document.getElementById('vector-dimension-display').textContent = data.dimension || '未知';
            document.getElementById('vector-model-path-display').textContent = data.model_path || '默认模型';
        } else {
            // 降级：显示前端默认值（可从 config.js 或 shared/config.js 读取）
            const defaultDim = typeof VECTOR_DIM !== 'undefined' ? VECTOR_DIM : 768;
            const defaultPath = typeof VECTOR_MODEL_PATH !== 'undefined' ? VECTOR_MODEL_PATH : 'BAAI/bge-small-zh-v1.5';
            document.getElementById('vector-dimension-display').textContent = defaultDim;
            document.getElementById('vector-model-path-display').textContent = defaultPath;
        }
    } catch (e) {
        console.error('加载向量配置失败', e);
        document.getElementById('vector-dimension-display').textContent = '加载失败';
        document.getElementById('vector-model-path-display').textContent = '加载失败';
    }
}

// ========== 6.7. 嵌套标签页初始化（用于自生成内容设置中的自主消息生成内部标签页） ==========
function initAutoMessageTabs(container = document) {
    if (!container) return;
    const tabsContainer = container.querySelector('.auto-message-tabs');
    if (!tabsContainer) return;
    const tabs = tabsContainer.querySelectorAll('.auto-tab');
    if (tabs.length === 0) return;

    // 构建内容映射
    const contents = {};
    tabs.forEach(tab => {
        const target = tab.dataset.tab;
        const contentId = `auto-tab-${target}`;
        const content = container.querySelector(`#${contentId}`);
        if (content) contents[target] = content;
    });

    if (Object.keys(contents).length === 0) return;

    const handleClick = (e) => {
        const tab = e.currentTarget;
        const target = tab.dataset.tab;
        if (!contents[target]) return;
        // 更新标签样式
        tabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        // 更新内容显示
        Object.values(contents).forEach(c => c.classList.add('hidden'));
        contents[target].classList.remove('hidden');
        // 刷新密度图（如果函数存在）
        if (target === 'private' && typeof drawDensityChart === 'function') drawDensityChart('private');
        else if (target === 'group' && typeof drawDensityChart === 'function') drawDensityChart('group');
    };

    tabs.forEach(tab => {
        tab.removeEventListener('click', handleClick);
        tab.addEventListener('click', handleClick);
    });

    // 设置默认激活（优先使用已有 active 类）
    let activeTab = tabsContainer.querySelector('.auto-tab.active');
    if (!activeTab && tabs.length) activeTab = tabs[0];
    if (activeTab) {
        const target = activeTab.dataset.tab;
        tabs.forEach(t => t.classList.remove('active'));
        activeTab.classList.add('active');
        Object.values(contents).forEach(c => c.classList.add('hidden'));
        if (contents[target]) contents[target].classList.remove('hidden');
    }
}

