// 渲染鸣谢列表
function renderThanksList() {
    const container = document.getElementById('thanks-list');
    if (!container) return;
    if (!thanksList || thanksList.length === 0) {
        container.innerHTML = '<div class="about-card-item"><div class="about-card-left"><div class="about-card-title">暂无鸣谢记录</div></div></div>';
        return;
    }
    container.innerHTML = thanksList.map(item => {
        const avatarUrls = item.avatars || (item.avatar ? [item.avatar] : []);
        const avatarsHtml = avatarUrls.map(url =>
            `<img src="${url}" class="about-card-avatar" onerror="this.src='/static/avatars/default.webp'">`
        ).join('');
        return `
            <div class="about-card-item">
                <div class="about-card-left">
                    <div class="about-card-avatars">${avatarsHtml}</div>
                    <div class="about-card-info">
                        <div class="about-card-title">${escapeHtml(item.title)}</div>
                        <div class="about-card-subtitle">${escapeHtml(item.subtitle)}</div>
                    </div>
                </div>
            </div>
        `;
    }).join('');
}

// 渲染赞助者列表
function renderSponsorsList() {
    const container = document.getElementById('sponsors-list');
    if (!container) return;
    if (!sponsorsList || sponsorsList.length === 0) {
        container.innerHTML = ''; // 无赞助者时不显示任何内容
        return;
    }

    // 分离详细和简略条目（示例：假设前3个为详细，其余简略，或根据 detailed 字段）
    const detailed = [];
    const compact = [];
    sponsorsList.forEach((item, index) => {
        // 若数据中有 detailed 字段则使用，否则默认前3个详细
        if (item.detailed !== undefined ? item.detailed : index < 10) {
            detailed.push(item);
        } else {
            compact.push(item);
        }
    });

    let html = '';

    // 渲染详细条目
    if (detailed.length) {
        html += `<div class="sponsor-detailed">`;
        detailed.forEach(item => {
            const avatarUrls = item.avatars || (item.avatar ? [item.avatar] : []);
            const avatarsHtml = avatarUrls.map(url =>
                `<img src="${url}" class="about-card-avatar" onerror="this.src='/static/avatars/default.webp'">`
            ).join('');
            html += `
                <div class="about-card-item">
                    <div class="about-card-left">
                        <div class="about-card-avatars">${avatarsHtml}</div>
                        <div class="about-card-info">
                            <div class="about-card-title">${escapeHtml(item.title)}</div>
                            <div class="about-card-subtitle">${escapeHtml(item.subtitle)}</div>
                        </div>
                    </div>
                </div>
            `;
        });
        html += `</div>`;
    }

    // 渲染简略条目
    if (compact.length) {
        html += `<div class="sponsor-compact">`;
        compact.forEach(item => {
            html += `
                <div class="compact-item" style="padding: 2px 16px; font-size: 13px;">
                    <span class="title">${escapeHtml(item.title)}</span>
                    <span class="subtitle" style="font-size: 10px; color: var(--text-secondary); margin-left: 12px;">${escapeHtml(item.subtitle)}</span>
                </div>
            `;
        });
        html += `</div>`;
    }

    container.innerHTML = html;
}

// 初始化关于页
function initAboutPage() {
    renderThanksList();
    renderSponsorsList();
    updateAboutLogo();

    // 监听主题变化
    window.addEventListener('themeChanged', updateAboutLogo);
    const observer = new MutationObserver(() => updateAboutLogo());
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });

    // 绑定按钮事件
    const sponsorBtn = document.getElementById('sponsor-author-btn');
    if (sponsorBtn) {
        sponsorBtn.onclick = () => {
            openSponsorSheet();
            bindSponsorQrSave();
        };
    }
    const feedbackBtn = document.getElementById('feedback-btn');
    if (feedbackBtn) {
        feedbackBtn.onclick = () => openBottomSheet('feedbackBottomSheet');
    }
    const joinEngineeringBtn = document.getElementById('join-engineering-btn');
    if (joinEngineeringBtn) {
        joinEngineeringBtn.onclick = () => openBottomSheet('joinQQBottomSheet');
    }
}

// 更新关于页 Logo（根据主题）
function updateAboutLogo() {
    const logoImg = document.getElementById('about-logo-img');
    if (!logoImg) return;
    const isDark = document.documentElement.classList.contains('dark-mode');
    logoImg.src = isDark ? '/static/images/Logo_ZOOT!.png' : '/static/images/Logo_ZOOT!_dark.png';
}

