// ========== 7.3. 状态映射 ==========
/**
 * 获取干员显示状态（优先级：固定状态映射 > 情绪值降级）
 * @param {Object} detail 干员详情对象，包含 status, mood, mood_value
 * @returns {Object} { icon, text } 其中 text 为情绪文本（如“开心”）
 */
function getOperatorDisplayStatus(detail) {
    const fixedStatusMap = {
        'energetic': { icon: 'sparkle', text: '精力充沛' },
        'calm': { icon: 'success', text: '心情平和' },
        'focused': { icon: 'search', text: '专注工作' },
        'tired': { icon: 'minus', text: '有点累' },
        'excited': { icon: 'sparkle', text: '兴致勃勃' },
        'thinking': { icon: 'thinking', text: '思考中' },
        'busy': { icon: 'clipboard', text: '忙碌中' },
        'leisure': { icon: 'diary', text: '悠闲' },
        'standby': { icon: 'sync', text: '待命中' },
        'sleeping': { icon: 'mute', text: '休息中' }
    };

    // 优先使用固定状态映射
    if (detail.status && fixedStatusMap[detail.status]) {
        return fixedStatusMap[detail.status];
    }

    // 降级：根据情绪值映射
    const moodValue = detail.mood_value ?? 0.5;
    let moodIcon;
    let moodText = detail.mood || '未知';
    if (moodValue <= 0.2) moodIcon = 'error';
    else if (moodValue <= 0.4) moodIcon = 'warning';
    else if (moodValue <= 0.6) moodIcon = 'minus';
    else if (moodValue <= 0.8) moodIcon = 'info';
    else moodIcon = 'success';

    return { icon: moodIcon, text: moodText };
}

/**
 * 获取干员完整状态栏 HTML（情绪 + 工作状态 + 位置）
 * @param {Object} detail 干员详情对象
 * @returns {string} HTML 字符串
 */
function getOperatorStatusHtml(detail) {
    const display = getOperatorDisplayStatus(detail);
    let parts = [`${ZootIcons.html(display.icon)} ${display.text}`];

    // 添加 sync_info（工作状态）
    const syncText = detail.sync_info?.text;
    if (syncText) parts.push(`· ${syncText}`);

    // 添加当前位置
    const location = detail.current_location;
    if (location && location !== '') parts.push(`· ${location}`);

    return parts.join(' ');
}

