// ========== 9. 消息显示与聊天详情页 ==========
// 判断用户是否在聊天消息区域底部附近（距离底部小于100px）
function isUserAtBottom() {
    return chatViewportController.isNearTail();
}

const chatViewportController = {
    followTail: true,
    layoutObserver: null,
    layoutTimer: 0,
    generation: 0,

    isNearTail(threshold = 50) {
        if (!chatMessages) return true;
        return chatMessages.scrollHeight
            - chatMessages.scrollTop
            - chatMessages.clientHeight < threshold;
    },

    capture() {
        if (!chatMessages) return { followTail: true, anchorId: null, offset: 0 };
        const followTail = this.isNearTail();
        this.followTail = followTail;
        if (followTail) return { followTail: true, anchorId: null, offset: 0 };

        const viewportTop = chatMessages.getBoundingClientRect().top;
        const rows = Array.from(chatMessages.querySelectorAll('.chat-message-row[data-msg-id]'));
        const anchor = rows.find(row => row.getBoundingClientRect().bottom > viewportTop + 1);
        return {
            followTail: false,
            anchorId: anchor?.dataset.msgId || null,
            offset: anchor ? anchor.getBoundingClientRect().top - viewportTop : 0
        };
    },

    restore(snapshot) {
        if (!chatMessages || !snapshot) return;
        if (snapshot.followTail) {
            this.pinTail();
            return;
        }
        if (!snapshot.anchorId) return;
        const selector = `.chat-message-row[data-msg-id="${CSS.escape(String(snapshot.anchorId))}"]`;
        const anchor = chatMessages.querySelector(selector);
        if (!anchor) return;
        const viewportTop = chatMessages.getBoundingClientRect().top;
        chatMessages.scrollTop += anchor.getBoundingClientRect().top
            - viewportTop
            - snapshot.offset;
    },

    pinTail() {
        if (!chatMessages) return;
        chatMessages.scrollTop = chatMessages.scrollHeight;
        this.followTail = true;
        hideNewMessageIndicator();
    },

    stabilizeTail(duration = 800) {
        if (!chatMessages || !this.followTail) return;
        const generation = ++this.generation;
        if (this.layoutObserver) this.layoutObserver.disconnect();
        if (this.layoutTimer) clearTimeout(this.layoutTimer);

        const keepPinned = () => {
            if (generation !== this.generation || !this.followTail) return;
            requestAnimationFrame(() => this.pinTail());
        };
        if (typeof ResizeObserver === 'function') {
            this.layoutObserver = new ResizeObserver(keepPinned);
            this.layoutObserver.observe(chatMessages);
            Array.from(chatMessages.children).slice(-3).forEach(child => {
                this.layoutObserver.observe(child);
            });
        }
        keepPinned();
        this.layoutTimer = setTimeout(() => {
            if (generation !== this.generation) return;
            this.layoutObserver?.disconnect();
            this.layoutObserver = null;
            this.layoutTimer = 0;
            this.pinTail();
        }, duration);
    },

    afterRender(snapshot, incomingMessageId = null) {
        requestAnimationFrame(() => {
            this.restore(snapshot);
            if (incomingMessageId && chatMessages) {
                const selector = `.chat-message-row[data-msg-id="${CSS.escape(String(incomingMessageId))}"]`;
                const row = chatMessages.querySelector(selector);
                if (row) {
                    row.classList.add('chat-message-enter');
                    row.addEventListener(
                        'animationend',
                        () => row.classList.remove('chat-message-enter'),
                        { once: true }
                    );
                }
            }
            if (snapshot?.followTail) {
                this.stabilizeTail();
            } else {
                showNewMessageIndicator();
            }
        });
    }
};

// ---------- 状态更新防抖 ----------
let statusUpdateDebounceTimer = null;

function debouncedStatusUpdate(operatorId) {
    if (!operatorId) return;
    if (!currentOperatorId || currentOperatorId !== operatorId) return;
    if (getCurrentPageId() !== 'chat-detail') return;

    if (statusUpdateDebounceTimer) {
        clearTimeout(statusUpdateDebounceTimer);
    }
    statusUpdateDebounceTimer = setTimeout(() => {
        fetchAndUpdateOperatorStatus(operatorId);
        statusUpdateDebounceTimer = null;
    }, 300);
}

// ---------- addMessageToChat ----------
const chatMessageIdentityIndexes = new Map();

function getChatMessageIdentityIndex(chatKey, list) {
    const cached = chatMessageIdentityIndexes.get(chatKey);
    if (cached && cached.list === list && cached.length === list.length) return cached.index;
    const index = new Map();
    list.forEach(message => {
        messageIdentityAliases(message).forEach(alias => index.set(alias, message));
    });
    chatMessageIdentityIndexes.set(chatKey, {list, length: list.length, index});
    return index;
}

function indexChatMessageIdentity(chatKey, list, message) {
    const index = getChatMessageIdentityIndex(chatKey, list);
    messageIdentityAliases(message).forEach(alias => index.set(alias, message));
    const cached = chatMessageIdentityIndexes.get(chatKey);
    if (cached) cached.length = list.length;
}

function addMessageToChat(sender, content, cls, timestamp, chatType, chatId, isScenario, dbId, isAuto, msgType, emojiCode, emojiOperator, chatKeyParam, senderPersonaId = 'doctor', attachments = [], messageUid = null, clientRequestId = null, branchId = null, auxiliarySections = []) {
    const chatKey = chatKeyParam || `${chatType}:${chatId}`;
    if (sender !== 'doctor' && msgType !== 'system') {
        setTimeout(() => window.hydrateVisibleRedPackets?.(), 500 + Math.floor(Math.random() * 1001));
    }
    if (branchId && typeof window.zootTimelineAcceptMessage === 'function'
        && !window.zootTimelineAcceptMessage({branch_id: branchId}, chatKey)) {
        return null;
    }

    // 生成唯一标识：优先使用 dbId，否则基于内容生成
    let uniqueId = messageUid ? `uid_${messageUid}` : (dbId ? `db_${dbId}` : null);
    if (!uniqueId) {
        const contentHash = content.length > 80 ? content.substring(0, 80) : content;
        uniqueId = `temp_${timestamp}_${sender}_${contentHash}`;
    }

    // 处理发送者英文名和显示名称
    let senderEng = sender;
    let displaySender = sender;
    if (sender === 'doctor') {
        senderEng = 'doctor';
        displaySender = '博士';
    } else {
        const op = operatorMap.get(sender);
        if (op) {
            senderEng = op.id;
            displaySender = op.codename;
        } else {
            const found = Array.from(operatorMap.values()).find(op => op.codename === sender);
            if (found) {
                senderEng = found.id;
                displaySender = found.codename;
            } else {
                senderEng = sender;
                displaySender = sender;
            }
        }
    }

    // 修复表情包所有者
    let finalEmojiOperator = emojiOperator;
    if (msgType === 'emoji' && !finalEmojiOperator) {
        const match = content.match(/^\[emoji:([\w]+)\/([\u4e00-\u9fa5a-zA-Z0-9]+)\]$/);
        if (match) finalEmojiOperator = match[1];
    }
    if (finalEmojiOperator && !isNaN(finalEmojiOperator)) {
        const op = operatorMap.get(String(finalEmojiOperator));
        if (op) finalEmojiOperator = op.id;
    } else if (finalEmojiOperator && !operatorMap.has(finalEmojiOperator)) {
        const found = Array.from(operatorMap.values()).find(op => op.codename === finalEmojiOperator);
        if (found) finalEmojiOperator = found.id;
    }

    // 稳定身份优先去重；仅当任一侧缺少稳定身份时才使用内容时间兜底。
    const existingMsgs = messages[chatKey] || [];
    const normalizedDbId = dbId === null || dbId === undefined ? null : String(dbId);
    const normalizedUid = messageUid ? String(messageUid) : null;
    const normalizedRequestId = clientRequestId ? String(clientRequestId) : null;
    const identityIndex = getChatMessageIdentityIndex(chatKey, existingMsgs);
    const stableAliases = [
        normalizedUid ? `uid:${normalizedUid}` : '',
        normalizedDbId ? `db:${normalizedDbId}` : '',
        normalizedRequestId ? `request:${normalizedRequestId}` : ''
    ].filter(Boolean);
    let duplicate = stableAliases.map(alias => identityIndex.get(alias)).find(Boolean) || null;
    if (!duplicate && stableAliases.length === 0) {
        for (let index = existingMsgs.length - 1; index >= 0; index -= 1) {
            const message = existingMsgs[index];
            if (messageIdentityAliases(message).length > 0) continue;
            if (message.senderEng === senderEng && message.content === content &&
                (message.persona_id || 'doctor') === (senderPersonaId || 'doctor') &&
                Math.abs(Number(message.timestamp) - Number(timestamp)) < 3) {
                duplicate = message;
                break;
            }
        }
    }
    if (duplicate) {
        if (normalizedDbId && !duplicate.dbId) duplicate.dbId = normalizedDbId;
        if (normalizedUid && !duplicate.message_uid) duplicate.message_uid = normalizedUid;
        if (normalizedRequestId && !duplicate.client_request_id) duplicate.client_request_id = normalizedRequestId;
        if (normalizeMessageAuxiliarySections(auxiliarySections).length) {
            duplicate.auxiliary_sections = normalizeMessageAuxiliarySections(auxiliarySections);
        }
        if (normalizedDbId) duplicate.delivery_state = 'stored';
        duplicate.uniqueId = duplicate.message_uid ? `uid_${duplicate.message_uid}` :
            (duplicate.dbId ? `db_${duplicate.dbId}` : duplicate.uniqueId);
        const duplicateRow = document.querySelector(
            `#chat-messages .chat-message-row[data-msg-id="${CSS.escape(String(duplicate.id))}"]`
        );
        if (duplicateRow && normalizedDbId) {
            duplicateRow.dataset.deliveryState = 'stored';
            duplicateRow.classList.remove('message-delivery-queued', 'message-delivery-sending');
            duplicateRow.classList.add('message-delivery-stored');
        }
        if (normalizedDbId && duplicate.message_uid) {
            confirmPriestessMentionMessage(duplicate, chatKey, chatType, chatId);
        }
        indexChatMessageIdentity(chatKey, existingMsgs, duplicate);
        console.log(`[去重] 合并已存在消息 (${duplicate.uniqueId})`);
        return duplicate;
    }

    const msgId = Date.now() + '-' + Math.random().toString(36).substr(2, 8);
    const newMsg = {
        id: msgId,
        dbId: normalizedDbId,
        uniqueId: uniqueId,
        sender: displaySender,
        senderEng: senderEng,
        content: content,
        cls: cls,
        timestamp: timestamp,
        isScenario: isScenario || false,
        isAuto: isAuto || false,
        msgType: msgType || 'text',
        unitType: msgType || 'text',
        emojiCode: emojiCode,
        emojiOperator: finalEmojiOperator,
        persona_id: senderPersonaId || 'doctor',
        attachments: Array.isArray(attachments) ? attachments : [],
        auxiliary_sections: normalizeMessageAuxiliarySections(auxiliarySections)
    };
    newMsg.message_uid = messageUid || null;
    newMsg.client_request_id = normalizedRequestId;
    newMsg.branch_id = branchId || null;
    newMsg.delivery_state = normalizedDbId ? 'stored' : 'queued';

    if (!messages[chatKey]) messages[chatKey] = [];
    messages[chatKey].push(newMsg);
    indexChatMessageIdentity(chatKey, messages[chatKey], newMsg);
    if (cls !== 'system') {
        reactivateHiddenChat(chatId, chatType, {
            lastTime: timestamp,
            messageCount: messages[chatKey].length
        });
    }

    // 判断是否在当前活动聊天页
    const isActiveChat = isChatKeyActive(chatKey);

    if (isActiveChat && chatMessages) {
        // ---- 状态更新（私聊且发送者为干员） ----
        if (cls === 'operator' && chatType === 'private' && senderEng !== 'doctor') {
            debouncedStatusUpdate(senderEng);
        }

        const isLocalUserSend = cls === 'user' && senderEng === 'doctor';
        const wasNearTail = chatViewportController.isNearTail();
        const wasFollowingTail = chatWindowFollowsTail(chatKey);
        const requiresTailRerender = isLocalUserSend && (!wasNearTail || !wasFollowingTail);
        if (isLocalUserSend) {
            forceChatWindowTail(chatKey);
            chatViewportController.followTail = true;
        }
        const viewportSnapshot = isLocalUserSend
            ? {followTail: true, anchorId: null, offset: 0}
            : chatViewportController.capture();
        const shouldAppend = isLocalUserSend || (
            chatViewportController.isNearTail() && chatWindowFollowsTail(chatKey)
        );
        if (shouldAppend) {
            requestAnimationFrame(() => {
                if (requiresTailRerender) {
                    renderCurrentChat();
                } else {
                    const appended = renderMessageIncrementally(newMsg, chatType, chatId);
                    if (!appended) renderCurrentChat();
                }
                syncChatWindowTail(chatKey);
                chatViewportController.afterRender(viewportSnapshot, newMsg.id);
            });
        } else {
            showNewMessageIndicator();
        }
        if (cls === 'operator') clearUnread(chatKey);
    } else if (cls === 'operator') {
        increaseUnread(chatKey);
    }

    if (normalizedUid && (normalizedDbId || cls === 'operator')) {
        confirmPriestessMentionMessage(newMsg, chatKey, chatType, chatId);
    }

    // 更新聊天列表缩略
    if (cls !== 'system') {
        let chat = chats.find(c => c.type === chatType && c.id === chatId);
        if (!chat) {
            let name = '';
            if (chatType === 'private') {
                const op = operatorMap.get(chatId);
                name = op ? op.codename : chatId;
            } else {
                const group = groups[chatId];
                name = group ? group.name : chatId;
            }
            chat = {
                id: chatId,
                type: chatType,
                name: name,
                lastMsg: '',
                lastTime: 0,
                lastSender: '',
                isPinned: false
            };
            chats.push(chat);
        }
        const lastMsgContent = formatMessageThumbnail(content, msgType);
        chat.lastMsg = lastMsgContent;
        chat.lastTime = timestamp;
        chat.lastSender = displaySender;
        if (!isAuto) {
            chat.lastNonAssistantMsg = lastMsgContent;
            chat.lastNonAssistantSender = displaySender;
        }
        scheduleChatListRender();
    }

    window.dispatchEvent(new CustomEvent('messageAdded', {
        detail: { msg: newMsg, chatKey: chatKey, cls: cls }
    }));
    return newMsg;
}

function updateTrustDisplay(operatorId, newTrust) {
    const trustSpan = document.getElementById(`trust-value-${operatorId}`);
    const trustFill = document.getElementById(`trust-fill-${operatorId}`);
    if (trustSpan) trustSpan.textContent = newTrust;
    if (trustFill) {
        const percent = Math.min(newTrust / 2, 100);
        trustFill.style.width = percent + '%';
    }
}

// ========== 9.1. 渲染消息 ==========
let lastRenderedMsgCount = {};
const chatMessageWindows = new Map();

function chatWindowMessageId(message, index = 0) {
    return String(
        message?.message_uid
        || message?.uniqueId
        || message?.dbId
        || message?.id
        || `${message?.timestamp || 0}:${message?.senderEng || ''}:${index}`
    );
}

function selectChatMessageWindow(items, chatKey, limit) {
    const previous = chatMessageWindows.get(chatKey);
    let start = Math.max(0, items.length - limit);
    if (previous?.forceTail) {
        start = Math.max(0, items.length - limit);
    } else if (previous?.firstUid) {
        const anchorIndex = items.findIndex((item, index) => (
            chatWindowMessageId(item, index) === previous.firstUid
        ));
        if (anchorIndex >= 0) {
            if (previous.intent === 'older') {
                start = Math.max(0, anchorIndex - Math.min(32, Math.floor(limit / 2)));
            } else {
                start = Math.min(anchorIndex, Math.max(0, items.length - limit));
            }
        }
    }
    const end = Math.min(items.length, start + limit);
    const windowItems = items.slice(start, end);
    chatMessageWindows.set(chatKey, {
        start,
        end,
        total: items.length,
        firstUid: windowItems.length ? chatWindowMessageId(windowItems[0], start) : '',
        lastUid: windowItems.length ? chatWindowMessageId(windowItems[windowItems.length - 1], end - 1) : '',
        intent: '',
        forceTail: false
    });
    return windowItems;
}

function shiftChatWindowOlder(chatKey) {
    const state = chatMessageWindows.get(chatKey);
    if (!state || state.start <= 0) return false;
    state.intent = 'older';
    chatMessageWindows.set(chatKey, state);
    const anchor = chatViewportController.capture();
    renderCurrentChat();
    chatViewportController.restore(anchor);
    return true;
}

function forceChatWindowTail(chatKey) {
    const state = chatMessageWindows.get(chatKey) || {};
    state.forceTail = true;
    chatMessageWindows.set(chatKey, state);
}

function chatWindowFollowsTail(chatKey) {
    const state = chatMessageWindows.get(chatKey);
    return !state || state.end >= state.total;
}

function syncChatWindowTail(chatKey) {
    const items = messages[chatKey] || [];
    const limit = window.ZootRuntime?.getResourceBudget?.().maxLiveMessages || 100;
    const start = Math.max(0, items.length - limit);
    chatMessageWindows.set(chatKey, {
        start,
        end: items.length,
        total: items.length,
        firstUid: items.length ? chatWindowMessageId(items[start], start) : '',
        lastUid: items.length ? chatWindowMessageId(items[items.length - 1], items.length - 1) : '',
        intent: '',
        forceTail: false
    });
}

function updateChatWindowTotal(chatKey) {
    const state = chatMessageWindows.get(chatKey);
    if (!state) return;
    state.total = (messages[chatKey] || []).length;
    chatMessageWindows.set(chatKey, state);
}

function renderCurrentChat() {
    if (!chatMessages) return;
    const chatType = currentGroupId ? 'group' : 'private';
    const chatId = currentGroupId || currentOperatorId;
    const currentKey = currentGroupId ? `group:${currentGroupId}` : `private:${currentOperatorId}`;
    const msgs = messages[currentKey] || [];
    // 检测重复消息
    const seen = new Set();
    const duplicates = [];
    for (const msg of msgs) {
        const id = msg.uniqueId || msg.dbId || `${msg.timestamp}_${msg.senderEng}_${msg.content.substring(0,50)}`;
        if (seen.has(id)) duplicates.push(id);
        else seen.add(id);
    }
    if (duplicates.length) console.warn(`[重复消息] ${currentKey} 发现 ${duplicates.length} 条重复:`, duplicates);
    const renderLimit = window.ZootRuntime?.getResourceBudget?.().maxLiveMessages || 100;
    const renderWindow = selectChatMessageWindow(msgs, currentKey, renderLimit);
    fullRenderChat(renderWindow, chatType, chatId);
    chatMessages.dataset.virtualizedBefore = String(Math.max(0, msgs.length - renderWindow.length));
    lastRenderedMsgCount[currentKey] = msgs.length;
    if (isMultiSelectMode && currentKey === multiSelectChatKey) applyMultiSelectUI();
}

// 全量渲染（原 renderCurrentChat 逻辑）
// 全量渲染（原 renderCurrentChat 逻辑）
function renderGroupMemberTitle(chatType, chatId, senderId) {
    if (chatType !== 'group' || !senderId || senderId === 'doctor') return '';
    const title = groups[chatId]?.member_titles?.[String(senderId)];
    return title ? `<span class="group-member-title-badge">${escapeHtml(title)}</span>` : '';
}

function normalizeMessageAuxiliarySections(input) {
    if (!Array.isArray(input)) return [];
    return input.reduce((sections, raw, index) => {
        if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return sections;
        const content = String(raw.content || '');
        if (!content.trim()) return sections;
        sections.push({
            section_id: String(raw.section_id || `auxiliary-${index}`),
            type: String(raw.type || 'auxiliary'),
            label: String(raw.label || '附加说明'),
            content,
            presentation: raw.presentation === 'visible' ? 'visible' : 'collapsed',
            plugin_id: String(raw.plugin_id || ''),
            formatter_id: String(raw.formatter_id || ''),
            formatter_revision: Number(raw.formatter_revision || 0),
            source_hash: String(raw.source_hash || '')
        });
        return sections;
    }, []);
}

function renderMessageAuxiliarySections(message) {
    const sections = normalizeMessageAuxiliarySections(message?.auxiliary_sections);
    if (!sections.length) return '';
    const icon = window.ZootIcons?.html?.('expand') || '<span data-zoot-icon="expand" aria-hidden="true"></span>';
    return `<div class="message-auxiliary-sections">${sections.map(section => `
        <details class="message-auxiliary-section" data-auxiliary-section-id="${escapeHtml(section.section_id)}"${section.presentation === 'visible' ? ' open' : ''}>
            <summary>${icon}<span>${escapeHtml(section.label)}</span></summary>
            <div>${escapeHtml(section.content)}</div>
        </details>`).join('')}</div>`;
}

async function ensureGroupConfig(groupId) {
    try {
        const response = await fetch(`/group/config/${encodeURIComponent(groupId)}`);
        if (!response.ok) return;
        const config = await response.json();
        (config.ai_participants || []).forEach(item => registerChatTargetIdentity({
            ...item,
            id: item.actor_id,
            target_id: item.actor_id,
            name: item.display_name
        }));
        groups[groupId] = { ...(groups[groupId] || {}), ...config };
    } catch (error) {
        console.warn('群配置加载失败', error);
    }
}

function fullRenderChat(msgs, chatType, chatId) {
    let lastTimestamp = null;
    const htmlParts = [];

    // ===== 1. 前端二次过滤（与后端逻辑保持一致） =====
    const currentPersonaId = window.currentPersonaId || 'doctor';
    const allowSharing = window.allowContextSharing || false;

    let filteredMsgs = msgs;
    // 仅当关闭互通且非博士人格时进行过滤
    if (!allowSharing && currentPersonaId !== 'doctor') {
        filteredMsgs = msgs.filter(msg => {
            const msgPersonaId = msg.persona_id || msg.senderPersonaId || 'doctor';
            const cls = msg.cls || '';
            // 干员消息：只保留与当前人格相关的（即回复给当前人格的消息）
            if (cls === 'operator') {
                return msgPersonaId === currentPersonaId;
            }
            // 用户消息：只保留当前人格发送的
            if (cls === 'user') {
                return msgPersonaId === currentPersonaId;
            }
            // 系统消息：保留
            if (cls === 'system') {
                return true;
            }
            // 其他未知类型：保留
            return true;
        });
    }
    // 如果 allowSharing 为 true 或当前人格为博士，保留全部消息

    // ===== 2. 渲染过滤后的消息 =====
    function formatMessageText(text) {
        return escapeHtml(text).replace(/\n/g, '<br>');
    }

    filteredMsgs.forEach(msg => {
        const currentTimestamp = msg.timestamp;
        if (lastTimestamp !== null && (currentTimestamp - lastTimestamp) > 7200) {
            htmlParts.push(`<div class="chat-time-divider">${formatDateDivider(currentTimestamp)}</div>`);
        }
        lastTimestamp = currentTimestamp;

        // 获取消息发送者人格 ID
        const senderPersonaId = msg.persona_id || msg.senderPersonaId || 'doctor';
        // 是否为用户侧消息只由记录类型决定；人格 ID 仅决定历史头像和姓名。
        // 开启人格互通后，其他人格的旧消息仍然属于用户侧，不能伪装成干员消息。
        const isUser = msg.cls === 'user';

        // 获取发送者英文名
        let senderEng = msg.senderEng;
        if (!senderEng && msg.sender) {
            const found = Array.from(operatorMap.values()).find(op => op.codename === msg.sender);
            senderEng = found ? found.id : (msg.sender === '博士' ? 'doctor' : msg.sender);
        }
        if (!senderEng) senderEng = isUser ? 'doctor' : 'unknown';
        const specialSender = !isUser ? getChatTargetIdentity(senderEng) : null;

        // 获取显示名称
        let senderName;
        if (msg.cls === 'operator') {
            // 干员消息携带的 persona_id 表示回复对象，不能用作发送者姓名。
            const op = operatorMap.get(senderEng);
            senderName = specialSender?.display_name || specialSender?.name || (op ? op.codename : senderEng);
        } else if (senderPersonaId !== 'doctor') {
            senderName = window.personaDisplayNameMap?.[senderPersonaId] || senderPersonaId;
        } else {
            senderName = '博士';
        }
        // 保底
        if (!senderName) {
            senderName = senderEng || '未知';
        }

        const timestamp = formatTimestamp(msg.timestamp);
        const content = msg.content;
        const isEventNarration = msg.unitType === 'event_narration' || msg.unit_type === 'event_narration';
        const isScenario = msg.isScenario || isEventNarration || false;

        // ===== 构建消息 HTML（与原有逻辑相同） =====
        if (isScenario) {
            let isDoctorScenario = (senderEng === 'doctor');
            let labelHtml = '';
            let footerLabelHtml = '';
            let wrapperClass = '';
            if (isEventNarration) {
                footerLabelHtml = '<div class="event-narration-label">EVENT NARRATION</div>';
                wrapperClass = 'event-narration';
            } else if (isDoctorScenario) {
                labelHtml = '<div class="doctor-label">DOC</div>';
                wrapperClass = 'doctor-scenario';
            } else {
                labelHtml = `<div class="operator-label">${escapeHtml(senderEng)}</div>`;
                wrapperClass = 'operator-scenario';
            }
            htmlParts.push(`
                <div class="chat-message-row scenario-mode" data-msg-id="${msg.id}"
                    ontouchstart="startLongPress(event, '${msg.id}', '${chatType}', '${chatId}')"
                    ontouchend="cancelLongPress()"
                    ontouchcancel="cancelLongPress()">
                    <div class="scenario-message-wrapper ${wrapperClass}">
                        ${labelHtml}
                        <div class="message-bubble scenario-bubble">
                             ${window.chatMedia?.renderAttachments(msg.attachments) || ''}
                             <span class="message-text-content"><span class="message-text-original">${formatMessageText(content)}</span></span>
                         </div>
                        ${renderMessageAuxiliarySections(msg)}
                        ${footerLabelHtml}
                        <div class="scenario-timestamp">${timestamp}</div>
                    </div>
                </div>
            `);
        } else if (msg.msgType === 'emoji' && msg.emojiCode) {
            // 表情包消息
            let emojiOwner = msg.emojiOperator;
            if (!emojiOwner) {
                const match = msg.content.match(/^\[emoji:([\w]+)\/([\u4e00-\u9fa5a-zA-Z0-9]+)\]$/);
                if (match) emojiOwner = match[1];
            }
            if (emojiOwner) {
                if (!isNaN(emojiOwner)) {
                    const op = operatorMap.get(String(emojiOwner));
                    if (op) emojiOwner = op.id;
                } else if (!operatorMap.has(emojiOwner)) {
                    const found = Array.from(operatorMap.values()).find(op => op.codename === emojiOwner);
                    if (found) emojiOwner = found.id;
                }
            }
            if (!emojiOwner) emojiOwner = 'default';
            const encodedCode = encodeURIComponent(msg.emojiCode);
            const emojiUrl = `/static/emoji/${encodeURIComponent(emojiOwner)}/${encodedCode}.gif`;

            const recordPersonaId = isUser ? (msg.persona_id || msg.senderPersonaId || 'doctor') : '';
            let avatarUrl;
            if (isUser) {
                avatarUrl = getPersonaAvatarUrl(recordPersonaId);
            } else {
                avatarUrl = getOperatorAvatarUrl(senderEng);
            }
            const avatarOnclick = isUser ? 'showPage(\'profile\')' : `showOperatorDetail('${senderEng}')`;
            const rowClass = isUser ? 'user' : 'operator';
            htmlParts.push(`
                <div class="chat-message-row ${rowClass}" data-msg-id="${msg.id}"
                    ontouchstart="startLongPress(event, '${msg.id}', '${chatType}', '${chatId}')"
                    ontouchend="cancelLongPress()"
                    ontouchcancel="cancelLongPress()">
                    <div class="message-avatar" onclick="event.stopPropagation(); ${avatarOnclick}">
                        <img src="${avatarUrl}" alt="${senderName}" ${isUser ? `data-persona-id="${escapeHtml(recordPersonaId)}"` : ''} onerror="handlePersonaAvatarError(this)">
                    </div>
                    <div class="message-content">
                        <div class="message-name">
                            <span class="timestamp">[${timestamp}]</span> ${senderName}${renderGroupMemberTitle(chatType, chatId, senderEng)}
                        </div>
                        <div class="message-bubble emoji-bubble">
                            <img src="${emojiUrl}" class="message-emoji" alt="${escapeHtml(msg.emojiCode)}" onerror="this.onerror=null; this.src='/static/emoji/default.gif'">
                        </div>
                    </div>
                </div>
            `);
        } else if (msg.msgType === 'dynamic_card') {
            // 动态卡片
            let cardData = null;
            try {
                cardData = JSON.parse(msg.content);
            } catch(e) { console.warn('解析动态卡片失败', e); }
            if (cardData && cardData.type === 'dynamic_card') {
                const authorName = cardData.author_name || '未知';
                const previewText = cardData.content_preview || '';
                const dynamicId = cardData.dynamic_id;
                const authorEng = cardData.author_eng || cardData.author_name;
                const authorAvatar = getDynamicsActorMeta(authorEng).avatar;
                htmlParts.push(`
                    <div class="chat-message-row user dynamic-card-message" data-dynamic-id="${dynamicId}" style="cursor: pointer;">
                        <div class="message-avatar">
                            <img src="${getPersonaAvatarUrl(msg.persona_id || 'doctor')}" class="avatar" data-persona-id="${escapeHtml(msg.persona_id || 'doctor')}" onerror="handlePersonaAvatarError(this)">
                        </div>
                        <div class="message-content">
                            <div class="message-name">${escapeHtml(window.personaDisplayNameMap?.[msg.persona_id || 'doctor'] || '博士')}</div>
                            <div class="message-bubble dynamic-card-bubble" style="background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 12px; padding: 8px 12px;">
                                <div style="display: flex; align-items: center; gap: 8px; margin-bottom: 6px;">
                                    <img src="${authorAvatar}" style="width: 24px; height: 24px; border-radius: 50%;">
                                    <span style="font-weight: bold;">${escapeHtml(authorName)}</span>
                                </div>
                                <div>${escapeHtml(previewText)}</div>
                            </div>
                            <div class="message-time">${formatTimestamp(msg.timestamp)}</div>
                        </div>
                    </div>
                `);
            } else {
                htmlParts.push(`<div class="chat-message-row system">${escapeHtml(msg.content)}</div>`);
            }
        } else if (msg.msgType === 'red_packet_card') {
            try {
                const cardData = JSON.parse(msg.content);
                htmlParts.push(window.renderRedPacketCardHTML
                    ? window.renderRedPacketCardHTML(cardData, { isUser, senderName, timestamp, msgId: msg.id })
                    : `<div class="chat-message-row ${isUser ? 'user' : 'operator'}">[红包] ${escapeHtml(cardData.note || '')}</div>`);
            } catch (e) {
                htmlParts.push(`<div class="chat-message-row system">红包卡片数据损坏</div>`);
            }
        } else if (msg.msgType === 'image_generation_card') {
            try {
                const cardData = JSON.parse(msg.content);
                const generatedAttachment = (msg.attachments || [])[0] || {};
                htmlParts.push(`
                    <div class="chat-message-row ${isUser ? 'user' : 'operator'} image-generation-message" data-msg-id="${msg.id}">
                        <div class="message-content">
                            <div class="message-name"><span class="timestamp">[${timestamp}]</span> ${escapeHtml(senderName)}</div>
                            <section class="image-proposal-card">
                                <span class="image-proposal-kicker">AI 生成图片 · ${escapeHtml(cardData.provider || '')} / ${escapeHtml(cardData.model || '')}</span>
                                ${window.chatMedia?.renderAttachments?.(msg.attachments || []) || ''}
                                <small>来源消息 ${Array.isArray(cardData.source_message_uids) ? cardData.source_message_uids.length : 0} 条 · ${escapeHtml(cardData.aspect_ratio || '1:1')} · ${escapeHtml(cardData.pov || 'first_person')} · AI 生成</small>
                                <details class="image-card-action-disclosure">
                                    <summary>${window.ZootIcons?.html?.('more') || '<span data-zoot-icon="more" aria-hidden="true"></span>'}<span>图片操作</span></summary>
                                    <div class="image-card-actions">
                                        <button type="button" onclick="viewGeneratedImage('${escapeHtml(generatedAttachment.id || cardData.attachment_id || '')}')">全屏查看</button>
                                        <button type="button" onclick="saveGeneratedImage('${escapeHtml(generatedAttachment.id || cardData.attachment_id || '')}')">保存图片</button>
                                        <button type="button" onclick="viewImagePlan('${escapeHtml(cardData.image_plan_id || '')}')">查看方案</button>
                                        <button type="button" onclick="locateImageSource('${escapeHtml((cardData.source_message_uids || [])[0] || '')}')">查看来源</button>
                                        <button type="button" onclick="replanImageCard('${escapeHtml(cardData.image_plan_id || '')}')">重新规划</button>
                                        <button type="button" onclick="regenerateImageCard('${escapeHtml(cardData.image_plan_id || '')}')">使用原方案生成</button>
                                    </div>
                                </details>
                            </section>
                            ${renderMessageAuxiliarySections(msg)}
                        </div>
                    </div>`);
            } catch (e) {
                htmlParts.push(`<div class="chat-message-row system">AI 图片卡片数据损坏</div>`);
            }
        } else if (msg.msgType === 'image_proposal_card') {
            try {
                const cardData = JSON.parse(msg.content);
                const canStart = !cardData.status || ['proposed', 'failed', 'planned'].includes(cardData.status);
                const canIgnore = !cardData.status || ['proposed', 'failed'].includes(cardData.status);
                const statusLabels = {
                    proposed: '等待确认',
                    planning: '正在规划',
                    planned: '方案待确认',
                    generating: '正在生成',
                    generated: '已生成',
                    ignored: '已忽略',
                    failed: '处理失败',
                };
                htmlParts.push(`
                    <div class="chat-message-row ${isUser ? 'user' : 'operator'} image-proposal-message" data-msg-id="${msg.id}">
                        <div class="message-content">
                            <div class="message-name"><span class="timestamp">[${timestamp}]</span> ${escapeHtml(senderName)}</div>
                            <section class="image-proposal-card">
                                <span class="image-proposal-kicker">照片提议 · 不会自动生图</span>
                                <strong>${escapeHtml(cardData.subject || '展示一张照片')}</strong>
                                <p>${escapeHtml(cardData.context || '')}</p>
                                <small>${escapeHtml(statusLabels[cardData.status] || cardData.status || '等待确认')}</small>
                                <div>
                                    <button type="button" onclick="handleImageProposal('${escapeHtml(cardData.proposal_id || '')}','generate')" ${canStart ? '' : 'disabled'}>${cardData.status === 'planned' ? '继续确认' : '生成'}</button>
                                    <button type="button" onclick="handleImageProposal('${escapeHtml(cardData.proposal_id || '')}','edit')" ${canStart ? '' : 'disabled'}>编辑方案</button>
                                    <button type="button" onclick="handleImageProposal('${escapeHtml(cardData.proposal_id || '')}','ignore')" ${canIgnore ? '' : 'disabled'}>忽略</button>
                                </div>
                            </section>
                        </div>
                    </div>`);
            } catch (e) {
                htmlParts.push(`<div class="chat-message-row system">照片提议卡片数据损坏</div>`);
            }
        } else if (msg.msgType === 'todo_card') {
            let cardData = null;
            try { cardData = JSON.parse(msg.content); } catch (e) { console.warn('解析待办卡片失败', e); }
            if (cardData && cardData.type === 'todo_card') {
                const progress = Math.max(0, Math.min(100, Number(cardData.progress || 0)));
                htmlParts.push(`
                    <div class="chat-message-row ${isUser ? 'user' : 'operator'} shared-todo-message" data-msg-id="${msg.id}">
                        <div class="message-content">
                            <div class="message-name"><span class="timestamp">[${timestamp}]</span> ${escapeHtml(senderName)}</div>
                            <button class="shared-todo-card ${cardData.completed ? 'completed' : ''}" onclick="openSharedTodoCard('${escapeHtml(String(cardData.todo_id || ''))}')">
                                <span class="shared-todo-kicker">待办事项 · ${escapeHtml(cardData.priority || 'normal')}</span>
                                <strong>${escapeHtml(cardData.title || '未命名事务')}</strong>
                                <span>${escapeHtml(cardData.description || '无描述')}</span>
                                <i><b style="width:${progress}%"></b></i>
                                <small>${cardData.completed ? '已完成' : `进度 ${progress}%`}${cardData.due_date ? ` · 截止 ${new Date(Number(cardData.due_date) * 1000).toLocaleDateString()}` : ''}</small>
                            </button>
                        </div>
                    </div>`);
            } else {
                htmlParts.push(`<div class="chat-message-row system">待办卡片数据已损坏</div>`);
            }
        } else if (msg.cls === 'system' && msg.isFailed) {
            htmlParts.push(`
                <div class="chat-message-row system">
                    <div class="message-avatar">
                        <div class="default-avatar">⚠️</div>
                    </div>
                    <div class="message-content">
                        <div class="message-name">
                            <span class="timestamp">[${timestamp}]</span> 系统
                        </div>
                        <div class="message-bubble error-bubble">
                            <span class="error-icon">⚠️</span> 发送失败: ${formatMessageText(msg.content)}
                            <button class="retry-btn" data-retry-content="${escapeHtml(msg.originalContent)}" data-chat-type="${msg.chatType}" data-chat-id="${msg.chatId}">重试</button>
                        </div>
                    </div>
                </div>
            `);
        } else {
            // 普通文本消息
            let avatarUrl;
            if (msg.cls === 'operator') {
                avatarUrl = specialSender?.avatar_url || getOperatorAvatarUrl(senderEng);
            } else {
                if (senderPersonaId !== 'doctor') {
                    avatarUrl = getPersonaAvatarUrl(senderPersonaId);
                } else {
                    avatarUrl = getPersonaAvatarUrl('doctor');
                }
            }
            const avatarOnclick = isUser
                ? 'showPage(\'profile\')'
                : specialSender?.profile_id
                    ? `window.openDoctorAgentEditor?.('${escapeHtml(specialSender.profile_id)}')`
                    : `showOperatorDetail('${senderEng}')`;
            const rowClass = isUser ? 'user' : 'operator';
            const deliveryState = ['queued', 'sending', 'stored', 'failed'].includes(msg.delivery_state)
                ? msg.delivery_state
                : 'stored';
            htmlParts.push(`
                <div class="chat-message-row ${rowClass} message-delivery-${deliveryState}"
                    data-msg-id="${msg.id}"
                    data-delivery-state="${deliveryState}"
                    ontouchstart="startLongPress(event, '${msg.id}', '${chatType}', '${chatId}')"
                    ontouchend="cancelLongPress()"
                    ontouchcancel="cancelLongPress()">
                    <div class="message-avatar" onclick="event.stopPropagation(); ${avatarOnclick}">
                        <img src="${avatarUrl}" alt="${senderName}" ${isUser ? `data-persona-id="${escapeHtml(senderPersonaId || 'doctor')}"` : ''} onerror="handlePersonaAvatarError(this)">
                    </div>
                    <div class="message-content">
                        <div class="message-name">
                            <span class="timestamp">[${timestamp}]</span> ${senderName}${renderGroupMemberTitle(chatType, chatId, senderEng)}
                        </div>
                        <div class="message-bubble">
                            ${window.chatMedia?.renderAttachments(msg.attachments) || ''}
                            <span class="message-text-content"><span class="message-text-original">${formatMessageText(content)}</span></span>
                        </div>
                        ${renderMessageAuxiliarySections(msg)}
                    </div>
                </div>
            `);
        }
    });
    chatMessages.innerHTML = htmlParts.join('');
    filteredMsgs.forEach(msg => {
        if (msg.cls !== 'operator') return;
        const actorId = String(msg.senderEng || msg.sender || '');
        if (actorId !== 'priestess') return;
        const messageId = String(msg.id || '');
        if (!messageId) return;
        const row = Array.from(chatMessages.querySelectorAll('[data-msg-id]'))
            .find(element => String(element.dataset.msgId || '') === messageId);
        if (!row) return;
        row.classList.add('priestess-related', 'priestess-message');
        row.dataset.actorId = 'priestess';
    });
    checkAndShowIndicatorAfterLoad();

    // 绑定动态跳转点击事件
    chatMessages.querySelectorAll('.dynamic-card-message').forEach(el => {
        el.addEventListener('click', () => {
            const dynamicId = el.dataset.dynamicId;
            if (dynamicId) scrollToDynamic(dynamicId);
        });
    });
}

async function openSharedTodoCard(todoId) {
    if (!todoId) return;
    const response = await fetch(`/todo/detail/${encodeURIComponent(todoId)}`);
    if (response.ok) return openTodoDetail(todoId, false);
    alert('原待办已不存在，当前卡片展示的是分享时的快照。');
}

// 辅助函数：追加单条消息到 DOM 底部
function appendMessageToChat(msg, chatType, chatId) {
    if (msg.is_memory_only) return;
    const isUser = msg.cls === 'user';
    const senderId = msg.sender;
    let senderActorId = String(msg.senderEng || senderId || '');
    if (!isUser && !operatorMap.has(senderActorId)) {
        const matchedOperator = Array.from(operatorMap.values())
            .find(operator => operator.codename === senderActorId);
        if (matchedOperator) senderActorId = String(matchedOperator.id);
    }
    const specialSender = !isUser ? getChatTargetIdentity(senderActorId) : null;
    const isPriestessActor = !isUser && senderActorId === 'priestess';
    let senderName;
    const senderPersonaId = msg.persona_id || 'doctor';
    if (msg.cls === 'operator') {
        senderName = specialSender?.display_name || specialSender?.name ||
            (operatorMap.get(senderActorId)?.codename || String(senderId));
    } else if (senderPersonaId !== 'doctor') {
        senderName = window.personaDisplayNameMap?.[senderPersonaId] || senderPersonaId;
    } else {
        senderName = '博士';
    }
    const timestamp = formatTimestamp(msg.timestamp);
    const content = msg.content;

    let avatarUrl;
    if (msg.cls === 'operator') {
        // 干员消息：始终使用干员自己的头像
        let engId = senderActorId;
        if (!engId && msg.sender) {
            const op = Array.from(operatorMap.values()).find(op => op.codename === msg.sender);
            if (op) engId = op.id;
            else engId = msg.sender;
        }
        avatarUrl = specialSender?.avatar_url || getOperatorAvatarUrl(engId);
    } else {
        // 用户消息：使用人格头像
        if (senderPersonaId !== 'doctor') {
                avatarUrl = getPersonaAvatarUrl(senderPersonaId);
            } else {
                avatarUrl = getPersonaAvatarUrl('doctor');
        }
    }
    const avatarOnclick = isUser
        ? 'showPage(\'profile\')'
        : specialSender?.profile_id
            ? `window.openDoctorAgentEditor?.('${escapeHtml(specialSender.profile_id)}')`
            : `showOperatorDetail('${senderActorId}')`;

    const msgDiv = document.createElement('div');
    msgDiv.className = `chat-message-row ${isUser ? 'user' : 'operator'}${isPriestessActor ? ' priestess-related priestess-message' : ''}`;
    msgDiv.setAttribute('data-msg-id', msg.id);
    if (isPriestessActor) msgDiv.dataset.actorId = 'priestess';
    msgDiv.setAttribute('ontouchstart', `startLongPress(event, '${msg.id}', '${chatType}', '${chatId}')`);
    msgDiv.setAttribute('ontouchend', 'cancelLongPress()');
    msgDiv.setAttribute('ontouchcancel', 'cancelLongPress()');
    msgDiv.innerHTML = `
        <div class="message-avatar" onclick="event.stopPropagation(); ${avatarOnclick}">
                    <img src="${avatarUrl}" alt="${senderName}" ${isUser ? `data-persona-id="${escapeHtml(senderPersonaId || 'doctor')}"` : ''} onerror="handlePersonaAvatarError(this)">
        </div>
        <div class="message-content">
            <div class="message-name">
                <span class="timestamp">[${timestamp}]</span> ${senderName}${renderGroupMemberTitle(chatType, chatId, senderId)}
            </div>
            <div class="message-bubble">
                <span class="message-text-content"><span class="message-text-original">${escapeHtml(content).replace(/\n/g, '<br>')}</span></span>
            </div>
        </div>
    `;
    chatMessages.appendChild(msgDiv);
    const priestessCanDisturbText = !msg.msgType
        || msg.msgType === 'text';
    const priestessIsStructured = msg.isScenario
        || msg.unitType === 'scenario'
        || msg.unit_type === 'scenario'
        || msg.unitType === 'event_narration'
        || msg.unit_type === 'event_narration';
    if (isPriestessActor && priestessCanDisturbText && !priestessIsStructured) {
        const bubble = msgDiv.querySelector('.message-bubble');
        applyPriestessGlitchToMessage(
            bubble,
            String(content || ''),
            msg.message_uid || msg.messageUid || msg.uniqueId || msg.id
        );
    }
}

function renderMessageIncrementally(msg, chatType, chatId) {
    if (!chatMessages || !msg) return false;
    const selector = `.chat-message-row[data-msg-id="${CSS.escape(String(msg.id))}"]`;
    if (chatMessages.querySelector(selector)) return true;

    const realContainer = chatMessages;
    const stagingContainer = document.createElement('div');
    try {
        chatMessages = stagingContainer;
        const registry = window.ZootRuntime?.messageRenderers;
        if (registry && !registry.hasFallback()) {
            registry.setFallback((message, context) => {
                fullRenderChat([message], context.chatType, context.chatId);
                return true;
            });
        }
        if (!registry?.render(msg, {chatType, chatId, container: stagingContainer})) {
            fullRenderChat([msg], chatType, chatId);
        }
    } catch (error) {
        console.warn('[chat] incremental render fallback', error);
        return false;
    } finally {
        chatMessages = realContainer;
    }

    if (!stagingContainer.childNodes.length) return true;
    const chatKey = `${chatType}:${chatId}`;
    const chatItems = messages[chatKey] || [];
    const messageIndex = chatItems.indexOf(msg);
    const previous = messageIndex > 0 ? chatItems[messageIndex - 1] : null;
    if (previous && Number(msg.timestamp) - Number(previous.timestamp) > 7200) {
        const divider = document.createElement('div');
        divider.className = 'chat-time-divider';
        divider.textContent = formatDateDivider(msg.timestamp);
        realContainer.appendChild(divider);
    }

    const fragment = document.createDocumentFragment();
    while (stagingContainer.firstChild) {
        fragment.appendChild(stagingContainer.firstChild);
    }
    realContainer.appendChild(fragment);

    const row = realContainer.querySelector(selector);
    if (row) {
        row.dataset.messageUid = String(msg.message_uid || '');
        row.dataset.deliveryState = String(msg.delivery_state || 'stored');
        row.classList.add(`message-delivery-${row.dataset.deliveryState}`);
    }

    const maxLive = window.ZootRuntime?.getResourceBudget?.().maxLiveMessages || 100;
    const rows = Array.from(realContainer.querySelectorAll('.chat-message-row[data-msg-id]'));
    if (rows.length > maxLive && chatViewportController.isNearTail()) {
        rows.slice(0, rows.length - maxLive).forEach(oldRow => {
            const divider = oldRow.previousElementSibling;
            oldRow.remove();
            if (divider?.classList.contains('chat-time-divider')) divider.remove();
        });
        realContainer.dataset.virtualizedBefore = String(
            Math.max(0, chatItems.length - maxLive)
        );
    }
    if (isMultiSelectMode && chatKey === multiSelectChatKey) applyMultiSelectUI();
    window.refreshTimelineMessageActions?.();
    return true;
}

let messageInputRevision = 0;
let messageInputResizeFrame = 0;
let messageInputResizeAfterPaint = false;
let messageInputResizeAllowShrink = false;
let messageInputDraftTimer = 0;
let messageInputDraftIdleHandle = 0;
let messageInputCompositionActive = false;
let messageInputPreviousValue = '';
const messageInputLayoutMetrics = new WeakMap();
const messageInputPerformanceSamples = [];
const supportsNativeTextareaContentSizing = Boolean(window.CSS?.supports?.('field-sizing', 'content'));

function getCurrentMessageComposerIdentity() {
    if (currentGroupId) {
        return {
            mode: 'group',
            chatId: String(currentGroupId)
        };
    }
    if (currentOperatorId) {
        return {
            mode: 'private',
            chatId: String(currentOperatorId)
        };
    }
    return {
        mode: '',
        chatId: ''
    };
}

function syncMessageInputHeight({ allowShrink = false } = {}) {
    const messageInput = getMessageInput();
    if (!messageInput || messageInput.getClientRects().length === 0) {
        return;
    }

    let metrics = messageInputLayoutMetrics.get(messageInput);
    const metricKey = `${messageInput.clientWidth}:${document.documentElement.dataset.theme || ''}`;
    if (!metrics || metrics.key !== metricKey) {
        const style = window.getComputedStyle(messageInput);
        const parsedLineHeight = Number.parseFloat(style.lineHeight);
        const lineHeight = Number.isFinite(parsedLineHeight)
            ? parsedLineHeight
            : Number.parseFloat(style.fontSize) * 1.4;
        const padding =
            Number.parseFloat(style.paddingTop) +
            Number.parseFloat(style.paddingBottom);
        const borders =
            Number.parseFloat(style.borderTopWidth) +
            Number.parseFloat(style.borderBottomWidth);
        metrics = {
            key: metricKey,
            borders,
            minimumHeight: Math.max(38, lineHeight + padding + borders),
            maximumHeight: lineHeight * 6 + padding + borders
        };
        messageInputLayoutMetrics.set(messageInput, metrics);
    }

    messageInput.style.maxHeight = `${metrics.maximumHeight}px`;
    if (supportsNativeTextareaContentSizing) {
        messageInput.style.setProperty('field-sizing', 'content');
        messageInput.style.height = 'auto';
        messageInput.style.overflowY = messageInput.scrollHeight > metrics.maximumHeight + 0.5 ? 'auto' : 'hidden';
        return;
    }
    if (allowShrink) {
        messageInput.style.height = `${metrics.minimumHeight}px`;
    }

    const contentHeight = messageInput.scrollHeight + metrics.borders;
    const currentHeight = Number.parseFloat(
        messageInput.dataset.measuredHeight || messageInput.style.height || metrics.minimumHeight
    );
    if (!allowShrink && contentHeight <= currentHeight + 0.5) {
        messageInput.style.overflowY = contentHeight > metrics.maximumHeight + 0.5 ? 'auto' : 'hidden';
        return;
    }
    const targetHeight = Math.min(
        metrics.maximumHeight,
        Math.max(metrics.minimumHeight, contentHeight)
    );
    const isOverflowing = contentHeight > metrics.maximumHeight + 0.5;
    const previousHeight = Number.parseFloat(messageInput.dataset.measuredHeight || '0');
    const heightChanged = Math.abs(previousHeight - targetHeight) > 0.5;

    messageInput.style.height = `${targetHeight}px`;
    messageInput.dataset.measuredHeight = String(targetHeight);
    messageInput.style.overflowY = isOverflowing ? 'auto' : 'hidden';
    if (heightChanged && chatViewportController.followTail && getCurrentPageId() === 'chat-detail') {
        chatViewportController.stabilizeTail(300);
    }
}

function scheduleMessageInputHeightSync(afterLayout = false, allowShrink = false) {
    messageInputResizeAfterPaint = messageInputResizeAfterPaint || afterLayout;
    messageInputResizeAllowShrink = messageInputResizeAllowShrink || allowShrink;
    if (messageInputResizeFrame) return;

    const measure = () => {
        messageInputResizeFrame = 0;
        const shrink = messageInputResizeAllowShrink;
        messageInputResizeAfterPaint = false;
        messageInputResizeAllowShrink = false;
        syncMessageInputHeight({ allowShrink: shrink });
    };

    messageInputResizeFrame = requestAnimationFrame(() => {
        if (messageInputResizeAfterPaint) {
            messageInputResizeFrame = requestAnimationFrame(measure);
        } else {
            measure();
        }
    });
}

function recordMessageInputPerformance(duration) {
    if (!Number.isFinite(duration)) return;
    messageInputPerformanceSamples.push(duration);
    if (messageInputPerformanceSamples.length > 120) messageInputPerformanceSamples.shift();
    if (duration > 8) {
        console.warn(`[输入性能] 输入事件处理耗时 ${duration.toFixed(1)}ms`);
    }
}

window.ZootInputDiagnostics = {
    snapshot() {
        const samples = [...messageInputPerformanceSamples].sort((a, b) => a - b);
        const percentile = ratio => samples.length
            ? samples[Math.min(samples.length - 1, Math.floor(samples.length * ratio))]
            : 0;
        return {
            samples: samples.length,
            p50_ms: Number(percentile(0.5).toFixed(2)),
            p95_ms: Number(percentile(0.95).toFixed(2)),
            max_ms: Number((samples[samples.length - 1] || 0).toFixed(2))
        };
    }
};

function scheduleCurrentMessageDraftSave(delay = 420) {
    clearTimeout(messageInputDraftTimer);
    if (messageInputDraftIdleHandle && 'cancelIdleCallback' in window) {
        cancelIdleCallback(messageInputDraftIdleHandle);
        messageInputDraftIdleHandle = 0;
    }

    const identity = getCurrentMessageComposerIdentity();
    const capturedRevision = messageInputRevision;
    if (!identity.mode || !identity.chatId) {
        return;
    }

    const persistDraft = () => {
        messageInputDraftIdleHandle = 0;
        const currentIdentity = getCurrentMessageComposerIdentity();
        if (
            capturedRevision !== messageInputRevision ||
            currentIdentity.mode !== identity.mode ||
            currentIdentity.chatId !== identity.chatId
        ) {
            return;
        }

        const messageInput = getMessageInput();
        if (messageInput) {
            saveDraft(identity.mode, identity.chatId, messageInput.value);
        }
    };
    messageInputDraftTimer = setTimeout(() => {
        messageInputDraftTimer = 0;
        if ('requestIdleCallback' in window) {
            messageInputDraftIdleHandle = requestIdleCallback(persistDraft, {timeout: 700});
        } else {
            persistDraft();
        }
    }, delay);
}

function restoreMessageInputDraft(mode, chatId) {
    const messageInput = getMessageInput();
    if (!messageInput) {
        return;
    }

    clearTimeout(messageInputDraftTimer);
    messageInput.value = loadDraft(mode, chatId);
    messageInputRevision += 1;
    scheduleMessageInputHeightSync(true, true);
    updateSendButtons();
}

function consumePendingSendCommand(command) {
    const messageInput = getMessageInput();
    const identity = getCurrentMessageComposerIdentity();
    if (!messageInput) {
        return false;
    }

    const isSameComposer =
        identity.mode === command.mode &&
        identity.chatId === String(command.chatId);
    const isSameRevision =
        messageInputRevision === command.composerRevision;

    if (!isSameComposer) {
        const storedDraft = loadDraft(command.mode, String(command.chatId));
        if (storedDraft === command.rawMsg) {
            clearDraft(command.mode, String(command.chatId));
        }
        scheduleMessageInputHeightSync();
        updateSendButtons();
        return false;
    }

    if (!isSameRevision) {
        if (identity.mode && identity.chatId) {
            saveDraft(identity.mode, identity.chatId, messageInput.value);
        }
        scheduleMessageInputHeightSync();
        updateSendButtons();
        return false;
    }

    clearTimeout(messageInputDraftTimer);
    messageInput.value = '';
    messageInputRevision += 1;
    clearDraft(command.mode, String(command.chatId));
    scheduleMessageInputHeightSync(true, true);
    updateSendButtons();
    return true;
}

// ========== 9.2.聊天列表本地缓存 ==========
// 保存聊天列表到本地存储
function saveChatsToLocalStorage() {
    try {
        // 只保存必要字段，避免存储过大，同时保留非助理消息信息
        const toStore = chats.map(chat => ({
            id: chat.id,
            type: chat.type,
            name: chat.name,
            lastMsg: chat.lastMsg,
            lastTime: chat.lastTime,
            avatar: chat.avatar,
            role_type: chat.role_type,
            game_namespace: chat.game_namespace,
            engine_state: chat.engine_state,
            contact_available: chat.contact_available,
            contact_status: chat.contact_status,
            avatar_ref: chat.avatar_ref,
            messageCount: Number(chat.messageCount || 0),
            isPinned: chat.isPinned,
            lastNonAssistantMsg: chat.lastNonAssistantMsg,
            lastNonAssistantSender: chat.lastNonAssistantSender
        }));
        localStorage.setItem('cachedChats', JSON.stringify(toStore));
    } catch (e) {
        console.error('保存聊天列表到本地失败', e);
    }
}

// 从本地存储加载聊天列表
function loadChatsFromLocalStorage() {
    try {
        const cached = localStorage.getItem('cachedChats');
        if (cached) {
            const parsed = JSON.parse(cached);
            const normalizedChats = parsed.map(chat => ({
                ...chat,
                // 确保字段完整
                avatar: chat.type === 'private'
                    ? (chat.avatar || chat.name[0] || '🧑')
                    : normalizeGroupAvatarValue(chat.avatar),
                role_type: chat.role_type || 'operator',
                game_namespace: chat.game_namespace || 'arknights',
                messageCount: Number(chat.messageCount || 0),
                lastNonAssistantMsg: chat.lastNonAssistantMsg,
                lastNonAssistantSender: chat.lastNonAssistantSender
            }));
            cachedChatActivity.clear();
            normalizedChats.forEach(chat => {
                cachedChatActivity.set(chatVisibilityKey(chat.id, chat.type), normalizeChatActivity(chat));
            });
            chats = normalizedChats.filter(chat => !shouldKeepChatHidden(chat));
            renderChatList();
            console.log(`从本地缓存加载了 ${chats.length} 个聊天项`);
        }
    } catch (e) {
        console.error('加载本地聊天列表失败', e);
    }
}

// ========== 9.3. 消息显示与聊天详情页 ==========
let longPressTimer = null;
let currentLongPressMsg = null;
let currentMessageMenu = null;
let globalMenuClickListener = null;
let currentMessageMenuRow = null;
let messageMenuCleanup = [];
let longPressStartPoint = null;

let isMultiSelectMode = false;
let selectedMsgIds = new Set();
let multiSelectChatKey = null;

function applyMultiSelectUI() {
    if (!chatMessages || !multiSelectChatKey) return;
    const list = messages[multiSelectChatKey] || [];
    chatMessages.querySelectorAll('.chat-message-row').forEach(row => {
        const msg = list.find(item => String(item.id) === String(row.dataset.msgId));
        if (!msg?.uniqueId) return;
        row.dataset.uid = msg.uniqueId;
        let checkbox = row.querySelector('.multi-select-checkbox');
        if (!checkbox) {
            checkbox = document.createElement('span');
            checkbox.className = 'multi-select-checkbox';
            row.insertBefore(checkbox, row.firstChild);
            row.addEventListener('click', event => {
                if (!isMultiSelectMode || event.target.closest('a, button, .message-avatar')) return;
                event.preventDefault();
                event.stopPropagation();
                toggleMsgSelect(row.dataset.uid);
            });
        }
        const selected = selectedMsgIds.has(msg.uniqueId);
        checkbox.classList.toggle('checked', selected);
        row.classList.toggle('multi-select-highlight', selected);
    });
}

function enterMultiSelectMode(msgId, chatType, chatId) {
    closeCurrentMessageMenu();
    multiSelectChatKey = `${chatType}:${chatId}`;
    isMultiSelectMode = true;
    selectedMsgIds = new Set();
    const msg = (messages[multiSelectChatKey] || []).find(item => String(item.id) === String(msgId));
    if (msg?.uniqueId) selectedMsgIds.add(msg.uniqueId);
    renderCurrentChat();
    showMultiSelectToolbar();
}

function exitMultiSelectMode() {
    isMultiSelectMode = false;
    selectedMsgIds = new Set();
    multiSelectChatKey = null;
    document.getElementById('multi-select-toolbar')?.remove();
    renderCurrentChat();
}

function toggleMsgSelect(uniqueId) {
    if (!uniqueId) return;
    if (selectedMsgIds.has(uniqueId)) selectedMsgIds.delete(uniqueId);
    else selectedMsgIds.add(uniqueId);
    applyMultiSelectUI();
    const count = document.querySelector('#multi-select-toolbar .selected-count');
    if (count) count.textContent = `已选 ${selectedMsgIds.size} 条`;
}

function selectAllMessages() {
    (messages[multiSelectChatKey] || []).forEach(msg => {
        if (msg.uniqueId && !msg.is_memory_only) selectedMsgIds.add(msg.uniqueId);
    });
    applyMultiSelectUI();
    const count = document.querySelector('#multi-select-toolbar .selected-count');
    if (count) count.textContent = `已选 ${selectedMsgIds.size} 条`;
}

function getSelectedMessages() {
    return (messages[multiSelectChatKey] || []).filter(msg => selectedMsgIds.has(msg.uniqueId));
}

function showMultiSelectToolbar() {
    document.getElementById('multi-select-toolbar')?.remove();
    const toolbar = document.createElement('div');
    toolbar.id = 'multi-select-toolbar';
    toolbar.className = 'multi-select-toolbar';
    toolbar.innerHTML = `
        <span class="selected-count">已选 ${selectedMsgIds.size} 条</span>
        <button class="toolbar-btn" onclick="selectAllMessages()">全选</button>
        <button class="toolbar-btn" onclick="copySelectedText()">复制</button>
        <button class="toolbar-btn" onclick="quoteCombineSelected()">引用</button>
        <button class="toolbar-btn" onclick="batchRecallMessages()">撤回</button>
        <button class="toolbar-btn danger" onclick="batchDeleteMessages()">删除</button>
        <button class="toolbar-btn" onclick="exitMultiSelectMode()">取消</button>`;
    document.getElementById('page-chat-detail')?.appendChild(toolbar);
}

async function runSelectedMessageAction(endpoint, verb) {
    const selected = getSelectedMessages();
    if (!selected.length) return showTemporaryToast('请先选择消息');
    const dbIds = selected.map(msg => msg.dbId).filter(Boolean);
    const messageUids = selected.map(msg => msg.message_uid).filter(Boolean);
    if (!dbIds.length && !messageUids.length) return showTemporaryToast('所选消息尚未完成保存');
    const prompt = verb === '隐藏'
        ? `确定仅在此设备隐藏选中的 ${selected.length} 条消息？之后可以恢复。`
        : `确定${verb}选中的 ${selected.length} 条消息？`;
    if (!await requestProjectConfirmation(verb === '撤回' ? '撤回消息' : '隐藏消息', `${prompt}${verb === '撤回' ? ' 关联业务和长期记忆不会被撤销。' : ''}`)) return;
    const [chatType, chatId] = multiSelectChatKey.split(':');
    const response = await fetch(endpoint, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ db_ids: dbIds, message_uids: messageUids, chat_type: chatType, chat_id: chatId })
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) {
        throw new Error(result.detail || `${verb}失败`);
    }
    exitMultiSelectMode();
    if (chatType === 'group') await loadGroupHistory(chatId, null, false, { bypassCache: true });
    else await loadPrivateHistory(chatId, null, false, { bypassCache: true });
    if (verb === '撤回') {
        showTemporaryToast(
            `已撤回 ${result.recalled || 0} 条`
            + (result.already_recalled ? `，此前已撤回 ${result.already_recalled} 条` : '')
            + (result.not_persisted ? `，未落库 ${result.not_persisted} 条` : '')
            + (result.not_found ? `，未找到 ${result.not_found} 条` : '')
            + (result.failed ? `，失败 ${result.failed} 条` : '')
        );
    } else {
        showTemporaryToast(`已隐藏 ${result.hidden || 0} 条消息`);
    }
}

async function batchDeleteMessages() {
    try { await runSelectedMessageAction('/messages/batch_delete', '隐藏'); }
    catch (error) { showTemporaryToast(error.message); }
}

async function batchRecallMessages() {
    try { await runSelectedMessageAction('/messages/batch_recall', '撤回'); }
    catch (error) { showTemporaryToast(error.message); }
}

async function restoreAllLocallyHiddenMessages() {
    if (!confirm('恢复当前设备上全部隐藏的消息？')) return;
    const response = await fetch('/messages/local_hides/restore', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) return showTemporaryToast(result.detail || '恢复失败');
    showTemporaryToast(`已恢复 ${result.restored || 0} 条本机隐藏消息`);
    if (currentGroupId) await loadGroupHistory(currentGroupId, null, false, { bypassCache: true });
    else if (currentOperatorId) await loadPrivateHistory(currentOperatorId, null, false, { bypassCache: true });
}

async function copySelectedText() {
    const selected = getSelectedMessages();
    if (!selected.length) return showTemporaryToast('请先选择消息');
    const text = selected.map(msg => `${msg.cls === 'user' ? '博士' : (msg.sender || msg.senderEng)}: ${msg.content}`).join('\n');
    try { await navigator.clipboard.writeText(text); showTemporaryToast(`已复制 ${selected.length} 条消息`); }
    catch (_) { showTemporaryToast('复制失败'); }
}

function quoteCombineSelected() {
    const selected = getSelectedMessages();
    if (!selected.length) return showTemporaryToast('请先选择消息');
    const input = getMessageInput();
    if (!input) return;
    const quote = selected.map(msg => `> ${msg.cls === 'user' ? '博士' : (msg.sender || msg.senderEng)}: ${msg.content}`).join('\n') + '\n';
    input.value = `${input.value || ''}${quote}`;
    input.dispatchEvent(new Event('input', { bubbles: true }));
    exitMultiSelectMode();
    input.focus();
}

function startLongPress(e, msgId, chatType, chatId) {
    cancelLongPress();
    const point = e.touches?.[0] || e;
    longPressStartPoint = { x: point.clientX, y: point.clientY };
    longPressTimer = setTimeout(() => {
        showMessageMenu(msgId, chatType, chatId, e);
        longPressTimer = null;
    }, 500);
}

function trackLongPressMove(e) {
    if (!longPressTimer || !longPressStartPoint) return;
    const point = e.touches?.[0] || e;
    if (Math.hypot(point.clientX - longPressStartPoint.x, point.clientY - longPressStartPoint.y) > 10) cancelLongPress();
}
document.addEventListener('touchmove', trackLongPressMove, { passive: true, capture: true });

function animateMessageEntrance(msgId) {
    requestAnimationFrame(() => {
        const row = chatMessages?.querySelector(`.chat-message-row[data-msg-id="${CSS.escape(String(msgId))}"]`);
        if (!row) return;
        row.classList.add('message-entering');
        row.addEventListener('animationend', () => row.classList.remove('message-entering'), { once: true });
    });
}

function animateSelectedMessagesOut() {
    const rows = Array.from(chatMessages?.querySelectorAll('.chat-message-row.multi-select-highlight') || []);
    rows.forEach(row => row.classList.add('message-removing'));
    return new Promise(resolve => setTimeout(resolve, rows.length ? 180 : 0));
}

function animateMessageOut(msgId) {
    const row = chatMessages?.querySelector(`.chat-message-row[data-msg-id="${CSS.escape(String(msgId))}"]`);
    if (!row) return Promise.resolve();
    row.classList.add('message-removing');
    return new Promise(resolve => setTimeout(resolve, 180));
}

function cancelLongPress() {
    if (longPressTimer) {
        clearTimeout(longPressTimer);
        longPressTimer = null;
    }
    longPressStartPoint = null;
    currentLongPressMsg = null;
}

// 统一关闭当前菜单
function closeCurrentMessageMenu() {
    if (currentMessageMenu) {
        currentMessageMenu.remove();
        currentMessageMenu = null;
    }
    currentMessageMenuRow?.classList.remove('message-menu-selected');
    currentMessageMenuRow = null;
    if (globalMenuClickListener) {
        document.removeEventListener('pointerdown', globalMenuClickListener, true);
        globalMenuClickListener = null;
    }
    messageMenuCleanup.splice(0).forEach(cleanup => cleanup());
}

function showMessageMenu(msgId, chatType, chatId, touchEvent) {
    // 先关闭已存在的菜单
    closeCurrentMessageMenu();

    const chatKey = `${chatType}:${chatId}`;
    const messagesList = messages[chatKey];
    if (!messagesList) {
        console.warn('[MessageMenu] 消息列表不存在', chatKey);
        return;
    }

    // 查找消息：统一转换为字符串比较，避免类型不匹配
    const msg = messagesList.find(m => String(m.id) === String(msgId));
    if (!msg) {
        console.warn('[MessageMenu] 未找到消息，msgId=', msgId, '类型:', typeof msgId);
        return;
    }

    const isPrivate = (chatType === 'private');
    const isOperatorReply = msg.cls === 'operator';
    // 所有已落库消息都可撤回，包括系统消息和结构化业务卡片。
    const isRecallAllowed = Boolean(msg.dbId || msg.message_uid) && !msg.deleted_at && !msg.recalled;

    const actions = [
        { id: 'quote', label: '引用', icon: 'message' },
        { id: 'copy', label: '复制', icon: 'clipboard' },
        ...(window.ZootTimelineMessageActions?.items?.(msg) || []),
        ...(isPrivate && isOperatorReply && !msg.isAuto
            ? [{ id: 'regenerate', label: '重生成', icon: 'refresh' }]
            : []),
        ...(isRecallAllowed ? [{ id: 'recall', label: '撤回', icon: 'trash', danger: true }] : []),
        { id: 'multi-select', label: '多选', icon: 'check' }
    ];

    // 创建菜单容器
    const menu = document.createElement('div');
    menu.className = 'message-menu';
    menu.id = 'active-message-menu';
    menu.setAttribute('role', 'menu');
    menu.setAttribute('aria-label', '消息操作');
    menu.innerHTML = actions.map(action => `
        <button type="button" class="menu-item${action.danger ? ' danger' : ''}" data-action="${escapeHtml(action.id)}" role="menuitem" aria-label="${escapeHtml(action.label)}" ${action.enabled === false ? 'disabled' : ''}>
            ${window.ZootIcons?.html?.(action.icon) || `<span data-zoot-icon="${escapeHtml(action.icon)}" aria-hidden="true"></span>`}
            <span>${escapeHtml(action.label)}</span>
        </button>
    `).join('');
    document.body.appendChild(menu);
    currentMessageMenu = menu;

    const row = chatMessages?.querySelector(`.chat-message-row[data-msg-id="${CSS.escape(String(msgId))}"]`);
    currentMessageMenuRow = row || null;
    row?.classList.add('message-menu-selected');

    const anchorRect = row?.getBoundingClientRect();
    const touchPoint = touchEvent?.touches?.[0] || touchEvent;
    const anchorLeft = anchorRect ? anchorRect.left + anchorRect.width / 2 : Number(touchPoint?.clientX || window.innerWidth / 2);
    const anchorTop = anchorRect?.top ?? Number(touchPoint?.clientY || window.innerHeight / 2);
    const anchorBottom = anchorRect?.bottom ?? anchorTop;
    const rect = menu.getBoundingClientRect();
    const left = Math.max(12, Math.min(window.innerWidth - rect.width - 12, anchorLeft - rect.width / 2));
    const above = anchorTop - rect.height - 10;
    const top = above >= 12 ? above : Math.min(window.innerHeight - rect.height - 12, anchorBottom + 10);
    menu.style.left = `${left}px`;
    menu.style.top = `${Math.max(12, top)}px`;

    // 菜单项点击处理
    const handleMenuItemClick = async (e) => {
        const item = e.target.closest('.menu-item');
        if (!item || item.disabled || menu.classList.contains('is-busy')) return;
        const action = item.dataset.action;
        menu.classList.add('is-busy');
        menu.querySelectorAll('button').forEach(button => { button.disabled = true; });
        try {
            if (action === 'quote') {
                quoteMessage(msgId, chatType, chatId);
            } else if (action === 'copy') {
                await copyMessage(msgId, chatType, chatId);
            } else if (action === 'regenerate') {
                await regenerateMessage(msgId, chatType, chatId);
            } else if (action === 'recall') {
                await recallMessage(msgId, chatType, chatId);
            } else if (action === 'multi-select') {
                enterMultiSelectMode(msgId, chatType, chatId);
            } else if (window.ZootTimelineMessageActions) {
                await window.ZootTimelineMessageActions.run(action, msg, item);
            }
        } catch (error) {
            showTemporaryToast(`操作失败：${error.message}`, 2600, 'error');
        } finally {
            closeCurrentMessageMenu();
        }
    };
    menu.addEventListener('click', handleMenuItemClick);

    // 全局点击关闭菜单
    globalMenuClickListener = (e) => {
        if (!currentMessageMenu) return;
        if (currentMessageMenu.contains(e.target)) return;
        closeCurrentMessageMenu();
    };
    setTimeout(() => {
        if (currentMessageMenu) {
            document.addEventListener('pointerdown', globalMenuClickListener, true);
        }
    }, 100);
    const closeOnScroll = () => closeCurrentMessageMenu();
    const closeOnPage = () => closeCurrentMessageMenu();
    const closeOnBack = () => closeCurrentMessageMenu();
    chatMessages?.addEventListener('scroll', closeOnScroll, { passive: true, once: true });
    document.addEventListener('pageShown', closeOnPage, { once: true });
    window.addEventListener('popstate', closeOnBack, { once: true });
    messageMenuCleanup.push(
        () => chatMessages?.removeEventListener('scroll', closeOnScroll),
        () => document.removeEventListener('pageShown', closeOnPage),
        () => window.removeEventListener('popstate', closeOnBack)
    );
    menu.querySelector('.menu-item:not(:disabled)')?.focus({ preventScroll: true });
}

// 重新生成AI回复（仅私聊）
async function regenerateMessage(msgId, chatType, chatId) {
    if (chatType !== 'private') {
        alert('重新生成功能仅支持私聊');
        return;
    }
    const chatKey = `${chatType}:${chatId}`;
    const messagesList = messages[chatKey];
    if (!messagesList) {
        alert('消息列表不存在');
        return;
    }

    const targetIndex = messagesList.findIndex(m => String(m.id) === String(msgId));
    if (targetIndex === -1) {
        alert('未找到目标消息');
        return;
    }
    const targetMsg = messagesList[targetIndex];
    if (targetMsg.cls !== 'operator') {
        alert('只能重新生成干员的回复消息');
        return;
    }
    if (!targetMsg.dbId) {
        alert('该消息尚未保存，无法重新生成');
        return;
    }

    const confirmMsg = targetIndex < messagesList.length - 1
        ? '该回复后仍有消息。重新生成会自动创建新时间线，原时间线保持不变，确定继续吗？'
        : '重新生成会替换当前时间线中的这批回复，确定继续吗？';
    if (!confirm(confirmMsg)) return;

    const operatorEng = chatId;
    const isScenario = targetMsg.isScenario || false;

    // 删除该消息及其之后的所有消息（整个干员回复段）
    const deletedCount = messagesList.length - targetIndex;
    await animateMessageOut(msgId);
    messagesList.splice(targetIndex, deletedCount);
    renderCurrentChat();

    showTypingIndicator();

    try {
        const res = await fetch('/private/regenerate', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                operator_id: operatorEng,
                reply_message_id: targetMsg.dbId,
                is_scenario: isScenario,
                operator_scenario: scenarioMode
            })
        });
        const data = await res.json();

        if (res.ok) {
            if (data.timeline_fork) {
                await loadPrivateHistory(operatorEng, null, false, { bypassCache: true });
                showTemporaryToast('已在新时间线中重新生成');
                return;
            }
            let lastReplyText = '';       // 用于更新聊天列表的最终文本
            let lastTimestamp = data.timestamp || Date.now() / 1000;
            let msgType = 'text';

            // 处理多段回复（新版格式）
            if (data.message_contents && data.message_types && data.message_contents.length > 0) {
                for (let i = 0; i < data.message_contents.length; i++) {
                    const segmentContent = data.message_contents[i];
                    const segmentType = data.message_types[i];
                    const isScenarioUnit = (segmentType === 'scenario');
                    const segmentTimestamp = data.timestamp + i * 0.001;
                    let currentMsgType = 'text';
                    let emojiCodeSeg = null;
                    let emojiOperatorSeg = null;
                    if (segmentType === 'emoji') {
                        currentMsgType = 'emoji';
                        emojiCodeSeg = segmentContent;
                        emojiOperatorSeg = data.operator_id;
                    }
                    const msgDbId = data.message_ids && data.message_ids[i] ? String(data.message_ids[i]) : null;
                    addMessageToChat(
                        data.operator_id,
                        segmentContent,
                        'operator',
                        segmentTimestamp,
                        'private',
                        currentOperatorId,
                        isScenarioUnit,
                        msgDbId,
                        false,
                        currentMsgType,
                        emojiCodeSeg,
                        emojiOperatorSeg,
                        `private:${currentOperatorId}`,
                        data.persona_id || currentPersonaId,
                        [],
                        data.message_uids?.[i] || null,
                        null,
                        data.branch_id || null,
                        data.message_auxiliary_sections?.[i] || []
                    );
                    // 如果是文本或情景段，记录为最后回复文本（用于更新列表）
                    if (segmentType === 'text' || segmentType === 'scenario') {
                        lastReplyText = segmentContent;
                        lastTimestamp = segmentTimestamp;
                        msgType = currentMsgType;
                    }
                    // 对于 emoji，可考虑保留，但通常列表缩略用文本，若只有 emoji，则取之
                    if (segmentType === 'emoji' && !lastReplyText) {
                        lastReplyText = `[表情: ${segmentContent}]`;
                        lastTimestamp = segmentTimestamp;
                        msgType = 'emoji';
                    }
                    if (i < data.message_contents.length - 1) {
                        await new Promise(resolve => setTimeout(resolve, 500 + Math.random() * 1000));
                    }
                }
                // 如果没有任何文本/情景/emoji，使用第一段内容
                if (!lastReplyText) {
                    lastReplyText = data.message_contents[0] || '[新回复]';
                }
            } else if (data.message_contents && data.message_contents.length > 0) {
                // 兼容旧格式（只有 content 列表）
                for (let i = 0; i < data.message_contents.length; i++) {
                    const segmentContent = data.message_contents[i];
                    const segmentTimestamp = data.timestamp + i * 0.001;
                    const msgDbId = data.message_ids && data.message_ids[i] ? String(data.message_ids[i]) : null;
                    addMessageToChat(
                        data.operator_id,
                        segmentContent,
                        'operator',
                        segmentTimestamp,
                        'private',
                        currentOperatorId,
                        false,
                        msgDbId,
                        false,
                        'text',
                        null,
                        null,
                        `private:${currentOperatorId}`,
                        data.persona_id || currentPersonaId,
                        [],
                        data.message_uids?.[i] || null,
                        null,
                        data.branch_id || null,
                        data.message_auxiliary_sections?.[i] || []
                    );
                    // 记录最后一段作为列表缩略
                    lastReplyText = segmentContent;
                    lastTimestamp = segmentTimestamp;
                    if (i < data.message_contents.length - 1) {
                        await new Promise(resolve => setTimeout(resolve, 500 + Math.random() * 1000));
                    }
                }
            } else {
                // 单条回复
                const dbId = data.message_id ? String(data.message_id) : null;
                addMessageToChat(
                    data.operator_id,
                    data.reply,
                    'operator',
                    data.timestamp,
                    'private',
                    currentOperatorId,
                    false,
                    dbId,
                    false,
                    'text',
                    null,
                    null,
                    `private:${currentOperatorId}`,
                    data.persona_id || currentPersonaId,
                    [],
                    data.message_uids?.[0] || null,
                    null,
                    data.branch_id || null,
                    data.message_auxiliary_sections?.[0] || data.auxiliary_sections || []
                );
                lastReplyText = data.reply;
                lastTimestamp = data.timestamp;
            }

            // 更新信赖值
            if (data.new_trust !== undefined) {
                updateTrustDisplay(operatorEng, data.new_trust);
            }

            // 更新聊天列表（使用我们记录的最终回复文本）
            if (lastReplyText) {
                updateChatListFromMessage(operatorEng, lastReplyText, lastTimestamp, 'private', undefined, false, msgType);
            } else {
                // 保底：使用 data.reply 或 '新回复'
                updateChatListFromMessage(operatorEng, data.reply || '新回复', data.timestamp, 'private', undefined, false, 'text');
            }

            hideTypingIndicator();
        } else {
            // 失败处理
            alert('重新生成失败：' + (data.detail || '未知错误'));
            await loadPrivateHistory(operatorEng);
            hideTypingIndicator();
        }
    } catch (err) {
        console.error('重新生成请求失败', err);
        alert('网络错误，请重试');
        await loadPrivateHistory(operatorEng);
        hideTypingIndicator();
    }
}

// 撤回消息（优化类型安全）
async function recallMessage(msgId, chatType, chatId) {
    const chatKey = `${chatType}:${chatId}`;
    const messagesList = messages[chatKey];
    if (!messagesList) {
        showTemporaryToast('消息不存在', 2400, 'error');
        return;
    }
    const msg = messagesList.find(m => String(m.id) === String(msgId));
    if (!msg) {
        showTemporaryToast('消息不存在', 2400, 'error');
        return;
    }
    if (!msg.dbId && !msg.message_uid) {
        showTemporaryToast('消息尚未完成保存，无法撤回', 2600, 'warning');
        return;
    }
    if (!await requestProjectConfirmation('撤回消息', '确定撤回这条消息？关联业务和长期记忆不会被撤销。')) return;

    try {
        const res = await fetch('/recall', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ db_id: msg.dbId, message_uid: msg.message_uid || null })
        });
        const respData = await res.json();
        if (res.ok && ['recalled', 'already_recalled'].includes(respData.status)) {
            // 从内存中删除该消息
            const index = messagesList.findIndex(m => String(m.id) === String(msgId));
            if (index !== -1) {
                await animateMessageOut(msgId);
                messagesList.splice(index, 1);
                document.querySelector(`.chat-message-row[data-msg-id="${CSS.escape(String(msgId))}"]`)?.remove();
                updateChatListAfterMessageRemoval(chatType, chatId);
            }
            showTemporaryToast(respData.status === 'recalled' ? '消息已撤回' : '消息此前已经撤回', 1800, 'success');
        } else {
            showTemporaryToast('撤回失败：' + (respData.detail || respData.message || '未知错误'), 2800, 'error');
        }
    } catch (err) {
        console.error('撤回请求失败', err);
        showTemporaryToast('网络错误，请重试', 2800, 'error');
    } finally {
        closeCurrentMessageMenu();
    }
}

// 辅助函数：消息删除后更新聊天列表缩略
function updateChatListAfterMessageRemoval(chatType, chatId) {
    const chat = chats.find(c => c.id === chatId && c.type === chatType);
    if (!chat) return;
    const chatKey = `${chatType}:${chatId}`;
    const msgs = messages[chatKey];
    if (msgs && msgs.length > 0) {
        const lastMsg = msgs[msgs.length - 1];
        chat.lastMsg = lastMsg.content;
        chat.lastTime = lastMsg.timestamp;
        chat.lastSender = lastMsg.cls === 'user'
            ? (window.personaDisplayNameMap?.[lastMsg.persona_id || 'doctor'] || '博士')
            : (operatorMap.get(lastMsg.sender)?.codename || lastMsg.sender);
        // 如果是干员消息且是助理消息，不要更新非助理字段（可选）
    } else {
        chat.lastMsg = '';
        chat.lastTime = 0;
        chat.lastSender = '';
    }
    renderChatList();
}

// 引用消息 - 修复发送者显示
function quoteMessage(msgId, chatType, chatId) {
    const chatKey = `${chatType}:${chatId}`;
    const msg = messages[chatKey]?.find(m => String(m.id) === String(msgId));
    if (!msg) {
        console.warn('quoteMessage: 消息不存在', msgId);
        return;
    }
    // 获取发送者名称
    let senderName = '';
    if (msg.cls === 'user') {
        senderName = window.personaDisplayNameMap?.[msg.persona_id || 'doctor'] || '博士';
    } else {
        const op = operatorMap.get(msg.sender);
        senderName = op ? op.codename : String(msg.sender);
    }
    const quoteText = `> ${senderName}: ${msg.content}\n\n`;
    const input = document.getElementById('message');
    if (input) {
        input.value = quoteText + input.value;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.focus();
    }
}

// 复制消息 - 修复发送者名称（不影响复制内容）
async function copyMessage(msgId, chatType, chatId) {
    const chatKey = `${chatType}:${chatId}`;
    const msg = messages[chatKey]?.find(m => String(m.id) === String(msgId));
    if (!msg) {
        alert('消息不存在');
        return;
    }
    try {
        await navigator.clipboard.writeText(msg.content);
        alert('已复制到剪贴板');
    } catch (err) {
        console.error('复制失败', err);
        const textarea = document.createElement('textarea');
        textarea.value = msg.content;
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand('copy');
        document.body.removeChild(textarea);
        alert('已复制到剪贴板');
    }
}

// ========== 9.4. 长时间相隔时间显示 ==========
function formatDateDivider(timestamp) {
    const date = new Date(timestamp * 1000);
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const msgDate = new Date(date.getFullYear(), date.getMonth(), date.getDate());
    const diffDays = Math.floor((today - msgDate) / (1000 * 60 * 60 * 24));
    const timeStr = date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    if (diffDays === 0) return `今天 ${timeStr}`;
    if (diffDays === 1) return `昨天 ${timeStr}`;
    if (diffDays === 2) return `前天 ${timeStr}`;
    return `${date.getMonth()+1}/${date.getDate()} ${timeStr}`;
}


