// ========== 9.5. 聊天页顶部状态管理 ==========
// ========== 9.5.1. 配置项 ==========
// 干员状态显示配置（存储到 localStorage）
let operatorStatusDisplayConfig = {
    showMood: true,   // 默认显示情绪
    showSync: true,
    showLocation: false
};

function loadOperatorStatusDisplayConfig() {
    const saved = localStorage.getItem('operatorStatusDisplayConfig');
    if (saved) {
        try {
            const config = JSON.parse(saved);
            operatorStatusDisplayConfig = { ...operatorStatusDisplayConfig, ...config };
        } catch(e) {}
    }
    // 同步 UI 复选框
    const moodCb = document.getElementById('status-show-mood');
    const syncCb = document.getElementById('status-show-sync');
    const locationCb = document.getElementById('status-show-location');
    if (moodCb) moodCb.checked = operatorStatusDisplayConfig.showMood;
    if (syncCb) syncCb.checked = operatorStatusDisplayConfig.showSync;
    if (locationCb) locationCb.checked = operatorStatusDisplayConfig.showLocation;
}

function saveOperatorStatusDisplayConfig() {
    localStorage.setItem('operatorStatusDisplayConfig', JSON.stringify(operatorStatusDisplayConfig));
}

function updateOperatorStatusDisplayFromCheckboxes() {
    operatorStatusDisplayConfig.showMood = document.getElementById('status-show-mood').checked;
    operatorStatusDisplayConfig.showSync = document.getElementById('status-show-sync').checked;
    operatorStatusDisplayConfig.showLocation = document.getElementById('status-show-location').checked;
    saveOperatorStatusDisplayConfig();
}

// ========== 9.5.2. 顶部状态渲染 ==========
async function fetchAndUpdateOperatorStatus(operatorId) {
    try {
        // 获取干员详情（包含 mood, mood_value, sync_info, status, current_location）
        const detailRes = await fetch(`/operator/detail/${encodeURIComponent(operatorId)}`);
        if (!detailRes.ok) throw new Error('获取详情失败');
        const detail = await detailRes.json();

        // 获取配置中的额外同步信息（如果详情中 sync_info 已完整，此步可省略，但保留兼容）
        // 注意：/operator/detail 已返回 sync_info，无需额外请求
        const state = {
            mood: detail.mood || '未知',
            mood_value: detail.mood_value,
            sync: detail.sync_info?.text || '',
            location: detail.current_location || ''
        };
        updateChatOperatorStatus(state);
    } catch (e) {
        console.error('获取干员状态失败', e);
    }
}

function updateChatOperatorStatus(state) {
    const statusDiv = document.getElementById('operator-status');
    if (!statusDiv) return;
    if (!state || (!operatorStatusDisplayConfig.showMood && !operatorStatusDisplayConfig.showSync && !operatorStatusDisplayConfig.showLocation)) {
        statusDiv.innerHTML = '';
        return;
    }
    const parts = [];
    if (operatorStatusDisplayConfig.showMood && state.mood) {
        // 构造一个临时的 detail 对象，以便使用 getOperatorDisplayStatus
        const tempDetail = { mood: state.mood, mood_value: state.mood_value };
        const display = getOperatorDisplayStatus(tempDetail);
        parts.push(`${ZootIcons.html(display.icon)} ${display.text}`);
    }
    if (operatorStatusDisplayConfig.showSync && state.sync) {
        parts.push(`${ZootIcons.html('clipboard')} ${state.sync}`);
    }
    if (operatorStatusDisplayConfig.showLocation && state.location) {
        parts.push(`${ZootIcons.html('location')} ${state.location}`);
    }
    statusDiv.innerHTML = parts.join(' · ');
}

// ========== 9.5.3. 输入指示器 ==========
function renderConversationActivity(chatKey = getActiveChatKey()) {
    const indicator = document.getElementById('typing-indicator');
    const spinner = document.getElementById('chat-activity-spinner');
    const state = chatKey ? chatResponseStates.get(chatKey) : null;
    if (indicator) {
        if (chatKey && isChatKeyActive(chatKey) && state) {
            indicator.textContent = state.phase === 'typing' ? '对方正在输入中...' : '思考中...';
            indicator.classList.remove('hidden');
            indicator.style.display = '';
        } else {
            indicator.classList.add('hidden');
            indicator.style.display = '';
        }
    }
    const pollingActive = chatKey?.startsWith('private:') && privatePollingStates.get(chatKey)?.active;
    const groupActive = chatKey?.startsWith('group:') && (groupGenerationStates.get(chatKey) || 0) > 0;
    if (spinner) spinner.classList.toggle('hidden', !(chatKey && isChatKeyActive(chatKey) && (pollingActive || groupActive)));
}

function showTypingIndicator(chatKey = getActiveChatKey(), phase = 'thinking') {
    if (!chatKey) return;
    const oldState = chatResponseStates.get(chatKey);
    if (oldState?.timer) clearTimeout(oldState.timer);
    const state = { phase, timer: null };
    state.timer = setTimeout(() => hideTypingIndicator(chatKey), TYPING_TIMEOUT);
    chatResponseStates.set(chatKey, state);
    renderConversationActivity(chatKey);
}

function hideTypingIndicator(chatKey = getActiveChatKey()) {
    if (!chatKey) return;
    const state = chatResponseStates.get(chatKey);
    if (state?.timer) clearTimeout(state.timer);
    chatResponseStates.delete(chatKey);
    renderConversationActivity(chatKey);
}

function finishTypingAfterRender(chatKey = getActiveChatKey()) {
    if (!chatKey) return;
    requestAnimationFrame(() => requestAnimationFrame(() => hideTypingIndicator(chatKey)));
}

function setPrivatePollingState(operatorId, active, phase = 'idle') {
    const chatKey = `private:${String(operatorId)}`;
    privatePollingStates.set(chatKey, { active: Boolean(active), phase });
    if (active && phase === 'generating') showTypingIndicator(chatKey, 'thinking');
    renderConversationActivity(chatKey);
}

function setGroupGenerationState(groupId, activeCount, serverConfirmed = false) {
    const chatKey = `group:${String(groupId)}`;
    const count = Math.max(0, Number(activeCount) || 0);
    const oldTimer = groupGenerationTimers.get(chatKey);
    if (oldTimer) clearTimeout(oldTimer);
    if (count) {
        groupGenerationStates.set(chatKey, count);
        groupGenerationTimers.set(chatKey, setTimeout(() => {
            discardPriestessMentionGroupConfirmations(groupId);
            setGroupGenerationState(groupId, 0);
        }, TYPING_TIMEOUT));
    } else {
        groupGenerationStates.delete(chatKey);
        groupGenerationTimers.delete(chatKey);
        if (serverConfirmed) confirmPriestessMentionGroupMessages(groupId);
        else discardPriestessMentionGroupConfirmations(groupId);
    }
    if (!count) finishTypingAfterRender(chatKey);
    renderConversationActivity(chatKey);
}

async function refreshPrivatePollingState(operatorId) {
    try {
        const res = await fetch(`/private/polling_status?operator_id=${encodeURIComponent(operatorId)}`);
        if (!res.ok) return;
        const data = await res.json();
        setPrivatePollingState(operatorId, data.active, data.phase);
    } catch (error) {
        console.warn('[轮询状态] 刷新失败', error);
    }
}

// ========== 9.6. 自定义聊天背景 ==========
// ========== 9.6.1. 聊天设置处自定义 ==========
// 获取当前聊天的背景（私聊用干员ID，群聊用群ID）
function getChatBgKey(chatType, chatId) {
    return chatType === 'private' ? `chatBg_private_${chatId}` : `chatBg_group_${chatId}`;
}

function getChatBg(chatType, chatId) {
    // 优先获取独立背景
    const key = getChatBgKey(chatType, chatId);
    const custom = localStorage.getItem(key);
    if (custom) return custom;
    // 降级到全局背景
    return localStorage.getItem('chatBg_global') || '';
}

function setChatBg(chatType, chatId, url) {
    const key = getChatBgKey(chatType, chatId);
    localStorage.setItem(key, url);
    applyChatBg(chatType, chatId);
}

function applyChatBg(chatType, chatId) {
    const url = getChatBg(chatType, chatId);
    const chatContainer = document.getElementById('page-chat-detail');
    if (!chatContainer) return;
    if (url) {
        chatContainer.style.backgroundImage = `url('${url}')`;
        chatContainer.style.backgroundSize = 'cover';
        chatContainer.style.backgroundPosition = 'center';
        chatContainer.style.backgroundAttachment = 'fixed';
    } else {
        chatContainer.style.backgroundImage = '';
        chatContainer.style.backgroundColor = 'var(--bg-color)';
    }
}

function openChatBgPicker(chatType, chatId) {
    const picker = document.getElementById('chatBgPicker');
    const grid = document.getElementById('chatBgGrid');
    if (!picker || !grid) return;

    grid.innerHTML = '<div style="text-align:center; padding:20px;">加载中...</div>';
    openBottomSheet('chatBgPicker');
    picker.dataset.chatType = chatType;
    picker.dataset.chatId = chatId;

    loadChatBgPicker(chatType, chatId, grid);
}

async function loadChatBgPicker(chatType, chatId, grid) {
    const currentBg = getChatBg(chatType, chatId);
    // 预设背景（共用个人页背景）
    const presetBanners = [];
    for (let i = 1; i <= 12; i++) {
        const url = `/static/backgrounds/banner_${i}.webp`;
        presetBanners.push({ url, type: 'preset' });
    }
    // 自定义背景（全局或独立？独立背景的 owner_id 为 chatId）
    let customBanners = [];
    try {
        const ownerId = chatType === 'private' ? `private_${chatId}` : `group_${chatId}`;
        const result = await CUSTOM_IMAGE_API.list('chat_bg', ownerId);
        customBanners = (result.data || []).map(item => ({
            url: item.url,
            type: 'custom',
            imageId: item.id,
        }));
    } catch (e) {
        console.warn('加载自定义聊天背景失败', e);
    }
    const allBanners = [...presetBanners, ...customBanners];

    let html = '';
    // 添加“无背景”选项
    html += `
        <div class="bg-option ${!currentBg ? 'selected' : ''}"
             style="height: 80px; border-radius: 8px; border: 2px solid ${!currentBg ? '#ffd700' : 'transparent'}; display: flex; align-items: center; justify-content: center; background: rgba(255,255,255,0.05); cursor: pointer; font-size: 14px; color: #aaa;"
             data-url="" data-type="clear">
            无背景
        </div>
    `;
    allBanners.forEach(banner => {
        const isSelected = banner.url === currentBg;
        html += `
            <div class="bg-option ${isSelected ? 'selected' : ''}"
                 style="background-image: url('${banner.url}'); background-size: cover; background-position: center; height: 80px; border-radius: 8px; border: 2px solid ${isSelected ? '#ffd700' : 'transparent'}; cursor: pointer; position: relative;"
                 data-url="${banner.url}"
                 data-type="${banner.type}"
                 data-image-id="${banner.imageId || ''}">
                ${banner.type === 'custom' ? '<span style="position:absolute;top:4px;right:4px;background:#ffd700;padding:0 6px;border-radius:8px;font-size:10px;color:#333;">C</span>' : ''}
            </div>
        `;
    });
    // 上传按钮
    html += `
        <div class="bg-option upload-btn"
             style="height: 80px; border-radius: 8px; border: 2px dashed rgba(255,255,255,0.3); display: flex; align-items: center; justify-content: center; font-size: 16px; color: #aaa; cursor: pointer; background: rgba(255,255,255,0.05);">
            + 上传
        </div>
    `;
    grid.innerHTML = html;

    // 绑定点击事件
    grid.querySelectorAll('.bg-option[data-url]').forEach(el => {
        el.addEventListener('click', () => {
            const url = el.dataset.url;
            const type = el.dataset.type;
            const chatType = document.getElementById('chatBgPicker').dataset.chatType;
            const chatId = document.getElementById('chatBgPicker').dataset.chatId;
            if (type === 'clear') {
                // 清除背景
                const key = getChatBgKey(chatType, chatId);
                localStorage.removeItem(key);
                applyChatBg(chatType, chatId);
                closeChatBgPicker();
                return;
            }
            if (type === 'preset') {
                setChatBg(chatType, chatId, url);
                closeChatBgPicker();
            } else {
                // 自定义背景直接应用
                const key = getChatBgKey(chatType, chatId);
                localStorage.setItem(key, url);
                applyChatBg(chatType, chatId);
                closeChatBgPicker();
            }
        });
    });

    // 上传按钮
    const uploadBtn = grid.querySelector('.upload-btn');
    if (uploadBtn) {
        uploadBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'image/*';
            input.onchange = async (ev) => {
                const file = ev.target.files[0];
                if (!file) return;
                const chatType = document.getElementById('chatBgPicker').dataset.chatType;
                const chatId = document.getElementById('chatBgPicker').dataset.chatId;
                const ownerId = chatType === 'private' ? `private_${chatId}` : `group_${chatId}`;
                try {
                    const result = await CUSTOM_IMAGE_API.upload('chat_bg', file, ownerId);
                    if (result.status === 'ok') {
                        loadChatBgPicker(chatType, chatId, grid);
                        setTimeout(() => {
                            const newUrl = result.data.url;
                            const key = getChatBgKey(chatType, chatId);
                            localStorage.setItem(key, newUrl);
                            applyChatBg(chatType, chatId);
                            closeChatBgPicker();
                        }, 100);
                    } else {
                        alert('上传失败');
                    }
                } catch (err) {
                    alert('上传失败: ' + err.message);
                }
            };
            input.click();
        });
    }
}

function closeChatBgPicker() {
    closeBottomSheet('chatBgPicker');
}

// ========== 9.6.2. 全局自定义 ==========
function openGlobalChatBgPicker() {
    // 使用 chat_bg 类型，owner_id 为 'global'
    const picker = document.getElementById('chatBgPicker');
    const grid = document.getElementById('chatBgGrid');
    if (!picker || !grid) return;

    grid.innerHTML = '<div style="text-align:center; padding:20px;">加载中...</div>';
    openBottomSheet('chatBgPicker');
    picker.dataset.chatType = 'global';
    picker.dataset.chatId = 'global';

    // 复用加载函数，但传入 owner_id = 'global'
    // 需要修改 loadChatBgPicker 支持 owner_id 参数，或单独处理
    loadChatBgPicker('global', 'global', grid);
}

function clearGlobalChatBg() {
    localStorage.removeItem('chatBg_global');
    // 刷新当前聊天页背景（如果有）
    const chatContainer = document.getElementById('page-chat-detail');
    if (chatContainer) {
        chatContainer.style.backgroundImage = '';
        chatContainer.style.backgroundColor = 'var(--bg-color)';
    }
    alert('已清除全局聊天背景');
}


// ========== 10. 附加设定 ==========
async function loadExtraPrompt(opId) {
    const extraInput = document.getElementById('extra-prompt');
    if (!extraInput) return;
    try {
        const res = await fetch(`/extra_prompt/${opId}`);
        const data = await res.json();
        extraInput.value = data.extra_prompt;
    } catch (e) {
        console.error(e);
    }
}

if (saveExtra) {
    saveExtra.onclick = async () => {
        if (!currentOperatorId) {
            alert('未选择干员，请先进入干员详情页');
            return;
        }
        const encodedId = encodeOperatorId(currentOperatorId);
        console.log('保存附加设定，encodedId:', encodedId);
        const extra = document.getElementById('extra-prompt').value;
        try {
            const res = await fetch(`/extra_prompt/${encodedId}`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ extra_prompt: extra })
            });
            if (res.ok) {
                alert('附加设定保存成功');
                // 重新加载显示，避免显示 undefined
                const reloadRes = await fetch(`/extra_prompt/${encodedId}`);
                const reloadData = await reloadRes.json();
                document.getElementById('extra-prompt').value = reloadData.extra_prompt || '';
            } else {
                const err = await res.json();
                alert('保存失败: ' + (err.detail || '未知错误'));
            }
        } catch (e) {
            console.error('保存扩展设定出错', e);
            alert('保存出错: ' + e.message);
        }
    };
}

function goToExtraPrompt(operatorId) {
    console.log('goToExtraPrompt called with operatorId:', operatorId);
    if (!operatorId || operatorId === 'custom') {
        alert('干员ID无效，请从联系人页重新进入');
        return;
    }
    currentOperatorId = operatorId;
    showPage('operator-extra');
}

// ========== 10.1. 干员对话偏向 ==========
async function loadOperatorChatBias(operatorId) {
    const encodedId = encodeOperatorId(operatorId);
    try {
        const res = await fetch(`/operator/config/${encodedId}`);
        const config = await res.json();
        const bias = normalizeOperatorChatBias(config.global_chat_bias);

        const lengthSelect = document.getElementById('bias-reply-length');
        const segmentsSlider = document.getElementById('bias-segments');
        const segmentsSpan = document.getElementById('segments-value');
        const strictnessSlider = document.getElementById('bias-strictness');
        const strictnessSpan = document.getElementById('strictness-value');
        const actionSlider = document.getElementById('bias-action-ratio');
        const actionSpan = document.getElementById('action-value');
        const emojiSlider = document.getElementById('bias-emoji-freq');
        const emojiSpan = document.getElementById('emoji-value');

        if (lengthSelect) lengthSelect.value = bias.reply_length;
        const customLength = document.getElementById('bias-custom-length');
        if (customLength) customLength.value = bias.reply_length_custom_chars ?? 100;
        updateReplyLengthCustomUI();
        if (segmentsSlider) {
            segmentsSlider.value = bias.segments;
            if (segmentsSpan) segmentsSpan.textContent = formatSegmentPreference(bias.segments);
        }
        if (strictnessSlider) {
            strictnessSlider.value = bias.personality_strictness;
            if (strictnessSpan) strictnessSpan.textContent = bias.personality_strictness;
        }
        if (actionSlider) {
            actionSlider.value = bias.action_desc_ratio;
            if (actionSpan) actionSpan.textContent = `${Math.round(bias.action_desc_ratio * 100)}%`;
        }
        if (emojiSlider) {
            emojiSlider.value = bias.emoji_frequency;
            if (emojiSpan) emojiSpan.textContent = bias.emoji_frequency;
        }
    } catch (e) {
        console.error('加载干员偏向失败', e);
    }
}

function bindAutoSaveChatBias(operatorId) {
    let saveTimer = null;
    const debouncedSave = () => {
        if (saveTimer) clearTimeout(saveTimer);
        saveTimer = setTimeout(() => saveOperatorChatBias(operatorId), 500);
    };

    const lengthSelect = document.getElementById('bias-reply-length');
    if (lengthSelect) lengthSelect.addEventListener('change', () => { updateReplyLengthCustomUI(); debouncedSave(); });
    document.getElementById('bias-custom-length')?.addEventListener('input', debouncedSave);

    const segmentsSlider = document.getElementById('bias-segments');
    if (segmentsSlider) {
        segmentsSlider.addEventListener('input', () => {
            const span = document.getElementById('segments-value');
            if (span) span.textContent = formatSegmentPreference(segmentsSlider.value);
            debouncedSave();
        });
    }

    const strictnessSlider = document.getElementById('bias-strictness');
    if (strictnessSlider) {
        strictnessSlider.addEventListener('input', () => {
            const span = document.getElementById('strictness-value');
            if (span) span.textContent = strictnessSlider.value;
            debouncedSave();
        });
    }

    const actionSlider = document.getElementById('bias-action-ratio');
    if (actionSlider) {
        actionSlider.addEventListener('input', () => {
            const span = document.getElementById('action-value');
            if (span) span.textContent = `${Math.round(Number(actionSlider.value) * 100)}%`;
            debouncedSave();
        });
    }

    const emojiSlider = document.getElementById('bias-emoji-freq');
    if (emojiSlider) {
        emojiSlider.addEventListener('input', () => {
            const span = document.getElementById('emoji-value');
            if (span) span.textContent = emojiSlider.value;
            debouncedSave();
        });
    }
}

async function saveOperatorChatBias(operatorId) {
    const lengthSelect = document.getElementById('bias-reply-length');
    const segmentsSlider = document.getElementById('bias-segments');
    const strictnessSlider = document.getElementById('bias-strictness');
    const actionSlider = document.getElementById('bias-action-ratio');
    const emojiSlider = document.getElementById('bias-emoji-freq');

    let reply_length = lengthSelect ? lengthSelect.value : "unlimited";
    const validLengths = ['short', 'medium', 'long', 'unlimited', 'custom'];
    if (!validLengths.includes(reply_length)) reply_length = "unlimited";

    let segments = segmentsSlider ? parseInt(segmentsSlider.value) : 0;
    if (isNaN(segments) || segments < 0) segments = 0;
    if (segments > 10) segments = 10;

    let personality_strictness = strictnessSlider ? parseFloat(strictnessSlider.value) : 1;
    let action_desc_ratio = actionSlider ? parseFloat(actionSlider.value) : 0.45;
    let emoji_frequency = emojiSlider ? parseFloat(emojiSlider.value) : 0.15;

    personality_strictness = Math.min(3, Math.max(0, Math.round(personality_strictness)));
    action_desc_ratio = Math.min(1, Math.max(0, action_desc_ratio));
    emoji_frequency = Math.min(1, Math.max(0, emoji_frequency));
    personality_strictness = Math.round(personality_strictness * 10) / 10;
    action_desc_ratio = Math.round(action_desc_ratio * 100) / 100;
    emoji_frequency = Math.round(emoji_frequency * 100) / 100;

    const biasData = {
        reply_length: reply_length,
        reply_length_custom_chars: Math.max(20, Math.min(5000, parseInt(document.getElementById('bias-custom-length')?.value) || 100)),
        segments: segments,
        personality_strictness: personality_strictness,
        action_desc_ratio: action_desc_ratio,
        emoji_frequency: emoji_frequency
    };

    console.log('保存对话偏向数据:', biasData);

    const encodedId = encodeURIComponent(operatorId);
    try {
        const response = await fetch(`/operator/chat_bias/${encodedId}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ global_chat_bias: biasData })
        });
        if (!response.ok) {
            const errorText = await response.text();
            console.error('保存对话偏向失败', errorText);
            alert('保存失败：' + errorText);
            return;
        }
        console.log('对话偏向保存成功');
    } catch (e) {
        console.error('保存对话偏向失败', e);
        alert('保存出错：' + e.message);
    }
}


