// ========== 11.1. 底部点阵导航栏背景 ==========
class BottomBarMask {
    constructor() {
        this.canvas = document.getElementById('bottom-mask-canvas');
        this.container = document.getElementById('bottom-mask-container');
        if (!this.canvas || !this.container) {
            console.error('底部栏蒙版容器或canvas不存在');
            return;
        }

        this.ctx = this.canvas.getContext('2d');
        this.offCanvas = null;
        this.offCtx = null;
        this.imageReady = false;
        this.animationId = null;
        this.startTime = null;

        // 配置参数
        this.config = {
            dotSpacing: 4,
            dotRadius: 2.0,
            initRotation: 50,
            rotationSpeed: 0.0012,
            translateSpeedX: 0.0005,
            translateSpeedY: 0.00045,
            translateAmpX: 22,
            translateAmpY: 16,
            breatheMin: 0.55,
            breatheMax: 0.98,
            breatheSpeed: 0.008,
            overallOpacity: 0.55,  // 日间默认
            imageFilter: "grayscale(1) brightness(0.55) contrast(1.5)"
        };

        // 动态状态
        this.currentRotation = this.config.initRotation * Math.PI / 180;
        this.offsetX = 0;
        this.offsetY = 0;
        this.currentAlpha = (this.config.breatheMin + this.config.breatheMax) / 2;

        this.canvasWidth = 0;
        this.canvasHeight = 0;
        this.dotsPositions = [];
        this.barRect = { x: 0, y: 0, w: 0, h: 0 };

        // 挂载到全局便于调试
        window.bottomMask = this;
    }

    // 获取底部导航栏位置和尺寸
    updateBarRect() {
        const bottomNav = document.querySelector('.bottom-nav');
        if (!bottomNav) {
            console.warn('未找到 .bottom-nav');
            return false;
        }
        const rect = bottomNav.getBoundingClientRect();
        if (rect.width === 0 || rect.height === 0) {
            console.warn('底部栏尺寸为0');
            return false;
        }
        this.barRect = {
            x: rect.left,
            y: rect.top,
            w: rect.width,
            h: rect.height
        };
        // 更新容器样式
        this.container.style.position = 'fixed';
        this.container.style.bottom = '0px';
        this.container.style.left = rect.left + 'px';
        this.container.style.width = rect.width + 'px';
        this.container.style.height = rect.height + 'px';
        return true;
    }

    updateCanvasSize() {
        if (!this.updateBarRect()) return;
        // 使用设备像素比确保清晰，但点阵不需要太清晰，直接用 CSS 尺寸作为物理尺寸
        this.canvasWidth = this.barRect.w;
        this.canvasHeight = this.barRect.h;
        this.canvas.width = this.canvasWidth;
        this.canvas.height = this.canvasHeight;
        console.log(`canvas 尺寸设为: ${this.canvasWidth}x${this.canvasHeight}`);
        this.generateDotPositions();
    }

    generateDotPositions() {
        this.dotsPositions = [];
        const diagonal = Math.sqrt(this.canvasWidth * this.canvasWidth + this.canvasHeight * this.canvasHeight);
        const gridRadius = diagonal * 1.5;
        const startX = -gridRadius;
        const endX = this.canvasWidth + gridRadius;
        const startY = -gridRadius;
        const endY = this.canvasHeight + gridRadius;

        const cols = Math.ceil((endX - startX) / this.config.dotSpacing);
        const rows = Math.ceil((endY - startY) / this.config.dotSpacing);

        for (let i = 0; i <= cols; i++) {
            const x = startX + i * this.config.dotSpacing;
            if (x > endX) continue;
            for (let j = 0; j <= rows; j++) {
                const y = startY + j * this.config.dotSpacing;
                if (y > endY) continue;
                this.dotsPositions.push({ x, y });
            }
        }
        console.log(`生成了 ${this.dotsPositions.length} 个点`);
    }

    getTransform() {
        const centerX = this.canvasWidth / 2;
        const centerY = this.canvasHeight / 2;
        const tx = centerX + this.offsetX;
        const ty = centerY + this.offsetY;
        const cos = Math.cos(this.currentRotation);
        const sin = Math.sin(this.currentRotation);
        return (px, py) => {
            const dx = px - centerX;
            const dy = py - centerY;
            const x = dx * cos - dy * sin + tx;
            const y = dx * sin + dy * cos + ty;
            return { x, y };
        };
    }

    // 加载个人页背景图
    async loadBackgroundImage() {
        return new Promise((resolve) => {
            const img = new Image();
            // 允许跨域（如果图片来自同源则不需要）
            img.crossOrigin = "Anonymous";
            let bgUrl = localStorage.getItem('profileBanner');
            if (!bgUrl || bgUrl === '') {
                bgUrl = '/static/backgrounds/default_banner.webp';
            }
            // 处理相对路径
            if (bgUrl.startsWith('/')) {
                bgUrl = window.location.origin + bgUrl;
            }
            img.src = bgUrl;
            img.onload = () => {
                this.offCanvas = document.createElement('canvas');
                this.offCanvas.width = this.canvasWidth;
                this.offCanvas.height = this.canvasHeight;
                this.offCtx = this.offCanvas.getContext('2d');

                // cover 模式绘制
                const imgAspect = img.width / img.height;
                const canvasAspect = this.canvasWidth / this.canvasHeight;
                let drawWidth, drawHeight, offsetX_img, offsetY_img;
                if (imgAspect > canvasAspect) {
                    drawHeight = this.canvasHeight;
                    drawWidth = drawHeight * imgAspect;
                    offsetX_img = (this.canvasWidth - drawWidth) / 2;
                    offsetY_img = 0;
                } else {
                    drawWidth = this.canvasWidth;
                    drawHeight = drawWidth / imgAspect;
                    offsetX_img = 0;
                    offsetY_img = (this.canvasHeight - drawHeight) / 2;
                }
                this.offCtx.drawImage(img, offsetX_img, offsetY_img, drawWidth, drawHeight);

                // 应用滤镜
                this.offCtx.filter = this.config.imageFilter;
                this.offCtx.drawImage(this.offCanvas, 0, 0);
                this.offCtx.filter = 'none';

                this.imageReady = true;
                console.log('底部栏背景图片加载成功');
                resolve();
            };
            img.onerror = (err) => {
                console.warn('个人页背景图加载失败，使用内置纹理', err);
                this.generateFallbackImage(resolve);
            };
        });
    }

    generateFallbackImage(resolve) {
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = this.canvasWidth;
        tempCanvas.height = this.canvasHeight;
        const tempCtx = tempCanvas.getContext('2d');
        // 绘制渐变纹理
        const grad = tempCtx.createLinearGradient(0, 0, this.canvasWidth, this.canvasHeight);
        grad.addColorStop(0, '#4a7db5');
        grad.addColorStop(1, '#2a2f3a');
        tempCtx.fillStyle = grad;
        tempCtx.fillRect(0, 0, this.canvasWidth, this.canvasHeight);
        // 添加噪点
        for (let i = 0; i < 500; i++) {
            tempCtx.fillStyle = `rgba(255,255,255,${Math.random() * 0.3})`;
            tempCtx.fillRect(Math.random() * this.canvasWidth, Math.random() * this.canvasHeight, 1, 1);
        }
        this.offCanvas = tempCanvas;
        this.offCtx = tempCtx;
        this.offCtx.filter = this.config.imageFilter;
        this.offCtx.drawImage(this.offCanvas, 0, 0);
        this.offCtx.filter = 'none';
        this.imageReady = true;
        console.log('使用内置纹理');
        resolve();
    }

    drawDots() {
        if (!this.imageReady || !this.offCtx) {
            // 调试：绘制红色测试矩形
            this.ctx.fillStyle = 'red';
            this.ctx.fillRect(0, 0, 50, 50);
            return;
        }
        let imgData = null;
        try {
            imgData = this.offCtx.getImageData(0, 0, this.canvasWidth, this.canvasHeight);
        } catch(e) {
            console.warn('获取图像数据失败', e);
            // fallback: 绘制白色点
            this.drawFallbackDots();
            return;
        }
        const data = imgData.data;
        const transform = this.getTransform();
        const finalAlpha = this.currentAlpha * this.config.overallOpacity;
        this.ctx.globalAlpha = finalAlpha;

        let drawnCount = 0;
        for (let i = 0; i < this.dotsPositions.length; i++) {
            const p = this.dotsPositions[i];
            const screen = transform(p.x, p.y);
            if (screen.x + this.config.dotRadius < 0 || screen.x - this.config.dotRadius > this.canvasWidth ||
                screen.y + this.config.dotRadius < 0 || screen.y - this.config.dotRadius > this.canvasHeight) {
                continue;
            }
            const sx = Math.floor(screen.x);
            const sy = Math.floor(screen.y);
            if (sx < 0 || sx >= this.canvasWidth || sy < 0 || sy >= this.canvasHeight) continue;
            const idx = (sy * this.canvasWidth + sx) * 4;
            const r = data[idx];
            const g = data[idx+1];
            const b = data[idx+2];
            this.ctx.fillStyle = `rgb(${r}, ${g}, ${b})`;
            this.ctx.beginPath();
            this.ctx.arc(screen.x, screen.y, this.config.dotRadius, 0, Math.PI * 2);
            this.ctx.fill();
            drawnCount++;
        }
        this.ctx.globalAlpha = 1.0;
        if (drawnCount === 0) {
            console.warn('没有绘制任何点，请检查点阵生成或图片数据');
        }
    }

    drawFallbackDots() {
        const transform = this.getTransform();
        const finalAlpha = this.currentAlpha * this.config.overallOpacity;
        this.ctx.globalAlpha = finalAlpha;
        for (let i = 0; i < this.dotsPositions.length; i++) {
            const p = this.dotsPositions[i];
            const screen = transform(p.x, p.y);
            if (screen.x + this.config.dotRadius < 0 || screen.x - this.config.dotRadius > this.canvasWidth ||
                screen.y + this.config.dotRadius < 0 || screen.y - this.config.dotRadius > this.canvasHeight) {
                continue;
            }
            this.ctx.fillStyle = '#ffffff';
            this.ctx.beginPath();
            this.ctx.arc(screen.x, screen.y, this.config.dotRadius, 0, Math.PI * 2);
            this.ctx.fill();
        }
        this.ctx.globalAlpha = 1.0;
    }

    updateAnimationParams(elapsed) {
        const breathe = (Math.sin(elapsed * this.config.breatheSpeed) + 1) / 2;
        this.currentAlpha = this.config.breatheMin + breathe * (this.config.breatheMax - this.config.breatheMin);
        this.currentRotation = (this.config.initRotation * Math.PI / 180) + (elapsed * this.config.rotationSpeed);
        this.offsetX = Math.sin(elapsed * this.config.translateSpeedX) * this.config.translateAmpX;
        this.offsetY = Math.cos(elapsed * this.config.translateSpeedY * 0.93) * this.config.translateAmpY;
    }

    render(nowMs) {
        if (!this.startTime) this.startTime = nowMs;
        const elapsed = (nowMs - this.startTime) / 1000;
        this.updateAnimationParams(elapsed);
        this.ctx.clearRect(0, 0, this.canvasWidth, this.canvasHeight);
        this.drawDots();
        this.animationId = requestAnimationFrame((t) => this.render(t));
    }

    async start() {
        // 等待 DOM 完全渲染
        await new Promise(resolve => setTimeout(resolve, 200));
        this.updateCanvasSize();
        await this.loadBackgroundImage();
        this.startTime = null;
        this.render(performance.now());

        window.addEventListener('resize', () => this.handleResize());
        window.addEventListener('orientationchange', () => setTimeout(() => this.handleResize(), 100));
        document.addEventListener('themeChanged', (e) => this.updateTheme(e.detail.theme, e.detail.scheme));
        console.log('底部栏蒙版已启动');
    }

    handleResize() {
        this.updateCanvasSize();
        this.loadBackgroundImage().then(() => {});
    }

    updateTheme(theme, scheme) {
        if (theme === 'dark') {
            this.config.overallOpacity = 0.15;  // 更淡
            this.config.imageFilter = "grayscale(1) brightness(0.35) contrast(1.6)";
        } else {
            this.config.overallOpacity = 0.25;  // 更淡
            this.config.imageFilter = "grayscale(1) brightness(0.55) contrast(1.5)";
        }
        // 重新加载图片
        this.loadBackgroundImage().then(() => {});
    }
}

// 全局初始化函数
function initBottomMask() {
    if (window.bottomMask) return;
    const mask = new BottomBarMask();
    mask.start();
}

// ========== 11.2. 全局时区设置 ==========
let currentGlobalTimezone = null;

async function loadGlobalTimezone() {
    try {
        const res = await fetch('/config/timezone');
        if (res.ok) {
            const data = await res.json();
            currentGlobalTimezone = data.timezone;
            const select = document.getElementById('global-timezone-select');
            if (select) select.value = currentGlobalTimezone;
        }
    } catch (e) {
        console.error('加载全局时区失败', e);
    }
}

async function saveGlobalTimezone() {
    const select = document.getElementById('global-timezone-select');
    if (!select) return;
    const tz = select.value;
    try {
        const res = await fetch('/config/timezone', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ timezone: tz })
        });
        if (res.ok) {
            alert('时区已保存，刷新页面后生效');
            currentGlobalTimezone = tz;
        } else {
            alert('保存失败');
        }
    } catch (e) {
        alert('保存失败');
    }
}

// 修改 formatTimestamp 函数，使用全局时区（如果已设置）
// 如果当前浏览器时区与全局时区不同，需要转换显示
function formatTimestamp(timestamp, tz = null) {
    const date = new Date(timestamp * 1000);
    const timezone = tz || currentGlobalTimezone;
    if (timezone && typeof Intl !== 'undefined' && Intl.DateTimeFormat) {
        try {
            const options = { hour12: timeFormat !== '24', hour: '2-digit', minute: '2-digit', second: '2-digit' };
            if (timeFormat === '24') options.hour12 = false;
            return new Intl.DateTimeFormat('zh-CN', {
                timeZone: timezone,
                year: 'numeric', month: '2-digit', day: '2-digit',
                hour: '2-digit', minute: '2-digit', second: '2-digit',
                hour12: timeFormat !== '24'
            }).format(date);
        } catch(e) {
            console.warn('时区转换失败', e);
            return date.toLocaleTimeString([], { hour12: timeFormat !== '24' });
        }
    }
    if (timeFormat === '24') {
        return date.toTimeString().slice(0, 8);
    } else {
        let hours = date.getHours();
        const minutes = date.getMinutes();
        const seconds = date.getSeconds();
        const ampm = hours >= 12 ? 'PM' : 'AM';
        hours = hours % 12 || 12;
        return `${hours}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')} ${ampm}`;
    }
}

function getChatListDateParts(timestamp, timezone = currentGlobalTimezone) {
    const date = new Date(Number(timestamp) * 1000);
    if (Number.isNaN(date.getTime())) return null;
    if (timezone && typeof Intl !== 'undefined' && Intl.DateTimeFormat) {
        try {
            const formatter = new Intl.DateTimeFormat('zh-CN-u-nu-latn', {
                timeZone: timezone,
                year: 'numeric',
                month: '2-digit',
                day: '2-digit',
                hour: '2-digit',
                minute: '2-digit',
                hourCycle: 'h23'
            });
            const values = {};
            formatter.formatToParts(date).forEach(part => {
                if (part.type !== 'literal') values[part.type] = Number(part.value);
            });
            return {
                year: values.year,
                month: values.month,
                day: values.day,
                hour: values.hour,
                minute: values.minute
            };
        } catch (error) {
            console.warn('聊天列表时区转换失败', error);
        }
    }
    return {
        year: date.getFullYear(),
        month: date.getMonth() + 1,
        day: date.getDate(),
        hour: date.getHours(),
        minute: date.getMinutes()
    };
}

function formatChatListTimestamp(timestamp, nowTimestamp = Date.now() / 1000, timezone = currentGlobalTimezone) {
    const message = getChatListDateParts(timestamp, timezone);
    const now = getChatListDateParts(nowTimestamp, timezone);
    if (!message || !now) return '';
    const messageDay = Date.UTC(message.year, message.month - 1, message.day) / 86400000;
    const currentDay = Date.UTC(now.year, now.month - 1, now.day) / 86400000;
    const dayDifference = currentDay - messageDay;
    const period = message.hour < 6
        ? '凌晨'
        : message.hour < 11 || (message.hour === 11 && message.minute < 30)
            ? '上午'
            : message.hour < 13
                ? '中午'
                : message.hour < 18 ? '下午' : '晚上';
    const clock = `${period}${String(message.hour).padStart(2, '0')}:${String(message.minute).padStart(2, '0')}`;
    if (dayDifference === 0) return clock;
    if (dayDifference === 1) return `昨日 ${clock}`;
    if (dayDifference === 2) return `前日 ${clock}`;
    const currentWeekday = new Date(Date.UTC(now.year, now.month - 1, now.day)).getUTCDay();
    const currentWeekStart = currentDay - ((currentWeekday + 6) % 7);
    if (messageDay >= currentWeekStart && messageDay < currentDay) {
        const weekday = new Date(Date.UTC(message.year, message.month - 1, message.day)).getUTCDay();
        return ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'][weekday];
    }
    return `${String(message.month).padStart(2, '0')}/${String(message.day).padStart(2, '0')}`;
}

// 修改 formatDateDivider 函数（如果需要）
function formatDateDivider(timestamp) {
    const date = new Date(timestamp * 1000);
    const tz = currentGlobalTimezone;
    let formatted;
    if (tz && typeof Intl !== 'undefined') {
        formatted = new Intl.DateTimeFormat('zh-CN', {
            timeZone: tz,
            year: 'numeric', month: '2-digit', day: '2-digit',
            hour: '2-digit', minute: '2-digit'
        }).format(date);
    } else {
        formatted = date.toLocaleString();
    }
    return formatted;
}



// ========== 12. 群组创建与管理 ==========
if (createGroupBtn) {
    createGroupBtn.onclick = () => {
        console.log('create-group clicked');
        showPage('create-group');
    };
}

if (modalCancel) {
    modalCancel.onclick = () => {
        hideModal('groupModal');
    };
}

if (modalConfirm) {
    modalConfirm.onclick = async () => {
        console.log('modal-confirm clicked');
        const checkboxes = document.querySelectorAll('#operator-checkboxes input[type=checkbox]:checked');
        if (checkboxes.length === 0) {
            showToast('请至少选择一名干员', 2600, 'warning');
            return;
        }
        const memberIds = Array.from(checkboxes).map(cb => cb.value);
        const tagsInput = document.getElementById('group-tags');
        const tags = tagsInput ? tagsInput.value.split(',').map(s => s.trim()).filter(s => s) : [];
        const groupName = document.getElementById('group-name').value.trim();
        const res = await fetch('/group/create', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                member_ids: memberIds,
                tags: tags,
                group_name: groupName
            })
        });
        if (!res.ok) {
            const err = await res.json();
            showToast(`创建群组失败：${err.detail || '未知错误'}`, 3200, 'error');
            return;
        }
        const data = await res.json();
        const memberNames = memberIds.map(id => {
            const op = operatorMap.get(id);
            return op ? op.codename : id;
        }).join(',');
        groups[data.group_id] = {
            group_id: data.group_id,
            ids: memberIds,
            names: memberNames,
            name: data.group_name,
            avatar: '',
            avatar_ref: ''
        };

        const newChat = {
            id: data.group_id,
            type: 'group',
            name: data.group_name || memberNames,
            lastMsg: '群组已创建',
            lastTime: Date.now() / 1000,
            avatar: '',
            avatar_ref: '',
            isPinned: false
        };
        chats.push(newChat);
        chatFilter = 'all';
        chatSearchQuery = '';
        document.querySelectorAll('.filter-tab').forEach(tab => {
            if (tab.dataset.filter === 'all') {
                tab.classList.add('active');
            } else {
                tab.classList.remove('active');
            }
        });
        if (searchInput) searchInput.value = '';
        renderChatList();

        currentGroupId = data.group_id;
        currentOperatorId = null;
        const titleEl = document.getElementById('chat-title');
        if (titleEl) titleEl.textContent = newChat.name;
        messages[`group:${data.group_id}`] = [];
        renderCurrentChat();
        showPage('chat-detail', false, false);

        document.getElementById('groupModal').style.display = 'none';
        checkboxes.forEach(cb => cb.checked = false);
        if (selectAllCheckbox) {
            selectAllCheckbox.checked = false;
            selectAllCheckbox.indeterminate = false;
        }
        disconnectWebSocket();
        connectWebSocket();
        restartPolling();
        alert('群组创建成功！');
    };
}

function renderCreateGroupMembers(filterText = '') {
    const container = document.getElementById('create-group-members');
    if (!container) return;

    // 过滤干员
    let filteredOps = operators;
    if (filterText) {
        const lower = filterText.toLowerCase();
        filteredOps = operators.filter(op =>
            op.codename.toLowerCase().includes(lower) ||
            op.id.toLowerCase().includes(lower)
        );
    }

    // 分组
    const grouped = {};
    filteredOps.forEach(op => {
        let firstChar = op.pinyin_initial || '#';
        if (!firstChar || !/[A-Z]/.test(firstChar)) firstChar = '#';
        if (!grouped[firstChar]) grouped[firstChar] = [];
        grouped[firstChar].push(op);
    });

    const sortedLetters = Object.keys(grouped).sort((a, b) => {
        if (a === '#') return 1;
        if (b === '#') return -1;
        return a.localeCompare(b);
    });

    container.innerHTML = sortedLetters.map(letter => `
        <div class="contact-letter">${letter}</div>
        ${grouped[letter].map(op => `
            <div class="contact-item" data-operator-id="${op.id}">
                <img src="${getOperatorAvatarUrl(op.id)}"
                     class="contact-avatar"
                     alt="${op.codename}"
                     onerror="this.onerror=null; this.src='/static/avatars/default.webp'">
                <div class="contact-name">${op.codename}</div>
                <input type="checkbox" class="member-checkbox" value="${op.id}">
            </div>
        `).join('')}
    `).join('');
}

async function openGroupConfigModal(groupId) {
    currentConfigGroupId = groupId;
    showModal('groupConfigModal');
    try {
        const res = await fetch(`/group/config/${groupId}`);
        if (!res.ok) {
            alert('获取群组配置失败');
            return;
        }
        const config = await res.json();

        if (groupConfigNameSpan) groupConfigNameSpan.textContent = config.name || groupId;
        if (groupConfigNameInput) groupConfigNameInput.value = config.name || '';
        if (groupConfigTagsInput) groupConfigTagsInput.value = (config.tags || []).join(', ');

        let html = '';
        // 从 operatorMap 获取所有干员（包括普瑞塞斯）
        const allOps = Array.from(operatorMap.values());
        allOps.forEach(op => {
            const checked = config.members.includes(op.id) ? 'checked' : '';
            html += `
                <div class="operator-item">
                    <label>
                        <input type="checkbox" value="${op.id}" ${checked}> ${op.codename}
                    </label>
                </div>
            `;
        });
        if (groupConfigMembersDiv) {
            groupConfigMembersDiv.innerHTML = html;
        }

        groupConfigModal.style.display = 'block';
    } catch (e) {
        console.error('加载群组配置失败', e);
        alert('加载群组配置失败');
    }
}

function closeGroupConfigModal() {
    hideModal('groupConfigModal');
    currentConfigGroupId = null;
}

async function saveGroupConfig() {
    const groupId = currentConfigGroupId;
    const name = groupConfigNameInput.value.trim();
    const tagsInput = groupConfigTagsInput.value;
    const tags = tagsInput.split(',').map(s => s.trim()).filter(s => s);
    const checkboxes = groupConfigMembersDiv.querySelectorAll('input[type=checkbox]:checked');
    const members = Array.from(checkboxes).map(cb => cb.value);

    if (members.length === 0) {
        alert('群组至少需要一名成员');
        return;
    }

    const config = {
        name: name,
        tags: tags,
        members: members
    };

    try {
        const res = await fetch(`/group/config/${groupId}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(config)
        });
        if (res.ok) {
            alert('群组配置保存成功');
            if (name) {
                const option = document.querySelector(`#group option[value="${groupId}"]`);
                if (option) {
                    option.text = `群组 ${name}`;
                }
                if (groups[groupId]) {
                    groups[groupId].name = name;
                }
            }
            closeGroupConfigModal();
        } else {
            const err = await res.json();
            alert('保存失败: ' + (err.detail || '未知错误'));
        }
    } catch (e) {
        alert('保存出错');
        console.error(e);
    }
}

// 渲染创建群聊的成员列表（按拼音首字母分组，带复选框），包含普瑞塞斯
function renderCreateGroupMemberList() {
    const container = document.getElementById('create-group-members');
    if (!container) return;
    const preselectedId = localStorage.getItem('preselectedMember');
    // 获取所有干员（从 operatorMap 获取全部，包括星标状态）
    let allOperators = Array.from(operatorMap.values());
    let preselectedOp = null;
    let otherOperators = allOperators.filter(op => {
        if (preselectedId && op.id === preselectedId) {
            preselectedOp = op;
            return false;
        }
        return true;
    });
    // 为每个干员添加星标标记
    const opsWithStar = otherOperators.map(op => ({
        ...op,
        starred: starMap.get(op.id) || false
    }));
    const starredOps = opsWithStar.filter(op => op.starred);
    const normalOps = opsWithStar.filter(op => !op.starred);
    // 对普通干员按拼音分组
    const grouped = {};
    normalOps.forEach(op => {
        let firstChar = op.pinyin_initial || '#';
        if (!firstChar || !/[A-Z]/.test(firstChar)) firstChar = '#';
        if (!grouped[firstChar]) grouped[firstChar] = [];
        grouped[firstChar].push(op);
    });
    const sortedLetters = Object.keys(grouped).sort((a, b) => {
        if (a === '#') return 1;
        if (b === '#') return -1;
        return a.localeCompare(b);
    });

    let html = '';
    // 预选干员（如果有）
    if (preselectedOp) {
        html += `<div class="contact-letter">预选干员</div>`;
        html += `
            <div class="contact-item preselected-item" data-operator-id="${preselectedOp.id}">
                <input type="checkbox" class="member-checkbox" value="${preselectedOp.id}" checked disabled style="opacity: 0.6; cursor: not-allowed;">
                <input type="hidden" class="preselected-hidden" value="${preselectedOp.id}">
                <img src="${getOperatorAvatarUrl(preselectedOp.id)}" class="contact-avatar" onerror="this.src='/static/avatars/default.webp'">
                <div class="contact-name">${preselectedOp.codename}</div>
                <div style="margin-left: auto; font-size: 12px; color: #999;">(默认已选)</div>
            </div>
        `;
    }
    // 星标干员分组
    if (starredOps.length) {
        html += `<div class="contact-letter"><img class="star-icon-small" src="/static/images/icon_star_unselected.png"> 星标干员</div>`;
        starredOps.forEach(op => {
            html += `
                <div class="contact-item" data-operator-id="${op.id}">
                    <input type="checkbox" class="member-checkbox" value="${op.id}" style="margin-right: 12px;">
                    <img src="${getOperatorAvatarUrl(op.id)}" class="contact-avatar" onerror="this.src='/static/avatars/default.webp'">
                    <div class="contact-name">${op.codename}</div>
                    <img class="star-icon-img" src="/static/images/icon_star_selected.png">
                </div>
            `;
        });
    }
    // 普通干员按字母分组
    sortedLetters.forEach(letter => {
        html += `<div class="contact-letter">${letter}</div>`;
        grouped[letter].forEach(op => {
            html += `
                <div class="contact-item" data-operator-id="${op.id}">
                    <input type="checkbox" class="member-checkbox" value="${op.id}" style="margin-right: 12px;">
                    <img src="${getOperatorAvatarUrl(op.id)}" class="contact-avatar" onerror="this.src='/static/avatars/default.webp'">
                    <div class="contact-name">${op.codename}</div>
                </div>
            `;
        });
    });
    container.innerHTML = html;
    // 更新索引栏
    setTimeout(() => {
        const { letters, hasStar, hasCustom } = getCreateGroupLetters();
        updateContactIndex(letters, hasStar, hasCustom);
    }, 10);
}

// 创建群聊页搜索过滤
function handleCreateGroupSearch(e) {
    const searchTerm = e.target.value.toLowerCase();
    const container = document.getElementById('create-group-members');
    if (!container) return;

    const items = container.querySelectorAll('.contact-item');
    const preselectedItem = container.querySelector('.preselected-item');

    // 预选干员始终显示
    if (preselectedItem) {
        preselectedItem.style.display = 'flex';
    }

    // 过滤其他干员
    items.forEach(item => {
        if (item === preselectedItem) return;
        const name = item.querySelector('.contact-name').textContent.toLowerCase();
        item.style.display = name.includes(searchTerm) ? 'flex' : 'none';
    });

    // 隐藏没有可见项的分组字母（使用 lettersEl 避免与解构变量名冲突）
    const lettersEl = container.querySelectorAll('.contact-letter');
    lettersEl.forEach(letter => {
        // 跳过预选干员的分组字母（如果有）
        if (letter.innerText === '预选干员') return;
        let nextItems = [];
        let next = letter.nextElementSibling;
        while (next && next.classList.contains('contact-item')) {
            nextItems.push(next);
            next = next.nextElementSibling;
        }
        const anyVisible = nextItems.some(item => item.style.display !== 'none');
        letter.style.display = anyVisible ? 'block' : 'none';
    });

    // 过滤完成后，更新索引栏
    const { letters, hasStar, hasCustom } = getCreateGroupLetters();
    updateContactIndex(letters, hasStar, hasCustom);
}

