// 全局点击关闭模态框
window.onclick = function(event) {
    const groupPicker = document.getElementById('groupAvatarPicker');
    // 如果点击的是选择器内部或选择器本身，不关闭
    if (groupPicker && (event.target === groupPicker || groupPicker.contains(event.target))) {
        return;
    }

    // 群聊头像选择器（如果有其他类似选择器也可在此添加）
    const groupAvatarPicker = document.getElementById('groupAvatarPicker');
    if (groupAvatarPicker && (event.target === groupAvatarPicker || groupAvatarPicker.contains(event.target))) {
        return;
    }

    // 特定模态框的关闭逻辑
    if (event.target === document.getElementById('groupConfigModal')) {
        closeGroupConfigModal();
        return;
    }
    if (event.target === document.getElementById('configModal')) {
        closeConfigModal();
        return;
    }
    if (event.target === document.getElementById('groupModal')) {
        hideModal('groupModal');
        return;
    }
    if (event.target === document.getElementById('setupWizardModal')) {
        hideModal('setupWizardModal');
        return;
    }

    // 通用处理：如果点击的是模态框背景（.modal 元素），关闭该模态框
    if (event.target.classList && event.target.classList.contains('modal')) {
        const modalId = event.target.id;
        if (modalId === 'underDevModal') {
            hideModal('underDevModal');
        } else {
            // 可扩展其他模态框
            hideModal(modalId);
        }
        return;
    }
};

