// ========== 20.1. 博士档案 ==========
function clearPersonaEditorBindings() {
    const binding = window._personaAutoSaveBinding;
    if (binding) {
        binding.elements.forEach(({ element, event }) => element?.removeEventListener(event, binding.handler));
        binding.handler.cancel?.();
        window._personaAutoSaveBinding = null;
    }
    const nameInput = document.getElementById('doctor-name');
    nameInput?.removeEventListener('change', window._personaNameChangeHandler);
    const editor = document.getElementById('doctor-base-profile-editor');
    editor?.removeEventListener('input', window._personaProfileInputHandler);
    const extra = document.getElementById('doctor-extra-prompt');
    extra?.removeEventListener('input', window._personaExtraInputHandler);
    window._editingPersonaBaseProfile = null;
    window._personaSaveChain = Promise.resolve();
}

function detachDoctorProfileBindings() {
    const nameInput = document.getElementById('doctor-name');
    const genderSelect = document.getElementById('doctor-gender-select');
    const extra = document.getElementById('doctor-extra-prompt');
    const editor = document.getElementById('doctor-base-profile-editor');
    nameInput?.removeEventListener('blur', handleDoctorNameChange);
    genderSelect?.removeEventListener('change', handleGenderChange);
    extra?.removeEventListener('input', window._debouncedSaveExtra);
    editor?.removeEventListener('input', window._doctorBaseSaveDebounce);
    editor?.removeEventListener('profile-data-changed', window._doctorBaseSaveDebounce);
    clearTimeout(window._doctorBaseSaveTimer);
    window._doctorBaseSaveDebounce?.cancel?.();
    window._debouncedSaveExtra?.cancel?.();
}

async function loadDoctorProfile() {
    // 检查是否在编辑人格
    const editingId = sessionStorage.getItem('editingPersonaId');
    if (editingId && editingId !== 'doctor') {
        // 加载人格数据而不是博士数据
        await loadPersonaForEditing(editingId);
        return;
    }
    clearPersonaEditorBindings();
    window._editingPersonaId = null;
    window._editingPersonaData = null;
    window._editingPersonaProfile = null;
    const titleEl = document.querySelector('#page-settings-profile .page-header h2');
    if (titleEl) titleEl.textContent = '博士档案';
    const saveBtn = document.getElementById('save-doctor-preferences');
    if (saveBtn) {
        saveBtn.textContent = '保存博士档案';
        saveBtn.onclick = async () => {
            await saveDoctorBaseProfile();
            await saveDoctorExtra();
            showTemporaryToast('✅ 博士档案已保存', 2000, 'success');
        };
    }
    const resetButton = document.getElementById('reset-doctor-profile-btn');
    if (resetButton) resetButton.style.display = '';
    try {
        const res = await fetch('/doctor/preferences');
        let data = null;
        let baseProfile = null;
        if (res.ok) {
            data = await res.json();
            const doctorNameInput = document.getElementById('doctor-name');
            if (doctorNameInput) doctorNameInput.value = data.doctor_name || '';
            const genderSelect = document.getElementById('doctor-gender-select');
            if (genderSelect) genderSelect.value = data.gender || '未知';
            baseProfile = data.base_profile || {};
        } else {
            const doctorNameInput = document.getElementById('doctor-name');
            if (doctorNameInput) doctorNameInput.value = localStorage.getItem('doctorName') || '';
            const genderSelect = document.getElementById('doctor-gender-select');
            if (genderSelect) genderSelect.value = localStorage.getItem('doctorGender') || '未知';
            const savedBase = localStorage.getItem('doctorBaseProfile');
            if (savedBase) {
                try { baseProfile = JSON.parse(savedBase); } catch(e) {}
            }
        }

        const defaultProfile = JSON.parse(JSON.stringify(DOCTOR_BASE_PROFILE_DEFAULT));
        // 清洗并补全（仅加载时使用）
        baseProfile = cleanDoctorBaseProfile(baseProfile, defaultProfile);

        // 加载扩展设定和年份
        const extraRes = await fetch('/extra_prompt/doctor');
        if (extraRes.ok) {
            const extraData = await extraRes.json();
            const extraPrompt = document.getElementById('doctor-extra-prompt');
            if (extraPrompt) extraPrompt.value = extraData.extra_prompt || '';
        }
        const yearRes = await fetch('/global/year');
        if (yearRes.ok) {
            const yearData = await yearRes.json();
            const yearInput = document.getElementById('global-year');
            if (yearInput) yearInput.value = yearData.year;
        }

        // 在 loadDoctorProfile 函数末尾添加
        const resetBtn = document.getElementById('reset-doctor-profile-btn');
        if (resetBtn) {
            resetBtn.removeEventListener('click', window._resetDoctorHandler);
            window._resetDoctorHandler = resetDoctorProfile;
            resetBtn.addEventListener('click', window._resetDoctorHandler);
        }

        window._doctorBaseProfile = baseProfile;

        const editorContainer = document.getElementById('doctor-base-profile-editor');
        if (editorContainer) {
            renderEditableProfile(editorContainer, baseProfile, [], 'doctor');
        }

        // 定义防抖保存函数
        window._doctorBaseSaveDebounce = (function() {
            let timer = null;
            const debounced = function() {
                clearTimeout(timer);
                timer = setTimeout(() => {
                    saveDoctorBaseProfile();
                }, 600);
            };
            debounced.cancel = () => clearTimeout(timer);
            return debounced;
        })();

        if (editorContainer) {
            editorContainer.removeEventListener('input', window._doctorBaseSaveDebounce);
            editorContainer.removeEventListener('profile-data-changed', window._doctorBaseSaveDebounce);
            editorContainer.addEventListener('input', window._doctorBaseSaveDebounce);
            editorContainer.addEventListener('profile-data-changed', window._doctorBaseSaveDebounce);
        }

        bindAutoSaveEvents();

    } catch (e) {
        console.error('加载博士档案失败', e);
        const defaultBase = JSON.parse(JSON.stringify(DOCTOR_BASE_PROFILE_DEFAULT));
        window._doctorBaseProfile = defaultBase;
        const editorContainer = document.getElementById('doctor-base-profile-editor');
        if (editorContainer) {
            renderEditableProfile(editorContainer, defaultBase, [], 'doctor');
        }
        bindAutoSaveEvents();
    }
}

function cleanDoctorBaseProfile(userData, defaultData) {
    if (!userData || typeof userData !== 'object') {
        return JSON.parse(JSON.stringify(defaultData));
    }
    // 从用户数据开始，只补全缺失的键（不覆盖已有值，无论是否为空）
    const result = JSON.parse(JSON.stringify(userData));

    function mergeMissing(target, source) {
        for (const key of Object.keys(source)) {
            if (!(key in target)) {
                // 如果 target 中该键不存在，则复制 source 中的值
                target[key] = JSON.parse(JSON.stringify(source[key]));
            } else if (typeof source[key] === 'object' && source[key] !== null && typeof target[key] === 'object' && target[key] !== null) {
                // 递归处理对象，但列表（Array）不属于对象，直接跳过
                if (!Array.isArray(source[key])) {
                    mergeMissing(target[key], source[key]);
                }
                // 如果数组：不处理，保留原值
            }
            // 其他类型（字符串、数字、布尔、数组）不处理，保留原值
        }
        return target;
    }

    const merged = mergeMissing(result, defaultData);

    // 清理可能存在的嵌套（由渲染器产生的误嵌套）
    if (merged.background && merged.background.background) {
        delete merged.background.background;
    }
    if (merged.topic_preferences && merged.topic_preferences.topic_preferences) {
        delete merged.topic_preferences.topic_preferences;
    }

    return merged;
}

async function saveDoctorBaseProfile() {
    const profile = window._doctorBaseProfile;
    if (!profile) {
        console.warn('[博士档案] profile 为空，无法保存');
        return;
    }

    try {
        const doctorName = document.getElementById('doctor-name')?.value || '';
        const gender = document.getElementById('doctor-gender-select')?.value || '未知';

        const payload = {
            doctor_name: doctorName,
            gender: gender,
            base_profile: profile,
            chat_style: profile.topic_preferences?.chat_style || 'normal',
            topic_tags: profile.topic_preferences?.tags?.join(',') || '',
            preferences: '',
            topic_freq: {},
            mood_tendency: {}
        };

        console.log('[博士档案] 保存:', JSON.stringify(payload, null, 2));

        const res = await fetch('/doctor/preferences', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        if (!res.ok) {
            const text = await res.text();
            console.error('[博士档案] 保存失败:', res.status, text);
        } else {
            console.log('[博士档案] 保存成功');
        }
    } catch (e) {
        console.error('[博士档案] 保存异常:', e);
    }
}

function bindAutoSaveEvents() {
    // 博士姓名：失焦时保存
    const doctorName = document.getElementById('doctor-name');
    if (doctorName) {
        doctorName.removeEventListener('blur', handleDoctorNameChange);
        doctorName.addEventListener('blur', handleDoctorNameChange);
    }

    // 性别：直接保存到 localStorage 和后端
    const genderSelect = document.getElementById('doctor-gender-select');
    if (genderSelect) {
        genderSelect.removeEventListener('change', handleGenderChange);
        genderSelect.addEventListener('change', handleGenderChange);
    }

    // 扩展设定：使用防抖保存（保持不变）
    const extraPrompt = document.getElementById('doctor-extra-prompt');
    if (extraPrompt) {
        extraPrompt.removeEventListener('input', window._debouncedSaveExtra);
        window._debouncedSaveExtra = debounce(saveDoctorExtra, 500);
        extraPrompt.addEventListener('input', window._debouncedSaveExtra);
    }
}

// 防抖工具函数
function debounce(fn, delay) {
    let timer = null;
    return function(...args) {
        if (timer) clearTimeout(timer);
        timer = setTimeout(() => fn.apply(this, args), delay);
    };
}

// 博士姓名保存（触发统一保存）
async function handleDoctorNameChange(e) {
    const newName = e.target.value.trim();
    if (newName === '普瑞塞斯' || newName.toLowerCase() === 'priestess') {
        try {
            const res = await fetch('/personas/activate_priestess', { method: 'POST' });
            if (res.ok) {
                const data = await res.json();
                if (data.triggered) {
                    document.body.classList.add('priestess-activation-glitch');
                    setTimeout(() => document.body.classList.remove('priestess-activation-glitch'), 3000);
                    await updateProfilePage();
                    loadDoctorProfile();
                    return;
                }
            }
        } catch (err) {
            console.error('激活普瑞塞斯失败:', err);
        }
    }
    // 正常保存逻辑
    localStorage.setItem('doctorName', newName);
    clearTimeout(window._doctorBaseSaveTimer);
    window._doctorBaseSaveTimer = setTimeout(() => {
        saveDoctorBaseProfile();
    }, 200);
}

