function saveDoctorCall() {
    if (!currentOperatorId) return;
    const callInput = document.getElementById('doctor-call');
    if (!callInput) return;
    const newCall = callInput.value.trim();
    const autoToggle = document.getElementById('auto-call-toggle');
    const autoUpdate = autoToggle ? autoToggle.checked : false;

    // 使用 encodeURIComponent 避免 # 被截断
    const encodedId = encodeURIComponent(currentOperatorId);

    // 保存称呼
    fetch(`/doctor_call/${encodedId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ doctor_call: newCall })
    })
    .then(res => {
        if (res.ok) {
            showTemporaryToast('✅ 称呼保存成功', 2000, 'success');
        } else {
            showTemporaryToast('❌ 保存失败', 2000, 'error');
        }
    })
    .catch(err => showTemporaryToast('❌ 保存出错', 2000, 'error'));

    // 保存自动更新开关（通过角色类型感知的发言设置接口）
    fetch(getCharacterSettingsEndpoint(currentOperatorId, 'speech-settings'))
        .then(res => res.json())
        .then(config => {
            return fetch(getCharacterSettingsEndpoint(currentOperatorId, 'speech-settings'), {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    global_chat_bias: config.global_chat_bias,
                    polling_config: config.polling_config || {},
                    auto_update_call: autoUpdate,
                    expected_revision: Number(config.revision || 0)
                })
            });
        })
        .then(res => {
            if (!res.ok) console.warn('自动更新开关保存失败');
        })
        .catch(err => console.error('保存自动更新开关出错', err));
}


