// 加载并管理全局年份编辑
async function loadArchiveGlobalYear() {
    const yearDisplaySpan = document.getElementById('archive-global-year-display');
    const yearInput = document.getElementById('archive-global-year-input');
    const editBtn = document.getElementById('edit-archive-year-btn');
    const editorDiv = document.getElementById('archive-year-editor');
    const saveBtn = document.getElementById('archive-year-save');

    if (!yearDisplaySpan) return;

    // 加载当前年份
    try {
        const res = await fetch('/global/year');
        const data = await res.json();
        if (stretchModeActive) markAssistantRead();
        const year = data.year || 1099;
        yearDisplaySpan.innerText = year;
        yearInput.value = year;
    } catch (e) {
        console.error('加载全局年份失败', e);
    }

    // 编辑按钮点击显示编辑器
    editBtn.onclick = () => {
        editorDiv.style.display = 'block';
    };

    // 保存年份
    saveBtn.onclick = async () => {
        const newYear = parseInt(yearInput.value);
        if (isNaN(newYear) || newYear < 1 || newYear > 9999) {
            alert('年份必须为 1~9999');
            return;
        }
        try {
            await fetch('/global/year', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ year: newYear })
            });
            yearDisplaySpan.innerText = newYear;
            editorDiv.style.display = 'none';
            await renderTimeline();
            console.log('全局年份已更新');
        } catch (err) {
            console.error('保存年份失败', err);
            alert('保存失败');
        }
    };
}

// 绑定卡片点击事件
function bindArchiveCardEvents() {
    const routes = {
        'rhodes-setting': 'rhodes-setting',
        'chronicle': 'chronicle',
        'rumor': 'rumor'
    };
    Object.keys(routes).forEach(target => {
        const card = document.querySelector(`.archive-card[data-target="${target}"]`);
        if (card) card.onclick = () => showPage(routes[target]);
    });

    const timelineCard = document.getElementById('archive-timeline-card');
    if (timelineCard) {
        timelineCard.onclick = event => {
            if (event.target.closest('#timeline-year-display, #archive-year-editor')) return;
            showPage('timeline-full');
            window.setTimeout(initTimelineFullPage, 30);
        };
    }

    // 关系网 -> 跳转到全局图谱页面（使用静态模式）
    const relationCard = document.querySelector('.archive-card[data-target="global-graph"]');
    if (relationCard) {
        relationCard.onclick = () => {
            const iframe = document.getElementById('global-graph-iframe');
            if (iframe && !iframe.src.includes('mode=global_root')) {
                iframe.src = '/static/graph-viewer.html?mode=global_root&embedded=1';
            }
            showPage('global-graph');
        };
    }

    // 光荣之路卡片本身点击（因为内部占位暂不跳转，可预留）
    const achievementCard = document.querySelector('.archive-card.achievement');
    if (achievementCard) {
        achievementCard.addEventListener('click', (e) => {
            // 如果点击的是卡片头部或主体，可以跳转开发中提示
            if (e.target === achievementCard || e.target.classList.contains('archive-card-header')) {
                showUnderDevelopmentModal();
            }
        });
    }
}

