function escapeArchiveHtml(value) {
    return String(value == null ? '' : value)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function archiveEventYear(event) {
    const year = Number(event && event.year);
    if (!Number.isFinite(year)) return null;
    return String(event.era || 'AD').toUpperCase() === 'BC' ? -year : year;
}

async function fetchTimelineEvents() {
    const response = await fetch('/timeline/events');
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    return Array.isArray(data) ? data : (data.events || []);
}

async function renderTimeline() {
    const track = document.getElementById('timeline-track');
    if (!track) return;
    const globalYear = Number(document.getElementById('archive-global-year-display')?.textContent) || 1099;
    try {
        const events = await fetchTimelineEvents();
        track.innerHTML = [globalYear - 2, globalYear - 1, globalYear, globalYear + 1, globalYear + 2].map(year => {
            const around = events.filter(item => archiveEventYear(item) === year).slice(0, 2);
            const eventHtml = around.length
                ? around.map(item => `<div class="timeline-mini-event">${escapeArchiveHtml(item.title || item.content)}</div>`).join('')
                : '<div class="timeline-mini-no-event">暂无已记录事件</div>';
            return `<div class="timeline-mini-year${year === globalYear ? ' current' : ''}" data-year="${year}">
                <div class="timeline-mini-year-label">${year} 年</div>${eventHtml}</div>`;
        }).join('');
        track.querySelector('.timeline-mini-year.current')?.scrollIntoView({block: 'nearest', inline: 'center'});
    } catch (error) {
        console.error('[archives] 时间线概览加载失败:', error);
        track.innerHTML = '<span class="archive-mini-empty">时间线加载失败，请点击进入后重试</span>';
    }
}

