function getArchiveConditionLabel(condition) {
    if (!condition) return '';
    const schema = _rhodesConditionsSchema.find(item => item.type === condition.type);
    const params = normalizeRhodesCondition(condition).params;
    const summary = Object.entries(params)
        .filter(([, value]) => value !== '' && value != null && (!Array.isArray(value) || value.length))
        .slice(0, 2)
        .map(([key, value]) => {
            const paramSchema = schema?.params?.[key] || {};
            const shown = Array.isArray(value) ? value.join('、') : getRhodesOptionLabel(value);
            return `${paramSchema.label || key}：${shown}`;
        }).join('，');
    return `${schema?.label || condition.type || '全局'}${summary ? `（${summary}）` : ''}`;
}

