// ========== 21.1. 搜索辅助相关 ==========
// 判断干员是否匹配搜索关键词
function isOperatorMatch(operator, keyword) {
    if (!keyword || keyword.trim() === '') return true;
    const kw = keyword.trim().toLowerCase();
    const id = String(operator.id || '');
    const codename = String(operator.codename || '');
    const pinyinInitial = operator.pinyin_initial || '';

    // 1. 干员ID匹配（如 "amiya"）
    if (id.toLowerCase().includes(kw)) return true;

    // 2. 干员名称匹配（包含关键词）
    if (codename.toLowerCase().includes(kw)) return true;

    // 3. 拼音首字母匹配（单字母）
    if (String(pinyinInitial).toLowerCase().includes(kw)) return true;

    // 4. 别名、显示名及基础档案字段
    const basic = operator.profile?.basic_info || {};
    const aliases = [
        operator.display_name,
        operator.nickname,
        operator.alias,
        operator.aliases,
        basic.name,
        basic.alias,
        basic.aliases
    ].flatMap(value => Array.isArray(value) ? value : [value]);
    if (aliases.some(value => String(value || '').toLowerCase().includes(kw))) return true;

    // 5. 详情资料匹配
    const detail = operatorDetails[id];
    if ([detail?.race, detail?.origin, detail?.infection_status]
        .some(value => String(value || '').toLowerCase().includes(kw))) return true;

    return false;
}

// 在联系人列表上执行搜索
function performSearchOnContactList(keyword) {
    contactSearchQuery = String(keyword || '').trim().toLowerCase();
    const revision = ++contactSearchRevision;
    if (contactSearchTimer) clearTimeout(contactSearchTimer);
    contactSearchTimer = setTimeout(() => {
        contactSearchTimer = null;
        if (revision !== contactSearchRevision) return;
        renderContacts();
        if (contactSearchQuery
            && operatorDetailsLoaded.size < operators.length
            && !operatorDetailsLoading) {
            loadAllOperatorDetails().catch(error => console.warn('加载联系人搜索资料失败:', error));
        }
    }, 120);
}

// 成员选择页搜索
function filterMemberList(keyword) {
    if (!keyword || keyword.trim() === '') {
        // 清空搜索，显示所有
        document.querySelectorAll('#member-list .contact-item').forEach(item => {
            item.style.display = 'flex';
        });
        document.querySelectorAll('#member-list .contact-letter').forEach(letter => {
            letter.style.display = 'block';
        });
        return;
    }
    const kw = keyword.trim().toLowerCase();
    const items = document.querySelectorAll('#member-list .contact-item');
    items.forEach(item => {
        const operatorId = item.querySelector('.member-checkbox')?.value || item.dataset.operatorId;
        if (!operatorId) {
            item.style.display = 'none';
            return;
        }
        const operator = operatorMap.get(operatorId);
        if (!operator) {
            item.style.display = 'none';
            return;
        }
        const match = isOperatorMatch(operator, kw);
        item.style.display = match ? 'flex' : 'none';
    });

    // 隐藏没有可见项的分组字母
    const letters = document.querySelectorAll('#member-list .contact-letter');
    letters.forEach(letter => {
        let nextItems = [];
        let next = letter.nextElementSibling;
        while (next && next.classList.contains('contact-item')) {
            nextItems.push(next);
            next = next.nextElementSibling;
        }
        const anyVisible = nextItems.some(item => item.style.display !== 'none');
        letter.style.display = anyVisible ? 'block' : 'none';
    });

    // 更新索引栏
    const { letters: indexLetters, hasStar, hasCustom } = getMemberSelectLetters();
    updateContactIndex(indexLetters, hasStar, hasCustom);
}

// ========== 21.2. 过滤器 ==========
// ========== 21.2.1. 私聊/群聊过滤器 ==========
function initContactFilters() {
    const tabs = document.querySelectorAll('.contact-filter-tab');
    tabs.forEach(tab => {
        tab.onclick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            const filter = tab.dataset.filter;
            if (filter === contactFilter) return;
            contactFilter = filter;
            tabs.forEach(t => t.classList.remove('active'));
            tab.classList.add('active');
            renderContacts();
            // 控制右侧索引栏显示（仅私聊模式显示）
            const indexBar = document.getElementById('contact-index-bar');
            if (indexBar) {
                indexBar.style.display = (filter === 'private') ? 'flex' : 'none';
            }
        };
    });
}

// ========== 21.2.2. 标签过滤器 ==========
function toggleFilterTag(type, value) {
    if (activeFilters[type] && activeFilters[type].has(value)) {
        activeFilters[type].delete(value);
    } else {
        if (!activeFilters[type]) activeFilters[type] = new Set();
        activeFilters[type].add(value);
    }
    renderContacts();  // 直接调用渲染函数
}

function setTrustSort(order) {
    trustSort = order;
    renderContacts();
}

function clearAllFilters() {
    activeFilters = {
        class: new Set(),
        gender: new Set(),
        faction: new Set(),
        origin: new Set(),
        race: new Set()
    };
    trustSort = null;
    document.querySelectorAll('.group-tags span').forEach(span => span.classList.remove('active'));
    applyFiltersAndRender();
}

function bindFilterTagEvents() {
    const filterPanel = document.getElementById('filter-panel');
    if (!filterPanel || filterPanel.dataset.filterTagsBound === 'true') return;
    filterPanel.dataset.filterTagsBound = 'true';
    filterPanel.addEventListener('click', (event) => {
        const tag = event.target.closest('.group-tags span');
        if (!tag || !filterPanel.contains(tag)) return;
        if (tag.dataset.filterType) {
            event.preventDefault();
            event.stopPropagation();
            tag.classList.toggle('active');
            toggleFilterTag(tag.dataset.filterType, tag.dataset.value);
            return;
        }
        if (tag.dataset.sort) {
            event.preventDefault();
            event.stopPropagation();
            filterPanel.querySelectorAll('.group-tags span[data-sort]').forEach(item => {
                item.classList.toggle('active', item === tag);
            });
            setTrustSort(tag.dataset.sort === 'trust_asc' ? 'asc' : 'desc');
        }
    });
}

function initContactFilter() {
    const filterHeader = document.getElementById('filter-header');
    const filterPanel = document.getElementById('filter-panel');
    if (filterHeader && filterPanel) {
        // 使用可覆盖的单一处理器，避免每次进入联系人页重复绑定后一次点击开关两次。
        filterHeader.onclick = (event) => {
            event.preventDefault();
            event.stopPropagation();
            const isOpen = filterPanel.style.display === 'block' && !filterPanel.hidden;
            filterPanel.hidden = isOpen;
            filterPanel.style.display = isOpen ? 'none' : 'block';
            filterHeader.closest('.filter-collapse')?.classList.toggle('open', !isOpen);
        };
    }
    // 为每个分组添加折叠功能
    document.querySelectorAll('.filter-group .group-header').forEach(header => {
        const group = header.closest('.filter-group');
        const tagsContainer = group.querySelector('.group-tags');
        if (!tagsContainer) return;
        // 默认所有分组展开
        tagsContainer.style.display = 'flex';
        header.onclick = (e) => {
            e.stopPropagation();
            const isOpen = tagsContainer.style.display !== 'none';
            tagsContainer.style.display = isOpen ? 'none' : 'flex';
            group.classList.toggle('open', !isOpen);
        };
    });
    bindFilterTagEvents();
}

// ========== 21.3. 右侧索引栏 ==========
function updateContactIndex(letters, hasStar, hasCustom) {
    const indexBar = document.getElementById('contact-index-bar');
    if (!indexBar) return;

    // 关键修复：仅当当前活动页面是联系人页时才允许显示索引栏
    const activePage = document.querySelector('.page.active-page');
    const isContacts = activePage && activePage.id === 'page-contacts';
    if (!isContacts) {
        indexBar.style.display = 'none';
        indexBar.innerHTML = '';
        return;
    }

    if (letters.length === 0 && !hasStar && !hasCustom) {
        indexBar.style.display = 'none';
        return;
    }

    let itemsHtml = '';
    if (hasStar) itemsHtml += '<div class="index-item" data-letter="star">⭐</div>';
    if (hasCustom) itemsHtml += '<div class="index-item" data-letter="custom">🛠</div>';
    letters.forEach(letter => {
        itemsHtml += `<div class="index-item" data-letter="${letter}">${letter}</div>`;
    });
    indexBar.innerHTML = itemsHtml;
    indexBar.style.display = 'flex';

    // 事件绑定部分保持不变（但要确保不重复绑定）
    if (!window._indexBarEventBound) {
        indexBar.removeEventListener('click', window._indexBarClickHandler);
        window._indexBarClickHandler = (e) => {
            const item = e.target.closest('.index-item');
            if (!item) return;
            e.stopPropagation();
            const letter = item.dataset.letter;
            const activePage = document.querySelector('.page.active-page');
            if (!activePage) return;
            if (activePage.id === 'page-contacts') {
                scrollToContactGroup(letter);
            } else {
                scrollToContactGroupInContainer(letter, activePage);
            }
        };
        indexBar.addEventListener('click', window._indexBarClickHandler);
        let indexPointerActive = false;
        indexBar.addEventListener('pointerdown', event => {
            indexPointerActive = true;
            indexBar.setPointerCapture?.(event.pointerId);
            event.target.closest('.index-item')?.click();
            event.preventDefault();
        });
        indexBar.addEventListener('pointermove', event => {
            if (!indexPointerActive) return;
            document.elementFromPoint(event.clientX, event.clientY)
                ?.closest?.('.index-item')
                ?.click();
        });
        ['pointerup', 'pointercancel'].forEach(type => {
            indexBar.addEventListener(type, () => {
                indexPointerActive = false;
            });
        });
        window._indexBarEventBound = true;
    }
}

function handleIndexClick(e) {
    const letter = e.currentTarget.dataset.letter;
    scrollToContactGroup(letter);
}

function scrollToContactGroup(letter) {
    const activePage = document.querySelector('.page.active-page');
    if (!activePage) return;

    // 获取实际滚动容器（如果页面内有滚动容器，则使用它，否则使用页面本身）
    let scrollContainer = activePage;
    const innerScrollContainer = activePage.querySelector('.create-group-scrollable, .member-select-scrollable, .assistant-scrollable, .contact-list');
    if (innerScrollContainer && window.getComputedStyle(innerScrollContainer).overflowY === 'auto') {
        scrollContainer = innerScrollContainer;
    }

    let targetElement = null;
    if (letter === 'star') {
        targetElement = activePage.querySelector('.contact-letter[data-letter="star"]');
    } else if (letter === 'custom') {
        targetElement = activePage.querySelector('.contact-letter[data-letter="custom"]');
    } else {
        targetElement = activePage.querySelector(`.contact-letter[data-letter="${letter}"]`);
    }
    if (!targetElement) return;

    // 临时移除 sticky 定位以获取正确的 offsetTop（相对于滚动容器）
    const originalPosition = targetElement.style.position;
    targetElement.style.position = 'static';
    let absoluteTop = targetElement.offsetTop;
    targetElement.style.position = originalPosition;

    // 如果滚动容器不是页面本身，需要计算相对于滚动容器的偏移
    if (scrollContainer !== activePage) {
        const containerRect = scrollContainer.getBoundingClientRect();
        const elementRect = targetElement.getBoundingClientRect();
        absoluteTop = elementRect.top - containerRect.top + scrollContainer.scrollTop;
    }

    // 计算固定头部偏移量（只计算滚动容器内部的固定元素）
    let headerOffset = 0;
    const header = scrollContainer.querySelector('.page-header');
    if (header) headerOffset += header.offsetHeight;
    const searchBar = scrollContainer.querySelector('.search-bar');
    if (searchBar) headerOffset += searchBar.offsetHeight;
    const filterTabs = scrollContainer.querySelector('.contact-filter-tabs');
    if (filterTabs) headerOffset += filterTabs.offsetHeight;

    let targetScroll = absoluteTop - headerOffset;
    targetScroll = Math.max(0, targetScroll);
    const maxScroll = scrollContainer.scrollHeight - scrollContainer.clientHeight;
    targetScroll = Math.min(targetScroll, maxScroll);

    console.log(`[滚动] 目标: ${letter}, 计算偏移: ${absoluteTop}, 头部偏移: ${headerOffset}, 目标滚动: ${targetScroll}`);
    scrollContainer.scrollTo({ top: targetScroll, behavior: 'smooth' });
}

function scrollToContactGroupInContainer(letter, activePage) {
    // 确定实际滚动容器
    let scrollContainer = activePage;
    const innerScrollContainer = activePage.querySelector('.create-group-scrollable, .member-select-scrollable, .assistant-scrollable');
    if (innerScrollContainer && window.getComputedStyle(innerScrollContainer).overflowY === 'auto') {
        scrollContainer = innerScrollContainer;
    } else {
        scrollContainer = activePage;
    }

    // 查找目标元素
    let targetElement = null;
    if (letter === 'star') {
        targetElement = activePage.querySelector('.contact-letter[data-letter="star"]');
    } else if (letter === 'custom') {
        targetElement = activePage.querySelector('.contact-letter[data-letter="custom"]');
    } else {
        targetElement = activePage.querySelector(`.contact-letter[data-letter="${letter}"]`);
    }
    if (!targetElement) return;

    // 临时移除 sticky 定位以获取正确的 offsetTop（相对于滚动容器）
    const originalPosition = targetElement.style.position;
    targetElement.style.position = 'static';
    let absoluteTop = targetElement.offsetTop;
    targetElement.style.position = originalPosition;

    // 如果滚动容器不是页面本身，需要计算相对于滚动容器的偏移
    if (scrollContainer !== activePage) {
        const containerRect = scrollContainer.getBoundingClientRect();
        const elementRect = targetElement.getBoundingClientRect();
        absoluteTop = elementRect.top - containerRect.top + scrollContainer.scrollTop;
    }

    // 计算固定头部偏移量（只计算滚动容器内部的固定元素）
    let headerOffset = 0;
    const header = scrollContainer.querySelector('.page-header');
    if (header) headerOffset += header.offsetHeight;
    const searchBar = scrollContainer.querySelector('.search-bar');
    if (searchBar) headerOffset += searchBar.offsetHeight;
    const filterTabs = scrollContainer.querySelector('.contact-filter-tabs');
    if (filterTabs) headerOffset += filterTabs.offsetHeight;
    headerOffset += 5; // 微调

    let targetScroll = absoluteTop - headerOffset;
    targetScroll = Math.max(0, targetScroll);
    const maxScroll = scrollContainer.scrollHeight - scrollContainer.clientHeight;
    targetScroll = Math.min(targetScroll, maxScroll);

    console.log(`[内部滚动] 目标: ${letter}, 计算偏移: ${absoluteTop}, 头部偏移: ${headerOffset}, 目标滚动: ${targetScroll}`);
    scrollContainer.scrollTo({ top: targetScroll, behavior: 'smooth' });
}

// 控制筛选器区域和右侧索引栏的显示（仅在需要筛选的页面显示）
function setFilterUIVisible(visible) {
    const filterCollapse = document.querySelector('.filter-collapse');
    const indexBar = document.getElementById('contact-index-bar');
    if (filterCollapse) filterCollapse.style.display = visible ? 'block' : 'none';
    if (indexBar) indexBar.style.display = visible ? 'flex' : 'none';
}

// ========== 21.3.1. 获取各页面的分组字母列表 ==========
function getCreateGroupLetters(container = null) {
    const targetContainer = container || document.getElementById('create-group-members');
    if (!targetContainer) return { letters: [], hasStar: false, hasCustom: false };
    const letters = [];
    let hasStar = false;
    let hasCustom = false;
    targetContainer.querySelectorAll('.contact-letter').forEach(el => {
        const letter = el.innerText.trim();
        if (letter === '⭐ 星标干员' || letter === '⭐') {
            hasStar = true;
        } else if (letter === '预选干员' || letter === '自定义') {
            hasCustom = true;
        } else if (letter !== '') {
            letters.push(letter);
        }
    });
    return { letters, hasStar, hasCustom };
}

/**
 * 获取群成员编辑页的分组字母（基于 #member-list 中的 .contact-letter）
 * @returns {Object} { letters: string[], hasStar: boolean, hasCustom: boolean }
 */
function getMemberSelectLetters() {
    const container = document.getElementById('member-list');
    if (!container) return { letters: [], hasStar: false, hasCustom: false };
    const letters = [];
    let hasStar = false;
    let hasCustom = false;
    container.querySelectorAll('.contact-letter').forEach(el => {
        const letter = el.innerText.trim();
        if (letter === '⭐ 星标干员' || letter === '⭐') {
            hasStar = true;
        } else if (letter === '自定义') {
            hasCustom = true;
        } else if (letter !== '') {
            letters.push(letter);
        }
    });
    return { letters, hasStar, hasCustom };
}

