// ========== 24.2. 头像与背景 ==========
function initAvatar() {
    // 使用当前人格头像，而不是固定博士
    const setAvatar = (el) => {
        if (!el) return;
        // 从 currentPersonaId 获取头像
        const personaId = currentPersonaId || 'doctor';
        const avatarUrl = getPersonaAvatarUrl(personaId);
        el.src = avatarUrl;
        el.onerror = function() {
            this.onerror = null;
            this.src = getDefaultAvatarForPersona(personaId);
        };
    };

    document.querySelectorAll('.profile-avatar, .header-avatar').forEach(setAvatar);

    // 如果个人页已打开，确保更新
    if (document.getElementById('page-profile').classList.contains('active-page')) {
        updateProfilePage();
    }
}

// 辅助函数：获取人格头像 URL
function getPersonaAvatarUrl(personaId) {
    const normalizedId = String(personaId || 'doctor');
    const identity = window.personaIdentityStore?.get(normalizedId);
    if (identity?.avatar_url) return identity.avatar_url;
    const persona = personaList.find(p => String(p.persona_id) === normalizedId);
    if (persona?.avatar_url || persona?.profile_json?.avatar) {
        return persona.avatar_url || persona.profile_json.avatar;
    }
    if (normalizedId === 'doctor') return getOperatorAvatarUrl('doctor');
    return getDefaultAvatarForPersona(normalizedId);
}

function openAvatarPicker() {
    const picker = document.getElementById('avatarPicker');
    const grid = document.getElementById('avatarGrid');
    if (!grid) return;

    // 清空并显示加载状态
    grid.innerHTML = '<div style="text-align:center; padding:20px;">加载中...</div>';
    openBottomSheet('avatarPicker');

    // 并行加载预置头像和自定义头像
    const loadAvatars = async () => {
        // 1. 预置头像
        const presetAvatars = [];
        for (let i = 1; i <= 18; i++) {
            presetAvatars.push({
                id: `avatar_${i}.webp`,
                url: `/static/avatars/avatar_${i}.webp`,
                type: 'preset',
            });
        }

        // 2. 当前人格的自定义头像
        const current = await getCurrentPersona();
        const personaId = current?.persona_id || 'doctor';
        const imageType = personaId === 'doctor' ? 'doctor_avatar' : 'persona_avatar';
        let customAvatars = [];
        try {
            const result = await CUSTOM_IMAGE_API.list(imageType, personaId);
            customAvatars = (result.data || []).map(item => ({
                id: `custom_${item.id}`,
                url: item.url,
                type: 'custom',
                imageId: item.id,
                imageUid: item.image_uid || '',
            }));
        } catch (e) {
            console.warn('加载自定义头像失败', e);
        }

        const allAvatars = [...presetAvatars, ...customAvatars];
        const currentAvatar = getPersonaAvatarUrl(personaId);

        grid.innerHTML = allAvatars.map(avatar => `
            <div class="avatar-option ${avatar.url === currentAvatar ? 'selected' : ''}"
                 style="background-image: url('${avatar.url}'); background-size: cover; background-position: center; border-radius: 50%; width: 60px; height: 60px; border: 2px solid ${avatar.type === 'custom' ? '#ffd700' : 'transparent'};"
                 data-id="${avatar.id}"
                 data-url="${avatar.url}"
                 data-type="${avatar.type}"
                 data-image-id="${avatar.imageId || ''}"
                 data-image-uid="${avatar.imageUid || ''}">
                ${avatar.type === 'custom' ? '<div style="position:absolute;top:-4px;right:-4px;background:#ffd700;border-radius:50%;width:16px;height:16px;font-size:8px;display:flex;align-items:center;justify-content:center;border:1px solid #fff;">C</div>' : ''}
            </div>
        `).join('');

        // 绑定点击事件
        grid.querySelectorAll('.avatar-option').forEach(el => {
            el.addEventListener('click', () => {
                const url = el.dataset.url;
                const type = el.dataset.type;
                if (type === 'preset') {
                    selectAvatar(url.split('/').pop());
                } else {
                    selectCustomAvatar(url, el.dataset.imageUid || '');
                }
            });
        });

        // 添加上传按钮
        const uploadBtn = document.createElement('div');
        uploadBtn.className = 'avatar-option upload-btn';
        uploadBtn.style.cssText = 'width: 60px; height: 60px; border-radius: 50%; background: rgba(255,255,255,0.1); border: 2px dashed rgba(255,255,255,0.3); display: flex; align-items: center; justify-content: center; font-size: 24px; cursor: pointer; color: #aaa;';
        uploadBtn.textContent = '+';
        uploadBtn.title = '上传自定义头像';
        uploadBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'image/*';
            input.onchange = async (ev) => {
                const file = ev.target.files[0];
                if (!file) return;
                try {
                    const result = await CUSTOM_IMAGE_API.upload(imageType, file, personaId);
                    if (result.status === 'ok') {
                        // 刷新列表
                        openAvatarPicker();
                        // 自动选中新上传的头像
                        setTimeout(() => {
                            const newUrl = result.data.url;
                            selectCustomAvatar(newUrl, result.data.image_uid || '');
                        }, 100);
                    } else {
                        showToast('头像上传失败', 3000, 'error');
                    }
                } catch (err) {
                    showToast('头像上传失败：' + err.message, 3500, 'error');
                }
            };
            input.click();
        });
        // 将上传按钮添加到网格中
        grid.appendChild(uploadBtn);
    };

    loadAvatars();
}

async function selectCustomAvatar(url, avatarRef = '') {
    const current = await getCurrentPersona();
    if (!current) {
        showToast('当前人格尚未加载，请稍后重试', 3000, 'error');
        return;
    }
    const personaId = current.persona_id;
    const profile = {...(current.profile_json || {})};
    profile.avatar = url;
    if (personaId !== 'doctor' && avatarRef) profile.avatar_ref = avatarRef;
    const result = await updatePersona(personaId, {profile});
    if (!result) return;
    await updateProfilePage();
    await renderPersonaManager();
    closeAvatarPicker();
    showToast('头像已更新', 2000, 'success');
}

async function selectAvatar(avatarId) {
    const current = await getCurrentPersona();
    if (!current) {
        // 降级
        doctorAvatar = avatarId;
        localStorage.setItem('doctorAvatar', avatarId);
        document.querySelectorAll('.profile-avatar, .header-avatar').forEach(el => {
            el.src = `/static/avatars/${avatarId}`;
        });
        closeAvatarPicker();
        return;
    }
    const personaId = current.persona_id;
    const profile = {...(current.profile_json || {})};
    const avatarUrl = `/static/avatars/${avatarId}`;
    profile.avatar = avatarUrl;
    profile.avatar_ref = '';
    profile.avatar_revision = 0;
    const result = await updatePersona(personaId, {profile});
    if (!result) return;
    await updateProfilePage();
    await renderPersonaManager();
    closeAvatarPicker();
    showToast('✅ 头像已更新', 2000, 'success');
}

function closeAvatarPicker() {
    closeBottomSheet('avatarPicker');
}

let profileBannerDraft = null;

function setProfileAccentDraft(color) {
    const accent = normalizeProfileAccentColor(color);
    if (!accent || !profileBannerDraft) return false;
    profileBannerDraft.accent = accent;
    const colorInput = document.getElementById('profile-accent-color');
    const hexInput = document.getElementById('profile-accent-hex');
    if (colorInput) colorInput.value = accent;
    if (hexInput) hexInput.value = accent;
    applyProfileAccentColor(accent);
    return true;
}

function extractProfileAccentFromCanvas(canvas) {
    if (!canvas) return null;
    let pixels;
    try {
        pixels = canvas.getContext('2d', { willReadFrequently: true }).getImageData(0, 0, canvas.width, canvas.height).data;
    } catch (error) {
        console.warn('背景自动取色失败:', error);
        return null;
    }
    const buckets = new Map();
    for (let index = 0; index < pixels.length; index += 16) {
        const r = pixels[index], g = pixels[index + 1], b = pixels[index + 2], a = pixels[index + 3];
        if (a < 180) continue;
        const max = Math.max(r, g, b), min = Math.min(r, g, b);
        const brightness = max / 255;
        const saturation = max ? (max - min) / max : 0;
        if (brightness < .12 || brightness > .94) continue;
        const key = `${r >> 4},${g >> 4},${b >> 4}`;
        const entry = buckets.get(key) || { r: 0, g: 0, b: 0, count: 0, score: 0 };
        entry.r += r; entry.g += g; entry.b += b; entry.count += 1;
        entry.score += .45 + saturation * 1.35;
        buckets.set(key, entry);
    }
    const best = [...buckets.values()].sort((a, b) => b.score - a.score)[0];
    if (!best) return null;
    const toHex = value => Math.round(value / best.count).toString(16).padStart(2, '0');
    return getVibrantColor(`#${toHex(best.r)}${toHex(best.g)}${toHex(best.b)}`).toUpperCase();
}

function sampleProfileAccentAt(canvas, event) {
    if (!canvas || !profileBannerDraft) return;
    const rect = canvas.getBoundingClientRect();
    const x = Math.max(0, Math.min(canvas.width - 1, Math.round((event.clientX - rect.left) * canvas.width / rect.width)));
    const y = Math.max(0, Math.min(canvas.height - 1, Math.round((event.clientY - rect.top) * canvas.height / rect.height)));
    try {
        const pixel = canvas.getContext('2d', { willReadFrequently: true }).getImageData(x, y, 1, 1).data;
        const color = `#${[pixel[0], pixel[1], pixel[2]].map(value => value.toString(16).padStart(2, '0')).join('')}`;
        setProfileAccentDraft(color);
    } catch (error) {
        showToast('该图片暂时无法取色', 2000, 'error');
    }
}

function renderProfileAccentPreview(url, autoPick = false) {
    const canvas = document.getElementById('profile-accent-canvas');
    if (!canvas) return Promise.resolve(null);
    const previewToken = (profileBannerDraft?.previewToken || 0) + 1;
    if (profileBannerDraft) profileBannerDraft.previewToken = previewToken;
    const context = canvas.getContext('2d', { willReadFrequently: true });
    context.clearRect(0, 0, canvas.width, canvas.height);
    return new Promise(resolve => {
        const image = new Image();
        image.onload = () => {
            if (!profileBannerDraft || profileBannerDraft.previewToken !== previewToken || profileBannerDraft.url !== url) {
                resolve(null);
                return;
            }
            const scale = Math.max(canvas.width / image.naturalWidth, canvas.height / image.naturalHeight);
            const width = image.naturalWidth * scale, height = image.naturalHeight * scale;
            context.clearRect(0, 0, canvas.width, canvas.height);
            context.drawImage(image, (canvas.width - width) / 2, (canvas.height - height) / 2, width, height);
            const detected = extractProfileAccentFromCanvas(canvas);
            if (autoPick && detected) setProfileAccentDraft(detected);
            resolve(detected);
        };
        image.onerror = () => {
            context.fillStyle = '#20262c';
            context.fillRect(0, 0, canvas.width, canvas.height);
            context.fillStyle = '#ffffff';
            context.textAlign = 'center';
            context.fillText('背景预览加载失败', canvas.width / 2, canvas.height / 2);
            resolve(null);
        };
        image.src = url;
    });
}

async function selectProfileBannerDraft(url, type = 'preset') {
    if (!profileBannerDraft) return;
    profileBannerDraft.url = url;
    profileBannerDraft.type = type;
    document.querySelectorAll('#bannerGrid .banner-option[data-url]').forEach(option => {
        option.classList.toggle('selected', option.dataset.url === url);
    });
    const bannerId = getBannerIdFromUrl(url);
    if (bannerId && bannerColorMap[bannerId]) {
        setProfileAccentDraft(getVibrantColor(bannerColorMap[bannerId]));
        await renderProfileAccentPreview(url, false);
    } else {
        await renderProfileAccentPreview(url, true);
    }
}

async function applyProfileBannerDraft() {
    if (!profileBannerDraft?.url) return;
    const draft = profileBannerDraft;
    const accent = normalizeProfileAccentColor(draft.accent);
    if (!accent) {
        showToast('请输入有效的十六进制重点色', 2200, 'error');
        return;
    }
    const current = await getCurrentPersona();
    if (current) {
        const profile = { ...(current.profile_json || {}), background: draft.url, accent_color: accent };
        const success = await updatePersona(current.persona_id, { profile });
        if (!success) {
            showToast('背景保存失败，请稍后重试', 2500, 'error');
            return;
        }
        draft.applied = true;
        localStorage.setItem('profileBanner', draft.url);
        applyProfileAccentColor(accent);
        const bgLayer = document.getElementById('profile-bg-layer');
        if (bgLayer) bgLayer.style.backgroundImage = `url('${draft.url}')`;
        await updateProfilePage();
        await renderPersonaManager();
    } else {
        draft.applied = true;
        localStorage.setItem('profileBanner', draft.url);
        applyProfileAccentColor(accent);
        const bgLayer = document.getElementById('profile-bg-layer');
        if (bgLayer) bgLayer.style.backgroundImage = `url('${draft.url}')`;
    }
    if (profileBannerDraft === draft) closeBannerPicker();
    else closeBottomSheet('bannerPicker');
    showToast('✅ 背景与重点色已更新', 2000, 'success');
}

function bindProfileAccentEditor() {
    const canvas = document.getElementById('profile-accent-canvas');
    const colorInput = document.getElementById('profile-accent-color');
    const hexInput = document.getElementById('profile-accent-hex');
    const eyedropperButton = document.getElementById('profile-accent-eyedropper');
    const autoButton = document.getElementById('profile-accent-auto');
    const applyButton = document.getElementById('profile-banner-apply');
    if (canvas) canvas.onclick = event => sampleProfileAccentAt(canvas, event);
    if (colorInput) colorInput.oninput = () => setProfileAccentDraft(colorInput.value);
    if (hexInput) {
        hexInput.oninput = () => {
            hexInput.classList.toggle('invalid', !normalizeProfileAccentColor(hexInput.value));
            setProfileAccentDraft(hexInput.value);
        };
        hexInput.onblur = () => { if (profileBannerDraft) setProfileAccentDraft(profileBannerDraft.accent); };
    }
    if (eyedropperButton) {
        eyedropperButton.hidden = !('EyeDropper' in window);
        eyedropperButton.onclick = async () => {
            try {
                const result = await new EyeDropper().open();
                setProfileAccentDraft(result.sRGBHex);
            } catch (error) {
                if (error?.name !== 'AbortError') console.warn('屏幕吸色失败:', error);
            }
        };
    }
    if (autoButton) autoButton.onclick = () => {
        const detected = extractProfileAccentFromCanvas(canvas);
        if (detected) setProfileAccentDraft(detected);
    };
    if (applyButton) applyButton.onclick = applyProfileBannerDraft;
}

function openBannerPicker(preferredCustomUrl = null) {
    const picker = document.getElementById('bannerPicker');
    const grid = document.getElementById('bannerGrid');
    if (!picker || !grid) return;

    grid.innerHTML = '<div style="text-align:center; padding:20px;">加载中...</div>';
    openBottomSheet('bannerPicker');

    const loadBanners = async () => {
        // 预置背景
        const presetBanners = [];
        for (let i = 1; i <= 12; i++) {
            const url = `/static/backgrounds/banner_${i}.webp`;
            presetBanners.push({
                id: `banner_${i}`,
                url: url,
                type: 'preset',
            });
        }

        // 按当前人格加载自定义背景
        const current = await getCurrentPersona();
        const personaId = current?.persona_id || 'doctor';
        const imageType = personaId === 'doctor' ? 'profile_bg' : 'persona_bg';
        let customBanners = [];
        try {
            const result = await CUSTOM_IMAGE_API.list(imageType, personaId);
            customBanners = (result.data || []).map(item => ({
                id: `custom_${item.id}`,
                url: item.url,
                type: 'custom',
                imageId: item.id,
            }));
        } catch (e) {
            console.warn('加载自定义背景失败', e);
        }

        const allBanners = [...presetBanners, ...customBanners];
        const currentBanner = current?.profile_json?.background || getDefaultBackgroundForPersona(personaId);
        const originalAccent = getProfileAccentForBackground(currentBanner, current?.profile_json?.accent_color);
        profileBannerDraft = { url: currentBanner, type: getBannerIdFromUrl(currentBanner) ? 'preset' : 'custom', accent: originalAccent, originalAccent, applied: false };
        bindProfileAccentEditor();
        setProfileAccentDraft(originalAccent);
        await renderProfileAccentPreview(currentBanner, !current?.profile_json?.accent_color && !getBannerIdFromUrl(currentBanner));

        let html = '';
        allBanners.forEach(banner => {
            const isSelected = banner.url === currentBanner;
            html += `
                <div class="banner-option ${isSelected ? 'selected' : ''}"
                     style="background-image: url('${banner.url}'); background-size: cover; background-position: center;"
                     data-url="${banner.url}"
                     data-type="${banner.type}"
                     data-image-id="${banner.imageId || ''}"
                     title="${banner.type === 'custom' ? '自定义' : '预设'}">
                    ${banner.type === 'custom' ? '<span style="position:absolute;top:4px;right:4px;background:#ffd700;padding:0 6px;border-radius:8px;font-size:10px;color:#333;">C</span>' : ''}
                </div>
            `;
        });

        grid.innerHTML = html;

        // 绑定点击事件
        grid.querySelectorAll('.banner-option').forEach(el => {
            el.addEventListener('click', () => {
                const url = el.dataset.url;
                const type = el.dataset.type;
                selectProfileBannerDraft(url, type);
            });
        });

        // 添加上传按钮
        const uploadDiv = document.createElement('div');
        uploadDiv.className = 'banner-option upload-btn';
        uploadDiv.style.cssText = 'width: 100%; height: 80px; border: 2px dashed rgba(255,255,255,0.3); border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 24px; color: #aaa; cursor: pointer; background: rgba(255,255,255,0.05);';
        uploadDiv.textContent = '+ 上传背景';
        uploadDiv.addEventListener('click', (e) => {
            e.stopPropagation();
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'image/*';
            input.onchange = async (ev) => {
                const file = ev.target.files[0];
                if (!file) return;
                try {
                    const result = await CUSTOM_IMAGE_API.upload(imageType, file, personaId);
                    if (result.status === 'ok') {
                        openBannerPicker(result.data.url);
                    } else {
                        alert('上传失败');
                    }
                } catch (err) {
                    alert('上传失败: ' + err.message);
                }
            };
            input.click();
        });
        grid.appendChild(uploadDiv);
        if (preferredCustomUrl) await selectProfileBannerDraft(preferredCustomUrl, 'custom');
    };

    loadBanners();
}

function closeBannerPicker() {
    closeBottomSheet('bannerPicker');
    if (profileBannerDraft && !profileBannerDraft.applied) applyProfileAccentColor(profileBannerDraft.originalAccent);
    profileBannerDraft = null;
}

function loadProfileBanner() {
    const savedBanner = localStorage.getItem('profileBanner');
    const bannerEl = document.getElementById('profile-banner');
    if (!bannerEl) return;

    if (savedBanner) {
        // 检查图片是否存在，若不存在则降级
        const img = new Image();
        img.onload = () => {
            bannerEl.style.backgroundImage = `url('${savedBanner}')`;
        };
        img.onerror = () => {
            console.warn('保存的背景图片不可用，使用默认背景');
            const defaultUrl = '/static/backgrounds/default_banner.webp';
            bannerEl.style.backgroundImage = `url('${defaultUrl}')`;
            localStorage.setItem('profileBanner', defaultUrl);
        };
        img.src = savedBanner;
    } else {
        // 默认背景优先 webp
        const defaultUrl = '/static/backgrounds/default_banner.webp';
        bannerEl.style.backgroundImage = `url('${defaultUrl}')`;
        localStorage.setItem('profileBanner', defaultUrl);
    }
    bannerEl.style.backgroundSize = "cover";
    bannerEl.style.backgroundPosition = "center";
}

document.getElementById('change-banner-btn')?.addEventListener('click', () => openBannerPicker());


// ========== 25. 记忆相关设置 ==========
// 加载记忆设置
async function loadMemorySettings() {
    try {
        const res = await fetch('/memory/config');
        if (res.ok) {
            const data = await res.json();
            // 设置滑块和显示值
            const shortSlider = document.getElementById('short-term-limit');
            const midSlider = document.getElementById('mid-term-max');
            const longSlider = document.getElementById('long-term-max');
            const shortValue = document.getElementById('short-term-value');
            const midValue = document.getElementById('mid-term-value');
            const longValue = document.getElementById('long-term-value');
            if (shortSlider) shortSlider.value = data.short_term_limit;
            if (midSlider) midSlider.value = data.mid_term_max;
            if (longSlider) longSlider.value = data.long_term_max;
            if (shortValue) shortValue.textContent = data.short_term_limit;
            if (midValue) midValue.textContent = data.mid_term_max;
            if (longValue) longValue.textContent = data.long_term_max;

            // 索引配置
            const topicIndexLimit = document.getElementById('topic-index-limit');
            const topicMemPerIndex = document.getElementById('topic-memories-per-index');
            const eventIndexLimit = document.getElementById('event-index-limit');
            const eventMemPerIndex = document.getElementById('event-memories-per-index');
            const topicIndexLimitVal = document.getElementById('topic-index-limit-value');
            const topicMemPerIndexVal = document.getElementById('topic-memories-per-index-value');
            const eventIndexLimitVal = document.getElementById('event-index-limit-value');
            const eventMemPerIndexVal = document.getElementById('event-memories-per-index-value');

            if (topicIndexLimit) topicIndexLimit.value = data.topic_index_limit;
            if (topicMemPerIndex) topicMemPerIndex.value = data.topic_memories_per_index;
            if (eventIndexLimit) eventIndexLimit.value = data.event_index_limit;
            if (eventMemPerIndex) eventMemPerIndex.value = data.event_memories_per_index;
            if (topicIndexLimitVal) topicIndexLimitVal.textContent = data.topic_index_limit;
            if (topicMemPerIndexVal) topicMemPerIndexVal.textContent = data.topic_memories_per_index;
            if (eventIndexLimitVal) eventIndexLimitVal.textContent = data.event_index_limit;
            if (eventMemPerIndexVal) eventMemPerIndexVal.textContent = data.event_memories_per_index;

            // 绘制图表
            drawMemoryEffectChart(
                data.short_term_limit,
                data.mid_term_max,
                data.topic_index_limit,
                data.event_index_limit
            );

            // 加载完成后更新标注
            if (typeof updateChartMaxLabel === 'function') updateChartMaxLabel();

            // 加载自动总结重要记忆开关状态
            const autoSummaryToggle = document.getElementById('auto-summary-toggle');
            if (autoSummaryToggle && data.auto_summary_enabled !== undefined) {
                autoSummaryToggle.checked = data.auto_summary_enabled;
            }
        }
    } catch (e) {
        console.error('加载记忆设置失败', e);
    }
}

// 保存记忆设置
async function saveMemorySettings() {
    const shortTermLimit = parseInt(document.getElementById('short-term-limit').value) || 50;
    const midTermMax = parseInt(document.getElementById('mid-term-max').value) || 100;
    const longTermMax = parseInt(document.getElementById('long-term-max').value) || 500;
    const topicIndexLimit = parseInt(document.getElementById('topic-index-limit').value) || 50;
    const topicMemoriesPerIndex = parseInt(document.getElementById('topic-memories-per-index').value) || 20;
    const eventIndexLimit = parseInt(document.getElementById('event-index-limit').value) || 50;
    const eventMemoriesPerIndex = parseInt(document.getElementById('event-memories-per-index').value) || 20;
    const autoSummaryToggle = document.getElementById('auto-summary-toggle');
    const autoSummaryEnabled = autoSummaryToggle ? autoSummaryToggle.checked : true;

    try {
        const res = await fetch('/memory/config', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                short_term_limit: shortTermLimit,
                mid_term_max: midTermMax,
                long_term_max: longTermMax,
                topic_index_limit: topicIndexLimit,
                topic_memories_per_index: topicMemoriesPerIndex,
                event_index_limit: eventIndexLimit,
                event_memories_per_index: eventMemoriesPerIndex,
                auto_summary_enabled: autoSummaryEnabled   // 新增
            })
        });
        if (res.ok) {
            alert('记忆配置保存成功');
            drawMemoryEffectChart(shortTermLimit, midTermMax, topicIndexLimit, eventIndexLimit);
        } else {
            const err = await res.json();
            alert('保存失败: ' + (err.detail || '未知错误'));
        }
    } catch (e) {
        console.error('保存记忆设置失败', e);
        alert('保存出错: ' + e.message);
    }
}

// ========== 25.1. 记忆管理 ==========
async function openAddMemoryModal(operatorId, memoryId = null, existingContent = '', existingEventTime = null, returnType = 'pinned') {
    console.log('openAddMemoryModal called with operatorId:', operatorId);
    currentMemoryOperatorId = operatorId;
    currentEditingMemoryId = memoryId;
    currentMemoryReturnType = returnType;
    const modal = document.getElementById('addMemoryModal');
    const textarea = document.getElementById('memory-content');
    const eventTimeInput = document.getElementById('memory-event-time');
    const toggle = document.getElementById('auto-extract-toggle');
    const title = modal?.querySelector('.modal-header');
    const confirmBtn = document.getElementById('confirm-add-memory');
    if (title) title.textContent = memoryId ? '编辑重要记忆' : '添加重要记忆';
    if (confirmBtn) confirmBtn.textContent = memoryId ? '保存' : '添加';

    if (memoryId) {
        textarea.value = existingContent;
        if (existingEventTime) {
            // 使用手动转换函数，避免 UTC 偏移
            eventTimeInput.value = timestampToLocalDateTimeString(parseFloat(existingEventTime));
        } else {
            setDefaultDateWithGlobalYear(eventTimeInput);
        }
    } else {
        textarea.value = '';
        setDefaultDateWithGlobalYear(eventTimeInput);
    }
    showModal('addMemoryModal');
    confirmBtn.onclick = () => handleAddMemory();
}

function closeAddMemoryModal() {
    hideModal('addMemoryModal');
    currentMemoryOperatorId = null;
    currentEditingMemoryId = null;
    currentMemoryReturnType = 'pinned';
}

let isAddingMemory = false; // 全局或闭包变量

async function handleAddMemory() {
    if (isAddingMemory) {
        console.warn('[记忆] 已有添加请求进行中，跳过重复调用');
        return;
    }
    isAddingMemory = true;
        try {
        const content = document.getElementById('memory-content').value.trim();
        if (!content) return;
        const autoExtract = document.getElementById('auto-extract-toggle').checked;
        const eventTimeInput = document.getElementById('memory-event-time');
        let eventTime = null;
        if (eventTimeInput && eventTimeInput.value) {
            eventTime = new Date(eventTimeInput.value).getTime() / 1000;
        }
        if (autoExtract) {
            // 自动提取逻辑（保持不变，但提取后需要将 eventTime 应用到每条记忆？可选）
            try {
                const res = await fetch('/memory/extract', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ operator_id: currentMemoryOperatorId, text: content })
                });
                const data = await res.json();
                if (res.ok) {
                    if (currentEditingMemoryId) {
                        await fetch(`/operator/memory/${currentMemoryOperatorId}/${currentEditingMemoryId}`, { method: 'DELETE' });
                    }
                    for (const mem of data.memories) {
                        await fetch('/operator/memory', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                operator_id: currentMemoryOperatorId,
                                content: mem,
                                importance: 2,
                                event_time: eventTime  // 使用相同的事件时间
                            })
                        });
                    }
                    loadMemories(currentMemoryOperatorId, currentMemoryReturnType);
                }
            } catch (e) { console.error(e); }
        } else {
            if (currentEditingMemoryId) {
                await fetch(`/operator/memory/${currentMemoryOperatorId}/${currentEditingMemoryId}`, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ content: content, event_time: eventTime })
                });
            } else {
                await fetch('/operator/memory', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        operator_id: currentMemoryOperatorId,
                        content: content,
                        importance: 2,
                        event_time: eventTime
                    })
                });
            }
            loadMemories(currentMemoryOperatorId, currentMemoryReturnType);
        }
        closeAddMemoryModal();
    } finally {
        isAddingMemory = false;
    }
}

function memoryCognitionScope(operatorId) {
    return {
        operatorId: String(operatorId || ''),
        personaId: String(window.currentPersonaId || 'doctor'),
        cloneSourceId: String(window.currentPersonaCloneSourceId || '')
    };
}

function memoryCognitionDate(value) {
    const timestamp = Number(value || 0);
    return timestamp ? new Date(timestamp * 1000).toLocaleString() : '暂无记录';
}

function bindMemoryCognitionFilters(operatorId) {
    const search = document.getElementById(`memory-search-${operatorId}`);
    const sort = document.getElementById(`memory-sort-${operatorId}`);
    const apply = () => {
        const list = document.getElementById(`memory-list-${operatorId}`);
        if (!list) return;
        const query = String(search?.value || '').trim().toLowerCase();
        list.querySelectorAll('[data-memory-search]').forEach(card => {
            card.hidden = Boolean(query) && !String(card.dataset.memorySearch || '').toLowerCase().includes(query);
        });
        const sortGroups = [...list.querySelectorAll('[data-memory-sort-group]')];
        (sortGroups.length ? sortGroups : [list]).forEach(group => {
            const cards = [...group.querySelectorAll(':scope > [data-memory-search]')];
            cards.sort((a, b) => sort?.value === 'importance'
                ? Number(b.dataset.importance || 0) - Number(a.dataset.importance || 0)
                : Number(b.dataset.time || 0) - Number(a.dataset.time || 0));
            cards.forEach(card => group.appendChild(card));
        });
    };
    if (search) search.oninput = apply;
    if (sort) sort.onchange = apply;
    apply();
}

function renderCognitionEpisode(item, operatorId) {
    let metadata = {};
    try { metadata = JSON.parse(item.metadata_json || '{}'); } catch (_) {}
    const pinned = Boolean(metadata.pinned);
    const search = `${item.topic_key || ''} ${item.summary || ''} ${item.status || ''}`;
    return `<article class="memory-cognition-card" data-memory-search="${escapeHtml(search)}" data-time="${Number(item.last_seen || 0)}" data-importance="${Number(item.importance || 0)}">
        <div class="memory-cognition-head"><strong>${escapeHtml(item.topic_key || '未分类主题')}</strong><span>${pinned ? '已固定 · ' : ''}${escapeHtml(item.status || 'open')}</span></div>
        <p>${escapeHtml(item.summary || '')}</p>
        <div class="memory-cognition-meta">${memoryCognitionDate(item.first_seen)} — ${memoryCognitionDate(item.last_seen)} · ${Number(item.occurrence_count || 0)} 条证据 · 置信度 ${Math.round(Number(item.confidence || 0) * 100)}%</div>
        <button class="memory-inline-btn" onclick="showMemoryEpisodeDetail('${String(item.id)}','${escapeHtml(String(operatorId || ''))}')">查看证据与修订</button>
    </article>`;
}

function renderManualImportantMemories(items) {
    const cards = (items || []).map(item => {
        const memoryId = String(item.id || '');
        const eventTime = Number(item.event_time || 0);
        const timeLabel = eventTime ? new Date(eventTime * 1000).toLocaleString() : '未设置记忆时间';
        return `<article class="memory-cognition-card manual-important-memory" data-memory-search="${escapeHtml(item.content || '')}" data-time="${eventTime}" data-importance="5">
            <div class="memory-cognition-head"><strong>手动重要记忆</strong><span>${escapeHtml(timeLabel)}</span></div>
            <p>${escapeHtml(item.content || '')}</p>
            <div class="memory-cognition-actions"><button class="manual-important-edit" data-id="${escapeHtml(memoryId)}" data-content="${escapeHtml(item.content || '')}" data-event-time="${eventTime || ''}">编辑</button><button class="manual-important-delete danger" data-id="${escapeHtml(memoryId)}">删除</button></div>
        </article>`;
    }).join('');
    return `<div class="memory-important-toolbar"><div><strong>手动重要记忆</strong><span>由你确认的长期事实会直接参与该干员的记忆检索。</span></div><button class="manual-important-add" type="button">＋ 新增记忆</button></div><div class="memory-important-group" data-memory-sort-group>${cards || '<div class="memory-cognition-empty">暂无手动重要记忆</div>'}</div>`;
}

function bindManualImportantMemoryActions(root, operatorId) {
    root.querySelector('.manual-important-add')?.addEventListener('click', () => openAddMemoryModal(operatorId, null, '', null, 'pinned'));
    root.querySelectorAll('.manual-important-edit').forEach(button => button.addEventListener('click', () => openAddMemoryModal(operatorId, button.dataset.id, button.dataset.content || '', button.dataset.eventTime ? Number(button.dataset.eventTime) : null, 'pinned')));
    root.querySelectorAll('.manual-important-delete').forEach(button => button.addEventListener('click', async () => {
        if (!window.confirm('确定删除这条重要记忆吗？')) return;
        const response = await fetch(`/operator/memory/${encodeURIComponent(operatorId)}/${encodeURIComponent(button.dataset.id)}`, {method: 'DELETE'});
        if (!response.ok) return showToast('重要记忆删除失败', 2500, 'error');
        loadMemories(operatorId, 'pinned');
    }));
}

async function loadMemoryCognitionPanel(operatorId, type, listDiv) {
    const { personaId, cloneSourceId } = memoryCognitionScope(operatorId);
    const query = new URLSearchParams({ persona_id: personaId });
    if (cloneSourceId) query.set('clone_source_id', cloneSourceId);
    const getJson = async url => {
        const response = await fetch(url);
        if (!response.ok) throw new Error(await response.text() || `HTTP ${response.status}`);
        return response.json();
    };
    if (type === 'overview') {
        const data = await getJson(`/memory/v2/operator/${encodeURIComponent(operatorId)}/overview?${query}`);
        listDiv.innerHTML = `<div class="memory-cognition-overview">
            <div><span>当前人格</span><strong>${escapeHtml(personaId)}</strong></div><div><span>主题记忆</span><strong>${Number(data.episode_count || 0)}</strong></div>
            <div><span>证据</span><strong>${Number(data.evidence_count || 0)}</strong></div><div><span>固定</span><strong>${Number(data.pinned_count || 0)}</strong></div>
            <div><span>重复率</span><strong>${(Number(data.duplicate_ratio || 0) * 100).toFixed(1)}%</strong></div><div><span>读取模式</span><strong>${escapeHtml(data.read_mode || 'dual_read')}</strong></div>
        </div><div class="memory-cognition-note">最近整理：${memoryCognitionDate(data.last_consolidated_at)}。Memory 2.0 保留原始证据，并将重复表达续接到同一主题。</div>`;
    } else if (type === 'episodes' || type === 'pinned') {
        const params = new URLSearchParams({ operator_id: operatorId, persona_id: personaId, conversation_id: operatorId, limit: '200' });
        if (cloneSourceId) params.set('clone_source_id', cloneSourceId);
        const [data, manualData] = await Promise.all([
            getJson(`/memory/v2/episodes?${params}`),
            type === 'pinned' ? getJson(`/operator/memories/${encodeURIComponent(operatorId)}?memory_type=important&limit=200`) : Promise.resolve({memories: []})
        ]);
        let items = data.items || [];
        if (type === 'pinned') items = items.filter(item => { let metadata = {}; try { metadata = JSON.parse(item.metadata_json || '{}'); } catch (_) {} return Boolean(metadata.pinned) || Number(item.importance || 0) >= 4; });
        const episodeHtml = items.length ? items.map(item => renderCognitionEpisode(item, operatorId)).join('') : `<div class="memory-cognition-empty">${type === 'pinned' ? '暂无系统整理的重要主题' : '暂无 Memory 2.0 情节记忆'}</div>`;
        if (type === 'pinned') {
            listDiv.innerHTML = `${renderManualImportantMemories(manualData.memories || [])}<div class="memory-important-section-label">系统整理与固定主题</div><div class="memory-important-group" data-memory-sort-group>${episodeHtml}</div>`;
            bindManualImportantMemoryActions(listDiv, operatorId);
        } else {
            listDiv.innerHTML = episodeHtml;
        }
    } else if (type === 'impression') {
        const [data, settings] = await Promise.all([getJson(`/memory/v2/operator/${encodeURIComponent(operatorId)}/impressions?${query}`), getJson(`/memory/v2/operator/${encodeURIComponent(operatorId)}/impression-settings`)]);
        const current = data.current || data.legacy; const versions = data.versions || [];
        listDiv.innerHTML = `<article class="memory-cognition-card impression memory-current-impression" data-memory-search="${escapeHtml(current?.content || '')}" data-time="${Number(current?.updated_at || current?.created_at || 0)}"><div class="memory-cognition-head"><strong>当前博士印象</strong><span>${escapeHtml(current?.validation_state || '尚未形成')}</span></div><p class="memory-current-impression-text">${escapeHtml(current?.content || '尚无印象记录，多进行有意义的交流后会逐步形成。')}</p>${current ? `<div class="memory-cognition-meta memory-current-impression-meta">修订 ${Number(current.revision || 0)} · 置信度 ${Math.round(Number(current.confidence || 0) * 100)}% · ${memoryCognitionDate(current.updated_at || current.created_at)}</div>` : ''}<div class="memory-cognition-actions"><button onclick="editOperatorImpression('${operatorId}')">用户修订</button>${data.current ? `<button onclick="governOperatorImpression('${String(data.current.id)}','${data.current.pinned ? 'UNPIN' : 'PIN'}','${operatorId}')">${data.current.pinned ? '取消固定' : '固定'}</button><button class="danger" onclick="governOperatorImpression('${String(data.current.id)}','FORGET','${operatorId}')">遗忘当前</button>` : ''}</div></article><article class="memory-cognition-card impression-settings"><div class="memory-cognition-head"><strong>自动更新</strong><span>预计 ${Number(settings.rounds_until_update || 0)} 轮后</span></div><label class="memory-setting-row"><span>更新频率</span><input id="impression-v2-interval-${operatorId}" type="number" min="1" max="100" value="${Number(settings.interval_rounds || 10)}"><span>轮</span></label><label class="memory-setting-row"><span>总结风格</span><select id="impression-v2-style-${operatorId}"><option value="detailed" ${settings.style === 'detailed' ? 'selected' : ''}>复杂细腻</option><option value="concise" ${settings.style === 'concise' ? 'selected' : ''}>简短干练</option><option value="analytical" ${settings.style === 'analytical' ? 'selected' : ''}>客观分析</option><option value="custom" ${settings.style === 'custom' ? 'selected' : ''}>自定义</option></select></label><label class="memory-setting-row"><span>自定义要求</span><textarea id="impression-v2-custom-${operatorId}" maxlength="300" placeholder="仅在自定义模式使用">${escapeHtml(settings.custom_instruction || '')}</textarea></label><label class="memory-setting-row"><span>暂停自动更新</span><input id="impression-v2-paused-${operatorId}" type="checkbox" ${settings.paused ? 'checked' : ''}></label><div class="memory-cognition-actions"><button onclick="saveOperatorImpressionSettings('${operatorId}')">保存设置</button><button onclick="reevaluateOperatorImpression('${operatorId}',${Number(settings.estimated_input_tokens || 0) + Number(settings.estimated_output_tokens || 0)})">立即重新评估</button></div></article><details class="memory-cognition-versions"><summary>历史版本（${versions.length}）</summary>${versions.map(item => `<div class="memory-version-row" data-memory-search="${escapeHtml(item.content || '')}" data-time="${Number(item.updated_at || item.created_at || 0)}"><span>v${Number(item.revision || 0)} · ${escapeHtml(item.status || '')} · ${escapeHtml(item.authority >= 90 ? '用户确认' : item.validation_state || '')}</span><p>${escapeHtml(item.content || '')}</p>${item.status !== 'current' ? `<button onclick="governOperatorImpression('${String(item.id)}','RESTORE','${operatorId}')">恢复为当前</button>` : ''}</div>`).join('')}</details>`;
    } else if (type === 'index') {
        const params = new URLSearchParams({ operator_id: operatorId, persona_id: personaId, include_disabled: 'true', limit: '200' });
        const data = await getJson(`/memory/v2/indexes?${params}`);
        listDiv.innerHTML = data.items?.length ? data.items.map(item => `<article class="memory-cognition-card" data-memory-search="${escapeHtml(`${item.title || ''} ${item.summary || ''}`)}" data-time="${Number(item.updated_at || 0)}" data-importance="${Number(item.importance || 0)}"><div class="memory-cognition-head"><strong>${item.index_type === 'event' ? '事件' : '话题'} · ${escapeHtml(item.title || '未命名')}</strong><span>${item.pinned ? '已固定 · ' : ''}${escapeHtml(item.status || '')}</span></div><p>${escapeHtml(item.summary || '暂无摘要')}</p><div class="memory-cognition-meta">修订 ${Number(item.revision || 0)} · embedding ${escapeHtml(item.embedding_version || '待构建')}</div><div class="memory-cognition-actions"><button onclick="showDerivedIndexDetail('${String(item.id)}','${operatorId}')">成员</button><button onclick="governDerivedIndex('${String(item.id)}','RENAME','${operatorId}')">重命名</button><button onclick="governDerivedIndex('${String(item.id)}','${item.pinned ? 'UNPIN' : 'PIN'}','${operatorId}')">${item.pinned ? '取消固定' : '固定'}</button><button onclick="governDerivedIndex('${String(item.id)}','REBUILD','${operatorId}')">重建</button></div></article>`).join('') : '<div class="memory-cognition-empty">暂无派生话题或事件索引</div>';
    } else if (type === 'legacy') {
        const data = await getJson(`/memory/v2/operator/${encodeURIComponent(operatorId)}/legacy?${query}`);
        const redirects = new Map((data.redirects || []).map(item => [String(item.old_id), String(item.new_id || '')]));
        const groups = [['旧中期记忆', data.mid || [], 'content'], ['旧长期记忆', data.important || [], 'memory'], ['旧话题索引', data.topics || [], 'summary'], ['旧事件索引', data.events || [], 'description']];
        listDiv.innerHTML = `<div class="memory-cognition-note warning">旧库仅供迁移验收对照，不会在这里修改或删除。</div>` + groups.map(([label, items, field]) => `<details class="memory-legacy-group"><summary>${label}（${items.length}）</summary>${items.map(item => `<div class="memory-version-row" data-memory-search="${escapeHtml(item[field] || item.topic || item.title || '')}" data-time="${Number(item.end_time || item.event_time || item.last_updated || item.timestamp || 0)}"><p>${escapeHtml(item[field] || item.topic || item.title || '')}</p><span>${redirects.has(String(item.id)) ? `已映射 → ${escapeHtml(redirects.get(String(item.id)))}` : '尚未映射'}</span></div>`).join('')}</details>`).join('');
    }
    bindMemoryCognitionFilters(operatorId);
}

async function showMemoryEpisodeDetail(episodeId, operatorId) {
    const response = await fetch(`/memory/v2/episodes/${encodeURIComponent(episodeId)}`); if (!response.ok) return showToast('证据详情加载失败', 2500, 'error');
    const data = await response.json(); const list = document.getElementById(`memory-list-${operatorId}`); if (!list) return;
    const detail = document.createElement('details'); detail.className = 'memory-evidence-panel'; detail.open = true;
    detail.innerHTML = `<summary>证据时间线 · ${escapeHtml(data.episode?.topic_key || '')}</summary>${(data.occurrences || []).map(item => `<div><strong>${memoryCognitionDate(item.occurred_at)}</strong><span>来源 ${escapeHtml(item.source_event_id || '')}</span></div>`).join('') || '<p>暂无证据引用</p>'}<h4>修订记录</h4>${(data.revisions || []).map(item => `<div><strong>v${Number(item.revision || 0)} · ${escapeHtml(item.action || '')}</strong><span>${escapeHtml(item.reason || '')}</span></div>`).join('') || '<p>暂无修订</p>'}`; list.prepend(detail);
}

async function editOperatorImpression(operatorId) {
    const escapedId = globalThis.CSS?.escape ? CSS.escape(operatorId) : String(operatorId).replace(/[^a-zA-Z0-9_-]/g, '');
    const current = document.querySelector(`#memory-list-${escapedId} .memory-current-impression-text`)?.textContent || '';
    const content = await requestProjectTextInput('修订博士印象（使用干员第一人称）', current); if (!content?.trim()) return;
    const { personaId, cloneSourceId } = memoryCognitionScope(operatorId);
    const response = await fetch(`/memory/v2/operator/${encodeURIComponent(operatorId)}/impressions`, { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({operator_id:operatorId, persona_id:personaId, clone_source_id:cloneSourceId, content:content.trim(), actor_type:'user', pin:true}) });
    if (!response.ok) return showToast('印象修订失败', 2500, 'error'); loadMemories(operatorId, 'impression');
}

async function governOperatorImpression(id, action, operatorId) {
    if (action === 'FORGET' && !await requestProjectConfirmation('遗忘当前印象', '历史版本仍可恢复，确定继续吗？')) return;
    const response = await fetch(`/memory/v2/impressions/${encodeURIComponent(id)}/action`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({action, reason:'用户在干员档案操作'})});
    if (!response.ok) return showToast('印象操作失败', 2500, 'error'); loadMemories(operatorId, 'impression');
}

async function saveOperatorImpressionSettings(operatorId) { const interval = Number(document.getElementById(`impression-v2-interval-${operatorId}`)?.value || 10); const paused = Boolean(document.getElementById(`impression-v2-paused-${operatorId}`)?.checked); const style = document.getElementById(`impression-v2-style-${operatorId}`)?.value || 'concise'; const customInstruction = document.getElementById(`impression-v2-custom-${operatorId}`)?.value.trim() || ''; if (style === 'custom' && !customInstruction) return showToast('请填写自定义风格要求',2500,'error'); const response = await fetch(`/memory/v2/operator/${encodeURIComponent(operatorId)}/impression-settings`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({interval_rounds:interval,paused,style,custom_instruction:customInstruction})}); if (!response.ok) return showToast('印象设置保存失败',2500,'error'); showToast('印象设置已保存',2000,'success'); loadMemories(operatorId,'impression'); }
async function reevaluateOperatorImpression(operatorId, estimatedTokens) { if (!await requestProjectConfirmation('重新评估博士印象', `将同时读取近期与长期记忆，预计最多约 ${Number(estimatedTokens || 0)} Token，并记录为记忆反思消耗。确定继续吗？`)) return; const {personaId}=memoryCognitionScope(operatorId); showToast('正在根据近期与长期记忆重新评估…',2500,'info'); const response=await fetch(`/memory/v2/operator/${encodeURIComponent(operatorId)}/impressions/re-evaluate`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({persona_id:personaId,confirmed:true})}); if(!response.ok)return showToast(`重新评估失败：${await response.text()}`,3500,'error'); const data=await response.json(); const summary=data.evidence_summary||{}; showToast(`博士印象已重新评估 · 近期 ${Number(summary.recent_count||0)} 条 / 长期 ${Number(summary.long_term_count||0)} 条 / 置顶 ${Number(summary.pinned_count||0)} 条`,4200,'success'); loadMemories(operatorId,'impression'); }

async function showDerivedIndexDetail(id, operatorId) {
    const response = await fetch(`/memory/v2/indexes/${encodeURIComponent(id)}`); if (!response.ok) return showToast('索引详情加载失败', 2500, 'error');
    const data = await response.json(); const list = document.getElementById(`memory-list-${operatorId}`); const detail = document.createElement('details'); detail.className = 'memory-evidence-panel'; detail.open = true;
    detail.innerHTML = `<summary>${escapeHtml(data.index?.title || '')} · 成员 ${data.members?.length || 0}</summary>${(data.members || []).map(item => `<div><strong>${escapeHtml(item.target_type || '')}</strong><span>${escapeHtml(String(item.target_id || ''))}${item.excluded ? ' · 已排除' : ''}</span></div>`).join('') || '<p>暂无成员</p>'}`; list?.prepend(detail);
}

async function governDerivedIndex(id, action, operatorId) {
    const title = action === 'RENAME' ? (window.prompt('输入新的索引名称：') || '') : ''; if (action === 'RENAME' && !title.trim()) return;
    const response = await fetch(`/memory/v2/indexes/${encodeURIComponent(id)}/action`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({action,title,reason:'用户在干员档案操作'})});
    if (!response.ok) return showToast('索引操作失败', 2500, 'error'); loadMemories(operatorId, 'index');
}

async function loadMemories(operatorId, type) {
    const listDiv = document.getElementById(`memory-list-${operatorId}`);
    if (!listDiv) return;
    listDiv.innerHTML = '<div style="text-align:center;">加载中...</div>';
    const encodedId = encodeURIComponent(operatorId);

    if (['overview', 'episodes', 'pinned', 'impression', 'index', 'legacy'].includes(type)) {
        try { await loadMemoryCognitionPanel(operatorId, type, listDiv); }
        catch (error) { console.error('加载记忆与认知失败:', error); listDiv.innerHTML = `<div class="memory-cognition-empty error">加载失败：${escapeHtml(error.message || String(error))}</div>`; }
        return;
    }

    if (type === 'impression') {
        const op = operatorMap.get(operatorId);
        const codename = op ? op.codename : operatorId;

        // 添加超时控制（10秒）
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 10000);

        fetch(`/operator/impression/${encodedId}`, { signal: controller.signal })
            .then(res => {
                clearTimeout(timeoutId);
                if (!res.ok) {
                    throw new Error(`HTTP ${res.status}: ${res.statusText}`);
                }
                return res.json();
            })
            .then(data => {
                console.log('[博士印象] 接口返回数据:', data);
                let html = '';

                // 原有印象内容
                if (data.preferences) {
                    html += `<div class="memory-item">博士偏好：${escapeHtml(data.preferences)}</div>`;
                }
                const impressionText = data.impression || data.relationship;
                if (impressionText) {
                    html += `<div class="memory-item">博士印象：${escapeHtml(impressionText)}</div>`;
                }
                if (data.chat_style && data.chat_style !== 'normal') {
                    const styleMap = { enthusiastic: '热情', gentle: '温和', serious: '严肃' };
                    html += `<div class="memory-item">交流风格：${styleMap[data.chat_style] || data.chat_style}</div>`;
                }
                const topics = Object.keys(data.topic_freq || {}).slice(0, 5);
                if (topics.length) {
                    html += `<div class="memory-item">常聊话题：${topics.join('、')}</div>`;
                }
                const mood = data.mood_tendency ? Object.keys(data.mood_tendency)[0] : null;
                if (mood) {
                    const moodMap = { happy: '愉快', sad: '低落', angry: '生气', calm: '平静' };
                    html += `<div class="memory-item">近期情绪：${moodMap[mood] || mood}</div>`;
                }
                if (html === '') {
                    html = `<div style="text-align:center; color:#999;">暂无印象记录，多与${codename}交流吧</div>`;
                }

                // 更新时间与间隔设置行
                const lastUpdate = data.last_update ? new Date(data.last_update * 1000).toLocaleString() : '从未更新';
                const updateIntervalRounds = data.update_interval_rounds || 10;

                html += `
                    <div class="memory-item impression-settings" style="display: flex; justify-content: space-between; align-items: center; margin-top: 10px;">
                        <span style="font-size: 13px;">博士印象更新时间</span>
                        <span id="impression-last-update-${operatorId}" style="font-size: 12px; color: var(--text-secondary);">${lastUpdate}</span>
                    </div>
                    <div class="memory-item impression-settings" style="display: flex; justify-content: space-between; align-items: center;">
                        <span style="font-size: 13px;">更新频率（对话轮数）</span>
                        <div style="display: flex; align-items: center; gap: 12px;">
                            <input type="range" id="impression-interval-slider-${operatorId}"
                                   min="1" max="50" step="1" value="${updateIntervalRounds}"
                                   style="width: 150px;">
                            <span id="impression-interval-value-${operatorId}" style="min-width: 40px;">${updateIntervalRounds}</span>
                        </div>
                    </div>
                    <div class="memory-item impression-note" style="font-size: 12px; color: var(--text-secondary); padding: 4px 8px; margin-top: -2px;">
                        💡 修改后需要等待达到设定的对话轮数才会更新印象
                    </div>
                `;

                // ===== 关键修复：将 html 渲染到 listDiv =====
                listDiv.innerHTML = html;

                // 绑定滑动条事件
                const slider = document.getElementById(`impression-interval-slider-${operatorId}`);
                const valueSpan = document.getElementById(`impression-interval-value-${operatorId}`);
                if (slider) {
                    slider.addEventListener('input', (e) => {
                        const val = e.target.value;
                        valueSpan.textContent = val;
                    });
                    slider.addEventListener('change', async (e) => {
                        const newInterval = parseInt(e.target.value);
                        await fetch(`/operator/impression/${operatorId}/interval`, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ interval_rounds: newInterval })
                        });
                        console.log(`[印象] 更新频率已设为 ${newInterval} 轮`);
                    });
                }

                // 清空印象按钮
                document.getElementById('clear-impression-btn')?.addEventListener('click', async () => {
                    if (confirm('确定清空当前干员对博士的印象吗？')) {
                        const res = await fetch(`/operator/impression/${operatorId}/clear`, { method: 'POST' });
                        if (res.ok) loadMemories(operatorId, 'impression');
                        else alert('清空失败');
                    }
                });
            })
            .catch(e => {
                clearTimeout(timeoutId);
                console.error('[博士印象] 加载失败:', e);
                let errorMsg = '加载失败';
                if (e.name === 'AbortError') {
                    errorMsg = '请求超时，请检查网络';
                } else if (e.message) {
                    errorMsg = e.message;
                }
                listDiv.innerHTML = `<div style="text-align:center; color:red;">${errorMsg}</div>`;
            });
    } else if (type === 'important') {
        fetch(`/operator/memories/${encodedId}?memory_type=${type}&limit=20`)
            .then(res => res.json())
            .then(data => {
                let memories = data.memories;
                memories.sort((a, b) => (a.event_time || 0) - (b.event_time || 0));
                let html = '';
                if (memories.length === 0) {
                    html = '<div style="text-align:center; color:#999; padding:5px 5px;">暂无记忆</div>';
                } else {
                    html = memories.map(m => {
                        const timeStr = m.event_time ? new Date(m.event_time * 1000).toLocaleString() : '未知时间';
                        const memoryId = m.id;
                        return `
                            <div class="memory-item" data-id="${memoryId}">
                                <div class="memory-time">${escapeHtml(timeStr)}</div>
                                <div class="memory-content">${escapeHtml(m.content)}</div>
                                <div class="memory-actions">
                                    <button class="memory-edit" data-id="${memoryId}" data-content="${escapeHtml(m.content)}" data-event-time="${m.event_time || ''}"><span data-zoot-icon="edit"></span></button>
                                    <button class="memory-delete" data-id="${memoryId}"><span data-zoot-icon="trash"></span></button>
                                </div>
                            </div>
                        `;
                    }).join('');
                }
                html += `
                    <div class="memory-item new-memory">
                        <div class="memory-time" style="color: #999;">新记忆</div>
                        <div class="memory-content" style="color: #999;"></div>
                        <div class="memory-actions">
                            <button class="memory-add"><span data-zoot-icon="plus"></span></button>
                        </div>
                    </div>
                `;
                listDiv.innerHTML = html;

                listDiv.querySelectorAll('.memory-delete').forEach(btn => {
                    btn.addEventListener('click', async (e) => {
                        e.stopPropagation();
                        const memoryId = btn.dataset.id;
                        if (confirm('确定删除这条记忆吗？')) {
                            const res = await fetch(`/operator/memory/${operatorId}/${memoryId}`, { method: 'DELETE' });
                            if (res.ok) loadMemories(operatorId, 'important');
                            else alert('删除失败');
                        }
                    });
                });
                listDiv.querySelectorAll('.memory-edit').forEach(btn => {
                    btn.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const memoryId = btn.dataset.id;
                        const content = btn.dataset.content;
                        const eventTime = btn.dataset.eventTime;
                        openAddMemoryModal(operatorId, memoryId, content, eventTime ? parseFloat(eventTime) : null);
                    });
                });
                const addBtn = listDiv.querySelector('.memory-add');
                if (addBtn) addBtn.addEventListener('click', () => openAddMemoryModal(operatorId));
            })
            .catch(e => {
                console.error('加载重要记忆失败', e);
                listDiv.innerHTML = '<div style="text-align:center; color:red;">加载失败</div>';
            });
    } else if (type === 'mid') {
        fetch(`/operator/memories/${encodedId}?memory_type=${type}&limit=20`)
            .then(res => res.json())
            .then(data => {
                console.log('[中期记忆] 后端返回数据:', data);  // 调试用
                if (data.memories && data.memories.length) {
                    data.memories.sort((a, b) => (b.time || 0) - (a.time || 0));
                }
                if (data.memories.length === 0) {
                    listDiv.innerHTML = '<div style="text-align:center; color:#999;">暂无中期记忆</div>';
                    return;
                }
                let html = '<div style="margin-bottom:10px;"><button class="batch-delete-mid-btn" data-operator-id="' + operatorId + '"><span data-zoot-icon="trash"></span> 删除选中</button></div>';
                html += '<div class="memory-list-items">';
                data.memories.forEach(m => {
                    const timeStr = m.time ? new Date(m.time * 1000).toLocaleString() : '';
                    // 关键：使用 m.id（后端返回的字段）
                    const memoryId = m.id;
                    console.debug(`[中期记忆] 条目 ID: ${memoryId}, 长度: ${String(m.content || '').length}`);
                    html += `
                        <div class="memory-item" data-id="${memoryId}">
                            <input type="checkbox" class="memory-checkbox" data-id="${memoryId}" style="margin-right: 10px;">
                            <div class="memory-time">${timeStr}</div>
                            <div class="memory-content">${escapeHtml(m.content)}</div>
                        </div>
                    `;
                });
                html += '</div>';
                listDiv.innerHTML = html;
            })
            .catch(e => {
                console.error('加载中期记忆失败', e);
                listDiv.innerHTML = '<div style="text-align:center; color:red;">加载失败</div>';
            });
    } else if (type === 'index') {
        // 记忆索引（话题 + 事件）
        listDiv.innerHTML = '<div style="text-align:center;">加载索引中...</div>';
        try {
            const res = await fetch(`/operator/memories/${encodedId}?memory_type=index&limit=20`);
            if (res.ok) {
                const data = await res.json();
                let html = '';

                // 话题部分
                if (data.topics && data.topics.length) {
                    html += '<div class="memory-section-title">📌 话题索引</div>';
                    data.topics.forEach(topic => {
                        html += `
                            <div class="memory-item index-item" data-id="${topic.id}" data-type="topic">
                                <div class="memory-time">${topic.last_updated ? new Date(topic.last_updated * 1000).toLocaleDateString() : '未知'}</div>
                                <div class="memory-content">
                                    <strong>${escapeHtml(topic.topic)}</strong><br>
                                    <span class="index-summary">${escapeHtml(topic.summary || '无概要')}</span>
                                </div>
                                <div class="memory-actions">
                                    <button class="index-detail-btn" data-id="${topic.id}" data-type="topic"><span data-zoot-icon="book"></span> 详情</button>
                                </div>
                            </div>
                        `;
                    });
                }

                // 事件部分
                if (data.events && data.events.length) {
                    html += '<div class="memory-section-title">🎯 事件索引</div>';
                    data.events.forEach(event => {
                        html += `
                            <div class="memory-item index-item" data-id="${event.id}" data-type="event">
                                <div class="memory-time">${event.timestamp ? new Date(event.timestamp * 1000).toLocaleDateString() : '未知'}</div>
                                <div class="memory-content">
                                    <strong>${escapeHtml(event.title)}</strong><br>
                                    <span class="index-summary">${escapeHtml(event.description || '无描述')}</span>
                                </div>
                                <div class="memory-actions">
                                    <button class="index-detail-btn" data-id="${event.id}" data-type="event"><span data-zoot-icon="book"></span> 详情</button>
                                </div>
                            </div>
                        `;
                    });
                }

                if (!html) {
                    html = '<div style="text-align:center; color:#999;">暂无话题或事件索引</div>';
                }
                listDiv.innerHTML = html;

                // 绑定详情按钮事件
                listDiv.querySelectorAll('.index-detail-btn').forEach(btn => {
                    btn.addEventListener('click', async (e) => {
                        e.stopPropagation();
                        const id = btn.dataset.id;
                        const type = btn.dataset.type;
                        await showIndexDetail(id, type, operatorId);
                    });
                });
            } else {
                // 接口未实现或返回错误，显示友好提示
                listDiv.innerHTML = '<div style="text-align:center; padding:20px;">📌 记忆索引功能开发中，敬请期待</div>';
            }
        } catch (e) {
            console.error('加载记忆索引失败', e);
            listDiv.innerHTML = '<div style="text-align:center; color:red;">加载失败，请稍后重试</div>';
        }
    }
}

