async function showMemoryMenu(operatorId, memoryId, touchEvent) {
    const menu = document.createElement('div');
    menu.className = 'message-menu';
    menu.innerHTML = `<div class="menu-item" data-action="delete">删除</div>`;
    document.body.appendChild(menu);

    const touch = touchEvent.touches[0];
    menu.style.left = touch.clientX + 'px';
    menu.style.top = touch.clientY + 'px';

    menu.querySelector('.menu-item').addEventListener('click', async () => {
        if (confirm('确定删除这条记忆吗？')) {
            try {
                const res = await fetch(`/operator/memory/${operatorId}/${memoryId}`, { method: 'DELETE' });
                if (res.ok) {
                    // 重新加载当前标签页的记忆
                    const activeBtn = document.querySelector(`.memory-type-btn[data-opid="${operatorId}"].active`);
                    if (activeBtn) {
                        loadMemories(operatorId, activeBtn.dataset.type);
                    }
                } else {
                    alert('删除失败');
                }
            } catch (e) {
                alert('删除出错');
            }
        }
        menu.remove();
    });

    const closeMenu = (e) => {
        if (!menu.contains(e.target)) {
            menu.remove();
            document.removeEventListener('click', closeMenu);
        }
    };
    setTimeout(() => document.addEventListener('click', closeMenu), 0);
}

// ========== 25.2. 记忆设置页 ==========
function drawMemoryEffectChart(shortLimit, midLimit, topicIndexLimit, eventIndexLimit) {
    const canvas = document.getElementById('memory-effect-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const width = canvas.clientWidth;
    const height = canvas.clientHeight;
    canvas.width = width;
    canvas.height = height;

    // 读取每个索引关联的消息条数（取话题和事件中的较大值）
    const topicMemPerIndex = parseInt(document.getElementById('topic-memories-per-index')?.value) || 20;
    const eventMemPerIndex = parseInt(document.getElementById('event-memories-per-index')?.value) || 20;
    const memoriesPerIndex = Math.max(topicMemPerIndex, eventMemPerIndex);
    const maxIndexCount = Math.max(topicIndexLimit, eventIndexLimit);

    const shortUnits = shortLimit;
    const midUnits = midLimit;
    const indexUnits = maxIndexCount * memoriesPerIndex;
    const totalUnits = shortUnits + midUnits + indexUnits;
    if (totalUnits === 0) return;

    const drawWidth = width * 0.95;
    const startX = 0;

    function getX(unitIndex) {
        return startX + (unitIndex / totalUnits) * drawWidth;
    }

    // 1. 短期记忆：绿色竖条
    for (let i = 0; i < shortUnits; i++) {
        const x = getX(i);
        const nextX = getX(i + 1);
        const barWidth = Math.max(1, nextX - x);
        ctx.fillStyle = '#28a745';
        ctx.fillRect(x, 0, barWidth, height);
    }

    // 2. 中期记忆：按压缩层级渐变（三等分）
    const layerSize = midUnits / 3;
    const midColors = ['#6fbf4c', '#a4d482', '#c8e6b5'];
    for (let i = 0; i < midUnits; i++) {
        const unitIndex = shortUnits + i;
        const x = getX(unitIndex);
        const nextX = getX(unitIndex + 1);
        const barWidth = Math.max(1, nextX - x);
        let colorIndex = 0;
        if (i < layerSize) colorIndex = 0;
        else if (i < layerSize * 2) colorIndex = 1;
        else colorIndex = 2;
        ctx.fillStyle = midColors[colorIndex];
        ctx.fillRect(x, 0, barWidth, height);
    }

    // 3. 索引记忆：蓝紫色渐变组，每组内连续竖条
    const indexStartUnit = shortUnits + midUnits;
    const groupCount = maxIndexCount;
    const barsPerGroup = memoriesPerIndex;
    for (let g = 0; g < groupCount; g++) {
        // 颜色从浅蓝到深蓝渐变
        const r = 100 + Math.floor((g / groupCount) * 50);
        const gVal = 120 + Math.floor((g / groupCount) * 40);
        const b = 180 + Math.floor((g / groupCount) * 75);
        const groupColor = `rgb(${r}, ${gVal}, ${b})`;
        for (let bIdx = 0; bIdx < barsPerGroup; bIdx++) {
            const unitIndex = indexStartUnit + g * barsPerGroup + bIdx;
            if (unitIndex >= totalUnits) break;
            const x = getX(unitIndex);
            const nextX = getX(unitIndex + 1);
            const barWidth = Math.max(1, nextX - x);
            ctx.fillStyle = groupColor;
            ctx.fillRect(x, 0, barWidth, height);
        }
    }

    // 绘制分割线（关键点位）
    ctx.beginPath();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1.5;
    const shortEndX = getX(shortUnits);
    const midEndX = getX(shortUnits + midUnits);
    const lastX = getX(totalUnits);
    ctx.moveTo(shortEndX, 0);
    ctx.lineTo(shortEndX, height);
    ctx.stroke();
    ctx.moveTo(midEndX, 0);
    ctx.lineTo(midEndX, height);
    ctx.stroke();
    ctx.moveTo(lastX, 0);
    ctx.lineTo(lastX, height);
    ctx.stroke();

    // 绘制关键点位数字
    ctx.font = '10px sans-serif';
    ctx.fillStyle = '#333';
    ctx.fillText(`${shortUnits}`, shortEndX - 20, height - 5);
    ctx.fillText(`${shortUnits + midUnits}`, midEndX - 20, height - 5);
    ctx.fillText(`${totalUnits}`, lastX - 20, height - 5);

    // 右侧留白提示
    if (drawWidth < width) {
        ctx.fillStyle = '#999';
        ctx.font = '12px sans-serif';
        ctx.fillText('...', drawWidth + 5, height / 2);
    }

    // 同步更新理论最大记忆单元标注（直接使用已有的 totalUnits）
    const labelSpan = document.getElementById('chart-note-max');
    if (labelSpan) labelSpan.textContent = `理论最大记忆单元: ${totalUnits}`;
}

function showInfoBubble(content, targetElement) {
    // 移除已存在的气泡
    const existing = document.querySelector('.info-bubble');
    if (existing) existing.remove();

    const bubble = document.createElement('div');
    bubble.className = 'info-bubble';
    // 将换行符转换为 <br>，并保留空格
    bubble.innerHTML = content.replace(/\n/g, '<br>').replace(/ /g, '&nbsp;');
    document.body.appendChild(bubble);

    // 定位在目标元素下方
    const rect = targetElement.getBoundingClientRect();
    let left = rect.left;
    const bubbleWidth = bubble.offsetWidth;
    const viewportWidth = window.innerWidth;

    // 防止气泡超出右边界
    if (left + bubbleWidth > viewportWidth - 10) {
        left = viewportWidth - bubbleWidth - 10;
    }
    // 防止超出左边界
    if (left < 10) {
        left = 10;
    }

    bubble.style.top = (rect.bottom + 5) + 'px';
    bubble.style.left = left + 'px';

    // 调整小三角的位置（保持指向目标元素大致区域）
    const triangleOffset = rect.left - left + 15; // 15 为图标宽度的一半左右
    bubble.style.setProperty('--triangle-left', Math.min(Math.max(triangleOffset, 15), bubbleWidth - 30) + 'px');
    // 注意：需要在 CSS 中定义 ::before 的 left 使用 var(--triangle-left, 20px)
    // 或者直接动态修改样式
    const before = window.getComputedStyle(bubble, '::before');
    bubble.style.setProperty('--triangle-left', Math.min(Math.max(triangleOffset, 15), bubbleWidth - 30) + 'px');
    // 手动设置伪元素 left（需要添加 style 标签，或直接修改规则）
    // 更简单：动态添加内联样式覆盖伪元素 left
    const style = document.createElement('style');
    style.id = 'bubble-triangle-style';
    style.textContent = `.info-bubble::before { left: ${Math.min(Math.max(triangleOffset, 15), bubbleWidth - 30)}px !important; }`;
    // 移除旧的
    const oldStyle = document.getElementById('bubble-triangle-style');
    if (oldStyle) oldStyle.remove();
    document.head.appendChild(style);

    // 点击其他地方关闭
    const closeHandler = (e) => {
        if (!bubble.contains(e.target) && e.target !== targetElement) {
            bubble.remove();
            const styleEl = document.getElementById('bubble-triangle-style');
            if (styleEl) styleEl.remove();
            document.removeEventListener('click', closeHandler);
        }
    };
    setTimeout(() => {
        document.addEventListener('click', closeHandler);
    }, 10);
}

// 为所有 info-icon-btn 绑定事件
function bindMemoryInfoButtons() {
    document.querySelectorAll('.info-icon-btn').forEach(btn => {
        btn.removeEventListener('click', window._infoClickHandler);
        const infoKey = btn.dataset.info;
        if (infoKey && MEMORY_TIPS[infoKey]) {
            const handler = (e) => {
                e.stopPropagation();
                showInfoBubble(MEMORY_TIPS[infoKey], btn);
            };
            btn.addEventListener('click', handler);
            window._infoClickHandler = handler;
        }
    });
}

let memoryCapacityTimer = null;
let memoryCapacityGeneration = 0;

function memoryCapacityPayload() {
    return {
        short_term_limit: parseInt(document.getElementById('short-term-limit')?.value) || 50,
        mid_term_max: parseInt(document.getElementById('mid-term-max')?.value) || 100,
        long_term_max: parseInt(document.getElementById('long-term-max')?.value) || 500,
        topic_index_limit: parseInt(document.getElementById('topic-index-limit')?.value) || 50,
        topic_memories_per_index: parseInt(document.getElementById('topic-memories-per-index')?.value) || 20,
        event_index_limit: parseInt(document.getElementById('event-index-limit')?.value) || 50,
        event_memories_per_index: parseInt(document.getElementById('event-memories-per-index')?.value) || 20,
        prompt_token_budget: 4000
    };
}

function renderMemoryCapacity(data) {
    const expectedNode = document.getElementById('memory-capacity-expected');
    const rangeNode = document.getElementById('memory-capacity-range');
    const promptNode = document.getElementById('memory-capacity-prompt');
    const visualNode = document.getElementById('memory-capacity-visual');
    const labelNode = document.getElementById('chart-note-max');
    if (!expectedNode || !rangeNode || !promptNode || !visualNode) return;
    const range = data.equivalent_range || {};
    const layers = data.layers || {};
    const expected = Number(range.expected || 0);
    expectedNode.textContent = `约 ${expected.toLocaleString()} 条`;
    rangeNode.textContent = `重叠估算范围 ${Number(range.minimum || 0).toLocaleString()}–${Number(range.maximum || 0).toLocaleString()}`;
    promptNode.textContent = `单轮相关召回约 ${Number(data.prompt_recall?.estimated_items_per_turn || 0)} 条（${Number(data.prompt_recall?.memory_token_budget || 0)} Token 预算）`;
    if (labelNode) labelNode.textContent = `工作集等效中位估算：${expected.toLocaleString()} 条`;
    const segments = [
        ['short', '短期', Number(layers.short_term || 0)],
        ['mid', '中期摘要', Number(layers.mid_term_equivalent || 0)],
        ['topic', '话题索引', Number(layers.topic_index_equivalent || 0)],
        ['event', '事件索引', Number(layers.event_index_equivalent || 0)],
        ['important', '重要记忆', Number(layers.important_memory || 0)]
    ];
    const total = Math.max(segments.reduce((sum, item) => sum + item[2], 0), 1);
    visualNode.innerHTML = segments.map(([className, label, value]) => {
        const basis = Math.max(7, value / total * 100);
        return `<div class="memory-capacity-segment ${className}" style="flex:${basis} 1 0" title="${escapeHtml(label)}：${value.toLocaleString()} 条等效来源"><strong>${escapeHtml(label)}</strong><small>${value.toLocaleString()}</small></div>`;
    }).join('');
}

function updateChartMaxLabel() {
    clearTimeout(memoryCapacityTimer);
    const generation = ++memoryCapacityGeneration;
    memoryCapacityTimer = setTimeout(async () => {
        try {
            const response = await fetch('/memory/v2/capacity-estimate', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(memoryCapacityPayload())
            });
            if (!response.ok) throw new Error(await response.text());
            const data = await response.json();
            if (generation === memoryCapacityGeneration) renderMemoryCapacity(data);
        } catch (error) {
            const node = document.getElementById('memory-capacity-expected');
            if (node && generation === memoryCapacityGeneration) node.textContent = '暂时无法计算';
            console.error('记忆容量估算失败:', error);
        }
    }, 120);
}


