// 检查知识图谱健康状态
async function checkKgHealth() {
    const statusText = document.getElementById('kg-status-text');
    const statusDot = document.getElementById('kg-status-dot');
    if (!statusText || !statusDot) return;

    statusText.textContent = '检测中...';
    statusDot.className = 'status-dot pending';

    try {
        const res = await fetch('/kg-proxy/health');
        const data = await res.json();
        if (data.status === 'ok') {
            statusText.textContent = '正常';
            statusDot.className = 'status-dot ok';
        } else if (data.status === 'not_configured') {
            statusText.textContent = '未配置';
            statusDot.className = 'status-dot';
        } else {
            statusText.textContent = '异常';
            statusDot.className = 'status-dot error';
        }
    } catch (e) {
        statusText.textContent = '无法连接';
        statusDot.className = 'status-dot error';
        console.error('健康检查失败', e);
    }
}

// ==================== 27. API设置 ====================
// 模块功能：
// 1. 多服务商 API 配置（地址、密钥、模型）按服务商独立存储
// 2. 知识图谱独立配置（启用开关 + 密钥），与聊天 API 分离
// 3. 知识图谱服务状态健康检查
// 4. 消息推送 API 密钥（预留）

let apiSettingsInitialized = false;
let lastSavedModel = '';

// ========== 27.1. API向导框（首次启动，保留原有） ==========
async function checkApiKeyAndPrompt() {
    // 如果向导窗已经显示过（版本不一致导致的），不再重复提示
    if (window._wizardShown) return;

    // 获取当前服务商及其 API Key
    let currentProvider = 'deepseek';
    try {
        const res = await fetch('/get_current_provider');
        if (res.ok) currentProvider = (await res.json()).provider || 'deepseek';
    } catch (e) {}

    let apiKeyConfigured = false;
    try {
        const keyRes = await fetch(`/get_api_key_for_provider?provider=${currentProvider}`);
        if (keyRes.ok) apiKeyConfigured = Boolean((await keyRes.json()).configured);
    } catch (e) {}

    // 缺少密钥只标记设置入口，不再重新打开首次向导。
    if (!apiKeyConfigured && !window._wizardShown) {
        document.body.classList.add('api-key-missing');
        return;
    }
    document.body.classList.remove('api-key-missing');
}

// ========== 27.2. 知识图谱独立配置 ==========
// 加载知识图谱配置（仅 API 密钥）
async function loadKgConfig() {
    const keyInput = document.getElementById('kg-api-key-input');
    const statusSpan = document.getElementById('kg-config-status');
    if (!keyInput) return;

    try {
        const res = await fetch('/kg/api_key');
        if (res.ok) {
            const data = await res.json();
            const configured = Boolean(data.configured);
            keyInput.value = '';
            keyInput.dataset.configured = configured ? '1' : '0';
            keyInput.placeholder = configured
                ? `已保存密钥（${data.masked_value || '已配置'}）；留空保持不变`
                : '请输入知识图谱 API 密钥';
            if (statusSpan) {
                statusSpan.textContent = configured ? '已设置密钥' : '未设置密钥';
            }
        } else {
            keyInput.value = '';
            if (statusSpan) statusSpan.textContent = '未设置密钥';
        }
    } catch (e) {
        console.error('加载知识图谱配置失败', e);
        keyInput.value = '';
        if (statusSpan) statusSpan.textContent = '加载失败';
    }
}

function updateKgConfigStatus(enabled, apiKey) {
    const statusSpan = document.getElementById('kg-config-status');
    if (!statusSpan) return;
    if (enabled && apiKey) {
        statusSpan.textContent = '已启用';
    } else if (enabled && !apiKey) {
        statusSpan.textContent = '缺少密钥';
    } else {
        statusSpan.textContent = '未启用';
    }
}

async function resetKgApiKey() {
    if (!confirm('重置密钥将清除当前密钥并重新获取，确定继续吗？')) return;
    try {
        const res = await fetch('/kg/reset', { method: 'POST' });
        if (res.ok) {
            const data = await res.json();
            const keyInput = document.getElementById('kg-api-key-input');
            if (keyInput) {
                keyInput.value = '';
                keyInput.dataset.configured = data.configured ? '1' : '0';
                keyInput.placeholder = data.configured
                    ? `已保存密钥（${data.masked_value || '已配置'}）；留空保持不变`
                    : '请输入知识图谱 API 密钥';
            }
            const statusSpan = document.getElementById('kg-config-status');
            if (statusSpan) statusSpan.textContent = data.configured ? '已设置密钥' : '未设置密钥';
            alert('密钥已重置并自动保存');
            // 可选：刷新健康检查状态
            checkKgHealth();
        } else {
            const err = await res.json();
            alert('重置失败: ' + (err.detail || '未知错误'));
        }
    } catch (e) {
        alert('重置失败: ' + e.message);
    }
}

