async function saveCurrentApiBase() {
    const provider = document.getElementById('provider-select').value;
    const apiBase = document.getElementById('api-base-input').value.trim();
    await fetch('/set_api_base_for_provider', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ provider, api_base: apiBase })
    });
    await updateApiOptionsStatus(provider);
    showToast('API地址已保存', 2000, 'success');
}

async function saveCurrentModel(provider, model) {
    if (!model) return;
    await fetch('/set_model_for_provider', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ provider, model })
    });
    await updateApiOptionsStatus(provider);
    console.log(`模型已保存: ${model}`);
}

async function updateApiOptionsStatus(provider) {
    await loadApiKeyForProvider(provider);
    const apiBase = await loadApiBaseForProvider(provider);
    const model = await loadModelForProvider(provider);
    const hasKey = Boolean(window.savedApiKeyState?.[provider]?.configured);
    const hasBase = !!apiBase;
    const hasModel = !!model;
    const statusSpan = document.getElementById('api-options-status');
    if (statusSpan) {
        statusSpan.textContent = (hasKey && hasBase && hasModel) ? '已设置' : '未设置';
    }
}

async function refreshModelsFromApi() {
    const provider = document.getElementById('provider-select').value;
    const apiKey = document.getElementById('api-key-input').value.trim();
    const apiBase = document.getElementById('api-base-input').value.trim();

    const selectEl = document.getElementById('model-select');
    const customInput = document.getElementById('custom-model-input');
    const currentModel = (customInput?.value || selectEl?.value || lastSavedModel || '').trim();
    const preserveCurrentModel = (label) => {
        selectEl.innerHTML = '';
        const option = document.createElement('option');
        option.value = '';
        option.textContent = currentModel ? `${label}（保留 ${currentModel}）` : label;
        selectEl.appendChild(option);
        if (currentModel && customInput) customInput.value = currentModel;
    };
    const hasSavedKey = Boolean(window.savedApiKeyState?.[provider]?.configured);
    if ((!apiKey && !hasSavedKey) || !apiBase) {
        selectEl.innerHTML = '<option value="">请先保存 API 地址和密钥</option>';
        return;
    }
    selectEl.innerHTML = '<option value="">加载中...</option>';
    try {
        const res = await fetch('/api/models', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ provider, api_key: apiKey, api_base: apiBase })
        });
        if (!res.ok) {
            const errorText = await res.text();
            console.error(`获取模型列表失败 (${res.status}):`, errorText);
            preserveCurrentModel(`获取失败: ${res.status}`);
            let message = errorText;
            try {
                const parsed = JSON.parse(errorText);
                const detail = parsed.detail;
                const rawMessage = detail?.message || parsed.message || detail || parsed;
                message = typeof rawMessage === 'string' ? rawMessage : JSON.stringify(rawMessage);
            } catch (_error) {}
            if (typeof window.showTemporaryToast === 'function') {
                window.showTemporaryToast(`获取模型列表失败：${message}`, 4200, 'error');
            }
            return;
        }
        const data = await res.json();
        const models = data.models || [];
        if (models.length === 0) {
            selectEl.innerHTML = '<option value="">未获取到模型，请检查地址/密钥</option>';
            return;
        }
        selectEl.innerHTML = '<option value="">请选择模型</option>';
        models.forEach(modelId => {
            const option = document.createElement('option');
            option.value = String(modelId);
            option.textContent = String(modelId);
            selectEl.appendChild(option);
        });
        const savedModel = await loadModelForProvider(provider);
        if (savedModel) {
            if (models.includes(savedModel)) {
                selectEl.value = savedModel;
                document.getElementById('custom-model-input').value = '';
            } else {
                document.getElementById('custom-model-input').value = savedModel;
                selectEl.value = '';
            }
            lastSavedModel = savedModel;
        }
    } catch (e) {
        console.error('网络错误:', e);
        preserveCurrentModel('网络错误');
        if (typeof window.showTemporaryToast === 'function') {
            window.showTemporaryToast('网络错误，请检查后端服务是否正常运行', 3600, 'error');
        }
    }
}

async function onProviderChange() {
    const provider = document.getElementById('provider-select').value;
    await saveProvider(provider);

    // 1. 加载已保存的 API 密钥
    const apiKey = await loadApiKeyForProvider(provider);
    const apiKeyInput = document.getElementById('api-key-input');
    apiKeyInput.value = apiKey || '';
    const savedState = window.savedApiKeyState?.[provider];
    apiKeyInput.dataset.configured = savedState?.configured ? '1' : '0';
    apiKeyInput.placeholder = savedState?.configured
        ? `已保存密钥（${savedState.maskedValue || '已配置'}）；留空保持不变`
        : '请输入 API 密钥';

    // 2. 加载已保存的 API 地址，如果没有则使用默认地址
    let apiBase = await loadApiBaseForProvider(provider);
    if (!apiBase && DEFAULT_API_BASE[provider]) {
        apiBase = DEFAULT_API_BASE[provider];
        if (apiBase) {
            await fetch('/set_api_base_for_provider', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ provider, api_base: apiBase })
            });
        }
    }
    document.getElementById('api-base-input').value = apiBase || '';

    // 3. 加载已保存的模型
    const savedModel = await loadModelForProvider(provider);
    if (savedModel) {
        document.getElementById('custom-model-input').value = savedModel;
        document.getElementById('model-select').value = '';
        lastSavedModel = savedModel;
    } else {
        document.getElementById('custom-model-input').value = '';
        document.getElementById('model-select').value = '';
        lastSavedModel = '';
    }

    // 4. 刷新模型列表
    await refreshModelsFromApi();
    // 5. 更新折叠栏状态显示
    await updateApiOptionsStatus(provider);
    // 6. 更新厂商提示信息
    updateApiOptionsHint();
    // 7. 加载思考模式状态（新增）
    await loadThinkMode(provider);
}

async function onModelChange() {
    const selectEl = document.getElementById('model-select');
    const customInput = document.getElementById('custom-model-input');
    let model = '';
    if (selectEl.value) {
        model = selectEl.value;
        customInput.value = '';
    } else if (customInput.value.trim()) {
        model = customInput.value.trim();
    }
    if (model && model !== lastSavedModel) {
        const provider = document.getElementById('provider-select').value;
        await saveCurrentModel(provider, model);
        lastSavedModel = model;
        await updateApiOptionsStatus(provider);
    }
}

// 更新 API 选项中的提示信息
function updateApiOptionsHint() {
    const provider = document.getElementById('provider-select')?.value;
    const compatHint = document.getElementById('openai-compat-hint');
    const specificHint = document.getElementById('provider-specific-hint');
    if (!compatHint) return;

    if (provider === 'custom') {
        compatHint.style.display = 'block';
        if (specificHint) specificHint.style.display = 'none';
    } else {
        compatHint.style.display = 'none';
        if (specificHint) {
            let hintText = '';
            switch (provider) {
                case 'openai':
                case 'gemini':
                case 'grok':
                    hintText = `${ZootIcons.html('globe')} 该服务可能需要网络代理才能正常访问`;
                    break;
                case 'moonshot':
                    hintText = `${ZootIcons.html('book')} 请从模型列表选择当前可用模型（如 kimi-k3）`;
                    break;
                case 'cline':
                    hintText = `${ZootIcons.html('cloud')} ClinePass模型需保留完整ID（如 cline-pass/kimi-k3）；模型访问测试可能消耗额度`;
                    break;
                case 'siliconflow':
                    hintText = `${ZootIcons.html('brain')} 部分思考模型已自动禁用深度推理，如遇问题可调整参数`;
                    break;
                case 'zhipu':
                    hintText = `${ZootIcons.html('settings')} 智谱 AI 推荐使用 temperature=0.95，已自动适配`;
                    break;
                case 'alibaba':
                    hintText = `${ZootIcons.html('cloud')} 仅支持百炼按量付费 sk- / sk-ws- Key；Token Plan、Coding Plan 不可用于应用后端`;
                    break;
                default:
                    hintText = '';
            }
            specificHint.innerHTML = hintText;
            specificHint.style.display = hintText ? 'block' : 'none';
        }
    }
}

// ========== 27.3.2. 思考模式状态 ==========
// 加载当前服务商的思考模式状态
async function loadThinkMode(provider) {
    const itemDiv = document.getElementById('think-mode-item');
    if (provider === 'cline') {
        if (itemDiv) itemDiv.style.display = 'none';
        return;
    }
    try {
        const res = await fetch(`/get_think_mode?provider=${provider}`);
        const data = await res.json();
        const toggle = document.getElementById('think-mode-toggle');
        if (toggle) {
            toggle.value = data.mode || (data.enabled ? 'on' : 'off');
            // 更新提示文字
            updateThinkModeHint(provider, toggle.value);
        }
        if (itemDiv) itemDiv.style.display = 'flex';
    } catch (e) {
        console.error('加载思考模式状态失败', e);
    }
}

// 保存思考模式状态
async function saveThinkMode(provider, mode) {
    try {
        await fetch(`/set_think_mode?provider=${provider}&mode=${encodeURIComponent(mode || 'auto')}`, {
            method: 'POST'
        });
    } catch (e) {
        console.error('保存思考模式状态失败', e);
    }
}

// 更新思考模式提示文字
function updateThinkModeHint(provider, mode) {
    const hintDiv = document.getElementById('think-mode-hint');
    if (!hintDiv) return;
    const enabled = mode === true || mode === 'on';
    let hintText = '';
    if (mode === 'auto') {
        hintText = provider === 'alibaba'
            ? '由阿里云百炼模型自动决定是否启用思考；请求不强制发送 enable_thinking'
            : '由模型或服务商自动决定';
    } else if (provider === 'gemini_proxy' || provider === 'gemini') {
        hintText = enabled ? '将输出完整思考过程（含思维链）' : '仅输出最终答案';
    } else if (provider === 'siliconflow' || provider === 'moonshot') {
        hintText = enabled ? '启用深度推理' : '禁用深度推理（更快）';
    } else {
        hintText = enabled ? '尝试启用思考（模型可能不支持，是否支持请自行检查服务商文档）' : '思考模式已关闭';
    }
    hintDiv.innerText = hintText;
}

// ========== 27.4. 折叠面板与UI初始化 ==========
function initApiSettingsCollapse() {
    if (apiSettingsInitialized) return;
    apiSettingsInitialized = true;

    // 辅助函数：更新知识图谱密钥显示状态（保留原有逻辑）
    async function updateKgApiKeyStatus() {
        const res = await fetch('/kg/api_key');
        if (res.ok) {
            const data = await res.json();
            const hasKey = Boolean(data.configured);
            document.getElementById('kg-api-key-display').textContent = hasKey ? '已设置' : '未设置';
            const input = document.getElementById('kg-api-key-input');
            if (input) {
                input.value = '';
                input.placeholder = hasKey
                    ? `已保存密钥（${data.masked_value || '已配置'}）；留空保持不变`
                    : '请输入知识图谱 API 密钥';
            }
        }
    }

    // 处理所有折叠面板（包含 kg_api_key, push_api_key, api_options, kg_config）
    const headers = document.querySelectorAll('.collapsible-header');
    headers.forEach(header => {
        const key = header.dataset.key;
        const content = document.querySelector(`.collapse-content[data-key="${key}"]`);
        if (!content) return;

        // 初始化状态显示
        if (key === 'kg_api_key') {
            updateKgApiKeyStatus();
        } else if (key === 'push_api_key') {
            updatePushApiKeyStatus();
        } else if (key === 'kg_config') {
            loadKgConfig(); // 知识图谱独立配置
        }

        header.addEventListener('click', async (e) => {
            e.stopPropagation();
            const isOpen = header.classList.contains('open');
            if (isOpen) {
                header.classList.remove('open');
                content.classList.remove('open');
            } else {
                // 关闭其他所有折叠面板
                document.querySelectorAll('.collapsible-header').forEach(h => h.classList.remove('open'));
                document.querySelectorAll('.collapse-content').forEach(c => c.classList.remove('open'));
                header.classList.add('open');
                content.classList.add('open');

                // 根据不同类型的面板加载对应数据
                if (key === 'kg_api_key') {
                    const input = content.querySelector('input');
                    if (input) {
                        input.focus();
                        const res = await fetch('/kg/api_key');
                        if (res.ok) {
                            const data = await res.json();
                            input.value = '';
                            input.placeholder = data.configured
                                ? `已保存密钥（${data.masked_value || '已配置'}）；留空保持不变`
                                : '请输入知识图谱 API 密钥';
                        }
                    }
                } else if (key === 'push_api_key') {
                    const input = content.querySelector('input');
                    if (input) {
                        input.focus();
                        const res = await fetch('/push/api_key');
                        if (res.ok) {
                            const data = await res.json();
                            input.value = '';
                            input.placeholder = data.configured
                                ? `已保存密钥（${data.masked_value || '已配置'}）；留空保持不变`
                                : '请输入消息推送 API 密钥';
                        }
                    }
                } else if (key === 'api_options') {
                    // 加载当前服务商的 API 地址和密钥
                    const provider = document.getElementById('provider-select').value;
                    const apiKey = await loadApiKeyForProvider(provider);
                    const apiBase = await loadApiBaseForProvider(provider);
                    document.getElementById('api-key-input').value = apiKey || '';
                    document.getElementById('api-base-input').value = apiBase || '';
                } else if (key === 'kg_config') {
                    await loadKgConfig();
                }
            }
        });
    });

    // 单独处理消息推送密钥的保存事件（输入框变化时自动保存）
    const pushContent = document.querySelector('.collapse-content[data-key="push_api_key"]');
    if (pushContent) {
        const pushInput = pushContent.querySelector('input');
        if (pushInput) {
            pushInput.addEventListener('change', async () => {
                const value = pushInput.value.trim();
                const res = await fetch('/push/api_key', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ api_key: value })
                });
                if (res.ok) {
                    alert('消息推送API密钥已保存');
                    updatePushApiKeyStatus();
                } else {
                    alert('保存失败');
                }
            });
        }
    }

    // 单独处理知识图谱密钥的保存事件（输入框变化时自动保存）
    const kgContent = document.querySelector('.collapse-content[data-key="kg_api_key"]');
    if (kgContent) {
        const kgInput = kgContent.querySelector('input');
        if (kgInput) {
            kgInput.addEventListener('change', async () => {
                const value = kgInput.value.trim();
                const res = await fetch('/kg/api_key', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ api_key: value })
                });
                if (res.ok) {
                    alert('知识图谱API密钥已保存');
                    updateKgApiKeyStatus();
                } else {
                    alert('保存失败');
                }
            });
        }
    }

    // 辅助函数：更新消息推送密钥显示状态
    async function updatePushApiKeyStatus() {
        const res = await fetch('/push/api_key');
        if (res.ok) {
            const data = await res.json();
            const hasKey = Boolean(data.configured);
            document.getElementById('push-api-key-display').textContent = hasKey ? '已设置' : '未设置';
        }
    }

    // 服务商切换事件（保持不变）
    const providerSelect = document.getElementById('provider-select');
    if (providerSelect) {
        providerSelect.removeEventListener('change', onProviderChange);
        providerSelect.addEventListener('change', onProviderChange);
    }

    // API选项内的控件绑定（刷新模型、自定义模型等，保持不变）
    const refreshBtn = document.getElementById('refresh-models-btn');
    if (refreshBtn) refreshBtn.addEventListener('click', () => refreshModelsFromApi());
    const customModelInput = document.getElementById('custom-model-input');
    if (customModelInput) customModelInput.addEventListener('change', onModelChange);
    const modelSelect = document.getElementById('model-select');
    if (modelSelect) modelSelect.addEventListener('change', onModelChange);
    const apiBaseInput = document.getElementById('api-base-input');
    const apiKeyInput = document.getElementById('api-key-input');
    if (apiBaseInput) apiBaseInput.addEventListener('change', saveCurrentApiBase);
    if (apiKeyInput) apiKeyInput.addEventListener('change', saveCurrentApiKey);

    // 知识图谱独立配置按钮事件（新增的面板）
    const kgResetBtn = document.getElementById('kg-reset-key-btn');
    if (kgResetBtn) kgResetBtn.addEventListener('click', resetKgApiKey);

    // 知识图谱服务状态点击可重新检测
    const kgStatusItem = document.getElementById('kg-service-item');
    if (kgStatusItem) kgStatusItem.addEventListener('click', checkKgHealth);
}

