// 拉伸模式事件绑定
function initStretchMode() {
    const card = document.getElementById('assistant-card');
    const stretchMode = document.getElementById('stretch-mode');
    const closeBtn = document.getElementById('stretch-close');
    const sendBtn = document.getElementById('stretch-send');
    const input = document.getElementById('stretch-input');
    const msgContainer = document.getElementById('stretch-messages');

    if (!card || !stretchMode) return;

    // 点击卡片展开
    card.addEventListener('click', (e) => {
        if (e.target.closest('.assistant-avatar')) return;
        enterStretchMode();
    });

    // 关闭按钮
    if (closeBtn) closeBtn.addEventListener('click', exitStretchMode);

    // 发送消息
    if (sendBtn && input) {
        sendBtn.addEventListener('click', sendStretchMessage);
        input.addEventListener('keypress', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendStretchMessage();
            }
        });
    }

    // 拉伸模式内部滚动：向上滑动到顶部时退出
    if (msgContainer) {
        let touchStartY = 0;
        msgContainer.addEventListener('touchstart', (e) => {
            touchStartY = e.touches[0].clientY;
        });
        msgContainer.addEventListener('touchmove', (e) => {
            if (msgContainer.scrollTop === 0) {
                const delta = e.touches[0].clientY - touchStartY;
                if (delta < -50) {  // 向上滑动超过50px
                    exitStretchMode();
                    e.preventDefault();
                }
            }
        });
    }

    // 拉伸模式头像点击菜单
    const stretchAvatar = document.getElementById('stretch-avatar');
    const assistantMenu = document.getElementById('assistant-menu');
    if (stretchAvatar && assistantMenu) {
        stretchAvatar.style.cursor = 'pointer';
        stretchAvatar.addEventListener('click', (e) => {
            e.stopPropagation();
            document.removeEventListener('click', window.closeAssistantMenu);
            const rect = stretchAvatar.getBoundingClientRect();
            assistantMenu.style.top = rect.bottom + 5 + 'px';
            assistantMenu.style.left = rect.left + 'px';
            assistantMenu.style.display = 'block';
            setTimeout(() => {
                document.addEventListener('click', window.closeAssistantMenu);
            }, 0);
        });
    }
}

// ========== 29.2.  记录板功能 ==========
// 记录板功能（持久化存储、清空、分析总结）
function initRecordBoard() {
    const header = document.getElementById('record-board-header');
    const content = document.getElementById('record-board-content');
    const expandBtn = document.getElementById('record-board-expand-btn');
    const textarea = document.getElementById('record-board-text');
    const clearBtn = document.getElementById('record-board-clear');
    const analyzeBtn = document.getElementById('record-board-analyze');

    if (!header || !content || !expandBtn || !textarea || !clearBtn || !analyzeBtn) {
        console.warn('记录板元素缺失，跳过初始化');
        return;
    }

    // 折叠/展开状态（持久化）
    let expanded = localStorage.getItem('recordBoardExpanded') === 'true';
    function updateExpandState() {
        if (expanded) {
            content.style.display = 'block';
            expandBtn.textContent = '▲';
            // 展开后自动调整高度
            setTimeout(() => autoResizeTextarea(), 50);
        } else {
            content.style.display = 'none';
            expandBtn.textContent = '▼';
        }
        localStorage.setItem('recordBoardExpanded', expanded);
    }
    header.addEventListener('click', () => {
        expanded = !expanded;
        updateExpandState();
    });
    updateExpandState();

    // textarea 自动扩展高度函数
    function autoResizeTextarea() {
        if (!textarea) return;
        textarea.style.height = 'auto';
        let newHeight = Math.min(textarea.scrollHeight, 384);
        newHeight = Math.max(newHeight, 108);
        textarea.style.height = newHeight + 'px';
    }

    // 加载已保存内容
    const savedContent = localStorage.getItem('recordBoardContent');
    if (savedContent !== null) textarea.value = savedContent;
    // 初始调整高度
    autoResizeTextarea();

    // 输入时自动调整高度
    textarea.addEventListener('input', autoResizeTextarea);

    // 失去焦点时保存内容
    textarea.addEventListener('blur', () => {
        localStorage.setItem('recordBoardContent', textarea.value);
    });

    // 清空按钮
    clearBtn.addEventListener('click', () => {
        if (confirm('清空记录板后将无法恢复，确定清空吗？')) {
            textarea.value = '';
            localStorage.setItem('recordBoardContent', '');
            autoResizeTextarea();
        }
    });

    // 分析总结按钮：构造记录板卡片 + 异步调用助理
    analyzeBtn.addEventListener('click', async () => {
        const boardContent = textarea.value.trim();
        if (!boardContent) {
            alert('记录板内容为空，无法分析');
            return;
        }
        // 确保拉伸模式已打开
        if (!stretchModeActive) {
            await enterStretchMode();
        }
        // 1. 构造记录板卡片消息
        const recordCardMsg = {
            role: 'user',
            type: 'record',           // 自定义类型
            content: boardContent,
            timestamp: Date.now() / 1000
        };
        stretchMessages.push(recordCardMsg);
        renderStretchMessages();

        // 2. 构建发送给助理的真实 prompt（不显示在界面上）
        const analysisPrompt = `这是博士的记录板，里面记录了各种内容，现在博士需要你帮忙，依次针对其中的内容进行分析总结扩展。
如果是灵感或想法，可以分析其可行性或缺点，同时给出可能的实现方案，可能的扩展性建议；
如果是观点，可以分析后给出你的意见建议；
如果是需求，可以视情况调用自己的工具来协助博士；
如果是备忘，可以提醒博士，并询问是否需要创建相应的待办事项。
以上，核心即是帮助博士整理分析，给出合理的反馈。

博士记录的内容如下：
${boardContent}`;

        // 3. 显示“思考中...”
        const thinkingMsg = { role: 'assistant', content: '思考中...', timestamp: Date.now() / 1000 };
        stretchMessages.push(thinkingMsg);
        renderStretchMessages();

        // 4. 调用助理接口
        try {
            const res = await fetch('/assistant/chat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ message: analysisPrompt })
            });
            const data = await res.json();
            // 移除“思考中”
            stretchMessages.pop();

            // 处理回复（可能普通文本或事务卡片）
            let replyContent = data.reply;
            if (!replyContent || replyContent.trim() === '') {
                replyContent = '操作已完成。';
            }
            // 清理数据块
            replyContent = replyContent.replace(/\[DATA:.*?\]/g, '').trim();
            if (!replyContent) replyContent = '操作已完成。';

            // 分段处理
            if (replyContent.includes('|')) {
                const parts = replyContent.split('|').map(p => p.trim()).filter(p => p);
                for (let i = 0; i < parts.length; i++) {
                    stretchMessages.push({
                        role: 'assistant',
                        content: parts[i],
                        timestamp: Date.now() / 1000 + i * 0.001
                    });
                    renderStretchMessages();
                    if (i < parts.length - 1) await new Promise(resolve => setTimeout(resolve, 300));
                }
            } else {
                stretchMessages.push({
                    role: 'assistant',
                    content: replyContent,
                    timestamp: Date.now() / 1000
                });
                renderStretchMessages();
            }
        } catch (err) {
            console.error('助理分析失败', err);
            stretchMessages.pop(); // 移除“思考中”
            stretchMessages.push({ role: 'assistant', content: '分析失败，请稍后再试。', timestamp: Date.now() / 1000 });
            renderStretchMessages();
        }
    });
}

// ========== 29.3.  待办事项管理 ==========
function formatTodoSubmitter(item) {
    const submitter = item?.submitter || {};
    const name = submitter.name || '未知提交人';
    const roleLabels = {
        user: '用户人格', assistant: '助理', operator: '干员',
        generator: '生成器', system: '系统', integration: '外部服务'
    };
    const role = roleLabels[submitter.role] || '';
    return role ? `${name} · ${role}` : name;
}

async function loadTodoItems() {
    try {
        const res = await fetch('/todo/list');
        const items = await res.json();
        const todoSection = document.querySelector('.todo-section');
        if (!todoSection) {
            console.warn('未找到 .todo-section');
            return;
        }
        let gridContainer = todoSection.querySelector('.todo-grid');
        if (!gridContainer) {
            const oldTrack = document.getElementById('todo-track');
            if (oldTrack) oldTrack.remove();
            gridContainer = document.createElement('div');
            gridContainer.className = 'todo-grid';
            todoSection.appendChild(gridContainer);
        }
        if (!items || items.length === 0) {
            gridContainer.innerHTML = '<div class="empty-todo" style="grid-column:1/-1; text-align:center; padding:20px;">还没有事务，点击右上角 + 添加</div>';
        } else {
            gridContainer.innerHTML = items.map(item => {
                let sourceHtml = '';
                let extraClass = '';
                if (item.source === 'event') {
                    extraClass = 'todo-card-event';
                } else if (item.source === 'birthday') {
                    extraClass = 'todo-card-birthday';
                }
                const transferBtn = (item.status === 'pending' && !item.transferred_to && item.source === 'event') ?
                    `<button class="todo-transfer" data-id="${item.id}" data-event-id="${item.event_id}">转交</button>` : '';
                return `
                    <div class="todo-card ${item.priority} ${item.completed ? 'completed' : ''} ${extraClass}" data-id="${item.id}">
                        <div class="todo-card-checkbox">
                            <input type="checkbox" class="todo-select" data-id="${item.id}" onclick="event.stopPropagation()">
                        </div>
                        <div class="todo-card-content">
                            <div class="todo-title">${escapeHtml(item.title)}</div>
                            ${item.description ? `<div class="todo-desc">${escapeHtml(item.description)}</div>` : ''}
                            <div class="todo-submitter">提交人：${escapeHtml(formatTodoSubmitter(item))}</div>
                            <div class="todo-due">截止: ${item.due_date ? new Date(item.due_date * 1000).toLocaleDateString() : '无'}</div>
                            <div class="todo-actions">
                                ${!item.completed ? `<button class="todo-btn complete" data-id="${item.id}">完成</button>` : ''}
                                ${transferBtn}
                                <button class="todo-btn delete" data-id="${item.id}">删除</button>
                            </div>
                            ${sourceHtml}
                        </div>
                    </div>
                `;
            }).join('');
        }

        // 绑定卡片点击和触摸事件
        bindTodoCardEvents(gridContainer);
        bindTodoEvents();
        // 绑定卡片点击事件委托（打开详情）
        gridContainer.removeEventListener('click', handleTodoCardClick);
        gridContainer.addEventListener('click', handleTodoCardClick);
    } catch (e) {
        console.error('加载待办事项失败', e);
        const todoSection = document.querySelector('.todo-section');
        if (todoSection) {
            let gridContainer = todoSection.querySelector('.todo-grid');
            if (!gridContainer) {
                gridContainer = document.createElement('div');
                gridContainer.className = 'todo-grid';
                todoSection.appendChild(gridContainer);
            }
            gridContainer.innerHTML = '<div class="empty-todo" style="grid-column:1/-1; text-align:center; padding:20px; color:red;">加载失败，请刷新重试</div>';
        }
    }
}

// 卡片点击事件处理（委托）
function handleTodoCardClick(e) {
    // 如果点击的目标或其父级是按钮、复选框、转交按钮区域，则不打开详情
    if (e.target.closest('.todo-btn') ||
        e.target.closest('.todo-select') ||
        e.target.closest('.todo-transfer') ||
        e.target.closest('.todo-checkbox-label') ||
        e.target.closest('.todo-card-checkbox')) {
        return;
    }
    const card = e.target.closest('.todo-card');
    if (card) {
        const todoId = card.dataset.id;
        openTodoDetail(todoId, false);
    }
}

function enterBatchMode(triggerCard) {
    if (batchModeActive) return;
    batchModeActive = true;
    const todoSection = document.querySelector('.todo-section');
    if (todoSection) todoSection.classList.add('batch-mode');
    const batchBar = document.getElementById('todo-batch-bar');
    if (batchBar) batchBar.style.display = 'flex';
    // 选中触发卡片的复选框
    const checkbox = triggerCard.querySelector('.todo-select');
    if (checkbox) checkbox.checked = true;
    updateBatchSelection();
}

function exitBatchMode() {
    batchModeActive = false;
    const todoSection = document.querySelector('.todo-section');
    if (todoSection) todoSection.classList.remove('batch-mode');
    const batchBar = document.getElementById('todo-batch-bar');
    if (batchBar) batchBar.style.display = 'none';
    document.querySelectorAll('.todo-select').forEach(cb => cb.checked = false);
    updateBatchSelection();
    // 清除可能残留的定时器（由全局管理）
    if (touchStartTimer) {
        clearTimeout(touchStartTimer);
        touchStartTimer = null;
    }
}

function updateBatchSelection() {
    const selected = document.querySelectorAll('.todo-select:checked');
    const count = selected.length;
    const selectedSpan = document.getElementById('selected-count');
    if (selectedSpan) selectedSpan.textContent = count;
    const selectAllBtn = document.getElementById('batch-select-all');
    if (selectAllBtn) {
        const allCheckboxes = document.querySelectorAll('.todo-select');
        const allChecked = allCheckboxes.length > 0 && Array.from(allCheckboxes).every(cb => cb.checked);
        selectAllBtn.textContent = allChecked ? '取消全选' : '全选';
    }
}

function toggleSelectAll() {
    const allCheckboxes = document.querySelectorAll('.todo-select');
    const anyUnchecked = Array.from(allCheckboxes).some(cb => !cb.checked);
    allCheckboxes.forEach(cb => cb.checked = anyUnchecked);
    updateBatchSelection();
}

async function batchComplete() {
    const selected = document.querySelectorAll('.todo-select:checked');
    if (selected.length === 0) return;
    showConfirmDialog('批量完成', `确定完成 ${selected.length} 项事务吗？`, async () => {
        for (const cb of selected) {
            const todoId = cb.dataset.id;
            await fetch('/todo/update', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id: todoId, completed: 1 })
            });
        }
        await loadTodoItems();
        exitBatchMode();
    });
}

async function batchDelete() {
    const selected = document.querySelectorAll('.todo-select:checked');
    if (selected.length === 0) return;
    showConfirmDialog('批量删除', `确定删除 ${selected.length} 项事务吗？`, async () => {
        for (const cb of selected) {
            const todoId = cb.dataset.id;
            await fetch('/todo/delete', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id: todoId })
            });
        }
        await loadTodoItems();
        exitBatchMode();
    });
}

function cancelBatch() {
    document.querySelectorAll('.todo-select').forEach(cb => {
        cb.checked = false;
    });
    updateBatchSelection();
}

function bindTodoEvents() {
    document.querySelectorAll('.todo-btn.complete').forEach(btn => {
        btn.removeEventListener('click', window._todoCompleteHandler);
        window._todoCompleteHandler = (e) => {
            e.stopPropagation();
            handleTodoComplete(e);
        };
        btn.addEventListener('click', window._todoCompleteHandler);
    });
    document.querySelectorAll('.todo-btn.delete').forEach(btn => {
        btn.removeEventListener('click', window._todoDeleteHandler);
        window._todoDeleteHandler = (e) => {
            e.stopPropagation();
            handleTodoDelete(e);
        };
        btn.addEventListener('click', window._todoDeleteHandler);
    });
    document.querySelectorAll('.todo-transfer').forEach(btn => {
        btn.removeEventListener('click', window._todoTransferHandler);
        window._todoTransferHandler = (e) => {
            e.stopPropagation();
            handleTodoTransfer(e);
        };
        btn.addEventListener('click', window._todoTransferHandler);
    });
}

function bindTodoCardEvents(container) {
    // 移除旧的监听器，避免重复绑定
    container.removeEventListener('touchstart', onContainerTouchStart);
    container.removeEventListener('touchend', onContainerTouchEnd);
    container.removeEventListener('touchmove', onContainerTouchMove);
    container.addEventListener('touchstart', onContainerTouchStart);
    container.addEventListener('touchend', onContainerTouchEnd);
    container.addEventListener('touchmove', onContainerTouchMove, { passive: true });
}

function onContainerTouchStart(e) {
    const card = e.target.closest('.todo-card');
    if (!card) return;
    touchStartCard = card;
    todoTouchMoved = false;
    todoTouchStartPoint = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    // 清除之前的定时器
    if (touchStartTimer) clearTimeout(touchStartTimer);
    // 设置长按定时器
    touchStartTimer = setTimeout(() => {
        if (touchStartCard) {
            enterBatchMode(touchStartCard);
        }
        touchStartTimer = null;
    }, LONG_PRESS_DURATION);
}

function onContainerTouchMove(e) {
    if (!todoTouchStartPoint || !touchStartCard) return;
    const point = e.touches[0];
    if (Math.hypot(point.clientX - todoTouchStartPoint.x, point.clientY - todoTouchStartPoint.y) > 10) {
        todoTouchMoved = true;
        clearTimeout(touchStartTimer);
        touchStartTimer = null;
    }
}

function onContainerTouchEnd(e) {
    if (touchStartTimer) {
        clearTimeout(touchStartTimer);
        touchStartTimer = null;
    }
    // 如果没有进入批量模式，并且是点击（非长按），则打开详情
    if (!batchModeActive && touchStartCard && !todoTouchMoved) {
        const todoId = touchStartCard.dataset.id;
        if (todoId) {
            openTodoDetail(todoId, false);
        }
    }
    touchStartCard = null;
    todoTouchStartPoint = null;
}

async function handleTodoComplete(e) {
    if (e) e.stopPropagation();
    const id = e.target.dataset.id;
    try {
        const res = await fetch('/todo/update', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id, completed: 1 })
        });
        if (res.ok) loadTodoItems();
        else alert('操作失败');
    } catch (err) { alert('请求出错'); }
}

async function handleTodoDelete(e) {
    e.stopPropagation();
    e.stopImmediatePropagation();
    const btn = e.target;
    const id = btn.dataset.id;
    if (!confirm('确定删除该待办事项吗？')) return;
    try {
        const res = await fetch('/todo/delete', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id })
        });
        if (res.ok) {
            loadTodoItems();
        } else {
            alert('删除失败');
        }
    } catch (err) {
        alert('请求出错');
    }
}

async function handleTodoTransfer(e) {
    if (e) e.stopPropagation();
    const eventId = e.target.dataset.eventId;
    if (!eventId) {
        alert('该待办事项非事件生成，无法转交');
        return;
    }
    const target = prompt("转交给哪位干员？（输入干员英文名，如 'amiya'，或输入 'assistant' 交给助理）", "assistant");
    if (!target) return;
    try {
        const res = await fetch('/event/transfer', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ event_id: eventId, target: target })
        });
        const data = await res.json();
        if (res.ok) {
            alert(data.message || '转交成功');
            loadTodoItems();
        } else alert('转交失败: ' + (data.error || '未知错误'));
    } catch (err) { alert('请求出错'); }
}

// ========== 29.3. 添加事务模态框 ==========
function toggleTodoEditMode(todoId) {
    const card = document.querySelector(`.todo-card[data-id="${todoId}"]`);
    if (!card) return;
    const trigger = card.querySelector('.todo-edit-trigger');

    if (currentEditingCardId === todoId) {
        // 退出编辑模式：恢复卡片样式，重新绑定原有点击事件
        card.classList.remove('edit-mode');
        trigger.classList.remove('edit-mode');
        currentEditingCardId = null;
        // 恢复卡片原有的 onclick 事件（打开详情）
        card.onclick = () => openTodoDetail(todoId);
    } else {
        // 退出之前的编辑模式（如果有）
        if (currentEditingCardId) {
            const prevCard = document.querySelector(`.todo-card[data-id="${currentEditingCardId}"]`);
            if (prevCard) {
                prevCard.classList.remove('edit-mode');
                prevCard.querySelector('.todo-edit-trigger')?.classList.remove('edit-mode');
                prevCard.onclick = () => openTodoDetail(currentEditingCardId);
            }
        }
        // 进入编辑模式
        card.classList.add('edit-mode');
        trigger.classList.add('edit-mode');
        currentEditingCardId = todoId;
        // 解除卡片点击事件（避免打开详情）
        card.onclick = null;
        // 可选：自动打开事务详情模态框（或直接内联编辑，这里简单打开详情）
        // 为了符合您的要求“编辑模式下保存和取消按钮不变”，我们直接打开原有的详情模态框
        openTodoDetail(todoId);
    }
}

function showAddTodoModal() {
    // 确保助理头像加载完成（不阻塞弹窗显示）
    loadAssistantAvatarForModal().catch(e => console.warn('加载助理头像失败', e));
    const pref = localStorage.getItem('transferToAssistantPref');
    const checkbox = document.getElementById('transfer-to-assistant');
    if (checkbox && pref !== null) {
        checkbox.checked = pref === 'true';
    }
    // 强制显示模态框（如果元素缺失给出提示）
    const modal = document.getElementById('addTodoModal');
    if (!modal) {
        console.error('addTodoModal 元素不存在');
        alert('无法打开添加事务弹窗，请刷新页面');
        return;
    }

    // 设置截止日期默认值（全局年份）
    const dueDateInput = document.getElementById('todo-due-date');
    if (dueDateInput && !dueDateInput.value) {
        setDefaultDateWithGlobalYear(dueDateInput);
        const displaySpan = document.getElementById('selected-date-display');
        if (displaySpan) {
            const now = new Date();
            const defaultDate = new Date(globalYear || 1099, now.getMonth(), now.getDate());
            displaySpan.textContent = defaultDate.toISOString().slice(0, 10);
        }
    }

    showModal('addTodoModal');
}

function closeAddTodoModal() {
    hideModal('addTodoModal');
    document.getElementById('todo-title').value = '';
    document.getElementById('todo-description').value = '';
    document.getElementById('todo-category').value = 'task';
    document.getElementById('todo-due-date').value = '';
    document.getElementById('selected-date-display').textContent = '未选择';
    document.getElementById('transfer-to-assistant').checked = false;
    const priorityBtns = document.querySelectorAll('.priority-btn');
    priorityBtns.forEach(btn => btn.classList.remove('selected'));
    const mediumBtn = document.querySelector('.priority-btn.medium');
    if (mediumBtn) mediumBtn.classList.add('selected');
}

async function submitAddTodo() {
    const title = document.getElementById('todo-title').value.trim();
    if (!title) {
        alert('请输入任务标题');
        return;
    }
    const description = document.getElementById('todo-description').value.trim();
    const category = document.getElementById('todo-category').value;
    const selectedPriorityBtn = document.querySelector('.priority-btn.selected');
    let priority = 'medium';
    if (selectedPriorityBtn) priority = selectedPriorityBtn.dataset.priority;
    const dueDate = document.getElementById('todo-due-date').value;
    let dueTimestamp = dueDate ? new Date(dueDate).getTime() / 1000 : 0;
    const transferToAssistant = document.getElementById('transfer-to-assistant').checked;

    try {
        const res = await fetch('/todo/add', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                title, description: description || '', category, priority,
                due_date: dueTimestamp, transfer_to_assistant: transferToAssistant
            })
        });

        if (!res.ok) {
            let errorMsg = '添加失败';
            try {
                const err = await res.json();
                errorMsg = err.detail || err.message || errorMsg;
            } catch (e) {}
            alert(errorMsg);
            return;
        }

        // 成功：尝试解析返回的 JSON
        let todoId = null;
        try {
            const result = await res.json();
            todoId = result.id;
        } catch (jsonError) {
            console.warn('解析响应 JSON 失败，但请求已成功，事务可能已创建', jsonError);
            // 如果无法获取 ID，仍标记为成功
        }

        // 保存用户偏好
        localStorage.setItem('transferToAssistantPref', transferToAssistant);

        // 刷新待办列表
        await loadTodoItems();
        closeAddTodoModal();

        // 新事务通知
        const iconMap = {
            task: '/static/images/task_icon.png',
            encounter: '/static/images/encounter_icon.png',
            event: '/static/images/event_icon.png',
            birthday: '/static/images/birthday_icon.png',
            other: '/static/images/other_icon.png'
        };
        showNewTaskNotification(title, category, description, iconMap[category] || '');

         // 刷新未读计数，更新底部导航栏红点
        await updateTodoUnviewedCount();

        // 如果勾选了转交助手且获取到了 todoId，则将任务推送给助理
        if (transferToAssistant && todoId) {
            const newTodo = {
                id: todoId,
                title: title,
                description: description,
                priority: priority,
                due_date: dueTimestamp
            };
            if (typeof addTaskToStretchMode === 'function') {
                // 1. 确保拉伸模式已打开并等待其完全初始化
                if (!stretchModeActive) {
                    await enterStretchMode();  // 关键：使用 await
                    // 2. 等待一帧，确保 DOM 渲染完成（可选，但更稳妥）
                    await new Promise(resolve => setTimeout(resolve, 100));
                }
                // 3. 添加任务卡片
                addTaskToStretchMode(newTodo);
            } else {
                console.warn('addTaskToStretchMode 未定义');
            }
        }

    } catch (e) {
        console.error('添加事务出错', e);
        alert('添加失败，请检查网络或后端服务');
    }
}

function handlePriorityClick(e) {
    const container = e.currentTarget.parentElement;
    container.querySelectorAll('.priority-btn').forEach(btn => btn.classList.remove('selected'));
    e.currentTarget.classList.add('selected');
}

function showTransferInfo() {
    alert("转交助手说明\n\n勾选后，该任务将自动转交给助手处理。\n若任务指令清晰，助手将自动开始执行。\n您可以在任务卡片处修改内容，只要保持勾选，助手会自动同步更新。\n您也可以与助手对话，让助手帮助调整任务细节。");
}

// 向拉伸模式对话历史添加任务卡片
function addTaskToStretchMode(task) {
    const taskMessage = {
        role: 'user',
        type: 'task',
        content: task,
        timestamp: Date.now() / 1000
    };
    stretchMessages.push(taskMessage);
    if (stretchModeActive) {
        renderStretchMessages();
    }
    processTaskWithAssistant(task);
}

// 助理处理任务（发送给助理API，不通过用户输入框）
async function processTaskWithAssistant(task) {
    // 构建任务描述文本
    const taskText = `【转交事务】博士已将以下事务转交给你处理，请直接处理，不要再创建新的事务（不要调用 create_todo 工具）。事务详情：\n标题：${task.title}\n描述：${task.description || '无'}\n优先级：${task.priority}\n截止日期：${task.due_date ? new Date(task.due_date * 1000).toLocaleDateString() : '未设置'}`;

    // 直接调用助理接口，不通过用户输入框
    try {
        // 显示“思考中...”
        const thinkingMsg = { role: 'assistant', content: '思考中...', timestamp: Date.now() / 1000 };
        stretchMessages.push(thinkingMsg);
        renderStretchMessages();

        const res = await fetch('/assistant/chat', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ message: taskText })
        });
        const data = await res.json();

        // 移除“思考中”
        stretchMessages.pop();

        // 处理回复（可能是普通文本或事务卡片）
        if (data.reply.startsWith('[事务卡片]')) {
            try {
                const cardJson = data.reply.substring('[事务卡片]'.length).trim();
                const card = JSON.parse(cardJson);
                if (card.type === 'todo_card') {
                    await saveAssistantCard(card);
                    stretchMessages.push({
                        role: 'assistant',
                        type: 'task',
                        content: {
                            id: card.id,
                            title: card.title,
                            description: card.description,
                            priority: card.priority,
                            due_date: card.due_date,
                            progress: card.progress
                        },
                        timestamp: Date.now() / 1000
                    });
                    renderStretchMessages();
                    return;
                }
            } catch(e) {}
        }

        stretchMessages.push({ role: 'assistant', content: data.reply, timestamp: Date.now() / 1000 });
        renderStretchMessages();
    } catch (err) {
        stretchMessages.pop();
        stretchMessages.push({ role: 'assistant', content: '处理任务失败，请稍后再试。', timestamp: Date.now() / 1000 });
        renderStretchMessages();
    }
}

// ========== 29.4. 事务详情模态框 ==========
async function openTodoDetail(todoId, editMode = false) {
    try {
        const res = await fetch(`/todo/detail/${todoId}`);
        if (!res.ok) throw new Error('加载失败');
        const data = await res.json();

        // ✅ 标记该待办为已查看（无论是否编辑，打开就算查看）
        markTodoViewed(todoId);

        // 设置优先级颜色
        const modal = document.getElementById('todoDetailModal');
        modal.querySelector('.todo-detail-modal-content').setAttribute('data-priority', data.priority);

        // 展示模式填充
        document.getElementById('detail-title-display').textContent = data.title;
        document.getElementById('detail-description-display').textContent = data.description || '';
        const priorityMap = { high: '高', medium: '中', low: '低' };
        document.getElementById('detail-priority-display').textContent = priorityMap[data.priority] || '中';
        const dueDate = data.due_date ? new Date(data.due_date * 1000).toLocaleDateString() : '未设置';
        document.getElementById('detail-due-date-display').textContent = dueDate;
        document.getElementById('detail-submitter-display').textContent = formatTodoSubmitter(data);
        const progress = data.progress || 0;
        document.getElementById('detail-progress-fill').style.width = progress + '%';
        document.getElementById('detail-progress-display').textContent = progress + '%';
        document.getElementById('detail-notes-display').textContent = data.notes || '';

        // 编辑模式表单填充
        document.getElementById('edit-title').value = data.title;
        document.getElementById('edit-description').value = data.description || '';
        document.getElementById('edit-priority').value = data.priority;

        const editDueDateInput = document.getElementById('edit-due-date');
        if (data.due_date) {
            editDueDateInput.value = new Date(data.due_date * 1000).toISOString().slice(0,10);
        } else {
            // 没有截止日期时，设置默认值为全局年份的当天
            setDefaultDateWithGlobalYear(editDueDateInput);
        }

        document.getElementById('edit-progress').value = progress;
        document.getElementById('edit-progress-value').textContent = progress + '%';
        document.getElementById('edit-notes').value = data.notes || '';

        const editBtn = document.getElementById('todo-detail-edit-btn');
        const shareBtn = document.getElementById('todo-detail-share-btn');
        const displayDiv = document.getElementById('display-mode');
        const editDiv = document.getElementById('edit-mode');
        const saveBtn = document.getElementById('save-todo-detail');
        const cancelBtn = document.getElementById('cancel-edit');

        const enterEditMode = () => {
            displayDiv.style.display = 'none';
            editDiv.style.display = 'block';
            editBtn.classList.add('x-mode');
            shareBtn.style.display = 'none';
        };
        const exitEditMode = () => {
            displayDiv.style.display = 'block';
            editDiv.style.display = 'none';
            editBtn.classList.remove('x-mode');
            shareBtn.style.display = 'block';
            // 重置编辑表单为当前数据（可能已更新）
            document.getElementById('edit-title').value = data.title;
            document.getElementById('edit-description').value = data.description || '';
            document.getElementById('edit-priority').value = data.priority;
            if (data.due_date) {
                document.getElementById('edit-due-date').value = new Date(data.due_date * 1000).toISOString().slice(0,10);
            } else {
                document.getElementById('edit-due-date').value = '';
            }
            document.getElementById('edit-progress').value = data.progress || 0;
            document.getElementById('edit-progress-value').textContent = (data.progress || 0) + '%';
            document.getElementById('edit-notes').value = data.notes || '';
        };

        if (editMode) {
            enterEditMode();
        } else {
            exitEditMode();
        }

        editBtn.onclick = () => {
            if (editDiv.style.display === 'none') {
                enterEditMode();
            } else {
                exitEditMode();
            }
        };

        saveBtn.onclick = async () => {
            const updated = {
                id: todoId,
                title: document.getElementById('edit-title').value.trim(),
                description: document.getElementById('edit-description').value,
                priority: document.getElementById('edit-priority').value,
                due_date: document.getElementById('edit-due-date').value ? new Date(document.getElementById('edit-due-date').value).getTime() / 1000 : 0,
                progress: parseInt(document.getElementById('edit-progress').value),
                notes: document.getElementById('edit-notes').value
            };
            if (!updated.title) {
                alert('标题不能为空');
                return;
            }
            const updateRes = await fetch('/todo/update_detail', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updated)
            });
            if (updateRes.ok) {
                // 更新本地数据对象
                data.title = updated.title;
                data.description = updated.description;
                data.priority = updated.priority;
                data.due_date = updated.due_date;
                data.progress = updated.progress;
                data.notes = updated.notes;
                // 刷新显示区域
                document.getElementById('detail-title-display').textContent = updated.title;
                document.getElementById('detail-description-display').textContent = updated.description || '';
                const priorityMap = { high: '高', medium: '中', low: '低' };
                document.getElementById('detail-priority-display').textContent = priorityMap[updated.priority] || '中';
                const dueDate = updated.due_date ? new Date(updated.due_date * 1000).toLocaleDateString() : '未设置';
                document.getElementById('detail-due-date-display').textContent = dueDate;
                document.getElementById('detail-progress-fill').style.width = updated.progress + '%';
                document.getElementById('detail-progress-display').textContent = updated.progress + '%';
                document.getElementById('detail-notes-display').textContent = updated.notes || '';
                // 刷新待办列表（后台刷新，弹窗不关闭）
                loadTodoItems();
                // 退出编辑模式（回到显示模式）
                exitEditMode();
                alert('保存成功');
            } else {
                alert('保存失败');
            }
        };

        cancelBtn.onclick = exitEditMode;

        // 分享按钮
        shareBtn.onclick = () => {
            showShareOptions(todoId, data);
        };

        showModal('todoDetailModal');
    } catch (e) {
        console.error(e);
        alert('加载事务详情失败');
    }
}

// 分享选项弹窗
function showShareOptions(todoId, todoData) {
    // 移除已存在的分享模态框
    const existing = document.getElementById('shareModal');
    if (existing) existing.remove();

    const shareHtml = `
        <div class="modal" id="shareModal" style="display:flex;">
            <div class="modal-content">
                <div class="modal-header">分享事务</div>
                <div class="modal-body">
                    <button id="share-to-operator" class="share-option">分享给干员</button>
                    <button id="share-to-group" class="share-option">分享到群聊</button>
                </div>
                <div class="modal-footer">
                    <button onclick="hideModal('shareModal')">取消</button>
                </div>
            </div>
        </div>
    `;
    document.body.insertAdjacentHTML('beforeend', shareHtml);

    const shareModal = document.getElementById('shareModal');
    const shareToOperatorBtn = document.getElementById('share-to-operator');
    const shareToGroupBtn = document.getElementById('share-to-group');

    // 移除旧监听，避免重复绑定
    const newShareToOperator = shareToOperatorBtn.cloneNode(true);
    shareToOperatorBtn.parentNode.replaceChild(newShareToOperator, shareToOperatorBtn);
    const newShareToGroup = shareToGroupBtn.cloneNode(true);
    shareToGroupBtn.parentNode.replaceChild(newShareToGroup, shareToGroupBtn);

    newShareToOperator.onclick = () => {
        hideModal('shareModal');
        shareTodoToOperator(todoId, todoData);
    };
    newShareToGroup.onclick = () => {
        hideModal('shareModal');
        shareTodoToGroup(todoId, todoData);
    };
}

function selectTodoShareTarget(targetType) {
    return new Promise(resolve => {
        document.getElementById('todoShareTargetPage')?.remove();
        const entries = targetType === 'operator'
            ? Array.from(operatorMap.values()).map(op => ({ id: String(op.id), name: op.codename || String(op.id), avatar: getOperatorAvatarUrl(String(op.id)) }))
            : Object.entries(groups).map(([id, group]) => ({ id, name: group.name || id, avatar: group.avatar || '/static/avatars/default.webp' }));
        const page = document.createElement('div');
        page.id = 'todoShareTargetPage';
        page.className = 'modal todo-share-target-page';
        page.style.display = 'flex';
        page.innerHTML = `<div class="modal-content"><div class="modal-header">选择${targetType === 'operator' ? '干员' : '群聊'}</div><div class="modal-body"><input class="todo-share-search" placeholder="搜索名称"><div class="todo-share-target-list"></div></div><div class="modal-footer"><button type="button" class="todo-share-cancel">取消</button></div></div>`;
        document.body.appendChild(page);
        const list = page.querySelector('.todo-share-target-list');
        const close = value => { page.remove(); resolve(value); };
        const render = keyword => {
            const query = keyword.trim().toLowerCase();
            list.innerHTML = entries.filter(item => `${item.name} ${item.id}`.toLowerCase().includes(query)).map(item => `<button type="button" class="todo-share-target" data-id="${escapeHtml(item.id)}"><img src="${escapeHtml(item.avatar)}" onerror="this.src='/static/avatars/default.webp'"><span><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.id)}</small></span></button>`).join('') || '<div class="empty-state">没有匹配项</div>';
        };
        page.querySelector('.todo-share-search').addEventListener('input', event => render(event.target.value));
        list.addEventListener('click', event => {
            const item = event.target.closest('.todo-share-target');
            if (item) close(item.dataset.id);
        });
        page.querySelector('.todo-share-cancel').onclick = () => close(null);
        render('');
    });
}

async function shareTodoToOperator(todoId, todoData) {
    const target = await selectTodoShareTarget('operator');
    if (!target) return;

    try {
        const res = await fetch('/share/todo', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                target_type: 'operator',
                target_id: target,
                todo_id: todoId
            })
        });

        if (res.ok) {
            // 尝试解析响应，但不强制要求 JSON
            try {
                const data = await res.json();
                alert(`已分享给干员 ${target}`);
            } catch (e) {
                alert(`已分享给干员 ${target}`);
            }
        } else {
            let errorMsg = '分享失败';
            try {
                const err = await res.json();
                errorMsg = err.detail || err.message || errorMsg;
            } catch (e) {}
            alert(errorMsg);
        }
    } catch (err) {
        console.error('分享给干员失败', err);
        alert('分享失败，请检查网络连接');
    }
}

