// ========== 29.5. 全局事务提醒 ==========
class NotificationManager {
    constructor() {
        this.el = document.getElementById('global-notification');
        if (!this.el) return;
        this.timeout = null;
        this.autoHideDelay = 4000;
        this.currentChatKey = null;
        this.initEvents();
    }
    initEvents() {
        this.el.addEventListener('click', () => {
            this.hide();
            if (this.currentChatKey) {
                // 清除对应聊天的未读
                clearUnread(this.currentChatKey);
                // 解析 chatKey 并跳转到对应聊天页
                const [type, id] = this.currentChatKey.split(':');
                if (type === 'private') {
                    currentOperatorId = id;
                    currentGroupId = null;
                    loadPrivateHistory(id);
                } else if (type === 'group') {
                    currentGroupId = id;
                    currentOperatorId = null;
                    loadGroupHistory(id);
                }
                saveCurrentChat();
                showPage('chat-detail');
            } else {
                showPage('tasks');
            }
            this.currentChatKey = null;
        });
    }
    show(title, type, description, typeIcon = '', chatKey = null) {
        if (!this.el) return;
        this.currentChatKey = chatKey;  // 使用传入的 chatKey
        this.el.querySelector('.notif-title span:first-child').textContent = title || '新事务';
        this.el.querySelector('.type-name').textContent = type || '事务';
        this.el.querySelector('.notif-desc').textContent = this.truncate(description || '', 50);
        const iconImg = this.el.querySelector('.type-icon');
        if (typeIcon) {
            iconImg.src = typeIcon;
            iconImg.style.display = 'inline-block';
        } else {
            iconImg.style.display = 'none';
        }
        if (this.timeout) clearTimeout(this.timeout);
        this.el.classList.remove('hidden');
        this.el.classList.add('show');
        this.timeout = setTimeout(() => this.hide(), this.autoHideDelay);
    }
    hide() {
        if (!this.el) return;
        this.el.classList.remove('show');
        this.el.classList.add('hidden');
        if (this.timeout) clearTimeout(this.timeout);
    }
    truncate(str, maxLen) {
        if (!str) return '';
        return str.length > maxLen ? str.substring(0, maxLen) + '...' : str;
    }
}
window.notificationManager = new NotificationManager();

function showNewTaskNotification(title, type, description, iconUrl = '', chatKey = null) {
    if (window.notificationManager) {
        window.notificationManager.show(title, type, description, iconUrl, chatKey);
    }
    updateChatListFromMessage('assistant', `【事务】${title}`, Date.now()/1000, 'private', null, true, 'text');
}

// ========== 29.6. 简报相关 ==========
async function loadBriefing(date, period) {
    const dateStr = date.toISOString().slice(0,10);
    let url = `/briefing/get?date=${dateStr}`;
    if (period) url += `&period=${period}`;
    const res = await fetch(url);
    const data = await res.json();
    const periodLabel = period === 'morning' ? '早间简报' : (period === 'evening' ? '晚间简报' : '综合简报');
    document.getElementById('briefing-period-label').textContent = periodLabel;
    document.getElementById('briefing-date-label').textContent = dateStr;

    const section = document.querySelector('.briefing-section');
    section.classList.remove('morning', 'evening');
    if (period === 'morning') section.classList.add('morning');
    else if (period === 'evening') section.classList.add('evening');

    const regenerateBtn = document.getElementById('briefing-regenerate');
    if (data.status === 'ok') {
        const b = data.briefing;
        document.getElementById('briefing-text').textContent = b.content || '暂无内容';
        const stats = b.statistics || { total: 0, completed: 0, pending: 0 };
        document.getElementById('briefing-stats').innerHTML = `📊 总计: ${stats.total} | ✅ 完成: ${stats.completed} | ⏳ 未完成: ${stats.pending}`;

        const taskGroups = b.task_groups || { today_due: [], other_pending: [], no_due_pending: [], today_completed: [] };
        let detailsHtml = '';
        if (taskGroups.today_due && taskGroups.today_due.length > 0) {
            detailsHtml += `<div class="briefing-task-group"><strong>⚠️ 今日到期</strong><ul>${taskGroups.today_due.map(t => `<li>${escapeHtml(t.title)} (${t.priority})</li>`).join('')}</ul></div>`;
        }
        if (taskGroups.other_pending && taskGroups.other_pending.length > 0) {
            detailsHtml += `<div class="briefing-task-group"><strong>📋 其他待办</strong><ul>${taskGroups.other_pending.map(t => `<li>${escapeHtml(t.title)} (${t.priority})</li>`).join('')}</ul></div>`;
        }
        if (taskGroups.no_due_pending && taskGroups.no_due_pending.length > 0) {
            detailsHtml += `<div class="briefing-task-group"><strong>📅 无截止日期</strong><ul>${taskGroups.no_due_pending.map(t => `<li>${escapeHtml(t.title)} (${t.priority})</li>`).join('')}</ul></div>`;
        }
        if (taskGroups.today_completed && taskGroups.today_completed.length > 0) {
            detailsHtml += `<div class="briefing-task-group"><strong>✅ 今日完成</strong><ul>${taskGroups.today_completed.map(t => `<li>${escapeHtml(t.title)}</li>`).join('')}</ul></div>`;
        }
        if (detailsHtml) {
            const statsDiv = document.getElementById('briefing-stats');
            statsDiv.innerHTML += `<div class="briefing-details">${detailsHtml}</div>`;
        }
        regenerateBtn.textContent = '重新生成';
        regenerateBtn.disabled = false;
    } else {
        document.getElementById('briefing-text').innerHTML = '<div class="blur-placeholder">当日简报未总结</div>';
        document.getElementById('briefing-stats').innerHTML = '';
        regenerateBtn.textContent = '提前生成';
        regenerateBtn.disabled = false;
    }
}

async function generateBriefing(date, period) {
    const dateStr = date.toISOString().slice(0,10);
    const regenerateBtn = document.getElementById('briefing-regenerate');
    const overlay = document.getElementById('briefing-overlay');
    const progressText = document.getElementById('progress-text');

    if (regenerateBtn.dataset.generating === 'true') return;
    regenerateBtn.dataset.generating = 'true';
    regenerateBtn.disabled = true;
    overlay.style.display = 'flex';
    progressText.textContent = '整理事务中...';

    try {
        await new Promise(resolve => setTimeout(resolve, 500));
        progressText.textContent = '助理总结中...';

        // 手动生成：不传 period，但传 manual=true
        const body = { date: dateStr, manual: true };
        // 如果是早/晚间自动生成，需要传 period，但手动生成不传
        const res = await fetch('/briefing/generate', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(body)
        });

        if (res.ok) {
            const data = await res.json();
            if (data.status === 'ok') {
                // 重新加载简报（此时 period 传 null 表示综合简报）
                await loadBriefing(date, null);
            } else {
                alert('生成失败: ' + (data.message || '未知错误'));
            }
        } else {
            const err = await res.json();
            alert('生成失败: ' + (err.detail || '服务器错误'));
        }
    } catch (e) {
        console.error('生成简报异常:', e);
        alert('生成失败，请检查网络连接');
    } finally {
        overlay.style.display = 'none';
        regenerateBtn.disabled = false;
        delete regenerateBtn.dataset.generating;
    }
}

function initBriefing() {
    const header = document.getElementById('briefing-header');
    const expandBtn = document.getElementById('briefing-expand-btn');
    const contentDiv = document.getElementById('briefing-content');
    const prevBtn = document.getElementById('briefing-prev');
    const nextBtn = document.getElementById('briefing-next');
    const regenerateBtn = document.getElementById('briefing-regenerate');

    header.addEventListener('click', (e) => {
        if (e.target.closest('.briefing-nav')) return;
        briefingExpanded = !briefingExpanded;
        contentDiv.style.display = briefingExpanded ? 'block' : 'none';
        expandBtn.textContent = briefingExpanded ? '▲' : '▼';
    });

    prevBtn.addEventListener('click', () => {
        currentBriefingDate.setDate(currentBriefingDate.getDate() - 1);
        loadBriefing(currentBriefingDate, currentBriefingPeriod);
    });
    nextBtn.addEventListener('click', () => {
        const newDate = new Date(currentBriefingDate);
        newDate.setDate(newDate.getDate() + 1);
        if (newDate > new Date()) {
            alert('不能查看未来日期');
            return;
        }
        currentBriefingDate = newDate;
        loadBriefing(currentBriefingDate, currentBriefingPeriod);
    });

    regenerateBtn.addEventListener('click', () => {
        generateBriefing(currentBriefingDate, currentBriefingPeriod);
    });

    loadBriefing(new Date(), 'morning');
}

