function showStatDetail(type, value) {
    // 处理详细统计（跳转页面）
    if (type === 'detailed') {
        showPage('statistics-detail');
        if (typeof loadStatisticsDetail === 'function') loadStatisticsDetail();
        return;
    }
    // 开发中功能
    if (type === 'push' || type === 'agent') {
        showUnderDevelopmentModal();
        return;
    }
    const typeMap = {
        'chat': { title: '对话次数', metric: 'chat_count', unit: '次', color: '#28a745' },
        'token': { title: 'Token用量', metric: 'token_usage', unit: 'Token', color: '#007bff' },
        'kg': { title: '知识图谱调用', metric: 'kg_calls', unit: '次', color: '#6f42c1' },
        'operator': { title: '干员数量', metric: null, unit: '位', color: '#fd7e14' }
    };
    const info = typeMap[type];
    if (!info) {
        alert('未知统计类型');
        return;
    }

    // 确保值显示正常
    let displayValue = value;
    if (type === 'kg' && (value === '0' || value === '--')) displayValue = '0';
    if (type === 'operator') displayValue = operators.length;

    // 移除已存在的模态框（防止重复）
    const existingModal = document.getElementById('stat-detail-modal');
    if (existingModal) existingModal.remove();

    // 创建模态框
    const modal = document.createElement('div');
    modal.id = 'stat-detail-modal';
    modal.className = 'modal';
    modal.style.display = 'flex';
    modal.style.zIndex = '10001';
    modal.innerHTML = `
        <div class="modal-content" style="max-width: 500px; width: 90%; background: var(--bg-color, #fff); border-radius: 16px;">
            <div class="trust-modal-header" style="display: flex; justify-content: space-between; align-items: center; padding: 15px; border-bottom: 1px solid var(--border-color, #eee);">
                <span style="font-size: 18px; font-weight: bold;">${info.title}</span>
                <span class="close" style="cursor: pointer; font-size: 24px;">&times;</span>
            </div>
            <div class="trust-modal-body" style="padding: 20px;">
                <div style="text-align: center; margin-bottom: 20px;">
                    <span style="font-size: 48px; font-weight: bold; color: ${info.color};">${displayValue}</span>
                    <span style="font-size: 16px; margin-left: 8px;">${info.unit}</span>
                </div>
                ${info.metric ? `
                    <div style="margin-bottom: 15px;">
                        <div style="display: flex; justify-content: space-between; margin-bottom: 8px;">
                            <span>走势图</span>
                            <div>
                                <button class="trend-period-btn" data-period="day" style="margin-right: 5px;">按天</button>
                                <button class="trend-period-btn" data-period="hour">按小时</button>
                            </div>
                        </div>
                        <canvas id="stat-trend-canvas" width="400" height="200" style="width:100%; height:200px;"></canvas>
                    </div>
                ` : ''}
                <div style="margin-top: 15px; text-align: center;">
                    <button id="reset-stat-btn" style="padding: 8px 16px; background: #dc3545; color: white; border: none; border-radius: 4px;">重置此项统计</button>
                </div>
            </div>
        </div>
    `;
    document.body.appendChild(modal);

    // 关闭模态框时销毁图表
    let currentChart = null;
    const closeModal = () => {
        if (currentChart) {
            currentChart.destroy();
            currentChart = null;
        }
        modal.remove();
    };
    modal.querySelector('.close').onclick = closeModal;
    modal.addEventListener('click', (e) => { if (e.target === modal) closeModal(); });

    // 重置按钮
    const resetBtn = modal.querySelector('#reset-stat-btn');
    resetBtn.addEventListener('click', async () => {
        if (confirm(`确定重置${info.title}吗？`)) {
            const res = await fetch(`/stats/reset/${type}`);
            if (res.ok) {
                alert('重置成功');
                closeModal();
                loadStats();
                if (type === 'kg') {
                    const kgCard = document.getElementById('stat-kg-count');
                    if (kgCard) kgCard.textContent = '0';
                } else if (type === 'chat') {
                    const chatCard = document.getElementById('stat-chat-count');
                    if (chatCard) chatCard.textContent = '0';
                } else if (type === 'token') {
                    const tokenCard = document.getElementById('stat-token-count');
                    if (tokenCard) tokenCard.textContent = '0';
                }
            } else {
                alert('重置失败');
            }
        }
    });

    // 如果有走势数据，加载并绘制
    if (info.metric) {
        let currentPeriod = 'day';
        const canvas = document.getElementById('stat-trend-canvas');
        if (!canvas) return;

        async function loadTrend(period) {
            try {
                const res = await fetch(`/stats/trend_by_type?metric=${info.metric}&period=${period}&limit=${period === 'day' ? 30 : 168}`);
                const data = await res.json();
                if (!canvas || !canvas.parentNode) return; // 模态框可能已关闭
                const ctx = canvas.getContext('2d');
                if (currentChart) {
                    currentChart.destroy();
                    currentChart = null;
                }
                // 清除 canvas 内容
                ctx.clearRect(0, 0, canvas.width, canvas.height);

                const labels = data.data.map(item => period === 'day' ? item.date : new Date(item.hour * 1000).toLocaleString());
                const values = data.data.map(item => item.value);
                const isDark = document.documentElement.classList.contains('dark-mode');
                const textColor = isDark ? '#eee' : '#333';
                const gridColor = isDark ? '#444' : '#ddd';

                currentChart = new Chart(ctx, {
                    type: 'line',
                    data: {
                        labels: labels,
                        datasets: [{
                            label: info.title,
                            data: values,
                            borderColor: info.color,
                            backgroundColor: `${info.color}20`,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: true,
                        plugins: {
                            legend: { display: false },
                            tooltip: { callbacks: { label: (ctx) => `${ctx.raw} ${info.unit}` } }
                        },
                        scales: {
                            y: { grid: { color: gridColor }, ticks: { color: textColor } },
                            x: { ticks: { color: textColor, maxRotation: 45, minRotation: 45 } }
                        }
                    }
                });
            } catch (e) {
                console.error('加载走势失败', e);
            }
        }

        // 加载默认（按天）
        loadTrend(currentPeriod);

        // 绑定时段切换按钮
        const periodBtns = modal.querySelectorAll('.trend-period-btn');
        periodBtns.forEach(btn => {
            btn.addEventListener('click', async () => {
                const period = btn.dataset.period;
                if (period === currentPeriod) return;
                currentPeriod = period;
                periodBtns.forEach(b => b.style.backgroundColor = '');
                btn.style.backgroundColor = '#007bff';
                btn.style.color = 'white';
                await loadTrend(period);
            });
            // 高亮当前激活的按钮（默认按天）
            if (btn.dataset.period === 'day') {
                btn.style.backgroundColor = '#007bff';
                btn.style.color = 'white';
            }
        });
    }
}

async function resetStatType(type) {
    if (confirm(`确定重置${type === 'chat' ? '对话次数' : type === 'token' ? 'Token用量' : '知识图谱调用次数'}吗？`)) {
        const res = await fetch(`/stats/reset/${type}`, { method: 'POST' });
        if (res.ok) {
            loadStatisticsDetail();
            loadStats();
        } else {
            alert('重置失败');
        }
    }
}

async function resetAllStats() {
    if (confirm('确定重置所有统计吗？此操作不可恢复。')) {
        const res = await fetch('/stats/reset', { method: 'POST' });
        if (res.ok) {
            alert('重置成功');
            loadStats();
            if (document.getElementById('page-statistics-detail').classList.contains('active-page')) {
                loadStatisticsDetail();
            }
        } else {
            alert('重置失败');
        }
    }
}

let latestStatsTopicData = [];

function escapeStatsAttribute(value) {
    return String(value || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

function resolveStatsOperator(item) {
    const explicitId = String(item?.operator_id || '').trim();
    if (explicitId && operatorMap.has(explicitId)) {
        const operator = operatorMap.get(explicitId);
        return { id: explicitId, name: operator?.codename || item?.name || explicitId };
    }

    const statsName = String(item?.name || explicitId).trim();
    const normalizedName = statsName.toLocaleLowerCase();
    for (const [operatorId, operator] of operatorMap.entries()) {
        const candidates = [operatorId, operator?.codename, operator?.name]
            .filter(Boolean)
            .map(value => String(value).trim().toLocaleLowerCase());
        if (candidates.includes(normalizedName)) {
            return { id: operatorId, name: operator?.codename || statsName || operatorId };
        }
    }

    return { id: explicitId || statsName, name: statsName || explicitId || '未知干员' };
}

async function renderStatsWordcloud(topicData) {
    const container = document.getElementById('wordcloud-container');
    if (!container) return;

    const words = (Array.isArray(topicData) ? topicData : [])
        .map(item => [String(item?.topic || '').trim(), Number(item?.count)])
        .filter(([topic, count]) => topic && Number.isFinite(count) && count > 0)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 80);

    if (!words.length) {
        container.innerHTML = '<div class="stats-empty-state">暂无话题数据</div>';
        return;
    }

    // 对话分布标签默认隐藏；零尺寸容器会让 wordcloud2 的缩放逻辑递归溢出。
    if (container.clientWidth < 1 || container.clientHeight < 1) return;

    const renderFallback = () => {
        const maxCount = words[0][1] || 1;
        container.innerHTML = `<div class="stats-topic-fallback">${words.map(([topic, count]) => {
            const size = 12 + Math.round((count / maxCount) * 18);
            return `<span style="font-size:${size}px">${escapeHtml(topic)}</span>`;
        }).join('')}</div>`;
    };

    try {
        await window.ZootRuntime?.ensureVendor?.('wordcloud');
    } catch (error) {
        renderFallback();
        return;
    }

    const maxCount = words[0][1] || 1;
    try {
        container.innerHTML = '';
        WordCloud(container, {
            list: words,
            gridSize: Math.max(8, Math.round(container.clientWidth / 32)),
            weightFactor: count => 12 + (count / maxCount) * 30,
            fontFamily: 'sans-serif',
            color: () => `hsl(${Math.random() * 360}, 70%, 55%)`,
            rotateRatio: 0.35,
            backgroundColor: 'transparent',
            shape: 'circle',
            clearCanvas: true
        });
    } catch (error) {
        console.warn('词云渲染失败，已切换为话题列表', error);
        renderFallback();
    }
}

let detailedApiUsageChart = null;

function formatApiUsageNumber(value) {
    const number = Number(value || 0);
    if (number >= 1000000) return `${(number / 1000000).toFixed(1)}M`;
    if (number >= 1000) return `${(number / 1000).toFixed(1)}K`;
    return Math.round(number).toLocaleString('zh-CN');
}

function renderApiUsageRows(containerId, items, type) {
    const container = document.getElementById(containerId);
    if (!container) return;
    if (!items || !items.length) {
        container.innerHTML = '<div class="api-usage-empty">当前周期暂无记录</div>';
        return;
    }
    container.innerHTML = items.slice(0, 20).map(item => {
        let title = item.label || item.id || '未分类';
        let subtitle = item.description || '';
        if (type === 'provider') {
            title = item.provider || '未指定服务商';
            subtitle = `${item.model || '未指定模型'} · ${item.service_type || '服务'}`;
        } else if (type === 'service') {
            const unitParts = [];
            if (item.id === 'transcription' && item.input_units) unitParts.push(`音频 ${Math.round(item.input_units)} 秒`);
            if (item.id === 'image_generation' && item.output_units) unitParts.push(`生成 ${Math.round(item.output_units)} 张`);
            subtitle = unitParts.join(' · ');
        }
        const failure = item.failures ? ` · 失败 ${item.failures}` : '';
        return `<div class="api-usage-row">
            <div class="api-usage-row-main"><strong title="${escapeHtml(title)}">${escapeHtml(title)}</strong><small>${escapeHtml(subtitle)}</small></div>
            <div class="api-usage-metric"><strong>${formatApiUsageNumber(item.requests)}</strong><small>请求${failure}</small></div>
            <div class="api-usage-metric"><strong>${formatApiUsageNumber(item.tokens)}</strong><small>Token</small></div>
        </div>`;
    }).join('');
}

async function loadDetailedApiUsageStats(days) {
    const periodSelect = document.getElementById('api-usage-period');
    if (!periodSelect) return;
    const selectedDays = Number(days || periodSelect.value || 30);
    const response = await fetch(`/stats/api-usage?days=${selectedDays}`);
    const payload = await response.json();
    if (!response.ok) throw new Error(payload.detail || 'API 消耗统计加载失败');
    const data = payload.data || {};
    const totals = data.totals || {};
    const multimodalRequests = (data.services || []).filter(item => item.id !== 'llm').reduce((sum, item) => sum + Number(item.requests || 0), 0);
    document.getElementById('api-summary-requests').textContent = formatApiUsageNumber(totals.requests);
    document.getElementById('api-summary-tokens').textContent = formatApiUsageNumber(totals.tokens);
    document.getElementById('api-summary-multimodal').textContent = formatApiUsageNumber(multimodalRequests);
    document.getElementById('api-summary-failures').textContent = formatApiUsageNumber(totals.failures);
    renderApiUsageRows('api-service-breakdown', data.services, 'service');
    renderApiUsageRows('api-category-breakdown', data.categories, 'category');
    renderApiUsageRows('api-provider-breakdown', data.providers, 'provider');
    const notes = document.getElementById('api-usage-notes');
    if (notes) notes.innerHTML = (data.notes || []).map(note => `<div>• ${escapeHtml(note)}</div>`).join('');

    const canvas = document.getElementById('api-usage-trend-chart');
    if (canvas && typeof Chart !== 'undefined') {
        if (detailedApiUsageChart) detailedApiUsageChart.destroy();
        const daily = data.daily || [];
        const dark = document.documentElement.classList.contains('dark-mode');
        detailedApiUsageChart = new Chart(canvas.getContext('2d'), {
            type: 'line',
            data: { labels: daily.map(item => item.date), datasets: [
                { label: 'Token', data: daily.map(item => item.tokens), borderColor: '#4d8dff', backgroundColor: 'rgba(77,141,255,.12)', fill: true, tension: .3, yAxisID: 'y' },
                { label: '请求', data: daily.map(item => item.requests), borderColor: '#e69b32', tension: .3, yAxisID: 'y1' },
                { label: '多模态请求', data: daily.map(item => item.multimodal_requests), borderColor: '#8b65d6', tension: .3, yAxisID: 'y1' }
            ]},
            options: { responsive: true, maintainAspectRatio: true, interaction: { mode: 'index', intersect: false },
                plugins: { legend: { labels: { color: dark ? '#eee' : '#333' } } },
                scales: { y: { beginAtZero: true, position: 'left' }, y1: { beginAtZero: true, position: 'right', grid: { drawOnChartArea: false } } }
            }
        });
    }
    if (!periodSelect.dataset.bound) {
        periodSelect.addEventListener('change', () => loadDetailedApiUsageStats(Number(periodSelect.value)).catch(error => notifyMultimodal(error.message)));
        periodSelect.dataset.bound = '1';
    }
}

// ========== 详细统计页面加载（新增） ==========
async function loadStatisticsDetail() {
    try {
        // 1. 并行加载数据
        const [trendRes, distributionRes, usageRes] = await Promise.all([
            fetch('/stats/trend?period=day&limit=30'),
            fetch('/stats/distribution'),
            fetch('/stats/usage')
        ]);
        const trendData = await trendRes.json();
        const distributionData = await distributionRes.json();
        const usageData = await usageRes.json();

        // 2. 更新使用时长卡片
        const totalHoursElem = document.getElementById('usage-total-hours');
        if (totalHoursElem) totalHoursElem.textContent = usageData.total_hours || 0;

        // 3. 销毁旧图表实例
        destroyAllCharts();

        // 4. 获取主题颜色
        const isDark = document.documentElement.classList.contains('dark-mode');
        const textColor = isDark ? '#eee' : '#333';
        const gridColor = isDark ? '#444' : '#ddd';

        // ========== 走势趋势标签页 ==========
        // Token 走势图（按天）
        if (trendData.period === 'day' && trendData.api && trendData.api.length) {
            const dates = trendData.api.map(item => item.date);
            const tokens = trendData.api.map(item => item.total_tokens);
            const ctx = document.getElementById('token-trend-chart')?.getContext('2d');
            if (ctx && tokenTrendChart) tokenTrendChart.destroy();
            if (ctx) {
                tokenTrendChart = new Chart(ctx, {
                    type: 'line',
                    data: {
                        labels: dates,
                        datasets: [{
                            label: 'Token 使用量',
                            data: tokens,
                            borderColor: '#007bff',
                            backgroundColor: 'rgba(0,123,255,0.1)',
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: true,
                        plugins: { legend: { labels: { color: textColor } } },
                        scales: {
                            y: { grid: { color: gridColor }, ticks: { color: textColor } },
                            x: { ticks: { color: textColor, maxRotation: 45, minRotation: 45 } }
                        }
                    }
                });
            }
        }

        // 消息数量走势图（按天）
        if (trendData.period === 'day' && trendData.message && trendData.message.length) {
            const dates = trendData.message.map(item => item.date);
            const privateCounts = trendData.message.map(item => item.private_count);
            const groupCounts = trendData.message.map(item => item.group_count);
            const ctx = document.getElementById('message-trend-chart')?.getContext('2d');
            if (ctx && messageTrendChart) messageTrendChart.destroy();
            if (ctx) {
                messageTrendChart = new Chart(ctx, {
                    type: 'line',
                    data: {
                        labels: dates,
                        datasets: [
                            { label: '私聊消息', data: privateCounts, borderColor: '#28a745', backgroundColor: 'rgba(40,167,69,0.1)', fill: true, tension: 0.3 },
                            { label: '群聊消息', data: groupCounts, borderColor: '#ffc107', backgroundColor: 'rgba(255,193,7,0.1)', fill: true, tension: 0.3 }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: true,
                        plugins: { legend: { labels: { color: textColor } } },
                        scales: {
                            y: { grid: { color: gridColor }, ticks: { color: textColor } },
                            x: { ticks: { color: textColor, maxRotation: 45, minRotation: 45 } }
                        }
                    }
                });
            }
        }

        // ========== 使用时长标签页 ==========
        if (usageData.trend && usageData.trend.length) {
            const dates = usageData.trend.map(item => item.date);
            const hours = usageData.trend.map(item => Math.round(item.seconds / 3600 * 10) / 10);
            const ctx = document.getElementById('usage-trend-chart')?.getContext('2d');
            if (ctx && usageTrendChart) usageTrendChart.destroy();
            if (ctx) {
                usageTrendChart = new Chart(ctx, {
                    type: 'bar',
                    data: {
                        labels: dates,
                        datasets: [{
                            label: '使用时长 (小时)',
                            data: hours,
                            backgroundColor: 'rgba(102,126,234,0.7)',
                            borderColor: '#667eea',
                            borderWidth: 1
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: true,
                        plugins: { legend: { labels: { color: textColor } } },
                        scales: {
                            y: { grid: { color: gridColor }, ticks: { color: textColor } },
                            x: { ticks: { color: textColor, maxRotation: 45, minRotation: 45 } }
                        }
                    }
                });
            }
        }

        // ========== 对话分布标签页 ==========
        // 4.1 干员对话饼图（前15 + 其他）
        let privateData = distributionData.private_chat || [];
        if (!privateData.length) {
            console.warn('无干员对话数据');
        }
        privateData.sort((a, b) => b.count - a.count);
        const topN = 15;
        const topItems = privateData.slice(0, topN);
        const otherCount = privateData.slice(topN).reduce((sum, item) => sum + item.count, 0);
        let pieLabels = topItems.map(item => {
            const op = operatorMap.get(item.operator_name);
            return op ? op.codename : item.operator_name;
        });
        let pieData = topItems.map(item => item.count);
        if (otherCount > 0) {
            pieLabels.push('其他干员');
            pieData.push(otherCount);
        }
        const colorPalette = generateColors(pieLabels.length);
        const pieCtx = document.getElementById('private-chart')?.getContext('2d');
        if (pieCtx && privatePieChart) privatePieChart.destroy();
        if (pieCtx && pieLabels.length) {
            privatePieChart = new Chart(pieCtx, {
                type: 'pie',
                data: {
                    labels: pieLabels,
                    datasets: [{ data: pieData, backgroundColor: colorPalette, borderWidth: 0 }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: true,
                    plugins: {
                        legend: { display: false },
                        tooltip: { callbacks: { label: (ctx) => `${ctx.label}: ${ctx.raw} 次` } }
                    },
                    layout: { padding: 20 }
                }
            });
            // 绘制指示线
            setTimeout(() => drawLeaderLines(pieCtx, privatePieChart, pieLabels, pieData), 200);
        }

        // 4.2 排行榜（使用新的 interaction_stats）
        const rankingDiv = document.getElementById('private-ranking-list');
        if (rankingDiv) {
            const interactionStats = distributionData.interaction_stats || [];
            if (interactionStats.length === 0) {
                rankingDiv.innerHTML = '<div style="text-align:center; padding:20px; color:var(--text-secondary);">暂无对话数据</div>';
            } else {
                // 按发送数排序（或其他标准）
                interactionStats.sort((a, b) => (b.sent + b.received + b.group) - (a.sent + a.received + a.group));
                const rankColors = generateColors(interactionStats.length);
                rankingDiv.innerHTML = `
                    <div class="ranking-header" style="display: flex; padding: 10px 12px; background: var(--filter-bg); border-radius: 8px; margin-bottom: 8px; font-weight: bold;">
                        <div style="width: 40px;"></div>
                        <div style="flex: 2;">干员</div>
                        <div style="flex: 1; text-align: right;">📤 用户→干员</div>
                        <div style="flex: 1; text-align: right;">📥 干员→用户</div>
                        <div style="flex: 1; text-align: right;">💬 群聊发言</div>
                        <div style="width: 20px;"></div>
                    </div>
                    <div class="ranking-list-container" style="max-height: 300px; overflow-y: auto;">
                        ${interactionStats.map((item, idx) => {
                            const operator = resolveStatsOperator(item);
                            const avatarUrl = getOperatorAvatarUrl(operator.id);
                            const color = rankColors[idx % rankColors.length];
                            return `
                                <div class="ranking-item" style="display: flex; align-items: center; padding: 8px 12px; border-bottom: 1px solid var(--border-color);">
                                    <div style="width: 36px; margin-right: 8px;">
                                        <img class="ranking-avatar" src="${escapeStatsAttribute(avatarUrl)}" onerror="this.onerror=null;this.src='/static/avatars/default.webp'" alt="${escapeStatsAttribute(operator.name)}">
                                    </div>
                                    <div style="flex: 2; font-size: 14px; font-weight: 500;">${escapeHtml(operator.name)}</div>
                                    <div style="flex: 1; text-align: right; font-size: 13px;">${item.sent}</div>
                                    <div style="flex: 1; text-align: right; font-size: 13px;">${item.received}</div>
                                    <div style="flex: 1; text-align: right; font-size: 13px;">${item.group}</div>
                                    <div style="width: 20px; height: 16px; border-radius: 4px; background: ${color}; margin-left: 8px;"></div>
                                </div>
                            `;
                        }).join('')}
                    </div>
                `;
            }
        }

        // 4.3 时段分布柱状图（修复高度 + 柱子变细）
        const hourlyData = distributionData.hourly_distribution || [];
        const hours = Array.from({ length: 24 }, (_, i) => i);
        const counts = hours.map(h => {
            const found = hourlyData.find(item => item.hour === h);
            return found ? found.count : 0;
        });
        const hourlyCtx = document.getElementById('hourly-bar-chart')?.getContext('2d');
        if (hourlyCtx) {
            if (window.hourlyBarChart) window.hourlyBarChart.destroy();
            window.hourlyBarChart = new Chart(hourlyCtx, {
                type: 'bar',
                data: {
                    labels: hours.map(h => `${h}:00`),
                    datasets: [{
                        label: '消息数量',
                        data: counts,
                        backgroundColor: '#007bff',
                        barPercentage: 0.6,      // 柱子宽度比例（0-1，默认0.9）
                        categoryPercentage: 0.8  // 分类宽度比例
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: { beginAtZero: true, ticks: { color: textColor } },
                        x: { ticks: { color: textColor, maxRotation: 45, minRotation: 45 } }
                    },
                    plugins: { tooltip: { callbacks: { label: (ctx) => `${ctx.raw} 条` } } }
                }
            });
            // 设置 canvas 高度
            const canvas = document.getElementById('hourly-bar-chart');
            if (canvas) canvas.style.height = '200px';
        }

        // 4.4 常聊话题 - 词云（需要 wordcloud2 库）
        latestStatsTopicData = distributionData.topic_distribution || [];
        renderStatsWordcloud(latestStatsTopicData);

        // ========== API调用标签页 ==========
        try {
            await loadDetailedApiUsageStats();
            // 1. 对话API请求次数及走势
            const apiTrendRes = await fetch('/stats/trend?period=day&limit=30');
            const apiTrendData = await apiTrendRes.json();
            const totalRequests = apiTrendData.api.reduce((sum, item) => sum + item.request_count, 0);
            const apiTotalElem = document.getElementById('api-requests-total');
            if (apiTotalElem) apiTotalElem.textContent = totalRequests;

            // 绘制对话API请求走势图
            const apiCtx = document.getElementById('api-requests-chart')?.getContext('2d');
            if (apiCtx) {
                if (window.apiRequestsChart) window.apiRequestsChart.destroy();
                if (apiTrendData.api && apiTrendData.api.length) {
                    const dates = apiTrendData.api.map(item => item.date);
                    const requests = apiTrendData.api.map(item => item.request_count);
                    window.apiRequestsChart = new Chart(apiCtx, {
                        type: 'line',
                        data: {
                            labels: dates,
                            datasets: [{
                                label: 'API 请求次数',
                                data: requests,
                                borderColor: '#ff9800',
                                fill: false,
                                tension: 0.3
                            }]
                        },
                        options: {
                            responsive: true,
                            maintainAspectRatio: true,
                            plugins: { legend: { labels: { color: textColor } } },
                            scales: {
                                y: { grid: { color: gridColor }, ticks: { color: textColor } },
                                x: { ticks: { color: textColor, maxRotation: 45, minRotation: 45 } }
                            }
                        }
                    });
                } else {
                    // 无数据时显示空白提示
                    apiCtx.fillStyle = isDark ? '#333' : '#f5f5f5';
                    apiCtx.fillRect(0, 0, apiCtx.canvas.width, apiCtx.canvas.height);
                    apiCtx.fillStyle = isDark ? '#ccc' : '#666';
                    apiCtx.font = '14px sans-serif';
                    apiCtx.fillText('暂无API请求数据', 20, 50);
                }
            }

            // 2. 知识图谱总次数
            const kgRes = await fetch('/stats/total');
            const kgTotal = (await kgRes.json()).kgCount || 0;
            const kgTotalElem = document.getElementById('kg-requests-total');
            if (kgTotalElem) kgTotalElem.textContent = kgTotal;

            // 绘制知识图谱走势图（若后端提供 /stats/kg_trend 接口）
            const kgCtx = document.getElementById('kg-requests-chart')?.getContext('2d');
            if (kgCtx) {
                if (window.kgRequestsChart) window.kgRequestsChart.destroy();
                try {
                    const kgTrendRes = await fetch('/stats/kg_trend?period=day&limit=30');
                    const kgTrendData = await kgTrendRes.json();
                    if (kgTrendData.data && kgTrendData.data.length) {
                        const dates = kgTrendData.data.map(item => item.date);
                        const calls = kgTrendData.data.map(item => item.count);
                        window.kgRequestsChart = new Chart(kgCtx, {
                            type: 'line',
                            data: {
                                labels: dates,
                                datasets: [{
                                    label: '知识图谱调用次数',
                                    data: calls,
                                    borderColor: '#6f42c1',
                                    fill: false,
                                    tension: 0.3
                                }]
                            },
                            options: {
                                responsive: true,
                                maintainAspectRatio: true,
                                plugins: { legend: { labels: { color: textColor } } },
                                scales: {
                                    y: { grid: { color: gridColor }, ticks: { color: textColor } },
                                    x: { ticks: { color: textColor, maxRotation: 45, minRotation: 45 } }
                                }
                            }
                        });
                    } else {
                        // 无数据时显示提示
                        kgCtx.fillStyle = isDark ? '#333' : '#f5f5f5';
                        kgCtx.fillRect(0, 0, kgCtx.canvas.width, kgCtx.canvas.height);
                        kgCtx.fillStyle = isDark ? '#ccc' : '#666';
                        kgCtx.font = '14px sans-serif';
                        kgCtx.fillText('暂无知识图谱调用记录', 20, 50);
                    }
                } catch (e) {
                    console.warn('知识图谱走势数据加载失败', e);
                    // 降级显示无数据提示
                    kgCtx.fillStyle = isDark ? '#333' : '#f5f5f5';
                    kgCtx.fillRect(0, 0, kgCtx.canvas.width, kgCtx.canvas.height);
                    kgCtx.fillStyle = isDark ? '#ccc' : '#666';
                    kgCtx.font = '14px sans-serif';
                    kgCtx.fillText('知识图谱走势数据不可用', 20, 50);
                }
            }

            // 3. 推送次数（留空，显示 0 并标注开发中）
            const pushTotalElem = document.getElementById('push-requests-total');
            if (pushTotalElem) pushTotalElem.textContent = '0';
            // 可选：在推送卡片内添加“开发中”标记
            const pushCard = document.querySelector('#stats-tab-api .stat-card:last-child');
            if (pushCard && !pushCard.querySelector('.dev-badge')) {
                const badge = document.createElement('div');
                badge.className = 'dev-badge';
                badge.textContent = '开发中';
                badge.style.cssText = 'display: inline-block; background: var(--text-secondary); color: white; border-radius: 12px; padding: 2px 8px; font-size: 10px; margin-top: 8px;';
                pushCard.appendChild(badge);
            }

        } catch (e) {
            console.error('API 统计加载失败', e);
            const apiContainer = document.querySelector('#stats-tab-api');
            if (apiContainer && !apiContainer.querySelector('.error-placeholder')) {
                const errorDiv = document.createElement('div');
                errorDiv.className = 'error-placeholder';
                errorDiv.style.textAlign = 'center';
                errorDiv.style.padding = '20px';
                errorDiv.style.color = 'var(--danger-color)';
                errorDiv.textContent = 'API 统计数据加载失败，请刷新页面重试';
                apiContainer.prepend(errorDiv);
            }
        }

        // 5. 绑定标签切换事件
        bindStatsTabs();

    } catch (error) {
        console.error('加载统计详情失败', error);
        const container = document.querySelector('.statistics-detail-container');
        if (container) {
            container.innerHTML = '<div style="text-align:center; padding:20px; color:red;">加载失败，请刷新重试</div>';
        }
    }
}

// 绘制饼图指示线（简单实现：计算扇形中点角度，画线到外侧）
function drawLeaderLines(ctx, chart, labels, data) {
    // 如果图表未渲染完成，等待一帧再试
    if (!chart.data || !chart.data.datasets || chart.data.datasets.length === 0) {
        requestAnimationFrame(() => drawLeaderLines(ctx, chart, labels, data));
        return;
    }
    const canvas = ctx.canvas;
    const w = canvas.clientWidth, h = canvas.clientHeight;
    if (w === 0 || h === 0) return;
    // 使用 clientWidth/Height 而非 width/height，避免缩放失真
    const centerX = w/2, centerY = h/2;
    const meta = chart.getDatasetMeta(0);
    const arcs = meta.data;
    if (!arcs.length) return;
    // 获取实际半径（饼图可能因布局而缩放）
    const radius = arcs[0].outerRadius * (w / canvas.width); // 粗略换算
    ctx.save();
    ctx.strokeStyle = 'var(--text-secondary)';
    ctx.fillStyle = 'var(--text-color)';
    ctx.font = '12px sans-serif';
    ctx.lineWidth = 1;
    for (let i = 0; i < arcs.length; i++) {
        const arc = arcs[i];
        const startAngle = arc.startAngle;
        const endAngle = arc.endAngle;
        const midAngle = startAngle + (endAngle - startAngle)/2;
        const x = centerX + Math.cos(midAngle) * radius;
        const y = centerY + Math.sin(midAngle) * radius;
        const outerX = centerX + Math.cos(midAngle) * (radius + 15);
        const outerY = centerY + Math.sin(midAngle) * (radius + 15);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(outerX, outerY);
        const endX = outerX + (outerX > centerX ? 12 : -12);
        ctx.lineTo(endX, outerY);
        ctx.stroke();
        ctx.fillStyle = 'var(--text-color)';
        const text = labels[i];
        const textWidth = ctx.measureText(text).width;
        ctx.fillText(text, endX + (outerX > centerX ? 5 : -textWidth - 5), outerY - 5);
    }
    ctx.restore();
}

// 标签切换函数
function bindStatsTabs() {
    const tabs = document.querySelectorAll('.stats-tab');
    const panes = document.querySelectorAll('.stats-tab-pane');
    tabs.forEach(tab => {
        tab.onclick = () => {
            const targetTab = tab.dataset.tab;
            tabs.forEach(t => t.classList.remove('active'));
            tab.classList.add('active');
            panes.forEach(pane => pane.style.display = 'none');
            const activePane = document.getElementById(`stats-tab-${targetTab}`);
            if (activePane) activePane.style.display = 'block';
            if (targetTab === 'distribution') {
                requestAnimationFrame(() => renderStatsWordcloud(latestStatsTopicData));
            }
        };
    });
}

// 辅助函数：生成随机颜色数组
function generateColors(count) {
    const colors = [];
    for (let i = 0; i < count; i++) {
        const hue = (i * 360 / count) % 360;
        colors.push(`hsl(${hue}, 70%, 60%)`);
    }
    return colors;
}

function getColor(index) {
    return `hsl(${(index * 360 / 20) % 360}, 70%, 60%)`;
}

