// 渲染成员列表（包含普瑞塞斯，作为可选成员）
async function renderMemberList() {
    const container = document.getElementById('member-list');
    if (!container) return;

    // 获取当前群组成员列表（英文名）
    let groupMembers = [];
    try {
        const res = await fetch(`/group/config/${currentGroupId}`);
        if (res.ok) {
            const config = await res.json();
            groupMembers = config.members || [];
        }
    } catch (e) {
        console.error('获取群组成员失败', e);
    }

    // 获取所有干员（从 operatorMap 获取全部，包括普瑞塞斯）
    let allOperators = Array.from(operatorMap.values());

    let itemsToRender = [];

    if (memberSelectMode === 'remove') {
        // 移除模式：只显示群组已有的成员，默认全选（可包含普瑞塞斯）
        const membersToShow = allOperators.filter(op => groupMembers.includes(op.id));
        itemsToRender = membersToShow.map(op => ({
            operator: op,
            isMember: true,
            checked: true,
            disabled: false
        }));
        selectedMembers = membersToShow.map(op => op.id);
    } else {
        // 邀请模式：显示所有干员，群组成员置顶且复选框禁用，非成员未勾选
        const existing = [];
        const notInGroup = [];
        allOperators.forEach(op => {
            if (groupMembers.includes(op.id)) {
                existing.push(op);
            } else {
                notInGroup.push(op);
            }
        });
        const sorted = [...existing, ...notInGroup];
        itemsToRender = sorted.map(op => {
            const isMember = groupMembers.includes(op.id);
            return {
                operator: op,
                isMember: isMember,
                checked: isMember,
                disabled: isMember
            };
        });
        selectedMembers = []; // 初始为空，用户新勾选的才会加入
    }

    // 按拼音首字母分组
    const grouped = {};
    for (const item of itemsToRender) {
        const op = item.operator;
        let firstChar = op.pinyin_initial || '#';
        if (!firstChar || !/[A-Z]/.test(firstChar)) firstChar = '#';
        if (!grouped[firstChar]) grouped[firstChar] = [];
        grouped[firstChar].push(item);
    }

    const sortedLetters = Object.keys(grouped).sort((a, b) => {
        if (a === '#') return 1;
        if (b === '#') return -1;
        return a.localeCompare(b);
    });

    let html = '';
    for (const letter of sortedLetters) {
        html += `<div class="contact-letter">${letter}</div>`;
        for (const item of grouped[letter]) {
            const op = item.operator;
            const checkedAttr = item.checked ? 'checked' : '';
            const disabledAttr = item.disabled ? 'disabled' : '';
            html += `
                <div class="contact-item" data-operator-id="${op.id}">
                    <div class="contact-info">
                        <img src="${getOperatorAvatarUrl(op.id)}" class="contact-avatar" alt="${op.codename}">
                        <div class="contact-name">${op.codename}</div>
                    </div>
                    <input type="checkbox" class="member-checkbox" value="${op.id}" ${checkedAttr} ${disabledAttr}>
                </div>
            `;
        }
    }
    container.innerHTML = html;

    // 绑定复选框变化事件（仅非禁用）
    document.querySelectorAll('#member-list .member-checkbox:not([disabled])').forEach(cb => {
        cb.removeEventListener('change', handleCheckboxChange);
        cb.addEventListener('change', handleCheckboxChange);
    });
}

function handleCheckboxChange(e) {
    const id = e.target.value;
    if (e.target.checked) {
        if (!selectedMembers.includes(id)) selectedMembers.push(id);
    } else {
        selectedMembers = selectedMembers.filter(v => v !== id);
    }
}


// ========== 32. 意见提交 ==========
function showFeedbackModal() {
    const modal = document.getElementById('feedbackModal');
    if (!modal) {
        console.error('feedbackModal 元素不存在');
        alert('无法打开意见反馈弹窗，请刷新页面');
        return;
    }
    // 更新设备信息
    const deviceSpan = document.getElementById('device-info');
    if (deviceSpan) deviceSpan.textContent = getDeviceInfo();

    // 显示当前版本号
    const versionSpan = document.getElementById('app-version');
    if (versionSpan) {
        versionSpan.textContent = currentAppVersion || '加载中...';
    }

    // 清空上次内容
    document.getElementById('feedback-content').value = '';
    document.getElementById('feedback-type').value = 'suggestion';
    showModal('feedbackModal');
}

async function submitFeedback() {
    const content = document.getElementById('feedback-content').value.trim();
    if (!content) {
        alert('请输入反馈内容');
        return;
    }
    const feedbackType = document.getElementById('feedback-type').value;
    const typeMap = {
        'suggestion': '意见与建议',
        'bug': '问题反馈',
        'other': '其他'
    };

    // 确保版本号已加载（如果未加载则尝试重新获取）
    let version = currentAppVersion;
    if (!version || version === '0.0.0') {
        try {
            const res = await fetch('/api/version/local');
            if (res.ok) {
                const data = await res.json();
                version = data.app_version || '0.0.0';
                currentAppVersion = version; // 更新全局变量
                currentPlatform = String(data.platform || currentPlatform);
            }
        } catch (e) {
            console.warn('[反馈] 重新获取版本失败:', e);
        }
    }

    const payload = {
        type: feedbackType,
        type_text: typeMap[feedbackType],
        content: content,
        version: version || '0.0.0',
        device: getDeviceInfo(),
        device_id: localStorage.getItem('device_id') || undefined,
        timestamp: Math.floor(Date.now() / 1000)
    };

    try {
        const result = await CloudAPI.submitFeedback(payload);
        if (result.status === 'ok') {
            alert('反馈提交成功，感谢您的支持！');
            hideModal('feedbackModal');
            document.getElementById('feedback-content').value = '';
        } else {
            alert('提交失败：' + (result.message || '未知错误'));
        }
    } catch (e) {
        console.error('提交反馈出错:', e);
        alert(`提交失败，请检查网络。\n您的反馈已保留：\n${content}`);
    }
}

function getDeviceInfo() {
    if (deviceInfoCache) return deviceInfoCache;
    const ua = navigator.userAgent;
    let device = '未知设备';
    let platform = 'Android';

    if (/iPhone|iPad|iPod/i.test(ua)) {
        platform = 'iOS';
        device = ua.match(/iPhone|iPad|iPod/) ? ua.match(/iPhone|iPad|iPod/)[0] : 'Apple Device';
    } else if (/Android/i.test(ua)) {
        platform = 'Android';
        const match = ua.match(/Android[\s/]+([\d.]+)/);
        const version = match ? match[1] : '';
        const brandMatch = ua.match(/; ([\w\s]+) Build/);
        const brand = brandMatch ? brandMatch[1] : '';
        device = `${brand} ${version}`.trim() || 'Android设备';
    } else if (/Windows Phone/i.test(ua)) {
        platform = 'Windows Phone';
        device = 'Windows Phone';
    } else if (/Windows/i.test(ua)) {
        platform = 'Windows';
        device = 'Windows PC';
    } else if (/Macintosh/i.test(ua)) {
        platform = 'macOS';
        device = 'Mac';
    }

    deviceInfoCache = `${platform} - ${device}`;
    return deviceInfoCache;
}

