function bindChatItemSwipe() {
    document.querySelectorAll('.chat-item').forEach(item => {
        let startX = 0, isSwiping = false;
        let transformX = 0;
        const maxOffset = -60;
        const itemWidth = item.offsetWidth;
        item.addEventListener('touchstart', (e) => {
            startX = e.touches[0].clientX;
            startY = e.touches[0].clientY;
            isSwiping = true;
            item.style.transition = 'none';
            transformX = parseFloat(item.style.transform.replace('translateX(', '').replace('%)', '')) || 0;
        });
        item.addEventListener('touchmove', (e) => {
            if (!isSwiping) return;
            const touch = e.touches[0];
            const deltaX = touch.clientX - startX;
            const deltaY = touch.clientY - startY;
            if (Math.abs(deltaX) > Math.abs(deltaY)) {
                e.preventDefault();
                if (deltaX < 0) {
                    let newOffset = Math.max(maxOffset, transformX + (deltaX / itemWidth * 100));
                    item.style.transform = `translateX(${newOffset}%)`;
                    transformX = newOffset;
                } else if (transformX < 0) {
                    let newOffset = Math.min(0, transformX + (deltaX / itemWidth * 100));
                    item.style.transform = `translateX(${newOffset}%)`;
                    transformX = newOffset;
                }
            }
            startX = touch.clientX;
            startY = touch.clientY;
        });
        item.addEventListener('touchend', () => {
            isSwiping = false;
            item.style.transition = 'transform 0.3s ease';
            if (transformX < -30) {
                item.style.transform = 'translateX(-60%)';
                transformX = -60;
            } else {
                item.style.transform = 'translateX(0)';
                transformX = 0;
            }
            setTimeout(() => { item.style.transition = ''; }, 300);
        });
    });
}

async function locateAndHighlightMessage(chatType, chatId, keyword) {
    const chatKey = `${chatType}:${chatId}`;
    // 等待消息加载完成（使用轮询）
    let retries = 0;
    const maxRetries = 20;
    const interval = setInterval(() => {
        const msgs = messages[chatKey];
        if (msgs && msgs.length > 0) {
            clearInterval(interval);
            // 在消息列表中搜索包含关键词的消息
            const lowerKeyword = keyword.toLowerCase();
            const index = msgs.findIndex(msg => msg.content.toLowerCase().includes(lowerKeyword));
            if (index !== -1) {
                // 滚动到该消息位置
                const msgElements = document.querySelectorAll('#chat-messages .chat-message-row');
                if (msgElements[index]) {
                    msgElements[index].scrollIntoView({ behavior: 'smooth', block: 'center' });
                    // 高亮消息气泡
                    msgElements[index].classList.add('highlight-message');
                    setTimeout(() => {
                        msgElements[index].classList.remove('highlight-message');
                    }, 3000);
                }
            }
            // 显示聊天详情页
            showPage('chat-detail');
        }
        retries++;
        if (retries >= maxRetries) {
            clearInterval(interval);
            showPage('chat-detail');
        }
    }, 200);
}

// ========== 34. 启动优化 ==========
// 刷新所有依赖干员列表的 UI（联系人页、创建群聊页、助理选择页、成员管理页、统计卡片）
async function refreshAllOperatorDependentUI() {
    console.log('[刷新] 开始刷新干员相关界面');
    // 重新加载干员列表（会更新 operators、operatorMap）
    await loadOperators();
    console.log('[刷新] 干员数据已更新，数量:', operators.length);

    // 1. 联系人页（如果存在且可见）
    const contactsPage = document.getElementById('page-contacts');
    if (contactsPage && contactsPage.classList.contains('active-page')) {
        renderContacts();
        console.log('[刷新] 联系人页已刷新');
    } else if (contactsPage) {
        // 页面不可见，但为了下次进入时准确，可以标记需要刷新，但直接刷新也不影响，因为不可见的页面不会渲染
        renderContacts(); // 直接刷新全局变量，内部会更新容器内容，但容器可能隐藏，无所谓
    }

    // 2. 创建群聊页（如果存在）
    const createGroupPage = document.getElementById('page-create-group');
    if (createGroupPage && typeof renderCreateGroupMemberList === 'function') {
        renderCreateGroupMemberList();
        console.log('[刷新] 创建群聊页成员列表已刷新');
    }

    // 3. 助理选择页（如果存在）
    const assistantSelectPage = document.getElementById('page-assistant-select');
    if (assistantSelectPage && typeof renderAssistantList === 'function') {
        renderAssistantList();
        console.log('[刷新] 助理选择页列表已刷新');
    }

    // 4. 群聊成员管理页（如果存在）
    const memberSelectPage = document.getElementById('page-group-member-select');
    if (memberSelectPage && typeof renderMemberList === 'function') {
        renderMemberList();
        console.log('[刷新] 群聊成员管理页列表已刷新');
    }

    // 5. 助理排班页（它内部使用 renderAssistantList，已在上一步刷新，但排班页也需要刷新）
    const schedulePage = document.getElementById('page-assistant-schedule');
    if (schedulePage && typeof renderScheduleGrid === 'function') {
        // 重新加载排班数据并重新渲染网格
        if (window.scheduleData) {
            renderScheduleGrid(window.scheduleData);
            console.log('[刷新] 助理排班页已刷新');
        }
    }

    // 6. 个人页干员数量统计卡片（更新显示）
    updateOperatorCountStat();

    // 7. 其他可能依赖干员列表的页面（如群聊设置中的成员列表）
    // 如果当前在群聊信息页，且需要刷新成员列表，可以调用 loadGroupConfig 或相关方法
    const groupInfoPage = document.getElementById('page-group-info');
    if (groupInfoPage && groupInfoPage.classList.contains('active-page') && currentGroupId) {
        // 重新加载群组配置，会刷新成员列表
        fetch(`/group/config/${currentGroupId}`).then(res => res.json()).then(config => {
            const memberContainer = document.getElementById('member-avatars-container');
            if (memberContainer && config.members) {
                let membersHtml = '';
                config.members.forEach(memberEng => {
                    const op = operatorMap.get(memberEng);
                    const codename = op ? op.codename : memberEng;
                    const avatarUrl = getOperatorAvatarUrl(memberEng);
                    membersHtml += `
                        <div class="member-avatar" onclick="event.stopPropagation(); showOperatorDetail('${memberEng}')">
                            <img src="${avatarUrl}" alt="${codename}" onerror="this.onerror=null; this.src='/static/avatars/default.webp'">
                        </div>
                    `;
                });
                membersHtml += `<div class="member-avatar invite" onclick="openMemberSelect('invite')">+</div>`;
                membersHtml += `<div class="member-avatar remove" onclick="openMemberSelect('remove')">-</div>`;
                memberContainer.innerHTML = membersHtml;
                console.log('[刷新] 群聊信息页成员列表已刷新');
            }
        }).catch(e => console.warn('刷新群成员失败', e));
    }

    console.log('[刷新] 干员相关界面刷新完成');
}

// 更新个人页干员数量统计卡片
function updateOperatorCountStat() {
    const counts = operators.reduce((result, item) => {
        const roleType = String(item?.role_type || 'operator');
        if (roleType === 'endfield_character') result.endfield += 1;
        else if (roleType === 'character') result.external += 1;
        else if (roleType === 'operator') result.rhodes += 1;
        return result;
    }, { rhodes: 0, endfield: 0, external: 0 });
    NumericTransition.update(document.getElementById('stat-rhodes-operator-count'), counts.rhodes, { decimals: 0 });
    NumericTransition.update(document.getElementById('stat-endfield-operator-count'), counts.endfield, { decimals: 0 });
    NumericTransition.update(document.getElementById('stat-external-count'), counts.external, { decimals: 0 });
    const summary = document.getElementById('stat-operator-count');
    if (summary) summary.setAttribute('aria-label', `罗德岛干员 ${counts.rhodes} 名，塔卫二干员 ${counts.endfield} 名`);
    console.log(`[统计] 联络角色数量已更新：罗德岛 ${counts.rhodes}，塔卫二 ${counts.endfield}，对外联络 ${counts.external}`);
}


// ========== 35. 事件生成器 ==========
// 加载事件配置
// 加载事件配置
async function loadEventConfig() {
    try {
        const res = await fetch('/event/config');
        if (!res.ok) throw new Error('加载失败');
        const config = await res.json();
        console.log('后端事件配置:', config);

        const categories = ['task', 'encounter', 'event', 'birthday'];
        for (const cat of categories) {
            const cfg = config[cat];
            if (!cfg) continue;
            const catDiv = document.querySelector(`.event-category[data-category="${cat}"]`);
            if (!catDiv) continue;

            const checkbox = catDiv.querySelector('.event-enabled');
            const weightSlider = catDiv.querySelector('.event-weight');
            const weightSpan = catDiv.querySelector('.weight-value');
            const cooldownInput = catDiv.querySelector('.event-cooldown');

            if (checkbox) {
                checkbox.checked = cfg.enabled;
                checkbox.onchange = () => saveEventConfigImmediately(cat);
            }
            if (weightSlider) {
                weightSlider.value = cfg.weight;
                if (weightSpan) weightSpan.textContent = cfg.weight;
                weightSlider.oninput = (e) => {
                    const val = parseInt(e.target.value, 10);
                    if (weightSpan) weightSpan.textContent = val;
                    saveEventConfigImmediately(cat);
                };
            }
            if (cooldownInput) {
                // 后端 cooldown 是秒，转换为分钟并取整（不丢失配置）
                const minutes = Math.round(cfg.cooldown / 60);
                cooldownInput.value = minutes;
                // 添加说明：冷却时间（分钟）
                cooldownInput.onchange = () => saveEventConfigImmediately(cat);
            }
        }

        // 加载全局开关
        const globalRes = await fetch('/event/global_enabled');
        if (globalRes.ok) {
            const globalData = await globalRes.json();
            const globalCheckbox = document.getElementById('event-global-enabled');
            if (globalCheckbox) {
                globalCheckbox.checked = globalData.enabled;
                globalCheckbox.onchange = () => saveEventGlobalEnabled();
            }
        }

        const runtimeRes = await fetch('/event/runtime_config');
        if (runtimeRes.ok) {
            const runtime = await runtimeRes.json();
            const slider = document.getElementById('event-group-exploration-rate');
            const valueLabel = document.getElementById('event-group-exploration-rate-value');
            if (slider) {
                const percent = Math.round((Number(runtime.group_exploration_rate) || 0) * 100);
                slider.value = String(percent);
                if (valueLabel) valueLabel.textContent = `${percent}%`;
                slider.oninput = () => {
                    if (valueLabel) valueLabel.textContent = `${slider.value}%`;
                };
                slider.onchange = () => saveEventRuntimeConfig();
            }
            const intervalInput = document.getElementById('event-generation-interval');
            const dailyInput = document.getElementById('event-max-per-day');
            const operatorsInput = document.getElementById('event-max-operators');
            if (intervalInput) {
                intervalInput.value = String(Math.max(1, Math.round(Number(runtime.generation_interval || 3600) / 60)));
                intervalInput.onchange = () => saveEventRuntimeConfig();
            }
            if (dailyInput) {
                dailyInput.value = String(Number(runtime.max_per_day || 5));
                dailyInput.onchange = () => saveEventRuntimeConfig();
            }
            if (operatorsInput) {
                operatorsInput.value = String(Number(runtime.max_operators_per_event || 2));
                operatorsInput.onchange = () => saveEventRuntimeConfig();
            }
            const assistantOps = document.getElementById('event-allow-assistant-ops');
            if (assistantOps) { assistantOps.checked = Boolean(runtime.allow_assistant_auto_ops); assistantOps.onchange = () => saveEventRuntimeConfig(); }
        }
        await loadEventDeliveries();
        await loadEventManagement();
    } catch (e) {
        console.error('加载事件配置失败', e);
        showTemporaryToast('加载事件配置失败，请稍后重试');
    }
}

// 立即保存单个类别的配置
// 立即保存单个类别的配置
async function saveEventConfigImmediately(category) {
    const catDiv = document.querySelector(`.event-category[data-category="${category}"]`);
    if (!catDiv) return;
    const enabled = catDiv.querySelector('.event-enabled').checked;
    const weight = parseInt(catDiv.querySelector('.event-weight').value, 10);
    const cooldownInput = catDiv.querySelector('.event-cooldown');
    let minutes = parseInt(cooldownInput.value, 10);
    if (isNaN(minutes)) minutes = 0;
    const seconds = minutes * 60;  // 转回秒
    const config = { [category]: { enabled, weight, cooldown: seconds } };
    try {
        const res = await fetch('/event/config', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(config)
        });
        if (!res.ok) {
            const err = await res.json();
            throw new Error(err.detail || '保存失败');
        }
        console.log(`[事件配置] ${category} 配置已保存`);
    } catch (e) {
        console.error('保存事件配置失败', e);
        showTemporaryToast(`保存 ${category} 配置失败：${e.message}`);
        loadEventConfig();
    }
}

// 保存全局开关
async function saveEventGlobalEnabled() {
    const globalCheckbox = document.getElementById('event-global-enabled');
    const enabled = globalCheckbox.checked;
    try {
        const res = await fetch('/event/global_enabled', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ enabled })
        });
        if (!res.ok) throw new Error('保存失败');
        console.log('[事件配置] 全局开关已保存');
    } catch (e) {
        console.error('保存全局开关失败', e);
        showTemporaryToast('保存全局开关失败，请重试');
        // 恢复原状态（重新加载）
        const reloadRes = await fetch('/event/global_enabled');
        if (reloadRes.ok) {
            const data = await reloadRes.json();
            globalCheckbox.checked = data.enabled;
        }
    }
}

async function saveEventRuntimeConfig() {
    const slider = document.getElementById('event-group-exploration-rate');
    if (!slider) return;
    const intervalMinutes = Number(document.getElementById('event-generation-interval')?.value || 60);
    const maxPerDay = Number(document.getElementById('event-max-per-day')?.value || 5);
    const maxOperators = Number(document.getElementById('event-max-operators')?.value || 2);
    const allowAssistantOps = Boolean(document.getElementById('event-allow-assistant-ops')?.checked);
    try {
        const res = await fetch('/event/runtime_config', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                group_exploration_rate: Number(slider.value) / 100,
                generation_interval: intervalMinutes * 60,
                max_per_day: maxPerDay,
                max_operators_per_event: maxOperators,
                allow_assistant_auto_ops: allowAssistantOps
            })
        });
        if (!res.ok) throw new Error((await res.json()).detail || '保存失败');
        showTemporaryToast('事件运行参数已保存');
    } catch (e) {
        console.error('保存事件运行参数失败', e);
        showTemporaryToast(`保存失败：${e.message}`);
        loadEventConfig();
    }
}

async function loadEventDeliveries() {
    const summary = document.getElementById('event-delivery-summary');
    const list = document.getElementById('event-delivery-list');
    if (!summary || !list) return;
    try {
        const res = await fetch('/event/deliveries?limit=50');
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const deliveries = await res.json();
        const counts = deliveries.reduce((acc, item) => {
            acc[item.status] = (acc[item.status] || 0) + 1;
            return acc;
        }, {});
        summary.innerHTML = [
            ['待投递', (counts.pending || 0) + (counts.delivering || 0)],
            ['已投递', counts.delivered || 0],
            ['已确认', counts.acknowledged || 0],
            ['死信', counts.dead_letter || 0]
        ].map(([label, value]) => `<div class="event-delivery-stat"><span>${label}</span><strong>${value}</strong></div>`).join('');
        if (!deliveries.length) {
            list.innerHTML = '<div class="ops-empty">暂无事件投递记录</div>';
            return;
        }
        list.innerHTML = deliveries.slice(0, 12).map(item => {
            const canRetry = item.status === 'dead_letter' || item.status === 'failed';
            return `<div class="event-delivery-row">
                <div class="event-delivery-meta">
                    <strong>${escapeHtml(item.consumer)} · ${escapeHtml(item.target_type)}:${escapeHtml(item.target_id)}</strong>
                    <span>${escapeHtml(item.event_id)} · 尝试 ${Number(item.attempt_count || 0)}/${Number(item.max_attempts || 0)}</span>
                </div>
                ${canRetry
                    ? `<button type="button" class="settings-inline-btn" onclick="retryEventDelivery('${escapeHtml(item.delivery_id)}')">重试</button>`
                    : `<span class="event-delivery-status ${escapeHtml(item.status)}">${escapeHtml(item.status)}</span>`}
            </div>`;
        }).join('');
    } catch (e) {
        console.error('读取事件投递状态失败', e);
        summary.textContent = '投递状态暂时不可用';
        list.innerHTML = '';
    }
}

async function retryEventDelivery(deliveryId) {
    try {
        const res = await fetch(`/event/deliveries/${encodeURIComponent(deliveryId)}/retry`, { method: 'POST' });
        if (!res.ok) throw new Error((await res.json()).detail || '重试失败');
        showTemporaryToast('投递已重新加入队列');
        await loadEventDeliveries();
    } catch (e) {
        showTemporaryToast(`重试失败：${e.message}`);
    }
}

let eventManageTab = 'overview';
async function loadEventManagement(tab=eventManageTab){const content=document.getElementById('event-management-content');if(!content)return;eventManageTab=tab;document.querySelectorAll('[data-event-manage]').forEach(b=>{b.classList.toggle('active',b.dataset.eventManage===tab);b.onclick=()=>loadEventManagement(b.dataset.eventManage)});document.getElementById('event-manage-create')?.classList.toggle('hidden',['overview','instances','drafts'].includes(tab));closeEventManageEditor();content.innerHTML='<div class="ops-empty">正在读取…</div>';try{const r=await fetch(tab==='types'?'/event/types':`/event/manage/${tab}`);if(!r.ok)throw new Error((await r.json()).detail||`HTTP ${r.status}`);const payload=await r.json();renderEventManagement(tab,tab==='types'?payload.types:payload)}catch(e){content.innerHTML=`<div class="ops-empty">读取失败：${escapeHtml(e.message)}</div>`}}
function renderEventManagement(tab,data){const c=document.getElementById('event-management-content');if(!c)return;if(tab==='overview'){const labels={library_count:'事件模板',pool_count:'随机池',subscription_count:'启用路由',callback_count:'启用回调',pending_deliveries:'待处理投递',dead_letters:'死信',active_conversations:'持续情景',pending_drafts:'待审草稿'};c.innerHTML=`<div class="event-manage-overview">${Object.entries(labels).map(([k,l])=>`<div><span>${l}</span><strong>${Number(data[k]||0)}</strong></div>`).join('')}</div>`;return}if(!Array.isArray(data)||!data.length){c.innerHTML='<div class="ops-empty">暂无记录</div>';return}c.innerHTML=data.map(i=>{if(tab==='types')return `<details class="event-manage-row event-instance-row"><summary><div><strong>${escapeHtml(i.name)}</strong><span>${escapeHtml(i.type_id)} · v${i.version} · ${i.enabled?'启用':'停用'} · ${escapeHtml(i.source)}</span></div></summary><pre>${escapeHtml(JSON.stringify(i,null,2))}</pre></details>`;if(tab==='library')return `<div class="event-manage-row"><div><strong>${escapeHtml(i.name)}</strong><span>${escapeHtml(i.source)} · ${escapeHtml(i.direction)} · v${i.version}</span></div>${i.source==='builtin'?'<span>内置</span>':`<button onclick="deleteEventManageRecord('library','${i.entry_id}')">删除</button>`}</div>`;if(tab==='pools')return `<div class="event-manage-row"><div><strong>${escapeHtml(i.name)}</strong><span>${escapeHtml(i.direction)} · ${i.items.length} 项</span></div><button onclick="deleteEventManageRecord('pool','${i.pool_id}')">删除</button></div>`;if(tab==='subscriptions')return `<div class="event-manage-row"><div><strong>${escapeHtml(i.event_type)} → ${escapeHtml(i.consumer)}</strong><span>${escapeHtml(i.target_type)}:${escapeHtml(i.target_id)} · ${i.enabled?'启用':'停用'}</span></div><button onclick="deleteEventManageRecord('subscription','${i.subscription_id}')">删除</button></div>`;if(tab==='callbacks')return `<div class="event-manage-row"><div><strong>${escapeHtml(i.event_name)} → ${escapeHtml(i.handler_name)}</strong><span>${i.enabled?'启用':'停用'}</span></div><button onclick="deleteEventManageRecord('callback','${i.callback_id}')">删除</button></div>`;if(tab==='instances')return `<details class="event-manage-row event-instance-row"><summary><div><strong>${escapeHtml(i.title)}</strong><span>${escapeHtml(i.category)} · ${escapeHtml(i.status)} · ${escapeHtml(i.id)}</span></div></summary><pre>${escapeHtml(JSON.stringify(i.validation||{},null,2))}</pre><button onclick="routeEventInstance('${i.id}')">按当前订阅重新路由</button></details>`;return `<div class="event-manage-row"><div><strong>${escapeHtml(i.title)}</strong><span>${escapeHtml(i.draft_type)} · ${escapeHtml(i.status)} · ${escapeHtml(i.content.slice(0,100))}</span></div>${i.status==='pending'?`<span><button onclick="reviewEventDraft('${i.draft_id}','approved')">通过</button><button onclick="reviewEventDraft('${i.draft_id}','rejected')">驳回</button></span>`:''}</div>`}).join('')}
function openEventManageEditor(){const e=document.getElementById('event-manage-editor');if(!e)return;e.classList.remove('hidden');document.getElementById('event-manage-name').placeholder=eventManageTab==='types'?'事件类型 ID（英文、数字、下划线）':eventManageTab==='subscriptions'?'事件类型（* 表示全部）':eventManageTab==='callbacks'?'触发点（如 on_generated）':'名称';document.getElementById('event-manage-direction').placeholder=eventManageTab==='types'?'显示名称':eventManageTab==='subscriptions'?'消费者（如 chat.group）':eventManageTab==='callbacks'?'处理器名称（audit 为仅记录）':'事件方向';document.getElementById('event-manage-target').placeholder=eventManageTab==='types'?'适用范围，逗号分隔':'目标类型:目标ID';document.getElementById('event-manage-json').placeholder=eventManageTab==='types'?'JSON：描述、字段、上下文、Prompt 与输出结构':'JSON 配置或随机内容数组'}
function closeEventManageEditor(){document.getElementById('event-manage-editor')?.classList.add('hidden')}
async function saveEventManageEditor(){const name=document.getElementById('event-manage-name')?.value.trim()||'',direction=document.getElementById('event-manage-direction')?.value.trim()||'',targetValue=document.getElementById('event-manage-target')?.value.trim()||'',target=targetValue||(eventManageTab==='types'?'':'global:global'),raw=document.getElementById('event-manage-json')?.value.trim()||(eventManageTab==='pools'?'[]':'{}');let json;try{json=JSON.parse(raw)}catch(_){showTemporaryToast('JSON 格式不正确');return}let body;if(eventManageTab==='types')body={...json,type_id:name,name:direction||name,scopes:target.split(',').map(i=>i.trim()).filter(Boolean)};else if(eventManageTab==='library')body={name,direction:direction||'event',template:json};else if(eventManageTab==='pools')body={name,direction:direction||'event',items:json};else if(eventManageTab==='subscriptions'){const [t,...rest]=target.split(':');body={event_type:name||'*',consumer:direction||'transaction.todo',target_type:t||'global',target_id:rest.join(':')||'global',config:json}}else body={event_name:name||'on_generated',handler_name:direction||'audit',config:json};try{const r=await fetch(eventManageTab==='types'?'/event/types':`/event/manage/${eventManageTab}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw new Error((await r.json()).detail||'保存失败');showTemporaryToast('已保存');await loadEventManagement(eventManageTab)}catch(e){showTemporaryToast(`保存失败：${e.message}`)}}
