// ========== 36. 备份与导入导出内容 ==========
// 导出配置（显示预览并支持复制）
async function exportConfig() {
    try {
        const res = await fetch('/export/config');
        if (!res.ok) throw new Error('导出失败');
                const config = await res.json();
                const content = JSON.stringify(config, null, 2);
                await saveExportUrl('/export/config', `zoot_config_${archiveTimestamp()}.json`, 'application/json');
        const previewDiv = document.getElementById('config-preview-content');
        if (previewDiv) {
            previewDiv.textContent = content;
            showModal('configPreviewModal');
        } else {
            // 降级：直接下载
            const blob = new Blob([content], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `zoot_config_${new Date().toISOString().slice(0,19)}.json`;
            a.click();
            URL.revokeObjectURL(url);
        }
    } catch (e) {
        alert('导出配置失败：' + e.message);
    }
}

// 复制配置内容（在 configPreviewModal 显示后绑定）
async function bindCopyConfigButton() {
    const copyBtn = document.getElementById('copy-config-btn');
    if (copyBtn && !copyBtn._bound) {
        copyBtn._bound = true;
        copyBtn.addEventListener('click', async () => {
            const content = document.getElementById('config-preview-content')?.textContent;
            if (content) {
                try {
                    await navigator.clipboard.writeText(content);
                    alert('已复制到剪贴板');
                } catch (err) {
                    alert('复制失败，请手动复制');
                }
            }
        });
    }
}

