// ========== 40. 主题管理系统 ==========
class ThemeManager {
    constructor(themes) {
        this.themes = themes;
        this.currentThemeId = localStorage.getItem('colorScheme') || 'scheme1';
        this.currentIsDark = localStorage.getItem('theme') === 'dark';
        // 保存原始图标 src 映射，用于恢复
        this.originalIconSrcs = new Map();
        this.init();
    }

    init() {
        // 移除可能残留的 .ambient-bg
        const oldBg = document.querySelector('.ambient-bg');
        if (oldBg) oldBg.remove();
        this.applyCurrent();
        this.watchSystemTheme();
    }

    applyCurrent() {
        const theme = this.themes[this.currentThemeId];
        if (!theme) return;

        // 清除之前注入的 CSS 变量
        this.clearCssVariables();

        // 非 covenant 主题：注入 CSS 变量
        if (!theme.useCssOnly) {
            document.body.classList.remove('covenant-theme');
            const vars = this.currentIsDark ? theme.darkVars : theme.lightVars;
            for (const [key, value] of Object.entries(vars)) {
                document.documentElement.style.setProperty(key, value);
            }
        } else {
            const allThemeClasses = Object.keys(this.themes).map(id => `${id}-theme`);
            document.body.classList.remove(...allThemeClasses);
            if (theme.extraClasses) document.body.classList.add(...theme.extraClasses);
        }

        // 设置 body 背景图片
        const bgImageUrl = this.currentIsDark ? theme.darkBgImage : theme.lightBgImage;
        if (bgImageUrl) {
            document.body.style.backgroundImage = `url('${bgImageUrl}')`;
            document.body.style.backgroundSize = 'cover';
            document.body.style.backgroundPosition = 'center';
            document.body.style.backgroundRepeat = 'no-repeat';
            document.body.style.backgroundAttachment = 'fixed';
        } else {
            document.body.style.backgroundImage = '';
        }

        // 应用图标映射等（保持不变）
        this.applyIconMappings(theme);
        this.updateQuickToggleIcon();
        this.updateStatsCardBackground(theme.id === 'covenant');
        document.dispatchEvent(new CustomEvent('themeChanged', {
            detail: { themeId: this.currentThemeId, isDark: this.currentIsDark }
        }));
    }

    clearCssVariables() {
        const varsToClear = [
            '--bg-color', '--text-color', '--text-secondary', '--card-bg',
            '--border-color', '--hover-bg', '--pinned-bg', '--filter-bg',
            '--letter-bg', '--primary-color', '--secondary-color', '--danger-color',
            '--success-color', '--warning-color', '--info-color', '--shadow-color',
            '--shadow-heavy', '--overlay-bg', '--typing-bg', '--item-bg'
        ];
        varsToClear.forEach(v => document.documentElement.style.removeProperty(v));
    }

    applyIconMappings(theme) {
        const isCovenant = (theme.id === 'covenant');
        const mappings = theme.iconMappings || [];

        if (isCovenant) {
            // 承诺主题：替换为 sealed 图标
            mappings.forEach(map => {
                const imgs = document.querySelectorAll(`img[src*="${map.normal.replace('.png', '')}"]`);
                imgs.forEach(img => {
                    // 保存原始 src（如果尚未保存）
                    if (!this.originalIconSrcs.has(img)) {
                        this.originalIconSrcs.set(img, img.src);
                    }
                    const newSrc = img.src.replace(map.normal, map.sealed);
                    if (!img.src.includes(map.sealed)) img.src = newSrc;
                    if (map.scale) {
                        img.style.transform = 'scale(1.08)';
                        img.style.transition = 'transform 0.2s';
                    }
                    img.style.filter = 'none';
                });
            });
            if (theme.navIconScale) {
                document.querySelectorAll('.nav-icon').forEach(icon => {
                    icon.style.transform = 'scale(1.08)';
                    icon.style.filter = 'none';
                });
            }
        } else {
            // 非承诺主题：恢复原始图标
            // 先恢复所有曾替换过的图片
            this.originalIconSrcs.forEach((originalSrc, img) => {
                if (img.src !== originalSrc) {
                    img.src = originalSrc;
                }
                img.style.transform = '';
                img.style.filter = '';
            });
            // 清除导航栏样式
            document.querySelectorAll('.nav-icon').forEach(icon => {
                icon.style.transform = '';
                icon.style.filter = '';
            });
            // 如果有其他需要恢复的普通图标，可通过 mappings 的反向？但上述已足够
        }
    }

    updateQuickToggleIcon() {
        const btn = document.getElementById('theme-quick-toggle');
        if (!btn) return;
        const theme = this.themes[this.currentThemeId];
        if (theme.id === 'covenant') {
            btn.innerHTML = `<img src="${theme.quickToggleIcon}" style="width: 28px; height: 28px;">`;
        } else {
            btn.innerHTML = this.currentIsDark
                ? '<img src="/static/images/img_theme_day.png" alt="">'
                : '<img src="/static/images/img_theme_night.png" alt="">';
            btn.setAttribute('aria-label', this.currentIsDark ? '切换到日间模式' : '切换到夜间模式');
        }
    }

    updateStatsCardBackground(isCovenant) {
        const statsCards = document.querySelectorAll('.stats-card');
        if (!statsCards.length) return;
        const bgImage = isCovenant ? 'url("/static/images/img_room_bkg_sealed.png")' : 'url("/static/images/img_room_bkg.png")';
        statsCards.forEach(card => {
            card.style.backgroundImage = bgImage;
        });
    }

    setTheme(themeId, isDark = null) {
        if (!this.themes[themeId]) return;
        this.currentThemeId = themeId;
        localStorage.setItem('colorScheme', themeId);
        if (isDark !== null) {
            this.setDarkMode(isDark);
        } else {
            this.applyCurrent();
        }
    }

    setDarkMode(isDark) {
        this.currentIsDark = isDark;
        const root = document.documentElement;
        if (isDark) {
            root.classList.add('dark-mode');
            root.classList.remove('light-mode');
        } else {
            root.classList.add('light-mode');
            root.classList.remove('dark-mode');
        }
        localStorage.setItem('theme', isDark ? 'dark' : 'light');
        try {
            window.Android?.setSystemBarLightMode?.(!isDark);
        } catch (_) {
            // Browser preview and older Android bridges do not expose this method.
        }
        this.applyCurrent();
    }

    toggleDarkMode() {
        this.setDarkMode(!this.currentIsDark);
    }

    watchSystemTheme() {
        if (window.matchMedia) {
            const darkModeQuery = window.matchMedia('(prefers-color-scheme: dark)');
            darkModeQuery.addEventListener('change', (e) => {
                // 只有当用户从未手动切换过主题时才跟随系统
                const manualTheme = localStorage.getItem('theme_manual');
                if (!manualTheme) {
                    this.setDarkMode(e.matches);
                }
            });
        }
    }
}

// 兼容旧调用的 applyTheme 函数（保留用于外部调用）
function applyTheme(theme, scheme) {
    themeManager.setDarkMode(theme === 'dark');
    themeManager.setTheme(scheme, theme === 'dark');
}

// 加载显示设置（原有函数，但注意避免重复初始化 themeManager）
function loadDisplaySettings() {
    const theme = localStorage.getItem('theme') || 'light';
    const scheme = localStorage.getItem('colorScheme') || 'scheme1';
    // 直接使用 themeManager 设置，避免重复初始化
    themeManager.setDarkMode(theme === 'dark');
    themeManager.setTheme(scheme, theme === 'dark');
    // 字体设置部分保持不变
    const fontSize = localStorage.getItem('fontSize') || '16';
    const fontFamily = localStorage.getItem('fontFamily') || "system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif";
    const fontSizeSlider = document.getElementById('font-size-slider');
    const fontSizeValue = document.getElementById('font-size-value');
    const fontFamilySelect = document.getElementById('font-family-select');
    if (fontSizeSlider) fontSizeSlider.value = fontSize;
    if (fontSizeValue) fontSizeValue.textContent = fontSize + 'px';
    if (fontFamilySelect) fontFamilySelect.value = fontFamily;
    applyFontSize(parseInt(fontSize));
    applyFontFamily(fontFamily);
}

