// ========== 42. 多端互通&PC协同 ==========

// ========== Device Fabric：可信设备、短码配对与远程任务 ==========
const DEVICE_FABRIC_SCOPES = [
    'device.presence', 'assistant.monitor', 'assistant.approval',
    'assistant.cancel', 'workspace.remote.submit', 'data.sync'
];

async function deviceFabricRequest(path, options = {}) {
    const response = await fetch('/device-fabric' + path, options);
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
        const detail = data.detail;
        const message = typeof detail === 'string' ? detail : (detail?.message || detail?.code);
        throw new Error(message || ('请求失败：' + response.status));
    }
    return data;
}

function deviceFabricBadges(items) {
    return (items || []).map(item => `<span class="device-fabric-badge">${escapeHtml(String(item))}</span>`).join('');
}

function renderDeviceIndustrialState(data={}){const status=document.getElementById('multi-device-industrial-status');const matrix=document.getElementById('multi-device-industrial-matrix');const trusted=Array.isArray(data.trusted_devices)?data.trusted_devices.length:0;const pending=Array.isArray(data.pairing_sessions)?data.pairing_sessions.filter(item=>item.state==='pending_confirmation').length:0;const tasks=Array.isArray(data.tasks)?data.tasks:[];const activeTasks=tasks.filter(item=>['queued','running','pending'].includes(item.state)).length;const failedTasks=tasks.filter(item=>item.state==='failed').length;const available=data.available!==false&&Object.keys(data).length>0;if(status){status.dataset.status=!available?'unavailable':failedTasks||pending?'attention':'ok';status.querySelector('strong').textContent='DEVICE FABRIC';status.querySelector('span').textContent=!available?'可信设备服务在此设备上不可用':`${data.identity?.device_name||'本机'} · ${trusted} 台可信设备 · ${activeTasks} 个活动任务`;}if(!matrix)return;const cells=[['LAN','局域网',data.lan_enabled===false?'关闭':available?'就绪':'N/A'],['ID','本机身份',data.identity?.fingerprint?'就绪':'N/A'],['PAIR','待确认',pending],['SYN','活动同步',activeTasks],['QUE','失败任务',failedTasks],['KEY','密钥',data.identity?.key_storage||'N/A']];matrix.innerHTML=cells.map(([code,label,value])=>`<article class="industrial-status-cell" data-state="${!available?'unavailable':code==='PAIR'&&Number(value)>0||code==='QUE'&&Number(value)>0?'attention':'ok'}"><b>${code}</b><span>${escapeHtml(label)}</span><strong>${escapeHtml(String(value))}</strong></article>`).join('');}

function rememberRemoteDeviceTask(peerDeviceId, task) {
    const key = 'zootDeviceFabricRemoteTasks';
    let items = [];
    try { items = JSON.parse(localStorage.getItem(key) || '[]'); } catch (_) {}
    items = [{ peer_device_id: peerDeviceId, task_id: task.task_id, task_kind: task.task_kind, created_at: task.created_at }, ...items.filter(item => item.task_id !== task.task_id)].slice(0, 30);
    localStorage.setItem(key, JSON.stringify(items));
}

async function submitRemoteWorkspaceTask(peerDeviceId) {
    const overview = window.deviceFabricOverview || await deviceFabricRequest('/overview');
    const capability = (overview.capabilities || []).find(item => item.device_id === peerDeviceId) || {};
    const grants = capability.workspace_grants || [];
    if (!grants.length) return alert('该 PC 尚未发布可用的 Workspace Grant。请先在 PC 助理控制台创建限定工作区授权。');
    const taskKind = prompt('任务类型：workspace.list / workspace.search / workspace.read / workspace.changeset.verify', 'workspace.read');
    if (!taskKind) return;
    const grantId = prompt('Workspace Grant ID', grants[0]);
    if (!grantId) return;
    const payload = { grant_id: grantId };
    if (taskKind === 'workspace.search') {
        payload.query = prompt('检索文本') || '';
        payload.glob = prompt('文件范围', '*') || '*';
    } else if (taskKind === 'workspace.changeset.verify') {
        payload.changeset_id = prompt('变更集 ID') || '';
    } else {
        payload.path = prompt(taskKind === 'workspace.list' ? '目录相对路径' : '文件相对路径', '.') || '.';
    }
    try {
        const response = await deviceFabricRequest('/signed-send', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                peer_device_id: peerDeviceId, action: 'task.submit',
                payload: { task_kind: taskKind, payload, idempotency_key: `mobile:${Date.now()}:${Math.random().toString(36).slice(2)}` }
            })
        });
        const task = response.result;
        rememberRemoteDeviceTask(peerDeviceId, task);
        alert('任务已进入可信 PC 队列。PC Worker 会再次检查 Workspace Grant 和路径边界。');
        await loadDeviceFabricPanel();
    } catch (error) {
        alert('远程工作任务提交失败：' + error.message);
    }
}

async function renderRememberedRemoteTasks() {
    let remembered = [];
    try { remembered = JSON.parse(localStorage.getItem('zootDeviceFabricRemoteTasks') || '[]'); } catch (_) {}
    if (!remembered.length) return '';
    const cards = await Promise.all(remembered.slice(0, 12).map(async item => {
        try {
            const response = await deviceFabricRequest('/signed-send', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ peer_device_id: item.peer_device_id, action: 'task.status', payload: { task_id: item.task_id } })
            });
            const task = response.result || {};
            const resultText = task.result ? JSON.stringify(task.result).slice(0, 500) : (task.error_text || '');
            return `<div class="device-fabric-card"><b>PC · ${escapeHtml(task.task_kind || item.task_kind)}</b> · ${escapeHtml(task.state || 'unknown')}<br><small>${escapeHtml(resultText)}</small></div>`;
        } catch (error) {
            return `<div class="device-fabric-card"><b>PC · ${escapeHtml(item.task_kind)}</b><br><small>状态暂不可达：${escapeHtml(error.message)}</small></div>`;
        }
    }));
    return '<div class="device-fabric-section-title">由本机提交到 PC</div>' + cards.join('');
}

async function loadDeviceFabricPanel() {
    const identity = document.getElementById('device-fabric-identity');
    if (!identity) return;
    try {
        const data = await deviceFabricRequest('/overview');
        window.deviceFabricOverview = data;
        if (data.available === false) {
            renderDeviceIndustrialState(data);
            identity.innerHTML = '<b>可信设备服务未启用</b><br><small>Android Keystore 设备身份暂不可用。聊天、事务等其他功能不受影响。</small>';
            document.getElementById('device-fabric-pending').innerHTML = '';
            document.getElementById('device-fabric-trusted').innerHTML = '<div class="device-fabric-card">设备协作处于安全降级状态，当前不会接受配对或远程任务。</div>';
            document.getElementById('device-fabric-tasks').innerHTML = '';
            return;
        }
        renderDeviceIndustrialState(data);
        const self = data.identity || {};
        identity.innerHTML = `<b>${escapeHtml(self.device_name || '本机')}</b> · ${escapeHtml(self.platform || 'unknown')}<br>指纹 ${escapeHtml(self.fingerprint || '未生成')}<br><small>私钥保护：${escapeHtml(self.key_storage || 'unknown')} · 协议 ${escapeHtml(self.protocol_version || '')}</small>`;

        const pending = document.getElementById('device-fabric-pending');
        const pendingItems = (data.pairing_sessions || []).filter(item => item.state === 'pending_confirmation');
        pending.innerHTML = pendingItems.length
            ? '<div class="device-fabric-section-title">等待本机确认</div>' + pendingItems.map(item => {
                const peer = item.peer || {};
                return `<div class="device-fabric-card"><div class="device-fabric-card-row"><div><b>${escapeHtml(peer.device_name || peer.device_id || '未知设备')}</b><br>${escapeHtml(peer.platform || '')} · 指纹 ${escapeHtml(peer.fingerprint || '')}</div><button type="button" onclick="confirmSecureDevicePairing('${escapeHtml(item.pairing_id)}')">核对后信任</button></div></div>`;
            }).join('')
            : '';

        const trusted = document.getElementById('device-fabric-trusted');
        trusted.innerHTML = '<div class="device-fabric-section-title">可信设备</div>' + ((data.trusted_devices || []).length
            ? data.trusted_devices.map(item => `<div class="device-fabric-card"><div class="device-fabric-card-row"><div><b>${escapeHtml(item.device_name)}</b> · ${escapeHtml(item.platform)}<br>指纹 ${escapeHtml(item.fingerprint)}<br>${deviceFabricBadges(item.scopes)}</div><div>${item.platform==='pc'?`<button type="button" onclick="submitRemoteWorkspaceTask('${escapeHtml(item.device_id)}')">PC 工作任务</button>`:''}<button type="button" class="danger" onclick="revokeSecureDevice('${escapeHtml(item.device_id)}')">撤销</button></div></div></div>`).join('')
            : '<div class="device-fabric-card">尚无可信设备。旧设备发现或旧配对不会自动获得助理权限。</div>');

        const tasks = document.getElementById('device-fabric-tasks');
        const taskItems = data.tasks || [];
        tasks.innerHTML = '<div class="device-fabric-section-title">近期远程任务</div>' + (taskItems.length
            ? taskItems.map(item => `<div class="device-fabric-card"><b>${escapeHtml(item.task_kind)}</b> · ${escapeHtml(item.state)}<br><small>${new Date((item.updated_at || 0) * 1000).toLocaleString()} · 尝试 ${item.attempt_count || 0} 次</small></div>`).join('')
            : '<div class="device-fabric-card">暂无远程任务</div>');
        tasks.insertAdjacentHTML('beforeend', await renderRememberedRemoteTasks());
    } catch (error) {
        identity.textContent = '可信设备服务暂不可用：' + error.message;
        renderDeviceIndustrialState();
    }
}

async function startSecureDevicePairing() {
    try {
        const data = await deviceFabricRequest('/pairing/start', { method: 'POST' });
        const target = document.getElementById('device-fabric-pair-code');
        target.hidden = false;
        target.innerHTML = `请在五分钟内于另一台设备输入<b>${escapeHtml(data.short_code)}</b><small>配对 ID：${escapeHtml(data.pairing_id)}<br>请同时核对双方显示的设备指纹。</small>`;
        await loadDeviceFabricPanel();
    } catch (error) {
        alert('无法生成安全配对短码：' + error.message);
    }
}

async function connectSecureDevicePairing() {
    const peerBaseUrl = prompt('请输入对方设备可访问地址（例如 http://192.168.1.10:8000）');
    if (!peerBaseUrl) return;
    const pairingId = prompt('请输入对方显示的配对 ID');
    if (!pairingId) return;
    const shortCode = prompt('请输入六位短码');
    if (!shortCode) return;
    const localBaseUrl = prompt('请输入本机可被对方访问的地址。请使用局域网 IP，不要使用 127.0.0.1。', location.origin) || '';
    try {
        await deviceFabricRequest('/pairing/connect', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ peer_base_url: peerBaseUrl, pairing_id: pairingId, short_code: shortCode, local_base_url: localBaseUrl })
        });
        alert('配对申请已加密绑定到本机指纹，请在对方设备核对并确认。');
        await loadDeviceFabricPanel();
    } catch (error) {
        alert('安全配对申请失败：' + error.message);
    }
}

async function confirmSecureDevicePairing(pairingId) {
    if (!confirm('请确认您已通过另一渠道核对对方设备名称与指纹。继续后，该设备可在所列作用域内查看助理状态、审批并提交受限 PC 工作任务。')) return;
    const localBaseUrl = prompt('请输入本机可被对方访问的局域网地址', location.origin) || '';
    try {
        const data = await deviceFabricRequest('/pairing/' + encodeURIComponent(pairingId) + '/confirm', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ scopes: DEVICE_FABRIC_SCOPES, local_base_url: localBaseUrl })
        });
        alert(data.peer_accepted === false ? '本机已信任，但对方暂时不可达；请在对方设备重新连接。' : '可信配对已完成。');
        await loadDeviceFabricPanel();
    } catch (error) {
        alert('确认可信设备失败：' + error.message);
    }
}

async function revokeSecureDevice(deviceId) {
    if (!confirm('撤销后，该设备的现有会话和签名请求将立即失效。是否继续？')) return;
    try {
        await deviceFabricRequest('/devices/' + encodeURIComponent(deviceId) + '/revoke', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ state: 'revoked' })
        });
        await loadDeviceFabricPanel();
    } catch (error) {
        alert('撤销可信设备失败：' + error.message);
    }
}

document.addEventListener('DOMContentLoaded', () => {
    if (document.getElementById('device-fabric-identity')) loadDeviceFabricPanel();
});


// ========== 42.1. 设备发现与配对 ==========
let discoveredDevices = [];
let isScanning = false;
let pendingPollingInterval = null;
let scanTimeout = null;
let myDeviceId = null;          // 存储本机设备ID，用于过滤
// 避免重复声明
window.activePairTimeouts = window.activePairTimeouts || {};

// 获取本机设备ID（需Android接口支持）
function getMyDeviceId() {
    if (window.Android && typeof Android.getMyDeviceId === 'function') {
        return Android.getMyDeviceId();
    }
    return null;
}

// 初始化设备发现相关事件监听
function initDeviceDiscovery() {
    myDeviceId = getMyDeviceId();
    const scanBtn = document.getElementById('scan-devices-btn');
    const stopBtn = document.getElementById('stop-scan-btn');
    const clearBtn = document.getElementById('clear-paired-btn');
    if (scanBtn) {
        scanBtn.addEventListener('click', () => {
            if (isScanning) return;
            startScanning();
            if (window.Android) {
                Android.startDiscovery();
                console.log('[移动端] 开始扫描设备');
            } else {
                console.warn('Android 接口不可用');
            }
            if (scanTimeout) clearTimeout(scanTimeout);
            scanTimeout = setTimeout(() => {
                if (isScanning) stopScanning();
            }, 30000);
        });
    }
    if (stopBtn) {
        stopBtn.addEventListener('click', () => {
            if (window.Android) Android.stopDiscovery();
            stopScanning();
            console.log('[移动端] 停止扫描');
        });
    }
    if (clearBtn) {
        clearBtn.addEventListener('click', async () => {   // 注意这里加上 async
            if (window.Android) {
                Android.clearPairedDevice();
                // 停止 pending 轮询
                if (pendingPollingInterval) {
                    clearInterval(pendingPollingInterval);
                    pendingPollingInterval = null;
                }
                // 停止所有健康检查
                Object.keys(healthCheckIntervals).forEach(id => {
                    clearInterval(healthCheckIntervals[id]);
                    delete healthCheckIntervals[id];
                });
                // 停止同步管理器
                if (window.syncManager) {
                    window.syncManager.stop();
                    window.syncManager = null;
                }
                // 通知后端停止同步管理器
                try {
                    await fetch('/sync/set_pc_address', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ address: '' })
                    });
                    console.log('[移动端] 已通知后端停止同步管理器');
                } catch (e) {
                    console.warn('[移动端] 通知后端停止同步管理器失败', e);
                }
                window._processedPending = {};
                const devicesJson = Android.getDiscoveredDevices();
                if (devicesJson) window.onDeviceListUpdate(devicesJson);
                loadPairedDeviceInfo();
            }
        });
    }
    // 初始加载已配对设备
    loadPairedDeviceInfo();
    // 轮询函数
    startPendingRequestPolling();
}

function startScanning() {
    isScanning = true;
    // 清空旧的设备列表
    discoveredDevices = [];
    const container = document.getElementById('device-list');
    if (container) {
        container.innerHTML = '<li style="color: var(--text-secondary);"><span class="scanning-spinner"></span> 正在扫描...</li>';
    }
}

function stopScanning() {
    isScanning = false;
    if (scanTimeout) clearTimeout(scanTimeout);
    // 刷新设备列表，移除“扫描中”提示
    renderDeviceList();
}

function startPendingRequestPolling() {
    if (pendingPollingInterval) clearInterval(pendingPollingInterval);
    pendingPollingInterval = setInterval(() => {
        if (!window.Android) return;
        const pendingJson = Android.getPendingRequests();
        console.log('[移动端] 轮询 pending 请求, 原始数据:', pendingJson);
        if (pendingJson && pendingJson !== '[]') {
            try {
                const pendingList = JSON.parse(pendingJson);
                for (const req of pendingList) {
                    if (window._processedPending && window._processedPending[req.deviceId]) continue;
                    if (!window._processedPending) window._processedPending = {};
                    window._processedPending[req.deviceId] = true;
                    showPairConfirmDialogMobile(req.deviceId, req.deviceName, req.ip);
                    break;
                }
            } catch(e) { console.error(e); }
        }
    }, 1000);
}

// 前端回调：设备列表更新（由 Android 广播触发）
window.onDeviceListUpdate = function(devicesJson) {
    try {
        let allDevices = JSON.parse(devicesJson);
        // 转换驼峰为下划线
        allDevices = allDevices.map(device => ({
            device_id: device.deviceId,
            device_name: device.deviceName,
            ip: device.ip,
            port: device.port,
            paired: device.paired
        }));
        // 过滤掉本机设备
        if (myDeviceId) {
            allDevices = allDevices.filter(device => device.device_id !== myDeviceId);
        }
        discoveredDevices = allDevices;
        renderDeviceList();
        loadPairedDeviceInfo();

        // 清理已配对设备的超时
        if (window.activePairTimeouts) {
            Object.keys(window.activePairTimeouts).forEach(pid => {
                const device = allDevices.find(d => d.device_id === pid);
                if (device && device.paired) {
                    clearTimeout(window.activePairTimeouts[pid]);
                    delete window.activePairTimeouts[pid];
                }
            });
        }

        // 清理已配对设备的 _processedPending 标记
        if (window._processedPending && allDevices) {
            allDevices.forEach(device => {
                if (device.paired && window._processedPending[device.device_id]) {
                    delete window._processedPending[device.device_id];
                }
            });
        }
    } catch(e) {
        console.error('解析设备列表失败', e);
    }
    // 如果发现设备数量 > 0 且正在扫描，自动停止扫描
    if (isScanning && discoveredDevices.length > 0) {
        stopScanning();
    }
};

// 渲染发现的设备列表（增加 device-action 容器）
function renderDeviceList() {
    const container = document.getElementById('device-list');
    if (!container) return;
    if (isScanning && (!discoveredDevices || discoveredDevices.length === 0)) {
        container.innerHTML = '<li style="color: var(--text-secondary);"><span class="scanning-spinner"></span> 正在扫描...</li>';
        return;
    }
    if (!discoveredDevices.length) {
        container.innerHTML = '<li style="color: var(--text-secondary);">暂无发现设备</li>';
        return;
    }
    container.innerHTML = '';
    discoveredDevices.forEach(device => {
        const li = document.createElement('li');
        li.style.padding = '10px';
        li.style.borderBottom = '1px solid var(--border-color)';
        li.style.display = 'flex';
        li.style.justifyContent = 'space-between';
        li.style.alignItems = 'center';
        li.innerHTML = `
            <div>
                <div><strong>${escapeHtml(device.device_name)}</strong> ${device.paired ? '✅' : ''}</div>
                <div style="font-size: 12px; color: var(--text-secondary);">IP: ${device.ip}</div>
                <div style="font-size: 10px; color: var(--text-secondary);">ID: ${device.device_id.substring(0, 12)}...</div>
            </div>
        `;
        const actionDiv = document.createElement('div');
        actionDiv.className = 'device-action';
        if (device.paired) {
            actionDiv.innerHTML = '<span style="color:green;">已配对</span>';
        } else {
            actionDiv.innerHTML = `<button class="pair-device-btn" data-id="${device.device_id}">配对</button>`;
        }
        li.appendChild(actionDiv);
        container.appendChild(li);
    });
    // 绑定配对按钮事件
    document.querySelectorAll('.pair-device-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const deviceId = btn.getAttribute('data-id');
            pairDevice(deviceId, btn);
        });
    });
}

function pairDevice(deviceId, btnElement) {
    if (!btnElement) {
        console.error('[移动端] pairDevice: 缺少按钮元素');
        return;
    }
    if (!window.Android) return;

    const actionDiv = btnElement.closest('.device-action');
    if (!actionDiv) return;

    // 保存原始 HTML 以便恢复
    const originalHtml = actionDiv.innerHTML;

    // 显示加载动画
    actionDiv.innerHTML = '<div class="loading-spinner" style="width:20px;height:20px;border:2px solid #ccc;border-top-color:#333;border-radius:50%;animation:spin 0.8s linear infinite;"></div>';
    if (!document.querySelector('#spinner-style')) {
        const style = document.createElement('style');
        style.id = 'spinner-style';
        style.textContent = '@keyframes spin { to { transform: rotate(360deg); } }';
        document.head.appendChild(style);
    }

    // 设置超时定时器（10秒）
    if (window.activePairTimeouts[deviceId]) clearTimeout(window.activePairTimeouts[deviceId]);
    window.activePairTimeouts[deviceId] = setTimeout(() => {
        if (actionDiv && actionDiv.parentNode) {
            actionDiv.innerHTML = originalHtml;
            const newBtn = actionDiv.querySelector('.pair-device-btn');
            if (newBtn) {
                newBtn.addEventListener('click', (e) => {
                    pairDevice(deviceId, newBtn);
                });
            }
        }
        alert(`与设备 ${deviceId.substring(0,8)} 配对超时（10秒未响应）`);
        delete window.activePairTimeouts[deviceId];
    }, 10000);

    // 发送配对请求
    Android.pairDevice(deviceId);
    console.log('[移动端] 配对请求已发送');
}

// 加载已配对设备信息并自动填入 PC 地址
function loadPairedDeviceInfo() {
    if (!window.Android) return;
    const pairedJson = Android.getPairedDevice();
    const container = document.getElementById('paired-info');
    if (!container) return;
    if (pairedJson && pairedJson !== 'null' && pairedJson !== '') {
        try {
            const paired = JSON.parse(pairedJson);
            const normalized = {
                device_id: paired.deviceId,
                device_name: paired.deviceName,
                ip: paired.ip,
                port: paired.port,
                paired: paired.paired
            };
            const pairedMap = {};
            pairedMap[normalized.device_id] = normalized;
            renderPairedDevices(pairedMap);

            // 在 loadPairedDeviceInfo 中
            const baseUrl = `http://${paired.ip}:${paired.port}`;
            // ========== 自动存储协同配置并同步 UI ==========
            localStorage.setItem('pcAddress', baseUrl);
            localStorage.setItem('pcAccelerateEnabled', 'true');

            // 更新 UI 元素（开关和地址输入框）
            const toggle = document.getElementById('pc-accelerate-toggle');
            const addressInput = document.getElementById('pc-address');
            if (toggle) {
                toggle.checked = true;
            }
            if (addressInput) {
                addressInput.value = baseUrl;
                addressInput.readOnly = true;
                addressInput.style.background = 'var(--bg-secondary)';
            }
            // 显示地址输入项（因为开关为 true）
            const addrItem = document.getElementById('pc-address-item');
            if (addrItem) addrItem.style.display = 'flex';

            if (window.coopManager) {
                window.coopManager.loadConfig();
                console.log('[协同] 已自动启用代理，地址:', baseUrl);
            }
            // ============================================
            // 通知后端创建同步管理器
            fetch('/sync/set_pc_address', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ address: baseUrl })
            }).catch(e => console.warn('[移动端] 自动设置PC地址失败', e));
            // 启动前端同步管理器
            startSyncManager(paired.ip, paired.port);
        } catch(e) {
            console.error('[移动端] 解析配对信息失败', e, pairedJson);
            container.innerHTML = '<div>解析配对信息失败</div>';
        }
    } else {
        container.innerHTML = '<div>暂无配对设备</div>';
        // 如果没有配对设备，清除协同配置
        localStorage.removeItem('pcAddress');
        localStorage.setItem('pcAccelerateEnabled', 'false');
        if (window.coopManager) window.coopManager.loadConfig();
    }
}

function startSyncManager(ip, port) {
    if (window.syncManager) {
        window.syncManager.stop();
    }
    const baseUrl = `http://${ip}:${port}`;
    window.syncManager = new SyncManager(baseUrl);
    window.syncManager.start().catch(e => console.error('同步管理器启动失败', e));
    // 立即拉取全量消息（可选）
    setTimeout(() => {
        if (window.syncManager) window.syncManager.pullAllMessages().catch(e => console.warn('拉取全量消息失败', e));
    }, 2000);
}

// 应用已配对设备（手动触发）
function usePairedDevice(ip, port) {
    const addr = `http://${ip}:${port}`;
    const pcAddrInput = document.getElementById('pc-address');
    if (pcAddrInput) pcAddrInput.value = addr;
    localStorage.setItem('pcAddress', addr);
    localStorage.setItem('pcAccelerateEnabled', 'true');   // 关键：启用协同加速
    console.log(`[移动端] 已设置 PC 地址: ${addr} 并启用加速`);
    const toggle = document.getElementById('pc-accelerate-toggle');
    if (toggle && !toggle.checked) toggle.checked = true;
    if (window.coopManager) window.coopManager.loadConfig();
}

// 处理配对被拒绝的回调
window.onPairRejected = function(peerId) {
    alert('设备 ' + peerId + ' 拒绝了您的配对请求');
    // 找到该设备对应的操作容器并恢复按钮
    const actionDiv = document.querySelector(`.device-action .pair-device-btn[data-id="${peerId}"]`)?.closest('.device-action');
    if (actionDiv) {
        actionDiv.innerHTML = `<button class="pair-device-btn" data-id="${peerId}">配对</button>`;
        const newBtn = actionDiv.querySelector('.pair-device-btn');
        if (newBtn) {
            newBtn.addEventListener('click', (e) => pairDevice(peerId, newBtn));
        }
    }
    // 清除超时
    if (window.activePairTimeouts[peerId]) {
        clearTimeout(window.activePairTimeouts[peerId]);
        delete window.activePairTimeouts[peerId];
    }
    // 刷新设备列表以同步状态
    if (window.Android) {
        const devicesJson = Android.getDiscoveredDevices();
        if (devicesJson) window.onDeviceListUpdate(devicesJson);
        loadPairedDeviceInfo();
    }
};

function stopPendingRequestPolling() {
    if (pendingPollingInterval) {
        clearInterval(pendingPollingInterval);
        pendingPollingInterval = null;
    }
}


// ========== 42.2. 互通倒计时确认弹窗 ==========
let mobilePendingPeerId = null;
let mobileCountdownInterval = null;

// 关闭弹窗并清理资源
function closeMobileDialog() {
    if (mobileCountdownInterval) {
        clearInterval(mobileCountdownInterval);
        mobileCountdownInterval = null;
    }
    const modal = document.getElementById('pairConfirmModal');
    if (modal) modal.style.display = 'none';
    mobilePendingPeerId = null;
}

function showPairConfirmDialogMobile(peerId, peerName, ip) {
    // 如果已经有弹窗且正在显示，不再重复打开
    if (mobilePendingPeerId !== null) {
        console.log('[移动端] 已有弹窗存在，忽略新请求');
        return;
    }
    // 关闭可能遗留的弹窗（保险）
    closeMobileDialog();
    mobilePendingPeerId = peerId;

    const modal = document.getElementById('pairConfirmModal');
    const msgPara = document.getElementById('pairConfirmMsg');
    const countdownSpan = document.getElementById('countdownSec');
    if (!modal || !msgPara || !countdownSpan) {
        console.error('[移动端] 模态框元素缺失');
        return;
    }

    msgPara.innerText = `设备 ${peerName} (${ip}) 请求与您配对`;
    countdownSpan.innerText = '8';
    modal.style.display = 'flex';

    // 倒计时（8秒）
    let secondsLeft = 8;
    if (mobileCountdownInterval) clearInterval(mobileCountdownInterval);
    mobileCountdownInterval = setInterval(() => {
        secondsLeft--;
        if (secondsLeft <= 0) {
            clearInterval(mobileCountdownInterval);
            mobileCountdownInterval = null;
            // 自动拒绝
            if (mobilePendingPeerId) {
                Android.confirmPair(mobilePendingPeerId, false);
                closeMobileDialog();  // 关闭弹窗并清理标记
            }
        } else {
            const span = document.getElementById('countdownSec');
            if (span) span.innerText = secondsLeft.toString();
        }
    }, 1000);

    // 绑定按钮事件
    const acceptBtn = document.getElementById('pairAcceptBtn');
    const rejectBtn = document.getElementById('pairRejectBtn');
    if (!acceptBtn || !rejectBtn) return;

    const newAccept = acceptBtn.cloneNode(true);
    const newReject = rejectBtn.cloneNode(true);
    acceptBtn.parentNode.replaceChild(newAccept, acceptBtn);
    rejectBtn.parentNode.replaceChild(newReject, rejectBtn);

    // 在 newAccept 的 click 事件中增加清除标记
    newAccept.addEventListener('click', () => {
        if (mobilePendingPeerId) {
            Android.confirmPair(mobilePendingPeerId, true);
            // 清除已处理标记，避免残留
            if (window._processedPending) delete window._processedPending[mobilePendingPeerId];
            closeMobileDialog();
            setTimeout(() => {
                const devicesJson = Android.getDiscoveredDevices();
                if (devicesJson) window.onDeviceListUpdate(devicesJson);
                loadPairedDeviceInfo();
            }, 200);
        }
    });
    // 在 newReject 的 click 事件中同样清除
    newReject.addEventListener('click', () => {
        if (mobilePendingPeerId) {
            Android.confirmPair(mobilePendingPeerId, false);
            if (window._processedPending) delete window._processedPending[mobilePendingPeerId];
            closeMobileDialog();
        }
    });
}

// ========== 42.3. 互通设备健康状态检查&立即全量同步 ==========
// 配对成功后的处理
window.onPairConfirmed = function(deviceId, deviceName, ip, port) {
    const baseUrl = `http://${ip}:${port}`;
    // ========== 新增：自动存储协同配置 ==========
    localStorage.setItem('pcAddress', baseUrl);
    localStorage.setItem('pcAccelerateEnabled', 'true');
    if (window.coopManager) {
        window.coopManager.loadConfig();
        console.log('[协同] 配对后自动启用代理，地址:', baseUrl);
    }
    // ============================================
    if (confirm(`已与设备 ${deviceName} 配对成功，是否立即同步记忆数据？同步后双端记忆将保持一致。`)) {
        startFullSync(ip, port, deviceId);
    } else {
        startSyncManager(ip, port);
    }
    // 启动持续同步管理器
    startSyncManager(ip, port);
    // 刷新已配对设备列表
    if (window.Android) {
        const devicesJson = Android.getDiscoveredDevices();
        if (devicesJson) window.onDeviceListUpdate(devicesJson);
        loadPairedDeviceInfo();
    }
};

// 手动全量同步（移动端发起）
async function startFullSync(ip, port, deviceId) {
    const baseUrl = `http://${ip}:${port}`;

    // 1. 通知后端创建/更新同步管理器
    try {
        const resp = await fetch('/sync/set_pc_address', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ address: baseUrl })
        });
        if (!resp.ok) {
            console.warn('设置 PC 地址失败', resp.status);
        } else {
            console.log('[同步] 后端同步管理器已就绪');
        }
    } catch (e) {
        console.warn('设置 PC 地址异常', e);
    }

    // 2. 后续原有逻辑：重置版本号、执行全量同步等
    const btn = document.getElementById('manual-sync-btn');
    if (btn) btn.disabled = true;
    try {
        if (!window.syncManager) {
            window.syncManager = new SyncManager(baseUrl);
        } else {
            window.syncManager.updateBaseUrl(baseUrl);
        }
        if (!window.syncManager.enabled) {
            window.syncManager.enabled = true;
        }
        const units = ['mid_memories', 'long_memories', 'topics', 'events'];
        for (const unit of units) {
            window.syncManager.versionMgr.set(unit, 0);
        }
        await window.syncManager.fullSync();
        // 拉取所有消息
        if (window.syncManager) {
            await window.syncManager.pullAllMessages();
        }
        alert('同步完成');
        updateDeviceSyncProgress(deviceId, 1);
    } catch (e) {
        console.error('全量同步失败', e);
        alert('同步失败：' + e.message);
    } finally {
        if (btn) btn.disabled = false;
    }
}

// ========== 已配对设备列表渲染（支持多设备、健康检查、进度条预留） ==========
let healthCheckIntervals = {};   // 存储每个设备的健康检查定时器

function renderPairedDevices(pairedDevices) {
    const container = document.getElementById('paired-info');
    if (!container) return;
    const pairedList = Object.values(pairedDevices);
    if (!pairedList.length) {
        container.innerHTML = '<div>暂无配对设备</div>';
        return;
    }
    container.innerHTML = '';
    pairedList.forEach(device => {
        const card = createDeviceCard(device);
        container.appendChild(card);
        startHealthCheck(device.device_id, device.ip, device.port);
    });
}

function createDeviceCard(device) {
    const card = document.createElement('div');
    card.className = 'paired-device-card';
    card.dataset.deviceId = device.device_id;
    // 进度条占位（上边缘细线）
    const progressBar = document.createElement('div');
    progressBar.className = 'sync-progress-bar';
    card.appendChild(progressBar);
    // 卡片主体
    const header = document.createElement('div');
    header.className = 'card-header';
    header.innerHTML = `
        <div class="device-info">
            <div><strong>${escapeHtml(device.device_name)}</strong></div>
            <div>IP: ${device.ip}</div>
            <div>端口: ${device.port || 8000}</div>
            <div>ID: ${device.device_id.substring(0, 12)}...</div>
            <button class="manual-sync-btn">立即同步</button>
        </div>
        <div class="device-health">
            <span class="sync-status-text">检测中</span>
            <span class="sync-status-dot status-checking"></span>
        </div>
    `;
    // 展开区域（用于显示同步单元状态）
    const expandDiv = document.createElement('div');
    expandDiv.className = 'card-expand';
    expandDiv.style.display = 'none';
    expandDiv.innerHTML = '<div class="sync-units-status">同步单元状态待实现</div>';
    // 点击卡片头部展开/折叠
    header.addEventListener('click', (e) => {
        if (e.target.classList.contains('manual-sync-btn')) return;
        expandDiv.style.display = expandDiv.style.display === 'none' ? 'block' : 'none';
    });
    // 手动同步按钮事件
    const syncBtn = header.querySelector('.manual-sync-btn');
    syncBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        startFullSync(device.ip, device.port, device.device_id);
    });
    card.appendChild(header);
    card.appendChild(expandDiv);
    return card;
}

async function startHealthCheck(deviceId, ip, port) {
    if (healthCheckIntervals[deviceId]) clearInterval(healthCheckIntervals[deviceId]);
    const check = async () => {
        const card = document.querySelector(`.paired-device-card[data-device-id="${deviceId}"]`);
        if (!card) {
            clearInterval(healthCheckIntervals[deviceId]);
            return;
        }
        const statusSpan = card.querySelector('.sync-status-text');
        const dotSpan = card.querySelector('.sync-status-dot');
        try {
            const controller = new AbortController();
            const timeoutId = setTimeout(() => controller.abort(), 2000);
            const res = await fetch(`http://${ip}:${port}/proxy/health`, { signal: controller.signal });
            clearTimeout(timeoutId);
            if (res.ok) {
                statusSpan.textContent = '可达';
                dotSpan.className = 'sync-status-dot status-ok';
            } else {
                statusSpan.textContent = '不可达';
                dotSpan.className = 'sync-status-dot status-error';
            }
        } catch (e) {
            statusSpan.textContent = '不可达';
            dotSpan.className = 'sync-status-dot status-error';
        }
    };
    check();
    healthCheckIntervals[deviceId] = setInterval(check, 15000);
}

function updateDeviceSyncProgress(deviceId, progress) {
    const card = document.querySelector(`.paired-device-card[data-device-id="${deviceId}"]`);
    if (!card) return;
    const bar = card.querySelector('.sync-progress-bar');
    // 简化：根据进度改变背景色（后续可替换为动画）
    if (progress >= 1) {
        bar.style.backgroundColor = 'green';
    } else if (progress > 0) {
        bar.style.backgroundColor = 'orange';
    } else {
        bar.style.backgroundColor = 'red';
    }
    // TODO: 实现绿线从中间向两侧扩展的动画，进度与实际同步单元数量绑定
}

// ========== 42.4. PC 协同 ==========
function escapeHtml(str) {
    if (!str) return '';
    return str.replace(/[&<>]/g, function(m) {
        if (m === '&') return '&amp;';
        if (m === '<') return '&lt;';
        if (m === '>') return '&gt;';
        return m;
    });
}

function saveMessagesToLocalStorage() {
    try {
        // 只保留最近一定数量的消息，避免存储过大（例如每个会话最近200条）
        const toStore = {};
        for (const [key, msgs] of Object.entries(messages)) {
            toStore[key] = msgs.slice(-200); // 保留最近200条
        }
        localStorage.setItem('chatMessages', JSON.stringify(toStore));
    } catch (e) {
        console.error('保存消息到本地失败', e);
    }
}

function loadMessagesFromLocalStorage() {
    try {
        const stored = localStorage.getItem('chatMessages');
        if (stored) {
            const loaded = JSON.parse(stored);
            for (const [key, msgs] of Object.entries(loaded)) {
                if (!messages[key]) messages[key] = [];
                // 合并，避免重复（简单合并，可根据需要去重）
                const existingIds = new Set(messages[key].map(m => m.dbId));
                const newMsgs = msgs.filter(m => !existingIds.has(m.dbId));
                messages[key].push(...newMsgs);
            }
            console.log('从本地加载消息成功');
        }
    } catch (e) {
        console.error('加载本地消息失败', e);
    }
}

// ========== 43. 扩展页 ==========
// ========== 43.0. 常用扩展卡片 ==========
const EXTENSION_FAVORITE_PREFERENCE_KEY = 'zoot-extension-favorites-v1';
const EXTENSION_FAVORITE_LONG_PRESS_MS = 600;
const EXTENSION_FAVORITE_MOVE_TOLERANCE = 8;
const EXTENSION_FAVORITE_CATALOG = Object.freeze({
    'zoot-dynamics': { title: 'ZOOT!动态', background: 'backgrounds/profile_cardbanner_fold.webp' },
    'rhodes-island': { title: '罗德岛本舰', background: 'images/cg_locked.png' },
    'terra-journey': { title: '泰拉寻旅', background: 'backgrounds/Avg_bg_bg_fogwoods.png' },
    'u-official': { title: 'u-official直播间', background: 'backgrounds/default_banner.webp' },
    'terra-journey-rules': { title: 'Ark-TRPG', background: 'backgrounds/rogue_two_dice_replacement.png' },
    'doctor-ai': { title: 'AI 博士', background: 'backgrounds/operator_priestess.webp' },
    'rhodes-finance': { title: '财务部', background: 'backgrounds/default_banner.webp' },
    'procurement': { title: '采购部', background: 'backgrounds/operator_closure.webp' },
    'ops-department': { title: '外勤部', background: 'backgrounds/banner_9.webp' },
    'warehouse': { title: '仓储', background: 'backgrounds/Avg_bg_68_g8_gordoncollection.png' },
    'zoot-plugins': { title: 'ZOOT!插件扩展', background: 'images/default_graph.png' }
});
const extensionFavoriteState = {
    favorites: [null, null],
    targetSlot: null,
    longPressTimer: 0,
    suppressResetTimer: 0,
    pointerStart: null,
    suppressClick: false,
    initialized: false
};

function normalizeExtensionFavorites(value) {
    let source = value;
    if (typeof source === 'string') {
        try {
            source = JSON.parse(source);
        } catch (_) {
            source = [];
        }
    }
    const normalized = [null, null];
    const used = new Set();
    if (!Array.isArray(source)) return normalized;
    for (let index = 0; index < normalized.length; index += 1) {
        const pageId = typeof source[index] === 'string' ? source[index] : null;
        if (pageId && EXTENSION_FAVORITE_CATALOG[pageId] && !used.has(pageId)) {
            normalized[index] = pageId;
            used.add(pageId);
        }
    }
    return normalized;
}

function loadExtensionFavorites() {
    extensionFavoriteState.favorites = normalizeExtensionFavorites(
        localStorage.getItem(EXTENSION_FAVORITE_PREFERENCE_KEY)
    );
}

function persistExtensionFavorites() {
    const serialized = JSON.stringify(extensionFavoriteState.favorites);
    try {
        if (window.ZootDevicePreferences?.set) {
            window.ZootDevicePreferences.set(EXTENSION_FAVORITE_PREFERENCE_KEY, serialized);
        } else {
            localStorage.setItem(EXTENSION_FAVORITE_PREFERENCE_KEY, serialized);
        }
    } catch (error) {
        console.debug('常用扩展暂时仅在当前页面生效', error);
    }
}

function cssUrl(value) {
    return `url(${JSON.stringify(String(value))})`;
}

function resolveExtensionFavoriteBackground(pageId) {
    const item = EXTENSION_FAVORITE_CATALOG[pageId];
    if (!item) return 'none';
    if (pageId === 'zoot-dynamics') {
        const layerBackground = document.getElementById('dynamics-bg-layer')?.style.backgroundImage;
        if (layerBackground && layerBackground !== 'none') return layerBackground;
        try {
            const savedBackground = localStorage.getItem(getDynamicsBackgroundKey());
            if (savedBackground) return cssUrl(savedBackground);
        } catch (_) {
            // 使用随包默认背景。
        }
    }
    return cssUrl(`/static/${item.background}`);
}

function renderExtensionFavorites() {
    document.querySelectorAll('#page-moments .extension-favorite-card').forEach(card => {
        const slot = Number(card.dataset.favoriteSlot);
        const pageId = extensionFavoriteState.favorites[slot];
        const item = EXTENSION_FAVORITE_CATALOG[pageId];
        card.dataset.page = pageId || '';
        card.classList.toggle('is-empty', !item);
        card.style.setProperty('--extension-favorite-bg', item ? resolveExtensionFavoriteBackground(pageId) : 'none');
        card.setAttribute('aria-describedby', 'extension-favorite-hint');
        card.setAttribute(
            'aria-label',
            item
                ? `打开${item.title}，长按或按 F2 更换`
                : `设置第${slot + 1}个常用功能`
        );
        card.innerHTML = item
            ? `<span class="extension-favorite-title">${escapeHtml(item.title)}</span>`
            : `${ZootIcons.html('plus', 'extension-favorite-empty-icon')}<span class="extension-favorite-title">设置常用功能</span>`;
    });
}

function cancelExtensionFavoriteLongPress() {
    if (extensionFavoriteState.longPressTimer) {
        clearTimeout(extensionFavoriteState.longPressTimer);
        extensionFavoriteState.longPressTimer = 0;
    }
    extensionFavoriteState.pointerStart = null;
}

function isExtensionFavoriteSelectionActive() {
    return extensionFavoriteState.targetSlot !== null;
}

function enterExtensionFavoriteSelection(slot) {
    const safeSlot = Number(slot);
    if (safeSlot !== 0 && safeSlot !== 1) return;
    cancelExtensionFavoriteLongPress();
    extensionFavoriteState.targetSlot = safeSlot;
    const page = document.getElementById('page-moments');
    page?.classList.add('extension-selection-mode');
    page?.querySelectorAll('.extension-item').forEach(item => {
        item.style.display = 'flex';
        item.setAttribute('tabindex', '0');
        item.setAttribute('role', 'button');
    });
    page?.querySelector('.no-result')?.remove();
    const announcement = document.getElementById('extension-selection-announcement');
    if (announcement) announcement.textContent = `正在为第${safeSlot + 1}个卡片选择常用功能`;
    requestAnimationFrame(() => document.getElementById('extension-selection-close')?.focus());
}

function exitExtensionFavoriteSelection(options = {}) {
    if (!isExtensionFavoriteSelectionActive()) return false;
    const previousSlot = extensionFavoriteState.targetSlot;
    extensionFavoriteState.targetSlot = null;
    const page = document.getElementById('page-moments');
    page?.classList.remove('extension-selection-mode');
    page?.querySelectorAll('.extension-item').forEach(item => {
        item.removeAttribute('tabindex');
        item.removeAttribute('role');
    });
    const announcement = document.getElementById('extension-selection-announcement');
    if (announcement) announcement.textContent = '';
    document.getElementById('extension-search')?.dispatchEvent(new Event('input'));
    if (options.restoreFocus !== false) {
        requestAnimationFrame(() => {
            page?.querySelector(`.extension-favorite-card[data-favorite-slot="${previousSlot}"]`)?.focus();
        });
    }
    return true;
}

function selectExtensionFavorite(pageId) {
    if (!isExtensionFavoriteSelectionActive() || !EXTENSION_FAVORITE_CATALOG[pageId]) return;
    const targetSlot = extensionFavoriteState.targetSlot;
    const previousPage = extensionFavoriteState.favorites[targetSlot];
    const otherSlot = extensionFavoriteState.favorites.findIndex((value, index) => value === pageId && index !== targetSlot);
    extensionFavoriteState.favorites[targetSlot] = pageId;
    if (otherSlot >= 0) {
        extensionFavoriteState.favorites[otherSlot] = previousPage && previousPage !== pageId ? previousPage : null;
    }
    persistExtensionFavorites();
    renderExtensionFavorites();
    exitExtensionFavoriteSelection();
}

function bindExtensionFavoriteCard(card) {
    card.addEventListener('click', event => {
        if (extensionFavoriteState.suppressClick) {
            clearTimeout(extensionFavoriteState.suppressResetTimer);
            extensionFavoriteState.suppressClick = false;
            event.preventDefault();
            return;
        }
        const slot = Number(card.dataset.favoriteSlot);
        const pageId = extensionFavoriteState.favorites[slot];
        if (pageId) showPage(pageId);
        else enterExtensionFavoriteSelection(slot);
    });
    card.addEventListener('keydown', event => {
        if (event.key === 'F2' || (event.key === 'Enter' && event.shiftKey)) {
            event.preventDefault();
            enterExtensionFavoriteSelection(Number(card.dataset.favoriteSlot));
        }
    });
    card.addEventListener('pointerdown', event => {
        if (event.button !== undefined && event.button !== 0) return;
        cancelExtensionFavoriteLongPress();
        extensionFavoriteState.pointerStart = { x: event.clientX, y: event.clientY };
        extensionFavoriteState.longPressTimer = setTimeout(() => {
            extensionFavoriteState.longPressTimer = 0;
            extensionFavoriteState.suppressClick = true;
            clearTimeout(extensionFavoriteState.suppressResetTimer);
            extensionFavoriteState.suppressResetTimer = setTimeout(() => {
                extensionFavoriteState.suppressClick = false;
            }, 1200);
            enterExtensionFavoriteSelection(Number(card.dataset.favoriteSlot));
        }, EXTENSION_FAVORITE_LONG_PRESS_MS);
    });
    card.addEventListener('pointermove', event => {
        const start = extensionFavoriteState.pointerStart;
        if (!start) return;
        if (Math.hypot(event.clientX - start.x, event.clientY - start.y) > EXTENSION_FAVORITE_MOVE_TOLERANCE) {
            cancelExtensionFavoriteLongPress();
        }
    });
    card.addEventListener('pointerup', () => {
        cancelExtensionFavoriteLongPress();
        if (extensionFavoriteState.suppressClick) {
            setTimeout(() => {
                extensionFavoriteState.suppressClick = false;
            }, 0);
        }
    });
    card.addEventListener('pointercancel', () => {
        cancelExtensionFavoriteLongPress();
    });
    card.addEventListener('pointerleave', () => {
        cancelExtensionFavoriteLongPress();
    });
    card.addEventListener('contextmenu', event => {
        if (extensionFavoriteState.suppressClick) event.preventDefault();
    });
}

function initExtensionFavorites() {
    if (extensionFavoriteState.initialized) return;
    const page = document.getElementById('page-moments');
    if (!page) return;
    extensionFavoriteState.initialized = true;
    loadExtensionFavorites();
    page.querySelectorAll('.extension-favorite-card').forEach(bindExtensionFavoriteCard);
    document.getElementById('extension-selection-close')?.addEventListener('click', () => {
        exitExtensionFavoriteSelection();
    });
    page.addEventListener('keydown', event => {
        const item = event.target.closest?.('.extension-item');
        if (!item || !isExtensionFavoriteSelectionActive()) return;
        if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            selectExtensionFavorite(item.dataset.page);
        }
    });
    page.querySelector('.extension-list')?.addEventListener('scroll', cancelExtensionFavoriteLongPress, { passive: true });
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') exitExtensionFavoriteSelection({ restoreFocus: false });
    });
    document.addEventListener('pageShown', event => {
        if (String(event.detail?.pageId || '').split('?')[0] === 'moments') renderExtensionFavorites();
    });
    window.addEventListener('zoot:device-preferences-ready', () => {
        loadExtensionFavorites();
        renderExtensionFavorites();
    });
    renderExtensionFavorites();
}

// ========== 43.0. 扩展页搜索过滤 ==========
function initExtensionSearch() {
    const searchInput = document.getElementById('extension-search');
    const clearBtn = document.getElementById('clear-extension-search');
    if (!searchInput) return;

    const filterItems = () => {
        const keyword = searchInput.value.trim().toLowerCase();
        const items = document.querySelectorAll('#page-moments .extension-item');
        let hasVisible = false;
        items.forEach(item => {
            const title = item.querySelector('.extension-title')?.innerText.toLowerCase() || '';
            if (keyword === '' || title.includes(keyword)) {
                item.style.display = 'flex';
                hasVisible = true;
            } else {
                item.style.display = 'none';
            }
        });
        if (clearBtn) clearBtn.style.display = keyword ? 'flex' : 'none';
        const container = document.querySelector('#page-moments .extension-list');
        let noResult = container.querySelector('.no-result');
        if (!hasVisible && keyword) {
            if (!noResult) {
                noResult = document.createElement('div');
                noResult.className = 'no-result';
                noResult.textContent = '未找到相关扩展';
                noResult.style.padding = '20px';
                noResult.style.textAlign = 'center';
                noResult.style.color = 'var(--text-secondary)';
                container.appendChild(noResult);
            }
        } else if (noResult) noResult.remove();
    };

    searchInput.addEventListener('input', filterItems);
    if (clearBtn) {
        clearBtn.addEventListener('click', () => {
            searchInput.value = '';
            filterItems();
            searchInput.focus();
        });
    }
}

// ========== 43.1 通用底部半页框控制 ==========
const normalizedBottomSheets = new WeakSet();
const bottomSheetObservers = new WeakMap();
let bottomSheetReturnFocus = null;

function observeBottomSheetState(sheet) {
    if (!sheet || bottomSheetObservers.has(sheet)) return;
    const observer = new MutationObserver(records => {
        if (records.some(record => record.attributeName === 'class')) {
            const isOpen = !sheet.classList.contains('hidden');
            if (isOpen && !sheet.classList.contains('show')) {
                sheet.classList.add('show');
            } else if (!isOpen && sheet.classList.contains('show')) {
                sheet.classList.remove('show');
            }
            if (isOpen && !document.body.classList.contains('sheet-open')) {
                bottomSheetReturnFocus = document.activeElement instanceof HTMLElement
                    ? document.activeElement
                    : null;
                if (bottomSheetReturnFocus && !sheet.contains(bottomSheetReturnFocus)) {
                    bottomSheetReturnFocus.blur();
                }
            }
            syncBottomSheetOpenState();
            requestAnimationFrame(updateSheetViewportHeight);
        }
    });
    observer.observe(sheet, {
        attributes: true,
        attributeFilter: ['class']
    });
    bottomSheetObservers.set(sheet, observer);
}

function releaseBottomSheetState(sheet) {
    const observer = bottomSheetObservers.get(sheet);
    if (observer) observer.disconnect();
    bottomSheetObservers.delete(sheet);
    normalizedBottomSheets.delete(sheet);
}

function normalizeBottomSheet(sheet) {
    if (!sheet || !sheet.classList?.contains('bottom-sheet')) return sheet;
    if (sheet.classList.contains('app-modal-overlay') || sheet.parentElement?.classList?.contains('app-modal-overlay')) return sheet;
    if (normalizedBottomSheets.has(sheet)) return sheet;
    normalizedBottomSheets.add(sheet);
    sheet.classList.add('sheet-layer');
    const backdrop = sheet.querySelector(':scope > .bottom-sheet-overlay');
    const panel = sheet.querySelector(':scope > .bottom-sheet-content');
    backdrop?.classList.add('sheet-backdrop');
    panel?.classList.add('sheet-panel');
    panel?.querySelector('.bottom-sheet-header')?.classList.add('sheet-header');
    panel?.querySelector('.bottom-sheet-body')?.classList.add('sheet-body');
    panel?.querySelector('.bottom-sheet-footer')?.classList.add('sheet-footer');
    if (backdrop && !backdrop.dataset.sheetBackdropBound) {
        backdrop.dataset.sheetBackdropBound = 'true';
        backdrop.addEventListener('click', event => {
            if (event.target === backdrop && sheet.dataset.sheetDismissible !== 'false') {
                closeBottomSheet(sheet.id);
            }
        });
    }
    if (sheet.parentElement !== document.body) {
        document.body.appendChild(sheet);
    }
    observeBottomSheetState(sheet);
    return sheet;
}

function updateSheetViewportHeight() {
    const viewport = window.visualViewport;
    const viewportHeight = viewport?.height || window.innerHeight;
    const openSheets = Array.from(document.querySelectorAll('.sheet-layer:not(.hidden)'));
    const activeSheet = openSheets.at(-1) || null;
    const activeElement = document.activeElement;
    const editing = Boolean(
        activeSheet
        && activeElement instanceof Element
        && activeSheet.contains(activeElement)
        && activeElement.matches('input, textarea, select, [contenteditable="true"]')
    );
    const nativeState = window.ZootViewport?.getState?.() || {};
    const nativeImeBottom = nativeState.ime_visible ? Number(nativeState.ime_bottom || 0) : 0;
    const nativeWindowHeight = Number(nativeState.window_height_dp || 0);
    const viewportAlreadyResized = nativeImeBottom > 0
        && nativeWindowHeight > 0
        && viewportHeight <= nativeWindowHeight - nativeImeBottom + 24;
    const coveredBottom = viewport
        ? Math.max(0, window.innerHeight - viewport.height - viewport.offsetTop)
        : 0;
    const fallbackImeBottom = coveredBottom > 96 ? coveredBottom : 0;
    const keyboardOffset = editing
        ? (viewportAlreadyResized ? 0 : (nativeImeBottom || fallbackImeBottom))
        : 0;
    document.documentElement.style.setProperty('--sheet-viewport-height', `${window.innerHeight}px`);
    document.documentElement.style.setProperty('--sheet-visible-height', `${viewportHeight}px`);
    document.documentElement.style.setProperty('--sheet-keyboard-translate', `${-keyboardOffset}px`);
    document.body.classList.toggle('sheet-keyboard-open', keyboardOffset > 0);
}

function syncBottomSheetOpenState() {
    const hasOpenSheet = Boolean(document.querySelector('.sheet-layer:not(.hidden)'));
    const wasOpen = document.body.classList.contains('sheet-open');
    if (hasOpenSheet !== wasOpen) {
        document.body.classList.toggle('sheet-open', hasOpenSheet);
    }
    if (hasOpenSheet) {
        updateSheetViewportHeight();
    } else {
        document.documentElement.style.setProperty('--sheet-keyboard-translate', '0px');
        document.body.classList.remove('sheet-keyboard-open');
        if (bottomSheetReturnFocus?.isConnected) {
            bottomSheetReturnFocus.focus({ preventScroll: true });
        }
        bottomSheetReturnFocus = null;
    }
}

function closeAllBottomSheets({ restoreFocus = true } = {}) {
    if (!restoreFocus) bottomSheetReturnFocus = null;
    document.querySelectorAll('.sheet-layer:not(.hidden)').forEach(sheet => {
        sheet.classList.remove('show');
        sheet.classList.add('hidden');
    });
    syncBottomSheetOpenState();
}

function initBottomSheetSystem() {
    document.querySelectorAll('.bottom-sheet').forEach(normalizeBottomSheet);
    updateSheetViewportHeight();
    if (window.visualViewport && !window.visualViewport._zootSheetBound) {
        window.visualViewport._zootSheetBound = true;
        window.visualViewport.addEventListener('resize', updateSheetViewportHeight);
        window.visualViewport.addEventListener('scroll', updateSheetViewportHeight);
    }
    if (!window._zootSheetObserver) {
        window._zootSheetObserver = new MutationObserver(records => {
            records.forEach(record => {
                record.addedNodes.forEach(node => {
                    if (!(node instanceof Element)) return;
                    if (node.matches('.bottom-sheet')) normalizeBottomSheet(node);
                    node.querySelectorAll?.('.bottom-sheet').forEach(normalizeBottomSheet);
                });
                record.removedNodes.forEach(node => {
                    if (!(node instanceof Element)) return;
                    if (node.isConnected) return;
                    if (node.matches('.sheet-layer')) releaseBottomSheetState(node);
                    node.querySelectorAll?.('.sheet-layer').forEach(releaseBottomSheetState);
                });
            });
            syncBottomSheetOpenState();
        });
        window._zootSheetObserver.observe(document.body, {
            childList: true,
            subtree: true
        });
    }
    if (!window._zootSheetFocusBound) {
        window._zootSheetFocusBound = true;
        document.addEventListener('focusin', updateSheetViewportHeight, { passive: true });
        document.addEventListener('focusout', () => requestAnimationFrame(updateSheetViewportHeight), { passive: true });
        document.addEventListener('pageShown', () => closeAllBottomSheets({ restoreFocus: false }));
    }
    syncBottomSheetOpenState();
}

function openBottomSheet(sheetId) {
    const sheet = normalizeBottomSheet(document.getElementById(sheetId));
    if (sheet) {
        if (!document.querySelector('.sheet-layer:not(.hidden)')) {
            bottomSheetReturnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
        }
        const activeElement = document.activeElement;
        if (activeElement instanceof HTMLElement && !sheet.contains(activeElement)) {
            activeElement.blur();
        }
        document.documentElement.style.setProperty('--sheet-keyboard-translate', '0px');
        document.body.classList.remove('sheet-keyboard-open');
        sheet.classList.remove('hidden');
        sheet.classList.add('show');
        syncBottomSheetOpenState();
        requestAnimationFrame(updateSheetViewportHeight);
    }
}

function closeBottomSheet(sheetId) {
    const sheet = normalizeBottomSheet(document.getElementById(sheetId));
    if (sheet) {
        sheet.classList.remove('show');
        sheet.classList.add('hidden');
        syncBottomSheetOpenState();
    }
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initBottomSheetSystem, { once: true });
} else {
    initBottomSheetSystem();
}

// 动态页专用关闭函数
function closePostDynamicSheet() {
    closeBottomSheet('post-dynamic-bottom-sheet');
}
function closeCommentSheet() {
    closeBottomSheet('comment-bottom-sheet');
}

// 罗德岛本舰专用关闭函数
function closeLocationSheet() {
    closeBottomSheet('location-bottom-sheet');
}
function closeCharactersSheet() {
    closeBottomSheet('characters-bottom-sheet');
}
function closeChatSheet() {
    closeBottomSheet('chat-bottom-sheet');
}

// ========== 43.2. ZOOT!动态页 ==========
let currentDynamicId = null;          // 当前操作的动态ID（用于评论）
let currentReplyToCommentId = null;   // 当前正在回复的评论ID

// ---------- API 调用函数 ----------
async function fetchDynamics(limit = 20, before = null) {
    let url = `/dynamics?limit=${limit}`;
    if (before) url += `&before=${before}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error(`获取动态失败: ${res.status}`);
    return await res.json();
}

async function postDynamic(content, images = [], location = '') {
    const res = await fetch('/dynamics', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            operator_id: window.currentPersonaId || currentPersonaId || 'doctor',
            content: content,
            images: images,
            location: location
        })
    });
    if (!res.ok) throw new Error(`发布动态失败: ${res.status}`);
    return await res.json();
}

async function likeDynamic(dynamicId) {
    const res = await fetch(`/dynamics/${dynamicId}/like`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ operator_id: window.currentPersonaId || currentPersonaId || 'doctor' })
    });
    if (!res.ok) throw new Error(`点赞失败: ${res.status}`);
    const data = await res.json();
    return data.likes;  // 返回最新点赞数
}

async function deleteDynamic(dynamicId) {
    const res = await fetch(`/dynamics/${dynamicId}`, { method: 'DELETE' });
    if (!res.ok) throw new Error(`删除动态失败: ${res.status}`);
}

async function postComment(dynamicId, content, replyTo = null) {
    const res = await fetch(`/dynamics/${dynamicId}/comments`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            operator_id: window.currentPersonaId || currentPersonaId || 'doctor',
            content: content,
            reply_to_comment_id: replyTo
        })
    });
    if (!res.ok) throw new Error(`评论失败: ${res.status}`);
    return await res.json();
}

// 辅助：将后端动态数据转换为前端渲染格式
function transformDynamic(dynamic) {
    const actor = getDynamicsActorMeta(dynamic.operator_id);
    const author = {
        id: dynamic.operator_id,
        persona_id: dynamic.persona_id || dynamic.operator_id,
        name: actor.name,
        avatar: actor.avatar
    };
    return {
        id: String(dynamic.id),
        author: author,
        content: dynamic.content,
        images: dynamic.images || [],
        time: dynamic.created_at * 1000,
        likes: dynamic.likes,
        comment_count: dynamic.comment_count,
        comments: [],
        location: dynamic.location || ''
    };
}

function getCurrentDynamicsIdentityId() {
    const selectedId = window.currentPersonaId || currentPersonaId || 'doctor';
    const persona = personaList.find(item => item.persona_id === selectedId);
    const profile = persona?.profile_json || {};
    return profile.persona_type === 'cloned' && profile.source_operator_id
        ? profile.source_operator_id : selectedId;
}

function getDynamicsActorMeta(identityId) {
    const persona = personaList.find(item => item.persona_id === identityId);
    if (persona) {
        return {
            name: persona.profile_json?.doctor_name || persona.display_name || identityId,
            avatar: getPersonaAvatarUrl(identityId)
        };
    }
    if (identityId === 'doctor') return {name: '博士', avatar: getPersonaAvatarUrl('doctor')};
    return {name: operatorMap.get(identityId)?.codename || identityId, avatar: getOperatorAvatarUrl(identityId)};
}

// 构建评论树：将平铺的评论数组转为树形结构
function buildCommentTree(comments) {
    const map = new Map();
    const roots = [];

    // 先建立 id -> comment 映射，并初始化 children 数组
    comments.forEach(comment => {
        map.set(comment.id, { ...comment, children: [] });
    });

    comments.forEach(comment => {
        const node = map.get(comment.id);
        if (comment.reply_to_comment_id && map.has(comment.reply_to_comment_id)) {
            map.get(comment.reply_to_comment_id).children.push(node);
        } else {
            roots.push(node);
        }
    });

    // 根评论按时间正序（最旧在上，最新在下）
    roots.sort((a, b) => a.created_at - b.created_at);
    // 递归排序子评论
    const sortChildren = (node) => {
        node.children.sort((a, b) => a.created_at - b.created_at);
        node.children.forEach(sortChildren);
    };
    roots.forEach(sortChildren);
    return roots;
}

// 递归渲染评论树
function renderCommentTree(comments, dynamicId) {
    let html = '';
    for (const comment of comments) {
        const commentAuthor = getDynamicsActorMeta(comment.operator_id);
        // 根据回复深度缩进（最多3级，每级20px）
        const indent = Math.min((comment.reply_depth || 1) - 1, 3);
        const marginLeft = indent * 20;
        const replyIndicator = comment.reply_to_comment_id ? '<span class="reply-indicator">回复</span>' : '';
        html += `
            <div class="comment-item${String(comment.operator_id) === 'priestess' ? ' priestess-related priestess-comment' : ''}" data-comment-id="${comment.id}" data-author-id="${comment.operator_id}"${String(comment.operator_id) === 'priestess' ? ' data-actor-id="priestess"' : ''} style="margin-left: ${marginLeft}px;">
                <img src="${commentAuthor.avatar}" class="comment-avatar" onerror="this.src='/static/avatars/default.webp'">
                <div class="comment-content">
                    <span class="comment-author">${escapeHtml(commentAuthor.name)}</span>
                    ${replyIndicator}
                    ${escapeHtml(comment.content)}
                    <span class="comment-time">${formatTimeAgo(comment.created_at * 1000)}</span>
                    <button class="comment-reply-btn" data-comment-id="${comment.id}">回复</button>
                </div>
            </div>
        `;
        if (comment.children && comment.children.length) {
            html += renderCommentTree(comment.children, dynamicId);
        }
    }
    return html;
}

// 加载评论（按需），支持超过15条时显示展开/折叠
async function loadComments(dynamicId, dynamicCard) {
    const commentsSection = dynamicCard.querySelector('.comments-section');
    if (commentsSection.dataset.loaded === 'true') return;
    try {
        const res = await fetch(`/dynamics/${dynamicId}`);
        if (!res.ok) throw new Error('加载评论失败');
        const data = await res.json();
        let allComments = data.comments || [];

        // 构建树形结构
        const rootComments = buildCommentTree(allComments);
        const MAX_VISIBLE = 15;
        const shouldTruncate = rootComments.length > MAX_VISIBLE;

        function renderCommentsWithTruncation(showAll = false) {
            const visibleRoots = showAll ? rootComments : rootComments.slice(0, MAX_VISIBLE);
            return renderCommentTree(visibleRoots, dynamicId);
        }

        let commentsHtml = renderCommentsWithTruncation(false);
        let expandButtonHtml = '';
        if (shouldTruncate) {
            expandButtonHtml = `<div class="comments-expand-btn" data-dynamic-id="${dynamicId}">展开更多 (${allComments.length - MAX_VISIBLE})</div>`;
        }

        const inputHtml = `
            <div class="comment-input-area">
                <img src="${getDynamicsActorMeta(getCurrentDynamicsIdentityId()).avatar}" class="comment-input-avatar" alt="当前人格">
                <div class="comment-input" data-id="${dynamicId}" data-placeholder="评论点什么...">评论点什么...</div>
            </div>
        `;

        commentsSection.innerHTML = commentsHtml + expandButtonHtml + inputHtml;
        commentsSection.dataset.loaded = 'true';
        commentsSection.dataset.expanded = 'false';

        // 绑定评论回复按钮事件
        commentsSection.querySelectorAll('.comment-reply-btn').forEach(btn => {
            btn.removeEventListener('click', commentReplyHandler);
            btn.addEventListener('click', commentReplyHandler);
        });
        commentsSection.querySelectorAll('.comment-input').forEach(input => {
            input.removeEventListener('click', commentInputHandler);
            input.addEventListener('click', commentInputHandler);
        });

        // 为每条评论的头像添加点击事件（跳转个人主页）
        commentsSection.querySelectorAll('.comment-item').forEach(commentItem => {
            const commentId = commentItem.dataset.commentId;
            const commentData = allComments.find(c => c.id == commentId);
            if (commentData && commentData.operator_id && !commentData.operator_id.includes('#') && !commentData.operator_id.startsWith('custom')) {
                const avatar = commentItem.querySelector('.comment-avatar');
                if (avatar) {
                    avatar.addEventListener('click', (e) => {
                        e.stopPropagation();
                        showOperatorDynamics(commentData.operator_id);
                    });
                }
            }
        });

        // 展开/折叠按钮事件
        const expandBtn = commentsSection.querySelector('.comments-expand-btn');
        if (expandBtn) {
            expandBtn.addEventListener('click', async (e) => {
                e.stopPropagation();
                const isExpanded = commentsSection.dataset.expanded === 'true';
                if (!isExpanded) {
                    const fullCommentsHtml = renderCommentsWithTruncation(true);
                    commentsSection.innerHTML = fullCommentsHtml + `<div class="comments-expand-btn" data-dynamic-id="${dynamicId}">收起</div>` + inputHtml;
                    commentsSection.dataset.expanded = 'true';
                } else {
                    const truncatedHtml = renderCommentsWithTruncation(false);
                    commentsSection.innerHTML = truncatedHtml + `<div class="comments-expand-btn" data-dynamic-id="${dynamicId}">展开更多 (${allComments.length - MAX_VISIBLE})</div>` + inputHtml;
                    commentsSection.dataset.expanded = 'false';
                }
                // 重新绑定事件
                commentsSection.querySelectorAll('.comment-reply-btn').forEach(btn => {
                    btn.removeEventListener('click', commentReplyHandler);
                    btn.addEventListener('click', commentReplyHandler);
                });
                commentsSection.querySelectorAll('.comment-input').forEach(input => {
                    input.removeEventListener('click', commentInputHandler);
                    input.addEventListener('click', commentInputHandler);
                });
                // 重新绑定头像点击
                commentsSection.querySelectorAll('.comment-item').forEach(commentItem => {
                    const commentId = commentItem.dataset.commentId;
                    const commentData = allComments.find(c => c.id == commentId);
                    if (commentData && commentData.operator_id && !commentData.operator_id.includes('#') && !commentData.operator_id.startsWith('custom')) {
                        const avatar = commentItem.querySelector('.comment-avatar');
                        if (avatar) {
                            avatar.addEventListener('click', (e) => {
                                e.stopPropagation();
                                showOperatorDynamics(commentData.operator_id);
                            });
                        }
                    }
                });
            });
        }
    } catch (e) {
        console.error('加载评论失败', e);
        commentsSection.innerHTML = '<div style="padding:8px; color:red;">评论加载失败</div>';
    }
}

// 回复某条评论的处理函数
function commentReplyHandler(e) {
    e.stopPropagation();
    const commentItem = e.currentTarget.closest('.comment-item');
    const commentId = commentItem.dataset.commentId;
    const dynamicId = commentItem.closest('.dynamic-card').dataset.id;
    const authorName = commentItem.querySelector('.comment-author').innerText;
    currentDynamicId = dynamicId;
    currentReplyToCommentId = commentId;
    const commentInput = document.getElementById('comment-content');
    if (commentInput) commentInput.placeholder = `回复 @${authorName}：`;
    openBottomSheet('comment-bottom-sheet');
}

function formatTimeAgo(timestamp) {
    if (!timestamp) return '';
    const seconds = Math.floor((Date.now() - timestamp) / 1000);
    if (seconds < 60) return '刚刚';
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes}分钟前`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours}小时前`;
    const days = Math.floor(hours / 24);
    if (days < 7) return `${days}天前`;
    return new Date(timestamp).toLocaleDateString();
}

async function refreshDynamics() {
    await renderDynamics();
}

// 渲染动态列表
async function renderDynamics() {
    const container = document.getElementById('dynamics-list');
    if (!container) return;
    container.innerHTML = '<div style="text-align:center; padding:40px;">加载中...</div>';
    try {
        const dynamicsData = await fetchDynamics(20);
        if (!dynamicsData || dynamicsData.length === 0) {
            container.innerHTML = '<div class="empty-state" style="text-align:center; padding:40px; color:var(--text-secondary);">暂无动态，快发布一条吧~</div>';
            return;
        }
        const dynamics = dynamicsData.map(d => transformDynamic(d));
        container.innerHTML = dynamics.map(dynamic => `
            <div class="dynamic-card${String(dynamic.author.id) === 'priestess' ? ' priestess-related priestess-dynamic-card' : ''}" data-id="${dynamic.id}" data-author-id="${dynamic.author.id}"${String(dynamic.author.id) === 'priestess' ? ' data-actor-id="priestess"' : ''}>
                <div class="dynamic-header">
                    <img src="${dynamic.author.avatar}" class="dynamic-avatar" onerror="this.src='/static/avatars/default.webp'">
                    <div class="dynamic-author-info">
                        <div class="dynamic-author-name">${escapeHtml(dynamic.author.name)}</div>
                        <div class="dynamic-time">${formatTimeAgo(dynamic.time)}</div>
                    </div>
                    ${dynamic.author.id === getCurrentDynamicsIdentityId() ? `<button class="dynamic-menu-btn" data-id="${dynamic.id}"><span data-zoot-icon="more"></span></button>` : ''}
                </div>
                <div class="dynamic-content">${escapeHtml(dynamic.content)}</div>
                ${dynamic.location ? `<div class="dynamic-location" style="font-size: 12px; color: var(--text-secondary); margin-top: 4px;">📍 ${escapeHtml(dynamic.location)}</div>` : ''}
                ${dynamic.images.length ? `<div class="dynamic-images">${dynamic.images.map(img => `<img src="${img}" loading="lazy">`).join('')}</div>` : ''}
                <div class="dynamic-footer">
                    <div class="likers-avatar-wall" style="display: flex; align-items: center; gap: 4px; margin-right: auto;"></div>
                    <button class="like-btn" data-id="${dynamic.id}"><span data-zoot-icon="heart"></span> ${dynamic.likes}</button>
                    <button class="comment-btn" data-id="${dynamic.id}"><span data-zoot-icon="message"></span> ${dynamic.comment_count}</button>
                    <button class="share-btn" data-id="${dynamic.id}">↗️ 转发</button>
                </div>
                <div class="comments-section" id="comments-${dynamic.id}" data-loaded="false" style="display: block;"></div>
            </div>
        `).join('');

        // 绑定按钮事件
        document.querySelectorAll('.dynamic-card .dynamic-menu-btn').forEach(btn => {
            btn.removeEventListener('click', dynamicMenuHandler);
            btn.addEventListener('click', dynamicMenuHandler);
        });
        document.querySelectorAll('.dynamic-card .like-btn').forEach(btn => {
            btn.removeEventListener('click', likeHandler);
            btn.addEventListener('click', likeHandler);
        });
        document.querySelectorAll('.dynamic-card .comment-btn').forEach(btn => {
            btn.removeEventListener('click', commentBtnHandler);
            btn.addEventListener('click', commentBtnHandler);
        });
        document.querySelectorAll('.dynamic-card .share-btn').forEach(btn => {
            btn.removeEventListener('click', shareHandler);
            btn.addEventListener('click', shareHandler);
        });
        // 作者头像点击跳转个人主页
        document.querySelectorAll('.dynamic-card .dynamic-avatar').forEach(avatar => {
            const card = avatar.closest('.dynamic-card');
            const authorId = card.dataset.authorId;
            if (authorId && !authorId.includes('#') && !authorId.startsWith('custom')) {
                avatar.addEventListener('click', (e) => {
                    e.stopPropagation();
                    showOperatorDynamics(authorId);
                });
            }
        });

        // 异步加载评论和点赞头像墙
        for (const dynamic of dynamics) {
            const card = document.querySelector(`.dynamic-card[data-id="${dynamic.id}"]`);
            if (card) {
                loadComments(dynamic.id, card);
                loadLikersAvatar(dynamic.id, card);
            }
        }
    } catch (e) {
        console.error('渲染动态失败', e);
        container.innerHTML = '<div class="empty-state" style="text-align:center; padding:40px; color:red;">动态加载失败，请刷新页面重试</div>';
    }
}

// 删除动态
async function dynamicMenuHandler(e) {
    e.stopPropagation();
    const id = e.currentTarget.dataset.id;
    if (confirm('确定删除这条动态吗？')) {
        try {
            await deleteDynamic(id);
            await renderDynamics();
        } catch (err) {
            alert('删除失败：' + err.message);
        }
    }
}

// 点赞（支持增量更新）
async function likeHandler(e) {
    e.stopPropagation();
    const id = e.currentTarget.dataset.id;
    const btn = e.currentTarget;
    try {
        const newLikes = await likeDynamic(id);
        btn.textContent = `❤️ ${newLikes}`;
        // 刷新点赞头像墙
        const card = btn.closest('.dynamic-card');
        if (card) await loadLikersAvatar(id, card);
    } catch (err) {
        console.error('点赞失败', err);
    }
}

async function loadLikersAvatar(dynamicId, card) {
    const wall = card.querySelector('.likers-avatar-wall');
    if (!wall) return;
    try {
        const res = await fetch(`/dynamics/${dynamicId}/likers?limit=5`);
        const data = await res.json();
        const likers = data.likers || [];
        if (likers.length === 0) {
            wall.style.display = 'none';
            return;
        }
        wall.style.display = 'flex';
        let html = '';
        for (const liker of likers) {
            const avatarUrl = getOperatorAvatarUrl(liker.operator_id);
            html += `<img src="${avatarUrl}" alt="${liker.operator_id}" style="width: 28px; height: 28px; border-radius: 50%; object-fit: cover;" onerror="this.src='/static/avatars/default.webp'">`;
        }
        if (likers.length === 5) {
            html += `<span style="font-size: 12px; color: var(--text-secondary);">...</span>`;
        }
        wall.innerHTML = html;
        // 为每个头像添加点击事件
        wall.querySelectorAll('img').forEach(img => {
            const opId = img.alt;
            if (opId && !opId.includes('#') && !opId.startsWith('custom')) {
                img.addEventListener('click', (e) => {
                    e.stopPropagation();
                    showOperatorDynamics(opId);
                });
            }
        });
    } catch (e) {
        console.warn('加载点赞头像失败', e);
    }
}

// 评论按钮点击 → 打开评论半页框（用于发表新评论）
async function commentBtnHandler(e) {
    e.stopPropagation();
    const id = e.currentTarget.dataset.id;
    const card = e.currentTarget.closest('.dynamic-card');
    // 确保评论已加载（如果未加载，先加载）
    const commentsSection = card.querySelector('.comments-section');
    if (commentsSection.dataset.loaded !== 'true') {
        await loadComments(id, card);
    }
    currentDynamicId = id;
    currentReplyToCommentId = null;   // 清空回复目标，表示评论动态本身
    const commentInput = document.getElementById('comment-content');
    if (commentInput) commentInput.placeholder = '评论点什么...';
    openBottomSheet('comment-bottom-sheet');
}

// 评论输入框点击 → 打开半页框，回复为 null
function commentInputHandler(e) {
    e.stopPropagation();
    const id = e.currentTarget.dataset.id;
    currentDynamicId = id;
    currentReplyToCommentId = null;
    const commentInput = document.getElementById('comment-content');
    if (commentInput) commentInput.placeholder = '评论点什么...';
    openBottomSheet('comment-bottom-sheet');
}

// 提交新动态
async function submitDynamic() {
    const content = document.getElementById('dynamic-content').value.trim();
    if (!content) return;
    const submitBtn = document.getElementById('submit-dynamic-btn');
    submitBtn.disabled = true;
    submitBtn.textContent = '发布中...';
    try {
        await postDynamic(content);
        await renderDynamics();
        closePostDynamicSheet();
        document.getElementById('dynamic-content').value = '';
    } catch (err) {
        alert('发布失败：' + err.message);
    } finally {
        submitBtn.disabled = false;
        submitBtn.textContent = '发布';
    }
}

// 提交评论
async function submitComment() {
    const content = document.getElementById('comment-content').value.trim();
    if (!content) return;
    const submitBtn = document.getElementById('submit-comment-btn');
    submitBtn.disabled = true;
    submitBtn.textContent = '发送中...';
    try {
        // 如果有回复目标，传递 reply_to_comment_id
        await postComment(currentDynamicId, content, currentReplyToCommentId);
        // 刷新当前动态的评论区域
        const card = document.querySelector(`.dynamic-card[data-id="${currentDynamicId}"]`);
        if (card) {
            const commentsSection = card.querySelector('.comments-section');
            commentsSection.dataset.loaded = 'false';
            await loadComments(currentDynamicId, card);
        }
        closeCommentSheet();
        document.getElementById('comment-content').value = '';
        // 清空回复目标
        currentReplyToCommentId = null;
        // 恢复评论输入框的 placeholder
        const commentInput = document.getElementById('comment-content');
        if (commentInput) commentInput.placeholder = '写评论...';
        // 更新评论计数（增量）
        const commentBtn = card?.querySelector('.comment-btn');
        if (commentBtn) {
            const match = commentBtn.textContent.match(/💬\s*(\d+)/);
            if (match) {
                const currentCount = parseInt(match[1], 10);
                commentBtn.textContent = `💬 ${currentCount + 1}`;
            }
        }
    } catch (err) {
        alert('评论失败：' + err.message);
    } finally {
        submitBtn.disabled = false;
        submitBtn.textContent = '发送';
    }
}

// 转发
async function shareHandler(e) {
    e.stopPropagation();
    const dynamicId = e.currentTarget.dataset.id;
    const card = e.currentTarget.closest('.dynamic-card');
    const originalContent = card.querySelector('.dynamic-content').innerText;
    const author = card.querySelector('.dynamic-author-name').innerText;

    // 弹出选择菜单
    const action = await new Promise((resolve) => {
        const sheet = document.createElement('div');
        sheet.className = 'bottom-sheet show';
        sheet.innerHTML = `
            <div class="bottom-sheet-overlay"></div>
            <div class="bottom-sheet-content">
                <div style="padding: 20px; text-align: center;">分享动态</div>
                <button data-action="dynamic" style="width:100%; padding:12px;">转发为动态</button>
                <button data-action="chat" style="width:100%; padding:12px;">转发给干员</button>
                <button data-action="cancel" style="width:100%; padding:12px;">取消</button>
            </div>
        `;
        document.body.appendChild(sheet);
        const handleClick = (e) => {
            const action = e.target.dataset.action;
            if (action) resolve(action);
            sheet.remove();
        };
        sheet.addEventListener('click', handleClick);
    });

    if (action === 'dynamic') {
        const customText = prompt('请输入转发语（可不填）：', '');
        const finalContent = customText ? `${customText}\n\n转发 @${author} 的动态：${originalContent}` : `转发 @${author} 的动态：${originalContent}`;
        await postDynamic(finalContent);
        await renderDynamics();
        alert('已转发为动态');
    } else if (action === 'chat') {
        await openShareToChatPicker(dynamicId);
    }
}

async function openShareToChatPicker(dynamicId) {
    // 获取干员列表（排除博士）
    const ops = operators.filter(op => op.id !== 'doctor');
    if (ops.length === 0) {
        alert('没有可分享的干员');
        return;
    }
    // 构建半页框选择列表
    const sheet = document.createElement('div');
    sheet.className = 'bottom-sheet show';
    const listHtml = ops.map(op => `
        <div class="contact-item" data-operator-id="${op.id}" style="padding: 12px; display: flex; align-items: center; gap: 12px; border-bottom: 1px solid var(--border-color);">
            <img src="${getOperatorAvatarUrl(op.id)}" class="contact-avatar" style="width: 40px; height: 40px; border-radius: 50%;">
            <span>${op.codename}</span>
        </div>
    `).join('');
    sheet.innerHTML = `
        <div class="bottom-sheet-overlay"></div>
        <div class="bottom-sheet-content" style="max-height: 70vh;">
            <div class="bottom-sheet-header">选择分享对象</div>
            <div style="max-height: 60vh; overflow-y: auto;">${listHtml}</div>
            <button class="bottom-sheet-close" style="margin-top: 12px;">取消</button>
        </div>
    `;
    document.body.appendChild(sheet);
    // 选择干员
    const selected = await new Promise((resolve) => {
        const items = sheet.querySelectorAll('.contact-item');
        items.forEach(item => {
            item.addEventListener('click', () => {
                const opId = item.dataset.operatorId;
                resolve(opId);
                sheet.remove();
            });
        });
        sheet.querySelector('.bottom-sheet-close').addEventListener('click', () => {
            resolve(null);
            sheet.remove();
        });
    });
    if (selected) {
        try {
            const res = await fetch('/dynamics/share_to_chat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ dynamic_id: dynamicId, target_operator_id: selected, persona_id: window.currentPersonaId || currentPersonaId || 'doctor' })
            });
            if (res.ok) {
                alert('已分享给干员');
                // 跳转到与该干员的私聊页
                currentOperatorId = selected;
                currentGroupId = null;
                await loadPrivateHistory(selected);
                saveCurrentChat();
                showPage('chat-detail');
            } else {
                alert('分享失败');
            }
        } catch (err) {
            console.error(err);
            alert('分享失败');
        }
    }
}

async function resetNewDynamicFlag() {
    try {
        await fetch('/dynamics/unread_status/reset', { method: 'POST' });
        localStorage.removeItem('hasNewDynamic');
    } catch (e) {}
}

function adjustDynamicsBgHeight() {
    const container = document.querySelector('.dynamics-scroll-container');
    const bgLayer = document.getElementById('dynamics-bg-layer');
    if (!container || !bgLayer) return;
    const content = container.querySelector('.dynamics-content');
    if (content) {
        const contentHeight = content.scrollHeight;
        const containerHeight = container.clientHeight;
        bgLayer.style.height = Math.max(contentHeight, containerHeight) + 'px';
    }
}

// 初始化动态页
async function initDynamicsPage() {
    await loadPersonaList();
    await updatePersonaNameMap();
    await updatePersonaAvatarMap();
    await renderDynamics();

    // ========== 1. 头像背景相关 ==========
    loadDynamicsBackground();
    const topPlaceholder = document.querySelector('#page-zoot-dynamics .dynamics-top-placeholder');
    if (topPlaceholder && !topPlaceholder.dataset.bound) {
        topPlaceholder.addEventListener('click', openDynamicsBackgroundPicker);
        topPlaceholder.dataset.bound = 'true';
    }

    // 顶部头像和个人动态入口始终跟随当前人格；克隆人格指向源干员主页。
    const doctorAvatarImg = document.getElementById('dynamics-doctor-avatar');
    const dynamicsIdentityId = getCurrentDynamicsIdentityId();
    const dynamicsActor = getDynamicsActorMeta(dynamicsIdentityId);
    if (doctorAvatarImg) {
        doctorAvatarImg.src = dynamicsActor.avatar;
        doctorAvatarImg.onclick = () => showOperatorDynamics(dynamicsIdentityId);
    }
    const doctorNameDiv = document.querySelector('#page-zoot-dynamics .dynamics-user-name');
    if (doctorNameDiv) {
        doctorNameDiv.textContent = dynamicsActor.name;
        doctorNameDiv.onclick = () => showOperatorDynamics(dynamicsIdentityId);
    }

    // ========== 2. 全局动态生成开关 ==========
    const toggle = document.getElementById('dynamics-global-toggle');
    if (toggle && !toggle.dataset.bound) {
        try {
            const res = await fetch('/dynamics/global/config');
            const config = await res.json();
            toggle.checked = config.enabled === true;
        } catch (e) {
            console.warn('加载动态全局配置失败', e);
        }
        toggle.addEventListener('change', async (e) => {
            const enabled = e.target.checked;
            try {
                await fetch('/dynamics/global/config', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ enabled: enabled })
                });
            } catch (err) {
                console.warn('保存动态全局配置失败', err);
            }
        });
        toggle.dataset.bound = 'true';
    }

    // ========== 3. 绑定发布动态、提交评论等按钮 ==========
    const postBtn = document.getElementById('post-dynamic-btn');
    if (postBtn && !postBtn.dataset.bound) {
        postBtn.addEventListener('click', () => openBottomSheet('post-dynamic-bottom-sheet'));
        postBtn.dataset.bound = 'true';
    }
    const submitDynamicBtn = document.getElementById('submit-dynamic-btn');
    if (submitDynamicBtn && !submitDynamicBtn.dataset.bound) {
        submitDynamicBtn.addEventListener('click', submitDynamic);
        submitDynamicBtn.dataset.bound = 'true';
    }
    const submitCommentBtn = document.getElementById('submit-comment-btn');
    if (submitCommentBtn && !submitCommentBtn.dataset.bound) {
        submitCommentBtn.addEventListener('click', submitComment);
        submitCommentBtn.dataset.bound = 'true';
    }

    // ========== 4. 日志、留言按钮 ==========
    const logBtn = document.getElementById('post-log-btn');
    if (logBtn && !logBtn.dataset.bound) {
        logBtn.addEventListener('click', showUnderDevelopmentModal);
        logBtn.dataset.bound = 'true';
    }
    const messageBtn = document.getElementById('post-message-btn');
    if (messageBtn && !messageBtn.dataset.bound) {
        messageBtn.addEventListener('click', showUnderDevelopmentModal);
        messageBtn.dataset.bound = 'true';
    }

    // ========== 5. 清除新动态红点标记并刷新未读 ==========
    localStorage.removeItem('hasNewDynamic');
    await fetchUnreadCount();

    // ========== 6. 绑定消息按钮（打开通知半页框） ==========
    const notifBtn = document.getElementById('notifications-btn');
    if (notifBtn && !notifBtn.dataset.bound) {
        notifBtn.addEventListener('click', openNotificationsSheet);
        notifBtn.dataset.bound = 'true';
    }

    // ========== 7.  清除新动态标记 ==========
    resetNewDynamicFlag();
}

// ========== 43.2.1. 个人主页 ==========
let currentOperatorDynamicsId = null;

async function loadOperatorDynamics(operatorId, before = null, append = false) {
    let url = `/dynamics/user/${operatorId}?limit=20`;
    if (before) url += `&before=${before}`;
    const res = await fetch(url);
    if (!res.ok) throw new Error('加载失败');
    const dynamics = await res.json();
    const dynamicsList = dynamics.map(d => transformDynamic(d));
    const container = document.getElementById('op-dynamics-list');
    if (append) {
        const existingIds = new Set(Array.from(container.querySelectorAll('.dynamic-card')).map(card => card.dataset.id));
        for (const d of dynamicsList) {
            if (!existingIds.has(d.id)) {
                container.insertAdjacentHTML('beforeend', renderOperatorDynamicCard(d));
            }
        }
    } else {
        container.innerHTML = dynamicsList.map(d => renderOperatorDynamicCard(d)).join('');
    }
    bindDynamicCardEvents(container);
    // 为每个动态加载评论和点赞墙
    for (const d of dynamicsList) {
        const card = container.querySelector(`.dynamic-card[data-id="${d.id}"]`);
        if (card) {
            loadComments(d.id, card);
            loadLikersAvatar(d.id, card);
        }
    }
    return dynamicsList;
}

function renderOperatorDynamicCard(dynamic) {
    return `
        <div class="dynamic-card${String(dynamic.author.id) === 'priestess' ? ' priestess-related priestess-dynamic-card' : ''}" data-id="${dynamic.id}" data-author-id="${dynamic.author.id}"${String(dynamic.author.id) === 'priestess' ? ' data-actor-id="priestess"' : ''}>
            <div class="dynamic-header">
                <img src="${dynamic.author.avatar}" class="dynamic-avatar" onerror="this.src='/static/avatars/default.webp'">
                <div class="dynamic-author-info">
                    <div class="dynamic-author-name">${escapeHtml(dynamic.author.name)}</div>
                    <div class="dynamic-time">${formatTimeAgo(dynamic.time)}</div>
                </div>
                ${dynamic.author.id === getCurrentDynamicsIdentityId() ? `<button class="dynamic-menu-btn" data-id="${dynamic.id}"><span data-zoot-icon="more"></span></button>` : ''}
            </div>
            <div class="dynamic-content">${escapeHtml(dynamic.content)}</div>
            ${dynamic.images.length ? `<div class="dynamic-images">${dynamic.images.map(img => `<img src="${img}" loading="lazy">`).join('')}</div>` : ''}
            <div class="dynamic-footer">
                <div class="likers-avatar-wall" style="display: flex; align-items: center; gap: 4px; margin-right: auto;"></div>
                <button class="like-btn" data-id="${dynamic.id}"><span data-zoot-icon="heart"></span> ${dynamic.likes}</button>
                <button class="comment-btn" data-id="${dynamic.id}"><span data-zoot-icon="message"></span> ${dynamic.comment_count}</button>
                <button class="share-btn" data-id="${dynamic.id}">↗️ 转发</button>
            </div>
            <div class="comments-section" id="comments-${dynamic.id}" data-loaded="false" style="display: block;"></div>
        </div>
    `;
}

function bindDynamicCardEvents(container) {
    container.querySelectorAll('.dynamic-card .dynamic-menu-btn').forEach(btn => {
        btn.removeEventListener('click', dynamicMenuHandler);
        btn.addEventListener('click', dynamicMenuHandler);
    });
    container.querySelectorAll('.dynamic-card .like-btn').forEach(btn => {
        btn.removeEventListener('click', likeHandler);
        btn.addEventListener('click', likeHandler);
    });
    container.querySelectorAll('.dynamic-card .comment-btn').forEach(btn => {
        btn.removeEventListener('click', commentBtnHandler);
        btn.addEventListener('click', commentBtnHandler);
    });
    // 为每个动态的作者头像添加点击跳转
    container.querySelectorAll('.dynamic-card .dynamic-avatar').forEach(img => {
        const card = img.closest('.dynamic-card');
        const authorId = card?.dataset?.authorId || card?.querySelector('.dynamic-author-info')?.dataset?.authorId;
        if (authorId) {
            img.addEventListener('click', (e) => {
                e.stopPropagation();
                showOperatorDynamics(authorId);
            });
        }
    });
}

async function showOperatorDynamics(operatorId) {
    currentOperatorDynamicsId = operatorId;
    const actor = getDynamicsActorMeta(operatorId);
    const name = actor.name;
    const avatarUrl = actor.avatar;
    document.getElementById('op-dynamics-name').innerText = name;
    const avatarEl = document.getElementById('op-dynamics-avatar');
    avatarEl.src = avatarUrl;
    avatarEl.onclick = () => {
        if (personaList.some(item => item.persona_id === operatorId)) showPage('profile');
        else showOperatorDetail(operatorId);
    };
    const savedBg = localStorage.getItem(getDynamicsBackgroundKey(operatorId));
    if (savedBg) document.getElementById('op-dynamics-bg-layer').style.backgroundImage = `url('${savedBg}')`;
    await loadOperatorDynamics(operatorId);
    showPage('operator-dynamics');
}


// ========== 43.2.2. 动态生成配置 ==========
let dynamicWhitelist = [];           // 存储白名单干员英文名列表

// ---------- 辅助函数 ----------
function setDynamicSliderValue(sliderId, val, spanId) {
    const slider = document.getElementById(sliderId);
    if (slider) slider.value = val;
    const span = document.getElementById(spanId);
    if (span) span.innerText = val;
}

// 读取本地存储的数值（带默认值）
function getDynamicStorageInt(key, defaultValue) {
    const val = localStorage.getItem(key);
    return val !== null ? parseInt(val) : defaultValue;
}

function getDynamicStorageBool(key, defaultValue) {
    const val = localStorage.getItem(key);
    if (val === null) return defaultValue;
    return val === 'true';
}

// ---------- 保存配置到本地（并尝试同步后端）----------
async function saveDynamicConfigToLocal() {
    // 1. 全局开关
    const globalToggle = document.getElementById('dynamic-global-toggle');
    if (globalToggle) {
        localStorage.setItem('dynamic_global_enabled', globalToggle.checked);
    }

    // 2. 滑块值
    const pollInterval = parseInt(document.getElementById('dynamic-poll-interval')?.value || 60);
    const prePush = parseInt(document.getElementById('dynamic-pre-push-interval')?.value || 300);
    const minDelay = parseInt(document.getElementById('dynamic-min-push-delay')?.value || 30);
    const maxDelay = parseInt(document.getElementById('dynamic-max-push-delay')?.value || 600);
    const queueMin = parseInt(document.getElementById('dynamic-queue-min-size')?.value || 3);
    const queueMax = parseInt(document.getElementById('dynamic-queue-max-size')?.value || 10);
    const batchSize = parseInt(document.getElementById('dynamic-batch-size')?.value || 2);

    localStorage.setItem('dynamic_poll_interval', pollInterval);
    localStorage.setItem('dynamic_pre_push_interval', prePush);
    localStorage.setItem('dynamic_min_push_delay', minDelay);
    localStorage.setItem('dynamic_max_push_delay', maxDelay);
    localStorage.setItem('dynamic_queue_min_size', queueMin);
    localStorage.setItem('dynamic_queue_max_size', queueMax);
    localStorage.setItem('dynamic_batch_size', batchSize);

    // 3. 白名单模式
    const modeSelect = document.getElementById('dynamic-whitelist-mode-select');
    if (modeSelect) {
        localStorage.setItem('dynamic_whitelist_mode', modeSelect.value);
    }

    // 4. 白名单权重（混合模式时）
    const weightSlider = document.getElementById('dynamic-whitelist-weight');
    if (weightSlider) {
        localStorage.setItem('dynamic_whitelist_weight', weightSlider.value);
    }
    await flushGeneratedContentPreferences();

    // 可选：同步到后端（静默失败，不阻塞用户）
    try {
        const configData = {
            enabled: globalToggle ? globalToggle.checked : true,
            poll_interval: pollInterval,
            pre_push_interval: prePush,
            min_push_delay: minDelay,
            max_push_delay: maxDelay,
            min_queue_size: queueMin,
            max_queue_size: queueMax,
            batch_size: batchSize,
            whitelist_mode: modeSelect ? modeSelect.value : 'whitelist',
            whitelist_weight: weightSlider ? parseInt(weightSlider.value) : 2
        };
        const response = await fetch('/dynamics/global/config', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(configData)
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
    } catch (e) {
        console.warn('[动态配置] 同步后端失败，仅保存本地', e);
    }
}

// ---------- 从本地加载配置（并尝试从后端读取最新）----------
async function loadDynamicConfigFromLocal() {
    const config = {
        enabled: getDynamicStorageBool('dynamic_global_enabled', true),
        poll_interval: getDynamicStorageInt('dynamic_poll_interval', 60),
        pre_push_interval: getDynamicStorageInt('dynamic_pre_push_interval', 300),
        min_push_delay: getDynamicStorageInt('dynamic_min_push_delay', 30),
        max_push_delay: getDynamicStorageInt('dynamic_max_push_delay', 600),
        min_queue_size: getDynamicStorageInt('dynamic_queue_min_size', 3),
        max_queue_size: getDynamicStorageInt('dynamic_queue_max_size', 10),
        batch_size: getDynamicStorageInt('dynamic_batch_size', 2),
        whitelist_mode: localStorage.getItem('dynamic_whitelist_mode') || 'whitelist',
        whitelist_weight: getDynamicStorageInt('dynamic_whitelist_weight', 2)
    };
    try {
        const response = await fetch('/dynamics/global/config', { cache: 'no-store' });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const backendConfig = await response.json();
        Object.keys(config).forEach(key => {
            if (backendConfig[key] !== null && backendConfig[key] !== undefined) config[key] = backendConfig[key];
        });
    } catch (error) {
        console.warn('[动态配置] 后端配置回读失败，使用本机缓存', error);
    }

    localStorage.setItem('dynamic_global_enabled', String(parseGeneratedContentBoolean(config.enabled, true)));
    localStorage.setItem('dynamic_poll_interval', String(parseGeneratedContentInteger(config.poll_interval, 60)));
    localStorage.setItem('dynamic_pre_push_interval', String(parseGeneratedContentInteger(config.pre_push_interval, 300)));
    localStorage.setItem('dynamic_min_push_delay', String(parseGeneratedContentInteger(config.min_push_delay, 30)));
    localStorage.setItem('dynamic_max_push_delay', String(parseGeneratedContentInteger(config.max_push_delay, 600)));
    localStorage.setItem('dynamic_queue_min_size', String(parseGeneratedContentInteger(config.min_queue_size, 3)));
    localStorage.setItem('dynamic_queue_max_size', String(parseGeneratedContentInteger(config.max_queue_size, 10)));
    localStorage.setItem('dynamic_batch_size', String(parseGeneratedContentInteger(config.batch_size, 2)));
    localStorage.setItem('dynamic_whitelist_mode', String(config.whitelist_mode || 'whitelist'));
    localStorage.setItem('dynamic_whitelist_weight', String(parseGeneratedContentInteger(config.whitelist_weight, 2)));

    // 全局开关
    const globalToggle = document.getElementById('dynamic-global-toggle');
    if (globalToggle) {
        globalToggle.checked = parseGeneratedContentBoolean(config.enabled, true);
    }

    // 所有动态配置均以后端持久化值为权威，本机缓存只用于离线降级。
    setDynamicSliderValue('dynamic-poll-interval', parseGeneratedContentInteger(config.poll_interval, 60), 'dynamic-poll-interval-value');
    setDynamicSliderValue('dynamic-pre-push-interval', parseGeneratedContentInteger(config.pre_push_interval, 300), 'dynamic-pre-push-value');
    setDynamicSliderValue('dynamic-min-push-delay', parseGeneratedContentInteger(config.min_push_delay, 30), 'dynamic-min-delay-value');
    setDynamicSliderValue('dynamic-max-push-delay', parseGeneratedContentInteger(config.max_push_delay, 600), 'dynamic-max-delay-value');
    setDynamicSliderValue('dynamic-queue-min-size', parseGeneratedContentInteger(config.min_queue_size, 3), 'dynamic-queue-min-val');
    setDynamicSliderValue('dynamic-queue-max-size', parseGeneratedContentInteger(config.max_queue_size, 10), 'dynamic-queue-max-val');
    setDynamicSliderValue('dynamic-batch-size', parseGeneratedContentInteger(config.batch_size, 2), 'dynamic-batch-val');

    // 白名单模式
    const modeSelect = document.getElementById('dynamic-whitelist-mode-select');
    if (modeSelect) {
        const mode = String(config.whitelist_mode || 'whitelist');
        modeSelect.value = ['all', 'whitelist', 'mixed', 'blacklist'].includes(mode) ? mode : 'whitelist';
        updateUIBasedOnMode('dynamic', modeSelect.value);
    }

    // 白名单权重
    const weightSlider = document.getElementById('dynamic-whitelist-weight');
    if (weightSlider) {
        weightSlider.value = parseGeneratedContentInteger(config.whitelist_weight, 2);
        const weightSpan = document.getElementById('dynamic-whitelist-weight-value');
        if (weightSpan) weightSpan.innerText = weightSlider.value;
    }

    // 加载白名单列表
    await loadDynamicWhitelist();
}

// ---------- 白名单管理 ----------
async function loadDynamicWhitelist() {
    let list = [];
    // 优先读取 localStorage
    const stored = localStorage.getItem('dynamic_whitelist');
    if (stored) {
        try { list = JSON.parse(stored); } catch(e) {}
    }
    // 尝试从后端同步（静默）
    try {
        const res = await fetch('/dynamics/whitelist');
        if (res.ok) {
            const data = await res.json();
            if (data.whitelist && Array.isArray(data.whitelist)) {
                list = data.whitelist;
                localStorage.setItem('dynamic_whitelist', JSON.stringify(list));
            }
            if (data.mode) {
                const modeSelect = document.getElementById('dynamic-whitelist-mode-select');
                if (modeSelect) {
                    modeSelect.value = data.mode;
                    localStorage.setItem('dynamic_whitelist_mode', data.mode);
                    updateUIBasedOnMode('dynamic', data.mode);
                }
            }
        }
    } catch (e) {}
    window._dynamicWhitelist = list;
    const summarySpan = document.getElementById('dynamic-whitelist-summary');
    if (summarySpan) {
        summarySpan.innerText = list.length ? `已选 ${list.length} 个` : '未设置';
    }
    return list;
}

async function saveDynamicWhitelist(whitelist) {
    window._dynamicWhitelist = whitelist;
    localStorage.setItem('dynamic_whitelist', JSON.stringify(whitelist));
    const summarySpan = document.getElementById('dynamic-whitelist-summary');
    if (summarySpan) summarySpan.innerText = whitelist.length ? `已选 ${whitelist.length} 个` : '未设置';
    // 同步后端
    try {
        await fetch('/dynamics/whitelist', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                whitelist,
                mode: document.getElementById('dynamic-whitelist-mode-select')?.value || 'whitelist'
            })
        });
    } catch (e) {
        console.warn('[动态配置] 同步白名单到后端失败', e);
    }
}

// 打开白名单编辑页
function openDynamicWhitelistEditor() {
    renderDynamicWhitelistPage();
    showPage('auto-whitelist');
}

function renderDynamicWhitelistPage() {
    const savedSet = new Set(window._dynamicWhitelist || []);
    const allOps = operators.filter(op => op.id !== 'priestess' && op.id !== 'doctor');
    const selectedOps = allOps.filter(op => savedSet.has(op.id));
    const unselectedOps = allOps.filter(op => !savedSet.has(op.id));
    unselectedOps.sort((a, b) => (a.pinyin_initial || '#').localeCompare(b.pinyin_initial || '#'));
    const allSorted = [...selectedOps, ...unselectedOps];
    const container = document.getElementById('whitelist-page-list');
    if (!container) return;

    container.innerHTML = allSorted.map(op => `
        <div class="contact-item" data-id="${op.id}" style="display: flex; justify-content: space-between; align-items: center;">
            <div style="display: flex; align-items: center;">
                <img src="${getOperatorAvatarUrl(op.id)}" class="contact-avatar" style="width: 40px; height: 40px; margin-right: 12px;" onerror="this.src='/static/avatars/default.webp'">
                <span class="contact-name">${escapeHtml(op.codename)}</span>
            </div>
            <input type="checkbox" class="whitelist-checkbox" value="${op.id}" ${savedSet.has(op.id) ? 'checked' : ''}>
        </div>
    `).join('');

    const searchInput = document.getElementById('whitelist-page-search');
    if (searchInput) {
        searchInput.oninput = () => {
            const kw = searchInput.value.toLowerCase();
            container.querySelectorAll('.contact-item').forEach(item => {
                const name = item.querySelector('.contact-name').innerText.toLowerCase();
                item.style.display = name.includes(kw) ? 'flex' : 'none';
            });
        };
    }

    const saveBtn = document.getElementById('whitelist-page-save');
    if (saveBtn) {
        const newBtn = saveBtn.cloneNode(true);
        saveBtn.parentNode.replaceChild(newBtn, saveBtn);
        newBtn.onclick = async () => {
            const selected = Array.from(container.querySelectorAll('.whitelist-checkbox:checked')).map(cb => cb.value);
            await saveDynamicWhitelist(selected);
            goBack();
        };
    }
}

// ---------- 事件绑定 ----------
function bindDynamicConfigEvents() {
    // 滑块实时更新数值 + 保存
    const sliders = [
        'dynamic-poll-interval', 'dynamic-pre-push-interval',
        'dynamic-min-push-delay', 'dynamic-max-push-delay',
        'dynamic-queue-min-size', 'dynamic-queue-max-size', 'dynamic-batch-size'
    ];
    const spanMap = {
        'dynamic-poll-interval': 'dynamic-poll-interval-value',
        'dynamic-pre-push-interval': 'dynamic-pre-push-value',
        'dynamic-min-push-delay': 'dynamic-min-delay-value',
        'dynamic-max-push-delay': 'dynamic-max-delay-value',
        'dynamic-queue-min-size': 'dynamic-queue-min-val',
        'dynamic-queue-max-size': 'dynamic-queue-max-val',
        'dynamic-batch-size': 'dynamic-batch-val'
    };
    sliders.forEach(sliderId => {
        const slider = document.getElementById(sliderId);
        if (slider) {
            slider.oninput = () => {
                const span = document.getElementById(spanMap[sliderId]);
                if (span) span.innerText = slider.value;
            };
            slider.onchange = () => saveDynamicConfigToLocal();
        }
    });

    // 全局开关
    const globalToggle = document.getElementById('dynamic-global-toggle');
    if (globalToggle) globalToggle.onchange = () => saveDynamicConfigToLocal();

    // 白名单模式选择
    const modeSelect = document.getElementById('dynamic-whitelist-mode-select');
    if (modeSelect) {
        modeSelect.onchange = () => {
            saveDynamicConfigToLocal();
            updateUIBasedOnMode('dynamic', modeSelect.value);
        };
    }

    // 白名单编辑入口
    const whitelistItem = document.getElementById('dynamic-whitelist-item');
    if (whitelistItem) {
        whitelistItem.onclick = () => {
            if (whitelistItem.dataset.listDisabled === 'true') return;
            openDynamicWhitelistEditor();
        };
    }

    // 白名单权重（混合模式）
    const weightSlider = document.getElementById('dynamic-whitelist-weight');
    if (weightSlider) {
        weightSlider.oninput = (e) => {
            const span = document.getElementById('dynamic-whitelist-weight-value');
            if (span) span.innerText = e.target.value;
        };
        weightSlider.onchange = () => saveDynamicConfigToLocal();
    }
}

// ---------- 对外初始化入口 ----------
async function initDynamicConfigPage() {
    await loadDynamicConfigFromLocal();
    bindDynamicConfigEvents();
}

let generatedContentSettingsHydration = null;

async function activateGeneratedContentSettingsSection(target) {
    if (target === 'event') {
        await loadEventConfig();
    } else if (target === 'dynamic') {
        await initDynamicConfigPage();
    } else if (target === 'push') {
        bindAutoMessageImmediateSave();
        const pushPageToggle = document.getElementById('global-push-switch');
        if (pushPageToggle) pushPageToggle.checked = localStorage.getItem('globalAutoPushEnabled') !== 'false';
    } else {
        await loadAutoPushSettings();
    }
}

async function hydrateGeneratedContentSettingsPage() {
    if (generatedContentSettingsHydration) return generatedContentSettingsHydration;
    generatedContentSettingsHydration = (async () => {
        initSettingsTabs('settings-auto-gen');
        const innerContainer = document.getElementById('auto-gen-tab-auto-msg');
        if (innerContainer) {
            initAutoMessageTabs(innerContainer);
            innerContainer.dataset.tabsInitialized = 'true';
        }
        await Promise.allSettled([
            loadAutoPushSettings(),
            initDynamicConfigPage()
        ]);
        const activeTab = document.querySelector('#page-settings-auto-gen > .page-content > .auto-message-tabs > .auto-tab.active')
            || document.querySelector('#page-settings-auto-gen .auto-message-tabs > .auto-tab.active');
        if (activeTab?.dataset.tab === 'event') await loadEventConfig();
        bindAutoMessageImmediateSave();
    })().finally(() => {
        generatedContentSettingsHydration = null;
    });
    return generatedContentSettingsHydration;
}

window.addEventListener('zoot:device-preferences-ready', () => {
    if (window.privateQueueGenerator) window.privateQueueGenerator.loadConfig();
    if (window.groupQueueGenerator) window.groupQueueGenerator.loadConfig();
    void loadAutoPushSettings();
    const page = document.getElementById('page-settings-auto-gen');
    if (page?.classList.contains('active')) void hydrateGeneratedContentSettingsPage();
});

// ========== 43.2.3. 动态背景 ==========
// 加载动态背景
function loadDynamicsBackground() {
    const savedBg = localStorage.getItem(getDynamicsBackgroundKey());
    const bgLayer = document.getElementById('dynamics-bg-layer');
    if (bgLayer && savedBg) {
        bgLayer.style.backgroundImage = `url('${savedBg}')`;
    }
}

function getDynamicsBackgroundKey(identityId = getCurrentDynamicsIdentityId()) {
    return `dynamicsBg_${identityId}`;
}

// 打开动态背景选择半页框
async function openDynamicsBackgroundPicker() {
    const picker = document.getElementById('dynamicsBgPicker');
    const grid = document.getElementById('dynamicsBgGrid');
    if (!picker || !grid) return;

    try {
        const res = await fetch('/backgrounds/list');
        if (!res.ok) throw new Error();
        const data = await res.json();
        const backgrounds = data.backgrounds || [];
        const currentBg = localStorage.getItem(getDynamicsBackgroundKey()) || '/static/backgrounds/default_banner.jpg';
        grid.innerHTML = backgrounds.map(url => `
            <div class="bg-option" data-url="${url}" style="background-image: url('${url}');"></div>
        `).join('');
        grid.querySelectorAll('.bg-option').forEach(opt => {
            if (opt.dataset.url === currentBg) opt.classList.add('selected');
            opt.addEventListener('click', () => {
                selectDynamicsBackground(opt.dataset.url);
            });
        });
    } catch (e) {
        // 降级：使用预设背景（实际应从后端获取，但此处为降级）
        const fallbackBgs = [
            '/static/backgrounds/default_banner.jpg',
            '/static/backgrounds/banner_1.webp',
            '/static/backgrounds/banner_2.webp'
        ];
        const currentBg = localStorage.getItem(getDynamicsBackgroundKey()) || fallbackBgs[0];
        grid.innerHTML = fallbackBgs.map(url => `
            <div class="bg-option" data-url="${url}" style="background-image: url('${url}');"></div>
        `).join('');
        grid.querySelectorAll('.bg-option').forEach(opt => {
            if (opt.dataset.url === currentBg) opt.classList.add('selected');
            opt.addEventListener('click', () => {
                selectDynamicsBackground(opt.dataset.url);
            });
        });
    }
    openBottomSheet('dynamicsBgPicker');
}

function closeDynamicsBackgroundPicker() {
    closeBottomSheet('dynamicsBgPicker');
}

function selectDynamicsBackground(url) {
    const bgLayer = document.getElementById('dynamics-bg-layer');
    if (bgLayer) {
        bgLayer.style.backgroundImage = `url('${url}')`;
        localStorage.setItem(getDynamicsBackgroundKey(), url);
    }
    closeDynamicsBackgroundPicker();
}

// ========== 43.2.4. 动态通知相关 ==========
let currentNotifications = [];
let notificationsLoaded = false;

// 刷新动态列表
async function refreshDynamics() {
    if (getCurrentPageId() === 'zoot-dynamics') {
        await renderDynamics();
    }
}

// 统一更新红点（动态页按钮 + 底部导航栏）
function updateNotificationBadge(count, isDotOnly = false) {
    dynamicsUnreadCount = Number(count || 0);
    // 1. 动态页按钮内的 .badge（注意类名是 badge）
    const badgeInside = document.getElementById('notif-badge');
    if (badgeInside) {
        if (count > 0) {
            if (isDotOnly) {
                badgeInside.textContent = '';
                badgeInside.classList.add('dot');
                badgeInside.style.display = 'inline-block';
            } else {
                badgeInside.textContent = count > 99 ? '99+' : count;
                badgeInside.classList.remove('dot');
                badgeInside.style.display = 'inline-block';
            }
        } else {
            badgeInside.style.display = 'none';
        }
    }

    // 2. 底部导航栏“扩展”页红点
    const momentsBadge = document.querySelector('.nav-item[data-page="moments"] .nav-badge');
    if (momentsBadge) {
        const total = dynamicsUnreadCount + extensionUnreadCount;
        if (total > 0 || isDotOnly) {
            if (isDotOnly && total === 0) {
                momentsBadge.textContent = '';
                momentsBadge.classList.add('dot');
                momentsBadge.style.display = 'inline-block';
            } else {
                momentsBadge.textContent = total > 99 ? '99+' : total;
                momentsBadge.classList.remove('dot');
                momentsBadge.style.display = 'inline-block';
            }
        } else {
            momentsBadge.style.display = 'none';
        }
    }
}

// 获取未读消息数量
async function fetchUnreadCount() {
    try {
        const res = await fetch(`/dynamics/unread_status?persona_id=${encodeURIComponent(window.currentPersonaId || currentPersonaId || 'doctor')}`);
        if (res.ok) {
            const data = await res.json();
            const { interaction_unread, has_new_dynamic } = data;
            if (interaction_unread > 0) {
                updateNotificationBadge(interaction_unread, false);
            } else if (has_new_dynamic) {
                updateNotificationBadge(0, true);  // 仅红点
            } else {
                updateNotificationBadge(0, false);
            }
            localStorage.setItem('hasNewDynamic', has_new_dynamic ? 'true' : 'false');
            return interaction_unread;
        }
    } catch (e) {
        console.warn('通知接口未实现，使用本地存储红点', e);
        const hasNewDynamic = localStorage.getItem('hasNewDynamic') === 'true';
        updateNotificationBadge(hasNewDynamic ? 1 : 0, true);
        return hasNewDynamic ? 1 : 0;
    }
}

// 加载通知列表
async function loadNotifications() {
    const container = document.getElementById('notifications-list');
    if (!container) return;
    container.innerHTML = '<div style="text-align:center; padding:20px;">加载中...</div>';

    let notifications = [];
    let error = false;
    try {
        const res = await fetch(`/dynamics/notifications?limit=50&persona_id=${encodeURIComponent(window.currentPersonaId || currentPersonaId || 'doctor')}`);
        if (res.ok) {
            const data = await res.json();
            notifications = data.notifications || [];
        } else {
            throw new Error('接口返回非200');
        }
    } catch (e) {
        console.warn('加载通知接口失败，使用模拟数据', e);
        error = true;
        notifications = [{
            id: 1,
            type: 'new_dynamic',
            operator_id: 'amiya',
            content: '大家早呀',
            created_at: Date.now() / 1000,
            is_read: false,
            related_dynamic_id: 1
        }];
    }

    currentNotifications = notifications;
    if (currentNotifications.length === 0) {
        container.innerHTML = '<div style="text-align:center; padding:20px;">暂无消息</div>';
        return;
    }

    let html = '';
    for (const notif of currentNotifications) {
        const time = formatTimeAgo(notif.created_at * 1000);
        let text = '';
        if (notif.type === 'like') {
            const opName = operatorMap.get(notif.operator_id)?.codename || notif.operator_id;
            text = `${opName} 点赞了你的动态`;
        } else if (notif.type === 'reply') {
            const opName = operatorMap.get(notif.operator_id)?.codename || notif.operator_id;
            text = `${opName} 回复了你`;
            if (notif.content) text += `：${notif.content.slice(0, 50)}`;
        } else if (notif.type === 'mention') {
            const opName = operatorMap.get(notif.operator_id)?.codename || notif.operator_id;
            text = `${opName} 提到了你`;
        } else if (notif.type === 'new_dynamic') {
            const opName = operatorMap.get(notif.operator_id)?.codename || notif.operator_id;
            text = `${opName} 发布了新动态`;
        } else {
            text = notif.content || '新消息';
        }
        html += `
            <div class="notification-item" data-dynamic-id="${notif.related_dynamic_id || ''}" data-comment-id="${notif.related_comment_id || ''}" style="padding: 12px; border-bottom: 1px solid var(--border-color); cursor: pointer;">
                <div style="font-weight: ${notif.is_read ? 'normal' : 'bold'}">${escapeHtml(text)}</div>
                <div style="font-size: 12px; color: var(--text-secondary);">${time}</div>
            </div>
        `;
    }
    container.innerHTML = html;

    // 绑定点击跳转
    container.querySelectorAll('.notification-item').forEach(item => {
        item.addEventListener('click', () => {
            const dynamicId = item.dataset.dynamicId;
            if (dynamicId) {
                closeNotificationsSheet();
                scrollToDynamic(dynamicId);
            }
        });
    });

    // 标记所有为已读（仅当接口可用时）
    if (!error) {
        try {
            await fetch('/dynamics/notifications/mark_read', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({persona_id: window.currentPersonaId || currentPersonaId || 'doctor'}) });
        } catch(e) { /* ignore */ }
    }
    await fetchUnreadCount();
}

// 打开通知半页框
function openNotificationsSheet() {
    loadNotifications();
    openBottomSheet('notifications-bottom-sheet');
}

// 关闭通知半页框
function closeNotificationsSheet() {
    closeBottomSheet('notifications-bottom-sheet');
}

// 标记有新动态（由 WebSocket 调用）
function markNewDynamic() {
    localStorage.setItem('hasNewDynamic', 'true');
    fetchUnreadCount();
}

// 滚动到指定动态并高亮
async function scrollToDynamic(dynamicId) {
    if (getCurrentPageId() !== 'zoot-dynamics') {
        showPage('zoot-dynamics');
        await new Promise(resolve => setTimeout(resolve, 500));
    }
    const card = document.querySelector(`.dynamic-card[data-id="${dynamicId}"]`);
    if (card) {
        card.scrollIntoView({ behavior: 'smooth', block: 'center' });
        card.classList.add('highlight');
        setTimeout(() => card.classList.remove('highlight'), 2000);
    } else {
        await renderDynamics();
        const newCard = document.querySelector(`.dynamic-card[data-id="${dynamicId}"]`);
        if (newCard) newCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
}


// ========== 43.3. 罗德岛本舰页 ==========
function initRhodesIslandPage() {
    showUnderDevelopmentModal();
    const btns = document.querySelectorAll('.rhodes-bottom-btn');
    btns.forEach(btn => {
        btn.removeEventListener('click', rhodesBtnHandler);
        btn.addEventListener('click', rhodesBtnHandler);
    });

    function rhodesBtnHandler(e) {
        const panel = e.currentTarget.dataset.panel;
        if (panel === 'location') openBottomSheet('location-bottom-sheet');
        else if (panel === 'characters') openBottomSheet('characters-bottom-sheet');
        else if (panel === 'chat') openBottomSheet('chat-bottom-sheet');
    }

    initRhodesShipScene();
}

async function initRhodesShipScene() {
    const canvas = document.getElementById('rhodes-scene-canvas');
    const host = document.getElementById('rhodes-3d-container');
    if (!canvas || !host) return;
    try {
        if (!window.ZootShipScene) await import('/static/js/ship-scene.js?v=20260722-100-0674');
        if (window.ZootShipScene) return await window.ZootShipScene.mount(canvas, host);
    } catch (error) {
        console.warn('[ship-3d] WebGL 初始化失败，使用静态降级视图', error);
    }
    if (window._rhodesShipScene?.canvas === canvas) { window._rhodesShipScene.resize(); return; }
    const state = { canvas, host, ctx: canvas.getContext('2d'), manifest:null, facilities:[], presence:[], environment:null, zoom:1, panX:0, panY:30, hits:[], dragging:false, moved:false, pointerX:0, pointerY:0 };
    window._rhodesShipScene=state;
    const shade=(hex,amount)=>{const value=parseInt((hex||'#607d8b').slice(1),16),part=shift=>Math.max(0,Math.min(255,((value>>shift)&255)+amount));return `rgb(${part(16)},${part(8)},${part(0)})`;};
    const project=(x,y,z=0)=>({x:canvas.clientWidth/2+state.panX+(x-y)*28*state.zoom,y:canvas.clientHeight*.23+state.panY+(x+y)*14*state.zoom-z*28*state.zoom});
    const polygon=(points,fill,stroke='rgba(225,245,250,.18)')=>{const c=state.ctx;c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.closePath();c.fillStyle=fill;c.fill();c.strokeStyle=stroke;c.stroke();};
    const draw=()=>{const c=state.ctx;c.clearRect(0,0,canvas.clientWidth,canvas.clientHeight);state.hits=[];polygon([project(-9,-5),project(9,-5),project(9,14),project(-9,14)],'rgba(70,91,101,.72)','rgba(165,210,224,.32)');c.strokeStyle='rgba(160,205,219,.09)';for(let n=-8;n<=13;n++){const a=project(-9,n),b=project(9,n);c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.stroke();}const facilities=[...(state.manifest?.facilities||[])].sort((a,b)=>(a.x+a.y)-(b.x+b.y));facilities.forEach(f=>{const x0=f.x-f.w/2,x1=f.x+f.w/2,y0=f.y-f.d/2,y1=f.y+f.d/2,h=f.h,top=[project(x0,y0,h),project(x1,y0,h),project(x1,y1,h),project(x0,y1,h)];polygon([project(x1,y0),project(x1,y1),top[2],top[1]],shade(f.color,-24));polygon([project(x0,y1),project(x1,y1),top[2],top[3]],shade(f.color,-40));polygon(top,shade(f.color,15));state.hits.push({facility:f,points:top});const p=project(f.x,f.y,h+.25);c.fillStyle='#eaf8fb';c.font=`${Math.max(10,12*state.zoom)}px sans-serif`;c.textAlign='center';c.fillText(f.name,p.x,p.y);});state.presence.forEach((op,index)=>{const f=facilities.find(item=>item.id===op.facility_id);if(!f)return;const p=project(f.x+(index%3-1)*.4,f.y+1+Math.floor(index/3)*.35,f.h+.2);c.beginPath();c.arc(p.x,p.y,4.5,0,Math.PI*2);c.fillStyle=op.activity==='alert'?'#ff8b78':'#73d6ae';c.fill();});};
    state.resize=()=>{const rect=host.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,1.5);canvas.width=Math.max(320,Math.round(rect.width*dpr));canvas.height=Math.max(360,Math.round(rect.height*dpr));canvas.style.width=rect.width+'px';canvas.style.height=rect.height+'px';state.ctx.setTransform(dpr,0,0,dpr,0,0);draw();};
    const pointIn=(x,y,pts)=>{let inside=false;for(let i=0,j=pts.length-1;i<pts.length;j=i++){if(((pts[i].y>y)!==(pts[j].y>y))&&x<(pts[j].x-pts[i].x)*(y-pts[i].y)/(pts[j].y-pts[i].y)+pts[i].x)inside=!inside;}return inside;};
    const showFacility=facility=>{const panel=document.getElementById('ship-facility-panel');if(!panel)return;const fs=state.facilities.find(x=>x.facility_id===facility.id)||{},operators=state.presence.filter(x=>x.facility_id===facility.id);panel.hidden=false;panel.innerHTML=`<h3><span class="ship-status-dot"></span>${escapeHtml(facility.name)}</h3><p>状态：${escapeHtml(fs.status||'normal')} · 在场 ${operators.length}${fs.capacity?` / ${fs.capacity}`:''}</p><p>${escapeHtml(fs.summary||'设施运行正常')}</p><p>${operators.length?`活动：${operators.map(x=>escapeHtml(x.operator_id)+' · '+escapeHtml(x.activity)).join('、')}`:'当前没有登记在场干员'}</p>${facility.id==='zoot-core'?'<button class="zoot-facility-entry" onclick="showPage(\'zoot-runtime\')">进入 ZOOT 管理页</button>':''}`;};
    const updateEnvironmentBar=()=>{const env=state.environment,bar=document.getElementById('ship-environment-bar');if(env&&bar)bar.textContent=`${env.location} · ${env.weather} · ${env.time_period} · ${env.route_name} → ${env.destination}（${Math.round((env.route_progress||0)*100)}%）`;};
    const showEnvironmentEditor=()=>{const env=state.environment,panel=document.getElementById('ship-facility-panel');if(!env||!panel)return;panel.hidden=false;panel.innerHTML=`<h3>世界环境与航线</h3><label>地点<input id="ship-env-location" value="${escapeHtml(env.location||'')}"></label><label>天气<input id="ship-env-weather" value="${escapeHtml(env.weather||'')}"></label><label>航线<input id="ship-env-route" value="${escapeHtml(env.route_name||'')}"></label><label>目的地<input id="ship-env-destination" value="${escapeHtml(env.destination||'')}"></label><label>航程 %<input id="ship-env-progress" type="number" min="0" max="100" value="${Math.round((env.route_progress||0)*100)}"></label><button id="ship-env-save">保存环境</button>`;document.getElementById('ship-env-save').onclick=async()=>{const body={location:document.getElementById('ship-env-location').value,weather:document.getElementById('ship-env-weather').value,route_name:document.getElementById('ship-env-route').value,destination:document.getElementById('ship-env-destination').value,route_progress:Number(document.getElementById('ship-env-progress').value)/100};const response=await fetch('/ship-base/environment',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(response.ok){state.environment=await response.json();updateEnvironmentBar();panel.hidden=true;}};};
    canvas.addEventListener('pointerdown',e=>{state.dragging=true;state.moved=false;state.pointerX=e.clientX;state.pointerY=e.clientY;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!state.dragging)return;const dx=e.clientX-state.pointerX,dy=e.clientY-state.pointerY;if(Math.abs(dx)+Math.abs(dy)>3)state.moved=true;state.panX+=dx;state.panY+=dy;state.pointerX=e.clientX;state.pointerY=e.clientY;draw();});canvas.addEventListener('pointerup',e=>{state.dragging=false;if(state.moved)return;const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,hit=[...state.hits].reverse().find(item=>pointIn(x,y,item.points));if(hit)showFacility(hit.facility);});canvas.addEventListener('wheel',e=>{e.preventDefault();state.zoom=Math.max(.5,Math.min(2,state.zoom*(e.deltaY>0?.9:1.1)));draw();},{passive:false});
    host.querySelectorAll('[data-ship-action]').forEach(button=>button.onclick=()=>{const action=button.dataset.shipAction;if(action==='reset'){state.zoom=1;state.panX=0;state.panY=30;}else state.zoom=Math.max(.5,Math.min(2,state.zoom*(action==='zoom-in'?1.15:.85)));draw();});const environmentBar=document.getElementById('ship-environment-bar');if(environmentBar){environmentBar.title='点击编辑世界环境';environmentBar.onclick=showEnvironmentEditor;}new ResizeObserver(()=>state.resize()).observe(host);
    try{const responses=await Promise.all([fetch('/ship-base/manifest'),fetch('/ship-base/facilities'),fetch('/ship-base/presence'),fetch('/ship-base/environment')]);if(!responses.every(res=>res.ok))throw new Error('本舰数据接口不可用');state.manifest=await responses[0].json();state.facilities=(await responses[1].json()).facilities||[];state.presence=(await responses[2].json()).operators||[];state.environment=await responses[3].json();updateEnvironmentBar();}catch(error){console.error('[ship-base]',error);state.manifest={facilities:[]};const bar=document.getElementById('ship-environment-bar');if(bar)bar.textContent='本舰环境暂不可用';}state.resize();
}

let systemCenterActiveSection = 'monitor';
function setSystemCenterSection(section='monitor'){const normalized=section==='world-runtime'?'world-runtime':'monitor';systemCenterActiveSection=normalized;document.querySelectorAll('[data-system-section]').forEach(button=>{const active=button.dataset.systemSection===normalized;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));if(!button.dataset.systemSectionBound){button.dataset.systemSectionBound='true';button.addEventListener('click',()=>setSystemCenterSection(button.dataset.systemSection));}});document.querySelectorAll('[data-system-section-content]').forEach(content=>{const active=content.dataset.systemSectionContent===normalized;content.hidden=!active;content.classList.toggle('active',active);});const monitorControls=document.querySelector('.system-center-view-switch');if(monitorControls)monitorControls.hidden=normalized!=='monitor';const monitorRefresh=document.getElementById('system-center-refresh');if(monitorRefresh)monitorRefresh.hidden=normalized!=='monitor';if(normalized==='world-runtime')initZootRuntimePage();else if(typeof SystemCenterUI!=='undefined'){SystemCenterUI.init();SystemCenterUI.load(false);}}
function openSystemCenterSection(section='monitor'){showPage(`settings-system-center?section=${section==='world-runtime'?'world-runtime':'monitor'}`);}
function expandSystemCenter(section=systemCenterActiveSection){openSystemCenterSection(section);}
function collapseSystemCenterToSettings(){goBack();}
let zootRuntimeData=null,zootContextStats=null,zootRuntimeTab='overview';const zootPressureLabels={story:'叙事',social:'社交',supply:'物资',finance:'财务',medical:'医疗',security:'安全'};
let zootIntentData=null;
const zootIntentStatusLabels={proposed:'待安排',scheduled:'等待触发',due:'已到期',evaluating:'正在复核',review_required:'需要确认',blocked:'等待条件',executed:'已执行',adapted:'已适配执行',satisfied:'目标已完成',cancelled:'已取消',expired:'已过期',failed:'执行失败'};

async function loadZootIntents(force=false){
    if(zootIntentData&&!force)return zootIntentData;
    const response=await fetch('/zoot/intents?limit=120');
    if(!response.ok)throw new Error('计划意图读取失败');
    zootIntentData=await response.json();
    return zootIntentData;
}

function formatIntentTime(value){
    const number=Number(value);
    return Number.isFinite(number)?new Date(number*1000).toLocaleString():'未设置';
}

function operatorIntentCard(intent){
    const id=escapeHtml(String(intent.intent_id||''));
    const status=escapeHtml(zootIntentStatusLabels[intent.status]||intent.status||'未知');
    const target=escapeHtml(`${intent.executor_operator_id||'未知干员'} → ${intent.target_id||'doctor'}`);
    const active=!['executed','adapted','satisfied','cancelled','expired','failed'].includes(intent.status);
    const approve=['review_required','blocked'].includes(intent.status)?`<button type="button" onclick="approveOperatorIntent('${id}')">确认执行</button>`:'';
    const evaluate=intent.status==='scheduled'?`<button type="button" onclick="evaluateOperatorIntent('${id}')">立即复核</button>`:'';
    return `<article class="zoot-runtime-card operator-intent-card" data-intent-status="${escapeHtml(intent.status||'')}"><header><b>${escapeHtml(intent.intent_type||'follow_up')} · ${target}</b><span>${status}</span></header><p>${escapeHtml(intent.reason||intent.semantic_goal||'未填写原因')}</p><blockquote>${escapeHtml(intent.action_outline||'将在复核后确定表达内容')}</blockquote><div class="operator-intent-meta"><span>触发 ${formatIntentTime(intent.preferred_at)}</span><span>有效至 ${formatIntentTime(intent.latest_at)}</span><span>${escapeHtml(intent.action_type||'')}</span></div><div class="operator-intent-actions">${approve}${evaluate}<button type="button" onclick="showOperatorIntentTrace('${id}')">判断记录</button>${active?`<button class="danger" type="button" onclick="cancelOperatorIntent('${id}')">取消计划</button>`:''}</div><div id="intent-trace-${id}" class="operator-intent-trace" hidden></div></article>`;
}

async function renderZootIntentCenter(box){
    if(!box)return;
    box.innerHTML='<article class="zoot-runtime-card">正在读取计划意图…</article>';
    try{
        const data=await loadZootIntents();
        const settingsResponse=await fetch('/zoot/intents/settings');
        const settings=settingsResponse.ok?await settingsResponse.json():{};
        const groups=[['需要确认',['review_required','blocked','failed']],['即将触发',['scheduled','due','evaluating']],['最近结束',['executed','adapted','satisfied','cancelled','expired']]];
        const cards=groups.map(([title,states])=>{const items=(data.items||[]).filter(item=>states.includes(item.status));return `<section class="operator-intent-group"><header><b>${title}</b><span>${items.length}</span></header>${items.map(operatorIntentCard).join('')||'<p class="operator-intent-empty">暂无记录</p>'}</section>`;}).join('');
        box.innerHTML=`<section class="operator-intent-settings"><header><div><b>干员计划意图</b><small>规则优先，语境不确定时不会发送</small></div><label class="zoot-check"><input id="intent-enabled" type="checkbox" ${settings.enabled?'checked':''}> 启用</label></header><div class="operator-intent-setting-grid"><label>运行预设<select id="intent-preset"><option value="conservative">保守</option><option value="standard">标准</option><option value="immersive">沉浸</option></select></label><label>每名干员每日上限<input id="intent-daily-limit" type="number" min="0" max="20" value="${Number(settings.per_operator_daily_limit)||3}"></label><label>安静时段开始<input id="intent-quiet-start" type="time" value="${escapeHtml(settings.quiet_hours_start||'23:00')}"></label><label>安静时段结束<input id="intent-quiet-end" type="time" value="${escapeHtml(settings.quiet_hours_end||'07:00')}"></label></div><button type="button" onclick="saveOperatorIntentSettings()">保存计划设置</button></section>${cards}`;
        const preset=document.getElementById('intent-preset');
        if(preset)preset.value=settings.preset||'standard';
        const settingGrid=document.querySelector('.operator-intent-setting-grid');
        if(settingGrid){const allowed=new Set(settings.allowed_auto_actions||[]);settingGrid.insertAdjacentHTML('beforeend',`<fieldset class="operator-intent-auto-actions"><legend>高置信时允许自动执行</legend>${[['private_message','私聊'],['scenario_action','情景动作'],['local_notification','本地通知'],['local_draft','本地草稿']].map(([value,label])=>`<label><input type="checkbox" name="intent-auto-action" value="${value}" ${allowed.has(value)?'checked':''}> ${label}</label>`).join('')}</fieldset>`);}
    }catch(error){
        box.innerHTML=`<article class="zoot-runtime-card" data-state="error">${escapeHtml(error.message||'计划意图不可用')}<button type="button" onclick="retryOperatorIntentLoad()">重试</button></article>`;
    }
}

function retryOperatorIntentLoad(){zootIntentData=null;renderZootRuntimeContent();}
async function mutateOperatorIntent(id,action,body={}){const response=await fetch(`/zoot/intents/${encodeURIComponent(id)}/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error((await response.text())||'计划操作失败');zootIntentData=null;await renderZootIntentCenter(document.getElementById('zoot-runtime-content'));}
async function evaluateOperatorIntent(id){try{await mutateOperatorIntent(id,'evaluate',{force_review:true});}catch(error){showToast(error.message,3000,'error');}}
async function approveOperatorIntent(id){try{await mutateOperatorIntent(id,'approve');}catch(error){showToast(error.message,3000,'error');}}
function cancelOperatorIntent(id){showConfirmDialog('取消计划','取消后该计划不会再自动触发，是否继续？',async()=>{try{await mutateOperatorIntent(id,'cancel',{reason:'user_cancelled'});}catch(error){showToast(error.message,3000,'error');}});}
async function showOperatorIntentTrace(id){const target=document.getElementById(`intent-trace-${id}`);if(!target)return;if(!target.hidden){target.hidden=true;return;}const response=await fetch(`/zoot/intents/${encodeURIComponent(id)}/trace`);if(!response.ok){showToast('判断记录读取失败',2500,'error');return;}const data=await response.json();target.innerHTML=(data.items||[]).map(item=>`<p><time>${formatIntentTime(item.created_at)}</time><b>${escapeHtml(zootIntentStatusLabels[item.to_status]||item.to_status)}</b><span>${escapeHtml(item.reason_code||'')}</span></p>`).join('')||'<p>暂无判断记录</p>';target.hidden=false;}
async function saveOperatorIntentSettings(){const payload={enabled:Boolean(document.getElementById('intent-enabled')?.checked),preset:document.getElementById('intent-preset')?.value||'standard',per_operator_daily_limit:Number(document.getElementById('intent-daily-limit')?.value||3),quiet_hours_start:document.getElementById('intent-quiet-start')?.value||'23:00',quiet_hours_end:document.getElementById('intent-quiet-end')?.value||'07:00',allowed_auto_actions:Array.from(document.querySelectorAll('input[name="intent-auto-action"]:checked')).map(input=>input.value)};const response=await fetch('/zoot/intents/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok){showToast('计划设置保存失败',3000,'error');return;}zootIntentData=null;showToast('计划设置已保存',1800,'success');}
function initZootRuntimePage(){document.querySelectorAll('.zoot-runtime-tabs button').forEach(button=>{if(button.dataset.zootRuntimeBound)return;button.dataset.zootRuntimeBound='true';button.addEventListener('click',()=>{zootRuntimeTab=button.dataset.zootTab;document.querySelectorAll('.zoot-runtime-tabs button').forEach(x=>x.classList.toggle('active',x===button));renderZootRuntimeContent();});});refreshZootRuntime(false);}
async function refreshZootRuntime(runTick=false){const state=document.getElementById('zoot-runtime-state');const strip=state?.closest('.zoot-runtime-status-strip');if(state)state.textContent=runTick?'感知中':'同步中';if(strip)strip.dataset.status='attention';try{if(runTick){const tick=await fetch('/zoot/tick',{method:'POST'});if(!tick.ok)throw new Error('tick failed');}const [overview,contextStats]=await Promise.all([fetch('/zoot/overview'),fetch('/zoot/context/stats')]);if(!overview.ok)throw new Error('overview failed');zootRuntimeData=await overview.json();zootContextStats=contextStats.ok?await contextStats.json():null;if(state)state.textContent=zootRuntimeData.running?'运行中':'待机';if(strip)strip.dataset.status=zootRuntimeData.running?'ok':'attention';renderZootRuntime();}catch(error){if(state)state.textContent='不可用';if(strip)strip.dataset.status='error';console.error('[ZOOT]',error);}}
function renderZootRuntime(){if(!zootRuntimeData)return;const grid=document.getElementById('zoot-pressure-grid');if(grid)grid.innerHTML=(zootRuntimeData.pressures||[]).map(p=>{const trend=Number(p.trend)||0;return `<article class="zoot-pressure-card industrial-segment-card"><b>${zootPressureLabels[p.key]||escapeHtml(p.key)}</b><span class="zoot-pressure-value">${Math.round((p.value||0)*100)}</span><small>% · ${trend>0?'↑':trend<0?'↓':'→'}</small><div class="zoot-pressure-track"><i style="width:${Math.round((p.value||0)*100)}%"></i></div></article>`;}).join('');const summary=document.getElementById('zoot-runtime-summary-matrix');if(summary){const commands=zootRuntimeData.commands||[];const contextTotal=Number(zootContextStats?.documents)||0;const contextReady=Number(zootContextStats?.vectorized)||0;summary.innerHTML=[['EVT','事件',Number(zootRuntimeData.event_count)||0],['PLN','规划',(zootRuntimeData.plans||[]).filter(item=>!['completed','cancelled'].includes(item.status)).length],['CMD','命令',commands.filter(item=>item.status==='approval_required'||item.status==='failed').length],['CTX','上下文',contextTotal?`${Math.round(contextReady/contextTotal*100)}%`:'N/A']].map(([code,label,value])=>`<article class="industrial-status-cell"><b>${code}</b><span>${label}</span><strong>${value}</strong></article>`).join('');}const toggle=document.getElementById('zoot-planning-toggle');if(toggle)toggle.textContent=zootRuntimeData.settings?.auto_planning?'暂停规划':'恢复规划';renderZootRuntimeContent();}
function renderZootRuntimeContent(){const box=document.getElementById('zoot-runtime-content');if(!box||!zootRuntimeData)return;const d=zootRuntimeData;if(zootRuntimeTab==='overview'){box.innerHTML=`<div class="zoot-overview-grid"><div class="zoot-metric"><strong>${d.event_count||0}</strong><span>已感知事实</span></div><div class="zoot-metric"><strong>${d.pending_events||0}</strong><span>待投影事件</span></div><div class="zoot-metric"><strong>${zootContextStats?.documents||0}</strong><span>上下文文档</span></div></div><article class="zoot-runtime-card"><header><b>运行说明</b><span>NO TOKEN CONSUMPTION</span></header><p>ZOOT 通过实时事件、状态投影和受控规划维持全局环境；跨功能区上下文由本地混合检索选择。</p></article>`;return;}if(zootRuntimeTab==='events'){box.innerHTML=(d.states?.recent||[]).slice().reverse().map(x=>`<article class="zoot-runtime-card"><header><b>${escapeHtml(x.type)}</b><time>${new Date(x.at*1000).toLocaleString()}</time></header><p>来源：${escapeHtml(x.source)} · 重要度 ${Math.round((x.importance||0)*100)}%</p></article>`).join('')||'<article class="zoot-runtime-card">暂无事件</article>';return;}if(zootRuntimeTab==='plans'){box.innerHTML=(d.plans||[]).map(x=>`<article class="zoot-runtime-card"><header><b>${escapeHtml(x.plan_type)}</b><span>${Math.round((x.score||0)*100)} · ${escapeHtml(x.status)}</span></header><p>${escapeHtml(x.reason||'')}</p></article>`).join('')||'<article class="zoot-runtime-card">暂无规划候选</article>';return;}if(zootRuntimeTab==='commands'){box.innerHTML=(d.commands||[]).map(x=>`<article class="zoot-runtime-card"><header><b>${escapeHtml(x.command_type)}</b><span>${escapeHtml(x.status)} · ${escapeHtml(x.risk)}</span></header><p>${escapeHtml(x.reason||'')}</p>${x.status==='approval_required'?`<div class="zoot-command-actions"><button onclick="approveZootCommand('${escapeHtml(String(x.id))}')">批准</button><button onclick="cancelZootCommand('${escapeHtml(String(x.id))}')">取消</button></div>`:''}</article>`).join('')||'<article class="zoot-runtime-card">暂无命令</article>';return;}if(zootRuntimeTab==='context'){const sources=(zootContextStats?.sources||[]).slice(0,10);box.innerHTML=`<div class="zoot-overview-grid"><div class="zoot-metric"><strong>${zootContextStats?.documents||0}</strong><span>有效文档</span></div><div class="zoot-metric"><strong>${zootContextStats?.vectorized||0}</strong><span>已向量化</span></div><div class="zoot-metric"><strong>${zootContextStats?.snapshots||0}</strong><span>调用快照</span></div></div><article class="zoot-runtime-card"><header><b>上下文来源</b><button onclick="reindexZootContext()">增量索引</button></header><p>${sources.map(x=>`${escapeHtml(x.source)} · ${x.count}`).join('<br>')||'等待首次感知'}</p></article><div class="zoot-context-preview"><input id="zoot-context-query" placeholder="输入主题，预览注入内容"><select id="zoot-context-purpose"><option value="private_chat">私聊</option><option value="group_chat">群聊</option><option value="assistant">助理</option><option value="event_generation">事件</option><option value="dispatch_generation">外勤</option></select><button onclick="previewZootContext()">检索预览</button><pre id="zoot-context-preview-result">尚未检索</pre></div>`;return;}const s=d.settings||{};box.innerHTML=`<div class="zoot-policy-form"><label>运行间隔（秒）<input id="zoot-tick-seconds" type="number" min="10" value="${Number(s.tick_seconds)||60}"></label>${[['story','叙事',.62],['social','社交',.58],['supply','物资',.65],['finance','财务',.7],['medical','医疗',.65],['security','安全',.65]].map(([k,label,fallback])=>`<label>${label}阈值<input id="zoot-${k}-threshold" type="number" min="0" max="1" step=".01" value="${Number(s[`${k}_threshold`])||fallback}"></label>`).join('')}<label class="zoot-check"><input id="zoot-auto-execute" type="checkbox" ${s.auto_execute_low_risk?'checked':''}> 自动执行已批准的低风险命令</label><button onclick="saveZootPolicies()">保存策略</button></div>`;}
async function toggleZootPlanning(){if(!zootRuntimeData)return;await fetch('/zoot/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({auto_planning:!zootRuntimeData.settings.auto_planning})});await refreshZootRuntime(false);}
async function saveZootPolicies(){const body={tick_seconds:Number(document.getElementById('zoot-tick-seconds').value),auto_execute_low_risk:document.getElementById('zoot-auto-execute').checked};['story','social','supply','finance','medical','security'].forEach(k=>body[`${k}_threshold`]=Number(document.getElementById(`zoot-${k}-threshold`).value));await fetch('/zoot/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});await refreshZootRuntime(false);}

const renderZootRuntimeContentWithoutIntents=renderZootRuntimeContent;
renderZootRuntimeContent=function renderZootRuntimeContentWithIntents(){
    const box=document.getElementById('zoot-runtime-content');
    if(zootRuntimeTab==='intents'){
        renderZootIntentCenter(box);
        return;
    }
    renderZootRuntimeContentWithoutIntents();
};

const renderZootRuntimeWithoutIntentSummary=renderZootRuntime;
renderZootRuntime=function renderZootRuntimeWithIntentSummary(){
    renderZootRuntimeWithoutIntentSummary();
    const summary=document.getElementById('zoot-runtime-summary');
    if(!summary||summary.querySelector('[data-runtime-summary="intent"]'))return;
    const runtime=zootRuntimeData?.operator_intents||{};
    summary.insertAdjacentHTML('afterbegin',`<button type="button" class="industrial-mini-tile" data-runtime-summary="intent" data-state="${runtime.review_required?'attention':runtime.active?'active':'ok'}" onclick="document.querySelector('[data-zoot-tab=intents]')?.click()"><b>INT</b><span>计划意图</span><small>${Number(runtime.active)||0} 活动 · ${Number(runtime.review_required)||0} 待确认</small></button>`);
};

const ZOOT_SETTINGS_FIELDS = [['story','叙事',.62],['social','社交',.58],['supply','物资',.65],['finance','财务',.7],['medical','医疗',.65],['security','安全',.65]];
async function loadZootSettingsPage(){
    const response=await fetch('/zoot/settings');
    if(!response.ok){showToast('ZOOT 参数加载失败',2200,'error');return;}
    const data=await response.json();
    document.getElementById('settings-zoot-auto-planning').checked=data.auto_planning!==false;
    document.getElementById('settings-zoot-auto-execute').checked=!!data.auto_execute_low_risk;
    document.getElementById('settings-zoot-tick-seconds').value=Number(data.tick_seconds)||60;
    document.getElementById('settings-zoot-thresholds').innerHTML=ZOOT_SETTINGS_FIELDS.map(([key,label,fallback])=>`<label class="settings-field">${label}阈值（%）<input id="settings-zoot-${key}" type="number" min="0" max="100" step="1" value="${Math.round(Number(data[`${key}_threshold`]??fallback)*100)}"></label>`).join('');
}
async function saveZootSettingsPage(){
    const body={auto_planning:document.getElementById('settings-zoot-auto-planning').checked,auto_execute_low_risk:document.getElementById('settings-zoot-auto-execute').checked,tick_seconds:Number(document.getElementById('settings-zoot-tick-seconds').value)};
    ZOOT_SETTINGS_FIELDS.forEach(([key])=>body[`${key}_threshold`]=Math.max(0,Math.min(100,Number(document.getElementById(`settings-zoot-${key}`).value)))/100);
    const response=await fetch('/zoot/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
    showToast(response.ok?'ZOOT 参数已保存':'ZOOT 参数保存失败',2200,response.ok?'success':'error');
}
async function loadShipSettingsPage(){
    const [displayResponse,environmentResponse]=await Promise.all([fetch('/ship-base/display-settings'),fetch('/ship-base/environment')]);
    if(!displayResponse.ok||!environmentResponse.ok){showToast('本舰设置加载失败',2200,'error');return;}
    const display=await displayResponse.json(),environment=await environmentResponse.json();
    document.getElementById('settings-ship-style').value=display.style||'blueprint';
    document.getElementById('settings-ship-detail').value=display.detail_level||'low';
    document.getElementById('settings-ship-mode').value=display.display_mode||'single';
    document.getElementById('settings-ship-deck').value=String(display.active_deck||'top');
    document.getElementById('settings-ship-shadow').checked=!!display.shadow_enabled;
    document.getElementById('settings-ship-image-context').checked=display.export_to_image_context!==false;
    document.getElementById('settings-ship-location').value=environment.location||'';
    document.getElementById('settings-ship-weather').value=environment.weather||'';
    document.getElementById('settings-ship-route').value=environment.route_name||'';
    document.getElementById('settings-ship-destination').value=environment.destination||'';
    document.getElementById('settings-ship-movement').value=environment.movement_state||'moving';
    document.getElementById('settings-ship-progress').value=Math.round((Number(environment.route_progress)||0)*100);
}
