// ========== 43.4. 对外联络页 ==========
/**
 * 获取所有非罗德岛干员，并按势力分组
 * @returns {Object} { factions: ['势力1','势力2',...], operatorsByFaction: { '势力1': [op1, op2], ... } }
 */
function getExternalOperatorsGrouped() {
    const factionsSet = new Set();
    const operatorsByFaction = {};

    // 遍历所有干员（operatorMap 的 values）
    const allOps = Array.from(operatorMap.values());
    for (const op of allOps) {
        // 从 operatorDetails 中获取 origin（该字段在 loadAllOperatorDetails 中填充）
        const detail = operatorDetails[op.id];
        let origin = (detail && detail.origin) ? detail.origin : '';
        // 如果 origin 仍然为空，尝试从 op 的 origin 获取（如果存在）
        if (!origin && op.origin) origin = op.origin;

        // 排除罗德岛干员（origin 为 '罗德岛' 或 空值）
        if (!origin || origin === '罗德岛') continue;

        // 添加势力
        factionsSet.add(origin);
        if (!operatorsByFaction[origin]) operatorsByFaction[origin] = [];
        operatorsByFaction[origin].push({
            id: op.id,
            name: op.codename,
            avatar: getOperatorAvatarUrl(op.id),
            origin: origin
        });
    }

    // 排序势力（可选）
    const factions = Array.from(factionsSet).sort();
    return { factions, operatorsByFaction };
}

/**
 * 渲染对外联络页势力标签和角色列表
 * @param {string} activeFaction 当前激活的势力（默认 'all'）
 */
function renderExternalContactPage(activeFaction = null) {
    const { factions, operatorsByFaction } = getExternalOperatorsGrouped();
    const tabsContainer = document.getElementById('external-faction-tabs');
    const listContainer = document.getElementById('external-contact-list');
    if (!tabsContainer || !listContainer) return;

    // 生成标签 HTML
    let tabsHtml = '<div class="faction-tab active" data-faction="all">全部</div>';
    for (const faction of factions) {
        tabsHtml += `<div class="faction-tab" data-faction="${escapeHtml(faction)}">${escapeHtml(faction)}</div>`;
    }
    tabsContainer.innerHTML = tabsHtml;

    if (!activeFaction) activeFaction = 'all';

    // 绑定标签点击事件
    const tabs = tabsContainer.querySelectorAll('.faction-tab');
    tabs.forEach(tab => {
        tab.removeEventListener('click', factionClickHandler);
        tab.addEventListener('click', factionClickHandler);
    });

    function factionClickHandler(e) {
        const faction = e.currentTarget.dataset.faction;
        tabs.forEach(t => t.classList.remove('active'));
        e.currentTarget.classList.add('active');
        renderExternalContactList(faction, operatorsByFaction);
    }

    renderExternalContactList(activeFaction, operatorsByFaction);
}

/**
 * 渲染指定势力的角色列表
 * @param {string} faction 'all' 或具体势力名称
 * @param {Object} operatorsByFaction 分组数据
 */
function renderExternalContactList(faction, operatorsByFaction) {
    const listContainer = document.getElementById('external-contact-list');
    if (!listContainer) return;

    let operatorsToShow = [];
    if (faction === 'all') {
        for (const ops of Object.values(operatorsByFaction)) {
            operatorsToShow.push(...ops);
        }
    } else {
        operatorsToShow = operatorsByFaction[faction] || [];
    }

    if (operatorsToShow.length === 0) {
        listContainer.innerHTML = '<div class="empty-state" style="text-align:center; padding:20px;">暂无该势力角色</div>';
        return;
    }

    listContainer.innerHTML = operatorsToShow.map(op => `
        <div class="contact-item" data-operator-id="${op.id}" data-type="external">
            <img src="${op.avatar}" class="contact-avatar" onerror="this.src='/static/avatars/default.webp'">
            <div class="contact-name">${escapeHtml(op.name)}</div>
            <div class="contact-faction" style="font-size: 12px; color: var(--text-secondary);">${escapeHtml(op.origin)}</div>
        </div>
    `).join('');

    listContainer.querySelectorAll('.contact-item').forEach(item => {
        item.addEventListener('click', () => {
            const opId = item.dataset.operatorId;
            showOperatorDetail(opId);
        });
    });
}

// 对外联络页初始化入口（在 showPage 中调用）
function initExternalContactPage() {
    // 确保 operatorDetails 已加载完成
    if (operatorDetailsLoaded.size < operators.length) {
        loadAllOperatorDetails().finally(renderExternalContactPage);
        return;
    }
    renderExternalContactPage();
}

