let financeHistoryOffset = 0;
const FINANCE_HISTORY_LIMIT = 20;

async function loadFinanceOverview() {
    try {
        const res = await fetch('/finance/overview');
        if (!res.ok) throw new Error('加载失败');
        const data = await res.json();

        document.getElementById('total-assets').textContent = formatFinance(data.total_assets);
        document.getElementById('doctor-balance').textContent = formatFinance(data.doctor_balance);
        document.getElementById('rhodes-balance').textContent = formatFinance(data.rhodes_balance);
        document.getElementById('net-worth').textContent = formatFinance(data.net_worth);
        document.getElementById('today-income').textContent = formatFinance(data.today_income);
        document.getElementById('today-expense').textContent = formatFinance(data.today_expense);

        // 加载交易历史
        loadFinanceHistory();

        // 更新底部导航红点
        updateNavBadges();

        return data;
    } catch (e) {
        console.error('加载财务概览失败', e);
        return null;
    }
}

async function loadFinanceHistory(append = false) {
    try {
        const url = `/finance/history?wallet_type=doctor&limit=${FINANCE_HISTORY_LIMIT}&since=0`;
        const res = await fetch(url);
        if (!res.ok) throw new Error('加载失败');
        const data = await res.json();
        const container = document.getElementById('finance-history-list');
        if (!container) return;

        const html = data.map(tx => {
            const isIncome = tx.amount > 0;
            const amountStr = (isIncome ? '+' : '') + formatFinance(tx.amount);
            const time = new Date(tx.timestamp * 1000).toLocaleString();
            const categoryMap = {
                'income': '收入', 'expense': '支出', 'reward': '奖励',
                'task_dispatch': '任务派遣', 'task_reward': '任务奖励',
                'maintenance': '维护', 'pharmacy_production': '制药生产',
                'pharmacy_sale': '药品出售', 'stock_buy': '买入股票',
                'stock_sell': '卖出股票', 'jessica_loan_easter_egg': 'Jessica 彩蛋',
                'transfer': '转账'
            };
            const categoryLabel = categoryMap[tx.category] || tx.category || '其他';
            return `
                <div class="finance-history-item">
                    <div class="history-left">
                        <div class="history-category">${categoryLabel}</div>
                        <div class="history-reason">${escapeHtml(tx.reason)}</div>
                    </div>
                    <div class="history-right">
                        <div class="history-amount ${isIncome ? 'positive' : 'negative'}">${amountStr}</div>
                        <div class="history-time">${time}</div>
                    </div>
                </div>
            `;
        }).join('');

        if (data.length === 0) {
            container.innerHTML = '<div class="empty-state">暂无交易记录</div>';
        } else {
            container.innerHTML = html;
        }
    } catch (e) {
        console.error('加载交易历史失败', e);
    }
}

// 格式化金额
function formatFinance(amount) {
    if (amount === undefined || amount === null) return '0';
    if (Math.abs(amount) >= 10000) {
        return (amount / 10000).toFixed(1) + '万';
    }
    return amount.toLocaleString();
}

