// 当前外勤部标签页
let currentOpsTab = 'pending';
let opsTasksCache = Object.create(null);
let opsRequestSerial = 0;
const opsStartingTasks = new Set();

async function renderOpsTasks(tab = 'pending', { showLoading = true } = {}) {
    currentOpsTab = tab;
    const container = document.getElementById('ops-task-list');
    if (!container) return;

    const statusMap = {
        'pending': '待处理',
        'processing': '进行中',
        'completed': '已完成',
        'cancelled': '已取消'
    };
    const requestId = ++opsRequestSerial;
    if (showLoading && !opsTasksCache[tab]) {
        container.innerHTML = '<div class="ops-empty">正在加载任务…</div>';
    }
    try {
        const res = await fetch(`/ops/tasks/${tab}`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const tasks = await res.json();
        if (requestId !== opsRequestSerial || tab !== currentOpsTab) return;
        opsTasksCache[tab] = Array.isArray(tasks) ? tasks : [];
        updateOpsSummaryCount(tab, opsTasksCache[tab].length);
        renderOpsTaskList();
    } catch (e) {
        console.error('加载任务列表失败', e);
        if (requestId === opsRequestSerial) {
            container.innerHTML = `<div class="ops-empty">加载失败<br><button class="ops-primary-action" onclick="renderOpsTasks('${tab}')">重新加载</button></div>`;
        }
    }
}

function renderOpsTaskList() {
    const container = document.getElementById('ops-task-list');
    if (!container) return;
    const keyword = (document.getElementById('ops-task-search')?.value || '').trim().toLowerCase();
    const tasks = (opsTasksCache[currentOpsTab] || []).filter(task => {
        if (!keyword) return true;
        return [task.title, task.description, task.assigned_operator, task.selected_style]
            .some(value => String(value || '').toLowerCase().includes(keyword));
    });
    if (!tasks.length) {
        container.innerHTML = `<div class="ops-empty">${keyword ? '没有匹配的任务' : '暂无任务'}</div>`;
        return;
    }
    container.innerHTML = tasks.map(task => renderTaskCard(task, currentOpsTab)).join('');
    container.querySelectorAll('.ops-task-card').forEach(card => {
        card.addEventListener('click', () => openTaskDetail(card.dataset.taskId));
    });
    container.querySelectorAll('.ops-dispatch-btn').forEach(btn => {
        btn.addEventListener('click', event => {
            event.stopPropagation();
            openTaskDispatch(event.currentTarget.dataset.taskId);
        });
    });
    container.querySelectorAll('.ops-cancel-btn').forEach(btn => {
        btn.addEventListener('click', event => {
            event.stopPropagation();
            cancelTask(event.currentTarget.dataset.taskId);
        });
    });
    container.querySelectorAll('.ops-delete-btn').forEach(btn => {
        btn.addEventListener('click', event => {
            event.stopPropagation();
            deleteOpsTask(event.currentTarget.dataset.taskId);
        });
    });
}

function updateOpsSummaryCount(tab, count) {
    const node = document.getElementById(`ops-${tab}-count`);
    if (node) node.textContent = String(count || 0);
}

async function loadOpsOverview() {
    const tabs = ['pending', 'processing', 'completed', 'cancelled'];
    await Promise.all(tabs.map(async tab => {
        try {
            const res = await fetch(`/ops/tasks/${tab}?limit=100`);
            if (!res.ok) return;
            const tasks = await res.json();
            updateOpsSummaryCount(tab, Array.isArray(tasks) ? tasks.length : 0);
            if (tab !== currentOpsTab) opsTasksCache[tab] = Array.isArray(tasks) ? tasks : [];
        } catch (e) {
            console.warn(`读取${tab}任务数量失败`, e);
        }
    }));
}

function renderTaskCard(task, tab) {
    const urgency = Math.max(0, Math.min(5, Number(task.urgency) || 0));
    const urgencyStars = Array.from({ length: 5 }, (_, index) => ZootIcons.html(index < urgency ? 'favorite' : 'favoriteOutline')).join('');
    const durationMinutes = Math.max(1, Math.round((Number(task.base_duration) || 0) / 60));
    const description = String(task.description || '暂无任务描述');
    const nodes = Array.isArray(task.nodes) ? task.nodes : [];
    const statusMap = {
        'pending': '⏳ 待处理',
        'processing': '🔄 进行中',
        'completed': '✅ 已完成',
        'cancelled': '❌ 已取消'
    };
    let actions = '';
    if (tab === 'pending') {
        actions = opsStartingTasks.has(String(task.id))
            ? '<button class="ops-dispatch-btn" disabled>正在生成执行结点…</button>'
            : `<button class="ops-dispatch-btn" data-task-id="${task.id}">确认派遣</button>`;
    }
    if (tab === 'processing') {
        actions = `<button class="ops-cancel-btn" data-task-id="${task.id}">取消任务</button>`;
    }
    if (tab === 'completed' || tab === 'cancelled') {
        actions = `${tab === 'completed' ? `<button class="ops-report-btn" type="button" onclick="openFieldReportForTask('${String(task.id)}')">外勤报告</button>` : ''}<button class="ops-delete-btn" data-task-id="${task.id}">删除记录</button>`;
    }
    const nodeProgress = nodes.length ? `进度 ${nodes.filter(n => n.completed).length}/${nodes.length}` : '';
    return `
        <div class="ops-task-card" data-task-id="${task.id}">
            <div class="ops-task-header">
                <span class="ops-task-urgency">${urgencyStars}</span>
                <span class="ops-task-status">${statusMap[task.status] || task.status}</span>
            </div>
            <div class="ops-task-title">${escapeHtml(String(task.title || '未命名任务'))}</div>
            <div class="ops-task-desc">${escapeHtml(description.slice(0, 80))}${description.length > 80 ? '...' : ''}</div>
            <div class="ops-task-meta">
                <span>⏱ 约 ${durationMinutes} 分钟</span>
                ${nodeProgress ? `<span>${nodeProgress}</span>` : ''}
                ${task.assigned_operator ? `<span>👤 ${escapeHtml(task.assigned_operator)}</span>` : ''}
            </div>
            ${actions ? `<div class="ops-task-actions">${actions}</div>` : ''}
        </div>
    `;
}

// ========== 外勤部标签页切换 ==========
function initOpsTabs() {
    const tabs = document.querySelectorAll('.ops-tab');
    tabs.forEach(tab => {
        tab.removeEventListener('click', opsTabHandler);
        tab.addEventListener('click', opsTabHandler);
    });
}

function opsTabHandler(e) {
    selectOpsTab(e.currentTarget.dataset.tab);
}

function selectOpsTab(tabName) {
    document.querySelectorAll('#page-ops-department .ops-tab').forEach(tab => {
        tab.classList.toggle('active', tab.dataset.tab === tabName);
    });
    return renderOpsTasks(tabName);
}

function getOpsOperatorOptions(includeRandom = false) {
    const operators = typeof operatorMap !== 'undefined' && operatorMap instanceof Map
        ? Array.from(operatorMap.values())
        : [];
    const options = operators
        .filter(op => op?.id && op.id !== 'priestess' && op.id !== 'kinou' && op.capabilities?.dispatch !== false)
        .sort((a, b) => String(a.codename || a.id).localeCompare(String(b.codename || b.id), 'zh-CN'))
        .map(op => `<option value="${escapeHtml(String(op.id))}">${escapeHtml(String(op.codename || op.name || op.id))}</option>`)
        .join('');
    return `${includeRandom ? '<option value="">随机干员</option>' : ''}${options}`;
}

async function ensureOpsOperatorsLoaded() {
    if (typeof operatorMap !== 'undefined' && operatorMap instanceof Map && operatorMap.size) return;
    if (typeof loadOperators === 'function') {
        try {
            await loadOperators();
        } catch (e) {
            console.warn('外勤部加载干员列表失败', e);
        }
    }
}

let currentOpsSourceType = 'user';
let opsSourceEvents = [];
let opsCreateRequestId = null;

function setOpsTaskSource(sourceType) {
    currentOpsSourceType = sourceType === 'generated' ? 'generated' : 'user';
    document.querySelectorAll('#ops-task-create-bottom-sheet .ops-source-tab').forEach(tab => {
        tab.classList.toggle('active', tab.dataset.source === currentOpsSourceType);
    });
    document.getElementById('ops-source-user')?.classList.toggle('hidden', currentOpsSourceType !== 'user');
    document.getElementById('ops-source-generated')?.classList.toggle('hidden', currentOpsSourceType !== 'generated');
    if (currentOpsSourceType === 'generated') loadOpsSourceEvents();
}

function openOpsTaskCreate() {
    const sheet = document.getElementById('ops-task-create-bottom-sheet');
    const confirmBtn = document.getElementById('ops-create-confirm');
    if (!sheet || !confirmBtn) return;
    sheet.querySelectorAll('.ops-source-tab').forEach(tab => {
        tab.onclick = () => setOpsTaskSource(tab.dataset.source);
    });
    const refreshBtn = document.getElementById('ops-source-refresh');
    const generateBtn = document.getElementById('ops-source-generate');
    const eventSelect = document.getElementById('ops-source-event');
    if (refreshBtn) refreshBtn.onclick = loadOpsSourceEvents;
    if (generateBtn) generateBtn.onclick = generateOpsSourceEvent;
    if (eventSelect) eventSelect.onchange = renderOpsSourcePreview;
    confirmBtn.disabled = false;
    confirmBtn.textContent = '建立待处理任务';
    opsCreateRequestId = crypto.randomUUID ? crypto.randomUUID() : `ops-${Date.now()}-${Math.random()}`;
    confirmBtn.onclick = confirmOpsTaskCreate;
    setOpsTaskSource('user');
    openBottomSheet('ops-task-create-bottom-sheet');
}

async function loadOpsSourceEvents() {
    const select = document.getElementById('ops-source-event');
    const preview = document.getElementById('ops-source-preview');
    if (!select) return;
    select.innerHTML = '<option value="">正在读取事件库…</option>';
    try {
        const res = await fetch('/ops/source-events?limit=100');
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        opsSourceEvents = Array.isArray(data) ? data : [];
        select.innerHTML = opsSourceEvents.length
            ? '<option value="">请选择事件</option>' + opsSourceEvents.map(event => `<option value="${escapeHtml(String(event.id))}">${escapeHtml(String(event.title || '未命名事件'))}</option>`).join('')
            : '<option value="">暂无可用事件</option>';
        if (preview) preview.textContent = opsSourceEvents.length ? '选择事件后将在这里显示来源摘要。' : '事件库中没有尚未提交的任务事件，可以点击“生成新的外勤事件”。';
    } catch (e) {
        select.innerHTML = '<option value="">事件库读取失败</option>';
        if (preview) preview.textContent = e.message;
    }
}

function renderOpsSourcePreview() {
    const eventId = document.getElementById('ops-source-event')?.value;
    const preview = document.getElementById('ops-source-preview');
    if (!preview) return;
    const event = opsSourceEvents.find(item => String(item.id) === String(eventId));
    if (!event) {
        preview.textContent = '选择事件后将在这里显示来源摘要。';
        return;
    }
    const structure = event.task_structure || {};
    preview.textContent = `${event.title || '未命名事件'}\n${event.description || '暂无描述'}\n紧要程度：${structure.urgency || 3}　执行结点：${structure.node_count || 3}`;
}

async function generateOpsSourceEvent() {
    const button = document.getElementById('ops-source-generate');
    if (button?.disabled) return;
    if (button) {
        button.disabled = true;
        button.textContent = '正在生成…';
    }
    try {
        const res = await fetch('/ops/source-events/generate', { method: 'POST' });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data.detail || `HTTP ${res.status}`);
        await loadOpsSourceEvents();
        const select = document.getElementById('ops-source-event');
        if (select && data.event_id) {
            select.value = String(data.event_id);
            renderOpsSourcePreview();
        }
    } catch (e) {
        alert('生成外勤事件失败: ' + e.message);
    } finally {
        if (button) {
            button.disabled = false;
            button.textContent = '生成新的外勤事件';
        }
    }
}

async function confirmOpsTaskCreate() {
    const confirmBtn = document.getElementById('ops-create-confirm');
    if (confirmBtn?.disabled) return;
    let payload;
    if (currentOpsSourceType === 'generated') {
        const sourceEventId = document.getElementById('ops-source-event')?.value;
        if (!sourceEventId) return alert('请先选择一个自生成事件');
        payload = { source_type: 'generated', source_event_id: sourceEventId };
    } else {
        const title = document.getElementById('ops-create-title')?.value.trim();
        const description = document.getElementById('ops-create-description')?.value.trim();
        if (!title || !description) return alert('请填写事件标题和事件描述');
        const urgency = Number(document.getElementById('ops-create-urgency')?.value || 3);
        const currencyMin = Math.max(0, Number(document.getElementById('ops-create-currency-min')?.value || 0));
        const currencyMax = Math.max(currencyMin, Number(document.getElementById('ops-create-currency-max')?.value || 0));
        const trustMax = Math.max(0, Number(document.getElementById('ops-create-trust-max')?.value || 0));
        const styles = (document.getElementById('ops-create-styles')?.value || '').split(/[、,，]/).map(item => item.trim()).filter(Boolean);
        payload = {
            source_type: 'user', title, description, urgency,
            base_duration: Math.max(10, Number(document.getElementById('ops-create-duration')?.value || 60)) * 60,
            mission_mode: document.getElementById('ops-create-mission-mode')?.value || 'standard',
            duration_float: 0,
            node_count: Number(document.getElementById('ops-create-nodes')?.value || 3),
            styles,
            recommended_rewards: {
                currency: { min: currencyMin, max: currencyMax },
                trust: { min: Math.min(urgency, trustMax), max: trustMax },
                items: []
            }
        };
    }
    payload.client_request_id = opsCreateRequestId || (crypto.randomUUID ? crypto.randomUUID() : `ops-${Date.now()}-${Math.random()}`);
    if (confirmBtn) {
        confirmBtn.disabled = true;
        confirmBtn.textContent = '正在校验…';
    }
    try {
        await new Promise(resolve => requestAnimationFrame(resolve));
        confirmBtn.textContent = '正在保存…';
        const res = await fetch('/ops/tasks/create', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data.detail?.message || data.detail || `HTTP ${res.status}`);
        const taskId = String(data.task_id || '');
        if (!taskId) throw new Error('服务未返回任务 ID');
        confirmBtn.textContent = '正在确认…';
        const verifyResponse = await fetch(`/ops/tasks/${encodeURIComponent(taskId)}`);
        if (!verifyResponse.ok) throw new Error('任务已提交，但回读失败；请在待处理列表刷新确认');
        const createdTask = await verifyResponse.json();
        opsTasksCache.pending = [createdTask, ...(opsTasksCache.pending || []).filter(item => String(item.id) !== taskId)];
        closeBottomSheet('ops-task-create-bottom-sheet');
        showTemporaryToast('外勤任务已建立', 2600, 'success');
        opsCreateRequestId = null;
        await Promise.all([selectOpsTab('pending'), loadOpsOverview()]);
    } catch (e) {
        showTemporaryToast(`建立失败：${e.message}`, 4200, 'error');
    } finally {
        if (confirmBtn) {
            confirmBtn.disabled = false;
            confirmBtn.textContent = '建立待处理任务';
        }
    }
}

// ========== 任务派遣半页框 ==========
function taskParticipantRow(optionsHtml, index) {
    const duties = [['recon', '侦察'], ['combat', '战斗'], ['medical', '医疗'], ['technical', '技术'], ['logistics', '后勤'], ['custom', '自定义']];
    return `<div class="task-participant-row" data-participant-index="${index}"><select class="task-participant-operator">${optionsHtml}</select><select class="task-participant-duty">${duties.map(([value, label]) => `<option value="${value}">${label}</option>`).join('')}</select><input class="task-participant-custom-duty" maxlength="24" placeholder="自定义职责" hidden><label class="task-participant-leader"><input type="radio" name="task-participant-leader" ${index === 0 ? 'checked' : ''}>队长</label><button type="button" class="task-participant-remove" aria-label="移除参与干员" ${index === 0 ? 'hidden' : ''}>移除</button></div>`;
}

function bindTaskParticipantRows(body, optionsHtml) {
    const container = body.querySelector('#task-dispatch-participants');
    const bindRow = row => {
        const duty = row.querySelector('.task-participant-duty');
        const custom = row.querySelector('.task-participant-custom-duty');
        duty.addEventListener('change', () => { custom.hidden = duty.value !== 'custom'; });
        row.querySelector('.task-participant-remove')?.addEventListener('click', () => row.remove());
    };
    container.querySelectorAll('.task-participant-row').forEach(bindRow);
    body.querySelector('#task-participant-add')?.addEventListener('click', () => {
        if (container.querySelectorAll('.task-participant-row').length >= 12) { showTemporaryToast('每次外勤最多12名参与干员', 3000, 'error'); return; }
        const wrapper = document.createElement('div');
        wrapper.innerHTML = taskParticipantRow(optionsHtml, Date.now());
        const row = wrapper.firstElementChild;
        container.appendChild(row);
        bindRow(row);
    });
}

async function openTaskDispatch(taskId) {
    const sheet = document.getElementById('task-dispatch-bottom-sheet');
    const body = document.getElementById('task-dispatch-body');
    if (!sheet || !body) return;

    body.innerHTML = '<div class="ops-empty">正在读取任务…</div>';
    openBottomSheet('task-dispatch-bottom-sheet');
    try {
            await ensureOpsOperatorsLoaded();
            const res = await fetch(`/ops/tasks/${encodeURIComponent(taskId)}`);
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            const task = await res.json();
            const operators = getOpsOperatorOptions(false);
            const taskStyles = Array.isArray(task.styles) && task.styles.length ? task.styles : ['稳妥处理', '快速推进', '灵活应变'];
            const styles = taskStyles.map((style, index) =>
                `<button class="style-option${index === 0 ? ' selected' : ''}" data-style="${escapeHtml(String(style))}">${escapeHtml(String(style))}</button>`
            ).join('');

            body.innerHTML = `
                <div style="margin-bottom:12px;">
                    <div style="font-weight:bold;font-size:16px;">${escapeHtml(String(task.title || '未命名任务'))}</div>
                    <div style="font-size:14px;color:var(--text-secondary);margin-top:4px;">${escapeHtml(String(task.description || '暂无任务描述'))}</div>
                </div>
                <div style="margin-bottom:12px;">
                    <label style="display:block;margin-bottom:4px;">任务类型</label>
                    <select id="task-dispatch-mode"><option value="standard" ${task.mission_mode !== 'long' ? 'selected' : ''}>标准外勤</option><option value="long" ${task.mission_mode === 'long' ? 'selected' : ''}>长线外勤</option></select>
                    ${Number(task.base_duration || 0) >= 86400 && task.mission_mode !== 'long' ? '<small class="task-long-suggestion">预计时长达到24小时，建议切换为长线外勤。</small>' : ''}
                </div>
                <div style="margin-bottom:12px;">
                    <label style="display:block;margin-bottom:4px;">参与干员、职责与队长</label>
                    <div id="task-dispatch-participants">${taskParticipantRow(operators, 0)}</div>
                    <button type="button" id="task-participant-add">增加参与干员</button>
                </div>
                <div style="margin-bottom:12px;">
                    <label style="display:block;margin-bottom:4px;">处理风格</label>
                    <div id="task-dispatch-styles" style="display:flex;gap:8px;flex-wrap:wrap;">
                        ${styles}
                    </div>
                </div>
                <div style="font-size:12px;color:var(--text-secondary);">
                    <span>💰 奖励: ${task.recommended_rewards?.currency?.min || 0}-${task.recommended_rewards?.currency?.max || 0} 龙门币</span>
                    <span style="margin-left:12px;">❤️ 信赖: ${task.recommended_rewards?.trust?.min || 0}-${task.recommended_rewards?.trust?.max || 0}</span>
                </div>
            `;
            // 绑定风格选择
            body.querySelectorAll('.style-option').forEach(btn => {
                btn.addEventListener('click', () => {
                    body.querySelectorAll('.style-option').forEach(b => b.classList.remove('selected'));
                    btn.classList.add('selected');
                });
            });
            bindTaskParticipantRows(body, operators);
            // 绑定确认按钮
            const confirmBtn = document.getElementById('task-dispatch-confirm');
            confirmBtn.onclick = () => confirmTaskDispatch(taskId);
    } catch (e) {
        console.error('加载任务详情失败', e);
        body.innerHTML = '<div class="ops-empty">任务详情加载失败</div>';
    }
}

async function confirmTaskDispatch(taskId) {
    const rows = [...document.querySelectorAll('#task-dispatch-participants .task-participant-row')];
    const participants = rows.map(row => ({operator_id: row.querySelector('.task-participant-operator')?.value || '', duty: row.querySelector('.task-participant-duty')?.value || '', duty_label: row.querySelector('.task-participant-custom-duty')?.value || '', is_leader: Boolean(row.querySelector('.task-participant-leader input')?.checked)}));
    const operator = participants.find(item => item.is_leader)?.operator_id;
    const selectedStyle = document.querySelector('#task-dispatch-body .style-option.selected')?.dataset.style;
    if (!participants.length || participants.some(item => !item.operator_id)) {
        showTemporaryToast('请为每个席位选择干员', 3000, 'error');
        return;
    }
    if (new Set(participants.map(item => item.operator_id)).size !== participants.length) { showTemporaryToast('同一干员不能重复加入任务', 3000, 'error'); return; }
    if (participants.filter(item => item.is_leader).length !== 1) { showTemporaryToast('请选择且仅选择一名队长', 3000, 'error'); return; }
    if (participants.some(item => item.duty === 'custom' && !item.duty_label.trim())) { showTemporaryToast('自定义职责不能为空', 3000, 'error'); return; }
    if (!selectedStyle) {
        showTemporaryToast('请选择处理风格', 3000, 'error');
        return;
    }
    const normalizedTaskId = String(taskId);
    if (opsStartingTasks.has(normalizedTaskId)) return;
    opsStartingTasks.add(normalizedTaskId);
    closeBottomSheet('task-dispatch-bottom-sheet');
    renderOpsTaskList();
    showTemporaryToast('派遣请求已提交，正在生成执行结点…', 3500, 'info');
    try {
        const res = await fetch('/ops/tasks/start', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                task_id: taskId,
                assigned_operator: operator,
                selected_style: selectedStyle,
                mission_mode: document.getElementById('task-dispatch-mode')?.value || 'standard',
                participants
            })
        });
        if (!res.ok) {
            const err = await res.json();
            throw new Error(err.detail || '未知错误');
        }
        await res.json();
        showTemporaryToast('任务已启动，后续进度将自动更新', 3000, 'success');
        await Promise.all([selectOpsTab('processing'), loadOpsOverview()]);
    } catch (e) {
        showTemporaryToast('任务启动失败，请重试', 3500, 'error');
        showTemporaryToast(`操作失败：${e.message}`, 4200, 'error');
        await renderOpsTasks('pending', { showLoading: false });
    } finally {
        opsStartingTasks.delete(normalizedTaskId);
        renderOpsTaskList();
    }
}

// ========== 任务详情半页框 ==========
function openTaskDetail(taskId) {
    const sheet = document.getElementById('task-detail-bottom-sheet');
    const body = document.getElementById('task-detail-body');
    const title = document.getElementById('task-detail-title');
    if (!sheet || !body) return;

    fetch(`/ops/tasks/${taskId}`)
        .then(res => {
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            return res.json();
        })
        .then(task => {
            title.textContent = String(task.title || '任务详情');
            const logs = Array.isArray(task.logs) ? task.logs : [];
            const nodes = Array.isArray(task.nodes) ? task.nodes : [];
            const urgency = Math.max(0, Math.min(5, Number(task.urgency) || 0));
            const statusLabels = { pending: '待处理', processing: '进行中', completed: '已完成', cancelled: '已取消' };
            let logHtml = '';
            if (logs.length > 0) {
                logHtml = logs.map((log, i) => `
                    <div class="ops-log-item ${log.completed ? 'completed' : 'pending'}">
                        <span class="ops-log-time">${new Date(log.timestamp * 1000).toLocaleTimeString()}</span>
                        <span class="ops-log-content">${escapeHtml(log.content)}</span>
                    </div>
                `).join('');
            } else {
                logHtml = '<div style="color:var(--text-secondary);font-size:13px;">暂无日志</div>';
            }

            let resultHtml = '';
            if (task.result) {
                resultHtml = `
                    <div class="ops-result">
                        <div style="font-weight:bold;margin:8px 0;">📋 任务总结</div>
                        <div style="font-size:14px;color:var(--text-color);">${escapeHtml(task.result.summary || '')}</div>
                        ${task.result.rewards ? `
                            <div style="margin-top:8px;font-size:13px;color:var(--text-secondary);">
                                🏆 奖励: ${task.result.rewards.currency || 0} 龙门币 | +${task.result.rewards.trust || 0} 信赖值
                            </div>
                        ` : ''}
                    </div>
                `;
            }

            body.innerHTML = `
                <div style="margin-bottom:12px;">
                    <div style="display:flex;gap:12px;flex-wrap:wrap;font-size:13px;color:var(--text-secondary);">
                        <span>紧要程度: ${Array.from({ length: 5 }, (_, index) => ZootIcons.html(index < urgency ? 'favorite' : 'favoriteOutline')).join('')}</span>
                        <span>⏱ ${Math.max(1, Math.round((Number(task.base_duration) || 0)/60))} 分钟</span>
                        <span>状态: ${statusLabels[task.status] || escapeHtml(String(task.status || '未知'))}</span>
                        <span>来源: ${task.source_type === 'generated' ? '自生成事件' : '用户设定事件'}</span>
                        ${task.assigned_operator ? `<span>👤 ${escapeHtml(task.assigned_operator)}</span>` : ''}
                        ${task.selected_style ? `<span>🎯 ${escapeHtml(task.selected_style)}</span>` : ''}
                        ${task.source_event_id ? `<span>来源事件: ${escapeHtml(String(task.source_event_id))}</span>` : ''}
                    </div>
                </div>
                <div style="margin-bottom:12px;font-size:14px;color:var(--text-color);">
                    ${escapeHtml(String(task.description || '暂无任务描述'))}
                </div>
                ${nodes.length ? `
                    <div style="margin-bottom:12px;">
                        <div style="font-weight:bold;font-size:14px;">结点进度 (${nodes.filter(n => n.completed).length}/${nodes.length})</div>
                        <div style="display:flex;gap:4px;margin-top:4px;">
                            ${nodes.map((n, i) => `
                                <div style="flex:1;height:4px;border-radius:2px;background:${n.completed ? '#28a745' : 'var(--border-color)'};"></div>
                            `).join('')}
                        </div>
                    </div>
                ` : ''}
                <div style="margin-bottom:12px;">
                    <div style="font-weight:bold;font-size:14px;">📋 日志</div>
                    ${logHtml}
                </div>
                ${resultHtml}
            `;
            openBottomSheet('task-detail-bottom-sheet');
        })
        .catch(e => {
            console.error('加载任务详情失败', e);
            alert('加载失败');
        });
}

// ========== 取消任务 ==========
async function cancelTask(taskId) {
    if (!confirm('确定要取消这个任务吗？')) return;
    try {
        const res = await fetch('/ops/tasks/cancel', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ task_id: taskId })
        });
        if (!res.ok) {
            const err = await res.json();
            alert('取消失败: ' + (err.detail || '未知错误'));
            return;
        }
        alert('任务已取消');
        await Promise.all([renderOpsTasks(currentOpsTab), loadOpsOverview()]);
    } catch (e) {
        alert('操作失败: ' + e.message);
    }
}

async function deleteOpsTask(taskId) {
    if (!confirm('删除后将无法恢复这条任务记录，是否继续？')) return;
    try {
        const res = await fetch(`/ops/tasks/${encodeURIComponent(taskId)}`, { method: 'DELETE' });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data.detail || `HTTP ${res.status}`);
        await Promise.all([renderOpsTasks(currentOpsTab), loadOpsOverview()]);
    } catch (e) {
        alert('删除失败: ' + e.message);
    }
}

// ========== 初始化外勤部 ==========
// 在 initOpsDepartment 中启动轮询
function initOpsDepartment() {
    initOpsTabs();
    const activeTab = document.querySelector('#page-ops-department .ops-tab.active')?.dataset.tab || currentOpsTab || 'pending';
    const searchInput = document.getElementById('ops-task-search');
    const refreshBtn = document.getElementById('ops-refresh-btn');
    const createBtn = document.getElementById('ops-create-task-btn');
    if (searchInput) searchInput.oninput = renderOpsTaskList;
    if (refreshBtn) refreshBtn.onclick = () => Promise.all([renderOpsTasks(currentOpsTab), loadOpsOverview()]);
    if (createBtn) createBtn.onclick = openOpsTaskCreate;
    selectOpsTab(activeTab);
    loadOpsOverview();
    if (window._opsPollTimer) clearInterval(window._opsPollTimer);
    window._opsPollTimer = setInterval(() => {
        const page = document.getElementById('page-ops-department');
        if (!page?.classList.contains('active')) return;
        loadOpsOverview();
        if (currentOpsTab === 'processing') renderOpsTasks('processing', { showLoading: false });
    }, 10000);
}

// ========== 43.9. 罗德岛采购部 ==========


// ========== 43.10. 仓储 ==========
let currentWhTab = 'inventory';
let whOperationType = 'add'; // add, remove, discard

function renderInventory() {
    const container = document.getElementById('wh-inventory-list');
    if (!container) return;

    fetch('/inventory/items')
        .then(res => {
            if (!res.ok) throw new Error('加载失败');
            return res.json();
        })
        .then(items => {
            if (!items || items.length === 0) {
                container.innerHTML = '<div class="empty-state">仓储为空</div>';
                return;
            }
            // 按分类排序
            items.sort((a, b) => (a.category || '').localeCompare(b.category || ''));
            container.innerHTML = items.map(item => `
                <div class="wh-item-card wh-item-rarity-${item.rarity || 'N'}">
                    <div class="wh-item-left">
                        <div class="wh-item-name">${escapeHtml(item.name || item.item_id)}</div>
                        <div class="wh-item-meta">
                            ${escapeHtml(item.category || '其他')} · ${escapeHtml(item.rarity || 'N')}
                            ${item.description ? `· ${escapeHtml(item.description.substring(0, 20))}${item.description.length > 20 ? '...' : ''}` : ''}
                        </div>
                    </div>
                    <div class="wh-item-quantity">×${item.quantity}</div>
                </div>
            `).join('');

            // 更新摘要
            updateWarehouseSummary(items);
        })
        .catch(e => {
            console.error('加载库存失败', e);
            container.innerHTML = '<div class="empty-state">加载失败，请刷新重试</div>';
        });
}

function renderWhTransactions() {
    const container = document.getElementById('wh-transactions-list');
    if (!container) return;

    fetch('/inventory/transactions?limit=100')
        .then(res => res.json())
        .then(txs => {
            if (!txs || txs.length === 0) {
                container.innerHTML = '<div class="empty-state">暂无交易记录</div>';
                return;
            }
            const typeMap = {
                'in': '入库',
                'out': '出库',
                'discard': '丢弃',
                'adjust': '调整'
            };
            container.innerHTML = txs.map(tx => {
                const isPositive = tx.quantity > 0;
                const typeLabel = typeMap[tx.transaction_type] || tx.transaction_type;
                const time = new Date(tx.timestamp * 1000).toLocaleString();
                return `
                    <div class="wh-tx-item tx-${tx.transaction_type}">
                        <div class="wh-tx-left">
                            <div class="wh-tx-item-name">${escapeHtml(tx.item_id)} ${isPositive ? '📥' : '📤'}</div>
                            <div class="wh-tx-item-reason">${escapeHtml(tx.reason || '无')} · ${typeLabel}</div>
                        </div>
                        <div class="wh-tx-right">
                            <div class="wh-tx-qty ${isPositive ? 'positive' : 'negative'}">${isPositive ? '+' : ''}${tx.quantity}</div>
                            <div class="wh-tx-time">${time}</div>
                        </div>
                    </div>
                `;
            }).join('');
        })
        .catch(e => {
            console.error('加载交易记录失败', e);
            container.innerHTML = '<div class="empty-state">加载失败</div>';
        });
}

function updateWarehouseSummary(items) {
    const totalTypes = items.length;
    const totalQty = items.reduce((sum, i) => sum + i.quantity, 0);
    document.getElementById('wh-total-types').textContent = totalTypes;
    document.getElementById('wh-total-qty').textContent = totalQty;

    // 获取最近交易
    fetch('/inventory/transactions?limit=1')
        .then(res => res.json())
        .then(txs => {
            if (txs && txs.length > 0) {
                const last = txs[0];
                const time = new Date(last.timestamp * 1000).toLocaleString();
                document.getElementById('wh-last-op').textContent = `${last.item_id} ${last.quantity > 0 ? '+' : ''}${last.quantity} @ ${time}`;
            } else {
                document.getElementById('wh-last-op').textContent = '无';
            }
        })
        .catch(() => {});
}

// ========== 仓储标签页切换 ==========

function initWhTabs() {
    const tabs = document.querySelectorAll('.wh-tab');
    tabs.forEach(tab => {
        tab.removeEventListener('click', whTabHandler);
        tab.addEventListener('click', whTabHandler);
    });
}

function whTabHandler(e) {
    const tab = e.currentTarget;
    const tabName = tab.dataset.tab;
    document.querySelectorAll('.wh-tab').forEach(t => t.classList.remove('active'));
    tab.classList.add('active');
    document.getElementById('wh-inventory-list').classList.toggle('hidden', tabName !== 'inventory');
    document.getElementById('wh-transactions-list').classList.toggle('hidden', tabName !== 'transactions');

    if (tabName === 'inventory') renderInventory();
    else if (tabName === 'transactions') renderWhTransactions();
}

// ========== 仓储操作半页框 ==========

function openWhOperation(type) {
    whOperationType = type;
    const sheet = document.getElementById('wh-operation-sheet');
    const title = document.getElementById('wh-op-title');
    const confirmBtn = document.getElementById('wh-op-confirm');

    const titles = { 'add': '📥 入库', 'remove': '📤 出库', 'discard': '🗑️ 丢弃' };
    title.textContent = titles[type] || '物品操作';

    document.getElementById('wh-op-item-id').value = '';
    document.getElementById('wh-op-quantity').value = '1';
    document.getElementById('wh-op-reason').value = '';

    // 移除旧监听
    confirmBtn.removeEventListener('click', whConfirmHandler);
    confirmBtn.addEventListener('click', whConfirmHandler);

    openBottomSheet('wh-operation-sheet');
}

async function whConfirmHandler() {
    const itemId = document.getElementById('wh-op-item-id').value.trim();
    const quantity = parseInt(document.getElementById('wh-op-quantity').value) || 1;
    const reason = document.getElementById('wh-op-reason').value.trim() || `${whOperationType}操作`;

    if (!itemId) {
        alert('请输入物品ID');
        return;
    }
    if (quantity <= 0) {
        alert('数量必须大于0');
        return;
    }

    const endpoints = {
        'add': '/inventory/add',
        'remove': '/inventory/remove',
        'discard': '/inventory/discard'
    };

    try {
        const res = await fetch(endpoints[whOperationType], {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                item_id: itemId,
                quantity: quantity,
                reason: reason
            })
        });
        if (!res.ok) {
            const err = await res.json();
            alert('操作失败: ' + (err.detail || '未知错误'));
            return;
        }
        const data = await res.json();
        alert(`操作成功！${itemId} 当前数量: ${data.balance_after}`);
        closeBottomSheet('wh-operation-sheet');
        renderInventory();
        renderWhTransactions();
    } catch (e) {
        alert('操作失败: ' + e.message);
    }
}

