function initWarehousePage() {
    initWhTabs();
    renderInventory();

    // 绑定操作按钮
    document.getElementById('wh-refresh-btn')?.addEventListener('click', () => {
        if (currentWhTab === 'inventory') renderInventory();
        else renderWhTransactions();
    });
    document.getElementById('wh-add-btn')?.addEventListener('click', () => openWhOperation('add'));
    document.getElementById('wh-remove-btn')?.addEventListener('click', () => openWhOperation('remove'));
    document.getElementById('wh-discard-btn')?.addEventListener('click', () => openWhOperation('discard'));
}


