// 初始化函数
function signalZootAppReady() {
    if (window.__zootAppReady) return;
    window.__zootAppReady = true;
    window.dispatchEvent(new CustomEvent('zoot:app-ready'));
    try {
        window.Android?.frontendReady?.();
    } catch (error) {
        console.warn('[启动] 无法提交原生前端就绪握手', error);
    }
}

window.onload = async () => {
    try {
        console.log('=== window.onload started ===');

        // 可选：更新开屏页文字（显示“等待服务器...”）
        const splashText = document.querySelector('#splash-screen .splash-text');
        if (splashText) splashText.textContent = '等待服务器...';

        await waitForServer();  // 等待后端启动

        // 立即隐藏开屏页（缩短延迟，提升响应速度）
        const splash = document.getElementById('splash-screen');
        let resolveSplashDismissed;
        const splashDismissed = new Promise(resolve => {
            resolveSplashDismissed = resolve;
        });
        if (splash) {
            splash.style.opacity = '0';
            setTimeout(() => {
                splash.style.display = 'none';
                const appContent = document.getElementById('app-content');
                if (appContent) appContent.style.display = 'block';
                resolveSplashDismissed();
            }, 150); // 由500ms缩短至150ms
        } else {
            resolveSplashDismissed();
        }

        // 后台加载任务（不阻塞UI显示）
        loadOperators().then(() => {
            renderContacts();
        }).catch(e => console.error('加载干员失败', e));

        // 并行执行其他不需要顺序的加载。聊天列表只在服务器就绪后请求一次，
        // 本地缓存先同步渲染，远端结果随后原位刷新，不触发页面导航。
        loadChatsFromLocalStorage();
        const startupDataPromise = Promise.allSettled([
            loadAllStars(),
            loadAppVersion(),
            fetchGlobalYear(),
            loadChats(),
            checkAndShowSetupWizard()
        ]);
        const hydrateEmojiMetadata = async () => {
            await loadAllEmojiMaps();
            if (document.getElementById('page-chat-list')?.classList.contains('active-page')) {
                scheduleChatListRender();
            }
        };
        if ('requestIdleCallback' in window) {
            requestIdleCallback(() => void hydrateEmojiMetadata(), {timeout: 2600});
        } else {
            setTimeout(() => void hydrateEmojiMetadata(), 900);
        }

        // 以下初始化不依赖上述异步结果，可以立即执行
        initGuideDebugTool();
        updateNavBadges();
        startupDataPromise.then(() => {
            if (window.firstRunCoordinator?.state === 'completed') initOnboarding();
        });
        initRouter();
        activateInitialPageInPlace();
        updateUI();
        await splashDismissed;
        signalZootAppReady();
        // 初始化自动输入框适应
        scheduleMessageInputHeightSync(true, true);
        // 初始化头像
        initAvatar();
        // 初始化全局情景切换按钮
        initScenarioToggle();
        // 初始化情景发言切换按钮
        initScenarioButtons();
        // 初始化API检查
        checkApiKeyAndPrompt();
        // 初始化标签事件
        initTagEvents();
        // 初始化信赖图表
        initTrustChartTabs();
        // 初始化事务页
        initTaskPage();
        // 记录板功能
        initRecordBoard();
        initHorizontalScrollBlocks();
        // 私聊/群聊过滤器
        initContactFilters();
        // 联系人过滤器
        initContactFilter();
        // 错误日志捕获
        initErrorLogCapture();
        // 初始化输入框
        initChatInputEvents();
        // 在加载完成并获取当前人格后执行
        await getCurrentPersona();
        await updateProfilePage();
        // 获取当前人格并设置全局变量
        const initialPersona = await getCurrentPersona();
        if (initialPersona) {
            window.currentPersonaId = initialPersona.persona_id;
            window.allowContextSharing = initialPersona.profile_json?.allow_context_sharing || false;
            console.log(`[初始化] allowContextSharing = ${window.allowContextSharing}`);
        }
        // 启动时自动检查更新弹窗
        setTimeout(() => {
            autoCheckUpdateOnStart();
        }, 1000);

        setTimeout(() => {
            updateInputButtons();
            updateDynamicButton();
        }, 100);

        window.addEventListener('resize', adjustChatListScroll);
        adjustChatListScroll();

        // 聊天按钮
        const chatPlusBtn = document.getElementById('chat-plus');
        if (chatPlusBtn) {
            chatPlusBtn.addEventListener('click', () => { showPlusMenu(chatPlusBtn, 'chat-detail'); });
        }

        // 预加载表情包映射（已包含在Promise.all中）
        // loadAllEmojiMaps().catch(e => console.error('表情包数据加载失败', e));
        initEmojiPicker();

        // 知识图谱API
        const savedKnowledgeApi = localStorage.getItem('knowledge_api');
        if (savedKnowledgeApi) document.getElementById('knowledge-api-display').textContent = '已设置';

        // 连接通知 WebSocket
        connectNotificationWebSocket();

        // 处理重试按钮（保留，因为可能动态添加）
        document.addEventListener('click', (e) => {
            const retryBtn = e.target.closest('.retry-btn');
            if (retryBtn) {
                e.preventDefault();
                const content = retryBtn.dataset.retryContent;
                const chatType = retryBtn.dataset.chatType;
                const chatId = retryBtn.dataset.chatId;
                const timestamp = Date.now() / 1000;
                resendFailedMessage(content, chatType, chatId, timestamp);
            }
        });

        // 服务状态栏添加点击刷新功能
        const kgServiceItem = document.getElementById('kg-service-item');
        if (kgServiceItem) {
            kgServiceItem.addEventListener('click', () => {
                checkKgHealth();
            });
        }

        // ========== 自主消息队列和生成器初始化 ==========
        window.messageQueue = new MessageQueue();
        window.messageQueue.pushEnabled = localStorage.getItem('globalAutoPushEnabled') !== 'false';

        window.privateQueueGenerator = new QueueGenerator('private');
        window.groupQueueGenerator = new QueueGenerator('group');

        if (window.privateQueueGenerator.config.autoGenerate) {
            window.privateQueueGenerator.start();
        }
        if (window.groupQueueGenerator.config.autoGenerate) {
            window.groupQueueGenerator.start();
        }

        await loadAutoPushSettings();
        initAutoMessageTabs();

        if (typeof loadAssistantInfo === 'function') {
            loadAssistantInfo();
        }

        startupDataPromise.then(() => {
            if (getCurrentPageId() === 'chat-list') {
                renderChatList();
                updateNavBadges();
            }
        });

        window.addEventListener('online', () => {
            console.log('[网络] 网络恢复，尝试重连同步管理器');
            if (window.syncManager) {
                if (window.syncManager._pc_reachable_last_check) {
                    window.syncManager._pc_reachable_last_check = 0;
                }
                window.syncManager.start();
            }
        });

        console.log('=== window.onload finished ===');
    } catch (e) {
        console.error('Uncaught error in window.onload:', e);
        const splash = document.getElementById('splash-screen');
        if (splash) {
            splash.style.opacity = '0';
            setTimeout(() => {
                splash.style.display = 'none';
                const appContent = document.getElementById('app-content');
                if (appContent) appContent.style.display = 'block';
                signalZootAppReady();
            }, 500);
        } else {
            signalZootAppReady();
        }
    }
};


const OPERATOR_CONTEXT_SOURCE_LABELS = Object.freeze({
    chronicles: '纪事',
    rumors: '传闻',
    dynamics: '干员动态',
    world_events: '相关世界事件'
});

const OPERATOR_TITLE_STYLE_OPTIONS = Object.freeze([
    {id: 'rhodes_blue', label: '罗德岛蓝', text: '#ffffff', start: '#173f78', end: '#18a7c8'},
    {id: 'tactical_purple', label: '战术紫', text: '#ffffff', start: '#3d2468', end: '#c13b9e'},
    {id: 'honor_gold', label: '荣誉金', text: '#241700', start: '#d58b18', end: '#ffd66b'},
    {id: 'elite_red', label: '精英红', text: '#ffffff', start: '#671c28', end: '#ed4b3e'},
    {id: 'medical_green', label: '医疗绿', text: '#ffffff', start: '#15543f', end: '#2bbf92'},
    {id: 'industrial_gray', label: '工业灰', text: '#15171a', start: '#59616b', end: '#c9d0d7'}
]);

function normalizeOperatorTitleText(value) {
    return String(value || '').normalize('NFKC').trim().replace(/\s+/g, ' ').toLocaleLowerCase();
}

function operatorTitleSimilarity(left, right) {
    const a = normalizeOperatorTitleText(left);
    const b = normalizeOperatorTitleText(right);
    if (!a || !b) return 0;
    if (a === b) return 1;
    if (Math.min(a.length, b.length) >= 2 && (a.includes(b) || b.includes(a))) return 0.86;
    const pairs = value => {
        const result = [];
        for (let index = 0; index < value.length - 1; index += 1) result.push(value.slice(index, index + 2));
        return result;
    };
    const leftPairs = pairs(a);
    const rightPairs = pairs(b);
    if (!leftPairs.length || !rightPairs.length) return 0;
    const remaining = [...rightPairs];
    let overlap = 0;
    leftPairs.forEach(pair => {
        const index = remaining.indexOf(pair);
        if (index >= 0) {
            overlap += 1;
            remaining.splice(index, 1);
        }
    });
    return (2 * overlap) / (leftPairs.length + rightPairs.length);
}

function formatOperatorContextLastUsed(value) {
    if (!value) return '尚未使用';
    const date = new Date(Number(value) * 1000);
    return Number.isNaN(date.getTime()) ? '尚未使用' : date.toLocaleString();
}



function normalizeOperatorTitleHex(value) {
    const normalized = String(value || '').trim().toUpperCase();
    return /^#[0-9A-F]{6}$/.test(normalized) ? normalized : null;
}

function operatorTitleGradientStyle(startValue, endValue) {
    const start = normalizeOperatorTitleHex(startValue) || '#173F78';
    const end = normalizeOperatorTitleHex(endValue) || '#18A7C8';
    const rgb = color => [1, 3, 5].map(index => parseInt(color.slice(index, index + 2), 16));
    const toHex = channels => '#' + channels.map(value => Math.max(0, Math.min(255, Math.round(value))).toString(16).padStart(2, '0')).join('').toUpperCase();
    const startRgb = rgb(start);
    const endRgb = rgb(end);
    const midpoint = toHex(startRgb.map((value, index) => (value + endRgb[index]) / 2));
    const luminance = color => {
        const channels = rgb(color).map(value => {
            const channel = value / 255;
            return channel <= 0.04045 ? channel / 12.92 : Math.pow((channel + 0.055) / 1.055, 2.4);
        });
        return 0.2126 * channels[0] + 0.7152 * channels[1] + 0.0722 * channels[2];
    };
    const minimumContrast = text => Math.min(...[start, midpoint, end].map(color => {
        const left = luminance(text);
        const right = luminance(color);
        return (Math.max(left, right) + 0.05) / (Math.min(left, right) + 0.05);
    }));
    const whiteContrast = minimumContrast('#FFFFFF');
    const blackContrast = minimumContrast('#15171A');
    return {
        text_color: whiteContrast >= blackContrast ? '#FFFFFF' : '#15171A',
        gradient_start: start,
        gradient_end: end,
        representative_color: midpoint,
        minimum_contrast: Math.max(whiteContrast, blackContrast)
    };
}

function operatorTitleStyleChoice(value) {
    const raw = String(value || '');
    if (raw.startsWith('palette:')) return {kind: 'palette', palette_id: raw.slice(8)};
    const presetId = raw.startsWith('preset:') ? raw.slice(7) : raw;
    return {kind: 'preset', preset_id: presetId || 'rhodes_blue'};
}

function renderOperatorTitleStyleOptions(styleOptions, palettes, currentItem = null) {
    const currentStyle = currentItem?.style || {};
    const sourcePalette = palettes.find(item => item.palette_id === currentStyle.palette_id);
    const snapshotLabel = sourcePalette?.archived
        ? `${currentStyle.label || '自定义色盘'}（原色盘已归档）`
        : (currentStyle.label || '自定义色盘');
    const customSnapshot = currentStyle.kind === 'palette_snapshot'
        ? `<option value="snapshot:${escapeHtml(currentItem.title_id)}" selected disabled>当前快照 · ${escapeHtml(snapshotLabel)}</option>`
        : '';
    const presets = styleOptions.map(style => {
        const selected = currentStyle.kind !== 'palette_snapshot'
            && (currentItem?.style_preset || currentStyle.preset) === style.id;
        return `<option value="preset:${style.id}" ${selected ? 'selected' : ''}>${style.label}</option>`;
    }).join('');
    const activePalettes = palettes.filter(item => !item.archived);
    const personal = activePalettes.map(item =>
        `<option value="palette:${escapeHtml(item.palette_id)}">${escapeHtml(item.name)}</option>`
    ).join('');
    return `${customSnapshot}<optgroup label="内置配色">${presets}</optgroup><optgroup label="我的色盘">${personal || '<option disabled>尚无个人色盘</option>'}</optgroup>`;
}

function resolveOperatorTitleStyle(value, styleOptions, palettes) {
    const choice = operatorTitleStyleChoice(value);
    if (choice.kind === 'palette') {
        const palette = palettes.find(item => item.palette_id === choice.palette_id && !item.archived);
        if (palette) return {
            text_color: palette.text_color,
            gradient_start: palette.gradient_start,
            gradient_end: palette.gradient_end,
            representative_color: palette.representative_color,
            minimum_contrast: palette.minimum_contrast
        };
    }
    const preset = styleOptions.find(item => item.id === choice.preset_id) || styleOptions[0];
    return {
        text_color: preset.text,
        gradient_start: preset.start,
        gradient_end: preset.end,
        representative_color: preset.end,
        minimum_contrast: 4.5
    };
}

async function loadOperatorTitleCard(operatorId) {
    const root = document.getElementById(`operator-title-inline-${operatorId}`);
    if (!root) return;
    const safe = value => escapeHtml(String(value ?? ''));
    try {
        const [response, paletteResponse] = await Promise.all([
            fetch(`/operator/titles/${encodeURIComponent(operatorId)}`),
            fetch('/operator/titles/palettes?include_archived=true')
        ]);
        const payload = await response.json();
        const palettePayload = await paletteResponse.json().catch(() => ({items: []}));
        if (!response.ok) throw new Error(payload.detail?.message || payload.detail || '头衔读取失败');
        if (!paletteResponse.ok) throw new Error(palettePayload.detail?.message || palettePayload.detail || '色盘读取失败');
        const currentId = payload.current?.title_id || '';
        const styleOptions = OPERATOR_TITLE_STYLE_OPTIONS;
        const titleItems = payload.titles || [];
        const palettes = palettePayload.items || [];
        root.innerHTML = `
            <div class="operator-title-current">
                <small>当前展示</small>
                <strong>${payload.current ? renderOperatorTitleBadge(payload.current, operatorId) : '尚未选择'}</strong>
                <span>显示格式：干员名 · 头衔</span>
            </div>
            <div class="operator-title-list">
                ${titleItems.map(item => `<article data-title-state="${safe(item.status)}">
                    <div>${renderOperatorTitleBadge(item, operatorId)}<small>${safe(item.description || item.source || '')}</small></div>
                    <div class="operator-title-actions">
                        ${!['historical', 'archived'].includes(item.status) ? `<select data-title-style="${safe(item.title_id)}" data-revision="${Number(item.revision || 0)}" aria-label="${safe(item.title)}的铭牌配色">${renderOperatorTitleStyleOptions(styleOptions, palettes, item)}</select>` : ''}
                        ${item.status === 'active' && item.title_id !== currentId ? `<button type="button" data-title-select="${safe(item.title_id)}">设为当前</button>` : ''}
                        ${item.status === 'proposed' ? `<button type="button" data-title-accept="${safe(item.title_id)}" data-revision="${Number(item.revision || 0)}">确认</button>` : ''}
                        ${!['historical', 'archived'].includes(item.status) ? `<button type="button" data-title-archive="${safe(item.title_id)}" data-revision="${Number(item.revision || 0)}">归档</button>` : ''}
                    </div>
                </article>`).join('') || '<p class="empty-state">尚无头衔</p>'}
            </div>
            <form class="operator-title-form">
                <div class="operator-title-editor-preview">
                    <small>实时预览</small>
                    <div><span data-title-preview-badge></span><strong> · ${safe(getOperatorById(operatorId)?.codename || operatorId)}</strong></div>
                </div>
                <label>新头衔<input name="title" maxlength="24" required autocomplete="off" aria-describedby="operator-title-match-${safe(operatorId)}" placeholder="输入1至24个字符"></label>
                <label>说明<input name="description" maxlength="300" placeholder="可选来源或说明"></label>
                <label>铭牌配色<select name="style_preset">${renderOperatorTitleStyleOptions(styleOptions, palettes)}</select></label>
                <div class="operator-title-match" id="operator-title-match-${safe(operatorId)}" role="status"></div>
                <div class="operator-title-suggestions" aria-label="相似头衔"></div>
                <button type="submit" data-title-submit>创建并授予</button>
            </form>
            <details class="operator-title-palette-editor">
                <summary>管理自定义渐变色盘</summary>
                <div class="operator-title-palette-list">
                    ${palettes.map(item => `<button type="button" data-palette-edit="${safe(item.palette_id)}" data-archived="${item.archived ? 'true' : 'false'}">${safe(item.name)}${item.archived ? ' · 已归档' : ''}</button>`).join('') || '<span>尚无个人色盘</span>'}
                </div>
                <form class="operator-title-palette-form">
                    <input type="hidden" name="palette_id"><input type="hidden" name="revision" value="0"><input type="hidden" name="archived" value="false">
                    <label>色盘名称<input name="palette_name" maxlength="24" required placeholder="例如：莱茵极光"></label>
                    <div class="operator-title-color-field"><label>起始色<input name="gradient_start_picker" type="color" value="#173f78"></label><input name="gradient_start" maxlength="7" value="#173F78" spellcheck="false" aria-label="渐变起始色十六进制值"></div>
                    <div class="operator-title-color-field"><label>结束色<input name="gradient_end_picker" type="color" value="#18a7c8"></label><input name="gradient_end" maxlength="7" value="#18A7C8" spellcheck="false" aria-label="渐变结束色十六进制值"></div>
                    <button type="button" data-palette-swap>交换起止色</button>
                    <div class="operator-title-palette-previews"><div data-theme-preview="light"><small>日间预览</small><span data-palette-preview-light></span></div><div data-theme-preview="dark"><small>夜间预览</small><span data-palette-preview-dark></span></div></div>
                    <p class="operator-title-palette-contrast" data-palette-contrast role="status"></p>
                    <div class="operator-title-palette-actions"><button type="button" data-palette-new>新建</button><button type="button" data-palette-save>保存</button><button type="button" data-palette-save-as>另存</button><button type="button" data-palette-archive hidden>归档</button></div>
                </form>
            </details>
            <p class="operator-title-status" role="status"></p>`;
        const status = root.querySelector('.operator-title-status');
        const form = root.querySelector('.operator-title-form');
        const titleInput = form?.elements.title;
        const styleSelect = form?.elements.style_preset;
        const previewBadge = root.querySelector('[data-title-preview-badge]');
        const matchStatus = root.querySelector('.operator-title-match');
        const suggestions = root.querySelector('.operator-title-suggestions');
        const submitButton = root.querySelector('[data-title-submit]');
        const paletteForm = root.querySelector('.operator-title-palette-form');
        const updateEditorPreview = () => {
            const enteredTitle = String(titleInput?.value || '').trim();
            const selectedStyle = resolveOperatorTitleStyle(styleSelect?.value, styleOptions, palettes);
            if (previewBadge) {
                previewBadge.innerHTML = renderOperatorTitleBadge({
                    title: enteredTitle || '头衔预览',
                    description: enteredTitle || '头衔预览',
                    style: {
                        text_color: selectedStyle.text_color,
                        gradient_start: selectedStyle.gradient_start,
                        gradient_end: selectedStyle.gradient_end,
                        representative_color: selectedStyle.representative_color
                    }
                }, operatorId);
            }
            const ranked = titleItems
                .filter(item => item.status !== 'historical' && item.status !== 'archived')
                .map(item => ({item, score: operatorTitleSimilarity(enteredTitle, item.title)}))
                .filter(entry => entry.score >= 0.5)
                .sort((left, right) => right.score - left.score)
                .slice(0, 4);
            const duplicate = ranked.find(entry => entry.score === 1);
            if (matchStatus) {
                matchStatus.textContent = duplicate
                    ? `已有同名头衔“${duplicate.item.title}”，请直接选择或编辑已有头衔。`
                    : ranked.length ? '发现相似头衔，可点击下方建议复用文字。' : (enteredTitle ? '未发现重复头衔。' : '输入时会检查重复与相似头衔。');
                matchStatus.dataset.state = duplicate ? 'duplicate' : (ranked.length ? 'similar' : 'clear');
            }
            if (submitButton) submitButton.disabled = Boolean(duplicate) || !enteredTitle;
            if (suggestions) {
                suggestions.innerHTML = ranked.map(entry => `<button type="button" data-title-suggestion="${safe(entry.item.title)}">${safe(entry.item.title)}</button>`).join('');
                suggestions.hidden = !ranked.length;
                suggestions.querySelectorAll('[data-title-suggestion]').forEach(button => {
                    button.onclick = () => {
                        titleInput.value = button.dataset.titleSuggestion || '';
                        updateEditorPreview();
                        titleInput.focus();
                    };
                });
            }
        };
        titleInput?.addEventListener('input', updateEditorPreview);
        styleSelect?.addEventListener('change', updateEditorPreview);
        updateEditorPreview();
        const run = async (url, options) => {
            status.textContent = '正在保存';
            const result = await fetch(url, {headers: {'Content-Type': 'application/json'}, ...options});
            const data = await result.json().catch(() => ({}));
            if (!result.ok) throw new Error(data.detail?.message || data.detail || '保存失败');
            operatorCurrentTitleCacheTime.delete(String(operatorId));
            await loadOperatorTitleCard(operatorId);
        };
        form?.addEventListener('submit', async event => {
            event.preventDefault();
            const data = new FormData(event.currentTarget);
            try {
                await run('/operator/titles', {
                    method: 'POST',
                    body: JSON.stringify({
                        operator_id: String(operatorId),
                        title: data.get('title'),
                        description: data.get('description'),
                        style_preset: operatorTitleStyleChoice(data.get('style_preset')).preset_id || 'rhodes_blue',
                        style: operatorTitleStyleChoice(data.get('style_preset')),
                        source: 'user'
                    })
                });
            } catch (error) {
                status.textContent = error.message;
            }
        });
        root.querySelectorAll('[data-title-select]').forEach(button => {
            button.onclick = () => run(`/operator/titles/${encodeURIComponent(operatorId)}/current`, {
                method: 'PUT',
                body: JSON.stringify({title_id: button.dataset.titleSelect})
            }).catch(error => { status.textContent = error.message; });
        });
        root.querySelectorAll('[data-title-style]').forEach(select => {
            select.onchange = () => run(`/operator/titles/${encodeURIComponent(select.dataset.titleStyle)}/style`, {
                method: 'PATCH',
                body: JSON.stringify({
                    style_preset: operatorTitleStyleChoice(select.value).preset_id || 'rhodes_blue',
                    style: operatorTitleStyleChoice(select.value),
                    expected_revision: Number(select.dataset.revision)
                })
            }).catch(error => { status.textContent = error.message; });
        });
        root.querySelectorAll('[data-title-accept]').forEach(button => {
            button.onclick = () => run(`/operator/titles/${encodeURIComponent(button.dataset.titleAccept)}/decision`, {
                method: 'POST',
                body: JSON.stringify({accept: true, expected_revision: Number(button.dataset.revision)})
            }).catch(error => { status.textContent = error.message; });
        });
        root.querySelectorAll('[data-title-archive]').forEach(button => {
            button.onclick = () => run(`/operator/titles/${encodeURIComponent(button.dataset.titleArchive)}?expected_revision=${encodeURIComponent(button.dataset.revision)}`, {
                method: 'DELETE'
            }).catch(error => { status.textContent = error.message; });
        });
        const updatePalettePreview = () => {
            if (!paletteForm) return false;
            const start = normalizeOperatorTitleHex(paletteForm.elements.gradient_start.value);
            const end = normalizeOperatorTitleHex(paletteForm.elements.gradient_end.value);
            paletteForm.elements.gradient_start.classList.toggle('invalid', !start);
            paletteForm.elements.gradient_end.classList.toggle('invalid', !end);
            const saveButton = paletteForm.querySelector('[data-palette-save]');
            const saveAsButton = paletteForm.querySelector('[data-palette-save-as]');
            const valid = Boolean(start && end && String(paletteForm.elements.palette_name.value || '').trim());
            if (saveButton) saveButton.disabled = !valid || paletteForm.elements.archived.value === 'true';
            if (saveAsButton) saveAsButton.disabled = !valid;
            if (!start || !end) return false;
            const style = operatorTitleGradientStyle(start, end);
            const previewTitle = String(paletteForm.elements.palette_name.value || '').trim() || '自定义色盘';
            const preview = renderOperatorTitleBadge({title: previewTitle, style}, operatorId);
            const light = paletteForm.querySelector('[data-palette-preview-light]');
            const dark = paletteForm.querySelector('[data-palette-preview-dark]');
            if (light) light.innerHTML = preview;
            if (dark) dark.innerHTML = preview;
            const contrast = paletteForm.querySelector('[data-palette-contrast]');
            if (contrast) {
                const score = Number(style.minimum_contrast || 0);
                contrast.textContent = score < 4.5
                    ? `最低对比度 ${score.toFixed(2)}:1，已增加文字描边；建议拉开两端明度。`
                    : `最低对比度 ${score.toFixed(2)}:1，文字可读性良好。`;
                contrast.dataset.state = score < 4.5 ? 'warning' : 'ok';
            }
            return true;
        };
        const fillPaletteEditor = palette => {
            if (!paletteForm) return;
            paletteForm.elements.palette_id.value = palette?.palette_id || '';
            paletteForm.elements.revision.value = String(palette?.revision || 0);
            paletteForm.elements.archived.value = palette?.archived ? 'true' : 'false';
            paletteForm.elements.palette_name.value = palette?.name || '';
            const start = normalizeOperatorTitleHex(palette?.gradient_start) || '#173F78';
            const end = normalizeOperatorTitleHex(palette?.gradient_end) || '#18A7C8';
            paletteForm.elements.gradient_start.value = start;
            paletteForm.elements.gradient_end.value = end;
            paletteForm.elements.gradient_start_picker.value = start.toLowerCase();
            paletteForm.elements.gradient_end_picker.value = end.toLowerCase();
            const archiveButton = paletteForm.querySelector('[data-palette-archive]');
            if (archiveButton) {
                archiveButton.hidden = !palette?.palette_id;
                archiveButton.textContent = palette?.archived ? '恢复' : '归档';
            }
            root.querySelectorAll('[data-palette-edit]').forEach(button => {
                button.classList.toggle('active', button.dataset.paletteEdit === palette?.palette_id);
            });
            updatePalettePreview();
        };
        const paletteRequest = async (url, options) => {
            status.textContent = '正在保存色盘';
            const response = await fetch(url, {headers: {'Content-Type': 'application/json'}, ...options});
            const data = await response.json().catch(() => ({}));
            if (!response.ok) throw new Error(data.detail?.message || data.detail || '色盘保存失败');
            await loadOperatorTitleCard(operatorId);
        };
        if (paletteForm) {
            const bindColorPair = (pickerName, textName) => {
                const picker = paletteForm.elements[pickerName];
                const textInput = paletteForm.elements[textName];
                picker?.addEventListener('input', () => {
                    textInput.value = String(picker.value || '').toUpperCase();
                    updatePalettePreview();
                });
                textInput?.addEventListener('input', () => {
                    const color = normalizeOperatorTitleHex(textInput.value);
                    if (color) picker.value = color.toLowerCase();
                    updatePalettePreview();
                });
                textInput?.addEventListener('blur', () => {
                    const color = normalizeOperatorTitleHex(textInput.value);
                    if (color) textInput.value = color;
                });
            };
            bindColorPair('gradient_start_picker', 'gradient_start');
            bindColorPair('gradient_end_picker', 'gradient_end');
            paletteForm.elements.palette_name?.addEventListener('input', updatePalettePreview);
            paletteForm.querySelector('[data-palette-swap]')?.addEventListener('click', () => {
                const start = paletteForm.elements.gradient_start.value;
                paletteForm.elements.gradient_start.value = paletteForm.elements.gradient_end.value;
                paletteForm.elements.gradient_end.value = start;
                paletteForm.elements.gradient_start_picker.value = paletteForm.elements.gradient_start.value.toLowerCase();
                paletteForm.elements.gradient_end_picker.value = paletteForm.elements.gradient_end.value.toLowerCase();
                updatePalettePreview();
            });
            paletteForm.querySelector('[data-palette-new]')?.addEventListener('click', () => fillPaletteEditor(null));
            const savePalette = async saveAs => {
                if (!updatePalettePreview()) throw new Error('请填写有效的色盘名称和颜色');
                const paletteId = String(paletteForm.elements.palette_id.value || '');
                const body = {
                    name: String(paletteForm.elements.palette_name.value || '').trim(),
                    gradient_start: normalizeOperatorTitleHex(paletteForm.elements.gradient_start.value),
                    gradient_end: normalizeOperatorTitleHex(paletteForm.elements.gradient_end.value),
                    expected_revision: Number(paletteForm.elements.revision.value || 0)
                };
                const updateExisting = paletteId && !saveAs;
                await paletteRequest(
                    updateExisting ? `/operator/titles/palettes/${encodeURIComponent(paletteId)}` : '/operator/titles/palettes',
                    {method: updateExisting ? 'PATCH' : 'POST', body: JSON.stringify(body)}
                );
            };
            paletteForm.querySelector('[data-palette-save]')?.addEventListener('click', () => {
                savePalette(false).catch(error => { status.textContent = error.message; });
            });
            paletteForm.querySelector('[data-palette-save-as]')?.addEventListener('click', () => {
                savePalette(true).catch(error => { status.textContent = error.message; });
            });
            paletteForm.querySelector('[data-palette-archive]')?.addEventListener('click', () => {
                const paletteId = String(paletteForm.elements.palette_id.value || '');
                const archived = paletteForm.elements.archived.value === 'true';
                if (!paletteId) return;
                const url = archived
                    ? `/operator/titles/palettes/${encodeURIComponent(paletteId)}/restore`
                    : `/operator/titles/palettes/${encodeURIComponent(paletteId)}?expected_revision=${encodeURIComponent(paletteForm.elements.revision.value)}`;
                const options = archived
                    ? {method: 'POST', body: JSON.stringify({expected_revision: Number(paletteForm.elements.revision.value || 0)})}
                    : {method: 'DELETE'};
                paletteRequest(url, options).catch(error => { status.textContent = error.message; });
            });
            root.querySelectorAll('[data-palette-edit]').forEach(button => {
                button.addEventListener('click', () => {
                    const palette = palettes.find(item => item.palette_id === button.dataset.paletteEdit);
                    fillPaletteEditor(palette || null);
                    root.querySelector('.operator-title-palette-editor').open = true;
                });
            });
            fillPaletteEditor(null);
        }

        operatorCurrentTitleCache.set(String(operatorId), payload.current || null);
        operatorCurrentTitleCacheTime.set(String(operatorId), Date.now());
        applyOperatorTitleDecorations([String(operatorId)]);
    } catch (error) {
        root.innerHTML = `<p class="inline-error">${safe(error.message)}</p><button type="button">重新加载</button>`;
        root.querySelector('button')?.addEventListener('click', () => loadOperatorTitleCard(operatorId));
    }
}

async function loadOperatorContextPolicyCard(operatorId) {
    const root = document.getElementById(`operator-context-inline-${operatorId}`);
    if (!root) return;
    root.innerHTML = '<div class="operator-context-inline-status">正在读取资料权限...</div>';
    try {
        const response = await fetch(`/operator/context-policy/${encodeURIComponent(operatorId)}`);
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const policy = await response.json();
        root.dataset.revision = String(policy.revision ?? 0);
        root.innerHTML = `
            <div class="operator-context-inline-heading">
                <div><strong>资料读取管理</strong><small>控制该干员可进入对话上下文的资料来源</small></div>
                <button type="button" data-context-open-global>全局管理</button>
            </div>
            <div class="operator-context-inline-grid">
                ${Object.entries(OPERATOR_CONTEXT_SOURCE_LABELS).map(([source, label]) => {
                    const state = policy.sources?.[source] || { mode: 'inherit', effective: false };
                    const usage = policy.usage?.[source] || {};
                    return `<label class="operator-context-row"><span>${label}<small>${state.effective ? '当前允许' : '当前禁止'} · ${usage.uses || 0} 次使用 · ${escapeHtml(formatOperatorContextLastUsed(usage.last_used))}</small></span><select data-inline-context-source="${source}"><option value="inherit" ${state.mode === 'inherit' ? 'selected' : ''}>继承全局</option><option value="allow" ${state.mode === 'allow' ? 'selected' : ''}>允许</option><option value="deny" ${state.mode === 'deny' ? 'selected' : ''}>禁止</option></select></label>`;
                }).join('')}
            </div>
            <div class="operator-context-inline-actions">
                <button type="button" data-context-reset>全部恢复全局</button>
                <button type="button" data-context-save>保存当前干员设置</button>
            </div>`;
        root.querySelector('[data-context-open-global]')?.addEventListener('click', () => showPage('settings-operator'));
        root.querySelector('[data-context-reset]')?.addEventListener('click', () => {
            root.querySelectorAll('[data-inline-context-source]').forEach(select => { select.value = 'inherit'; });
        });
        root.querySelector('[data-context-save]')?.addEventListener('click', async event => {
            const button = event.currentTarget;
            const sources = {};
            root.querySelectorAll('[data-inline-context-source]').forEach(select => { sources[select.dataset.inlineContextSource] = select.value; });
            button.disabled = true;
            const originalLabel = button.textContent;
            button.textContent = '保存中…';
            const controller = new AbortController();
            const timeout = setTimeout(() => controller.abort(), 12000);
            try {
                const save = revision => fetch(`/operator/context-policy/${encodeURIComponent(operatorId)}`, {
                    method: 'PATCH', headers: { 'Content-Type': 'application/json' }, signal: controller.signal,
                    body: JSON.stringify({ sources, expected_revision: Number(revision || 0) })
                });
                let saveResponse = await save(root.dataset.revision);
                if (saveResponse.status === 409) {
                    const latestResponse = await fetch(`/operator/context-policy/${encodeURIComponent(operatorId)}`, {signal: controller.signal});
                    const latest = latestResponse.ok ? await latestResponse.json() : null;
                    if (!latest || !confirm('资料设置已在其他位置更新。是否重新载入修订并保留本次选择后再保存？')) {
                        throw new Error('设置未保存；请重新载入后确认差异');
                    }
                    root.dataset.revision = String(latest.operator_revision ?? latest.revision ?? 0);
                    saveResponse = await save(root.dataset.revision);
                }
                if (!saveResponse.ok) throw new Error('保存失败，请稍后重试');
                const saved = await saveResponse.json();
                if (!root.isConnected) return;
                root.dataset.revision = String(saved.operator_revision ?? saved.revision ?? 0);
                root.querySelectorAll('[data-inline-context-source]').forEach(select => {
                    const state = saved.sources?.[select.dataset.inlineContextSource];
                    const summary = select.closest('.operator-context-row')?.querySelector('small');
                    if (state && summary) summary.firstChild.textContent = state.effective ? '当前允许' : '当前禁止';
                });
                showToast?.('资料读取设置已保存', 'success');
            } catch (error) {
                showToast?.(error.name === 'AbortError' ? '保存超时，输入已保留' : (error.message || '保存失败'), 'error');
            } finally {
                clearTimeout(timeout);
                if (button.isConnected) {
                    button.disabled = false;
                    button.textContent = originalLabel;
                }
            }
        });
    } catch (error) {
        root.innerHTML = `<div class="operator-context-inline-status">资料权限读取失败 <button type="button" data-context-retry>重试</button></div>`;
        root.querySelector('[data-context-retry]')?.addEventListener('click', () => loadOperatorContextPolicyCard(operatorId));
    }
}

// ========== end2. 占位函数（预留实现） ========== todo 占位功能
async function initArchiveReadingSetting() {
    const select = document.getElementById('archive-reading-operator-select');
    const search = document.getElementById('archive-reading-operator-search');
    const globalRoot = document.getElementById('operator-context-global');
    const overrideRoot = document.getElementById('operator-context-overrides');
    if (!select || !globalRoot || !overrideRoot) return;
    const sourceLabels = OPERATOR_CONTEXT_SOURCE_LABELS;
    const operators = Array.from(operatorMap.values());
    let visibleOperatorIds = operators.map(op => String(op.id));
    const renderOptions = keyword => {
        const current = select.value;
        const query = String(keyword || '').trim().toLocaleLowerCase();
        const visible = operators.filter(op => !query || String(op.id).toLocaleLowerCase().includes(query) || String(op.codename || '').toLocaleLowerCase().includes(query));
        visibleOperatorIds = visible.map(op => String(op.id));
        select.innerHTML = visible.map(op => `<option value="${escapeHtml(String(op.id))}">${escapeHtml(op.codename || String(op.id))}</option>`).join('');
        if (current && Array.from(select.options).some(option => option.value === current)) select.value = current;
    };
    renderOptions('');
    const globalResponse = await fetch('/operator/context-policy/global');
    const globals = globalResponse.ok ? await globalResponse.json() : { sources: {}, revision: 0 };
    window._operatorContextGlobal = globals;
    globalRoot.innerHTML = Object.entries(sourceLabels).map(([source, label]) => `<label class="operator-context-row"><span>${label}</span><input type="checkbox" data-context-global="${source}" ${globals.sources[source] ? 'checked' : ''}></label>`).join('');
    const load = async () => {
        if (!select.value) { overrideRoot.innerHTML = '<div class="empty-state">没有匹配的干员</div>'; return; }
        const response = await fetch(`/operator/context-policy/${encodeURIComponent(select.value)}`);
        if (!response.ok) { overrideRoot.textContent = '读取策略失败'; return; }
        const policy = await response.json();
        window._operatorContextSelected = policy;
        overrideRoot.innerHTML = Object.entries(sourceLabels).map(([source, label]) => {
            const state = policy.sources[source] || { mode: 'inherit', effective: false };
            return `<label class="operator-context-row"><span>${label}<small>当前${state.effective ? '允许' : '禁止'}</small></span><select data-context-source="${source}"><option value="inherit" ${state.mode === 'inherit' ? 'selected' : ''}>继承全局</option><option value="allow" ${state.mode === 'allow' ? 'selected' : ''}>允许</option><option value="deny" ${state.mode === 'deny' ? 'selected' : ''}>禁止</option></select></label>`;
        }).join('') + '<button type="button" data-context-batch>将当前策略应用到搜索结果</button>';
        overrideRoot.querySelector('[data-context-batch]')?.addEventListener('click', async () => {
            if (!visibleOperatorIds.length || !confirm(`将当前四项策略应用到 ${visibleOperatorIds.length} 名匹配干员？`)) return;
            const sources = {};
            overrideRoot.querySelectorAll('[data-context-source]').forEach(input => { sources[input.dataset.contextSource] = input.value; });
            const batchResponse = await fetch('/operator/context-policy-batch', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ operator_ids: visibleOperatorIds, sources }) });
            if (!batchResponse.ok) throw new Error('批量保存失败');
            showToast?.(`已更新 ${visibleOperatorIds.length} 名干员`, 'success');
            await load();
        });
    };
    if (search) search.oninput = () => { renderOptions(search.value); load(); };
    select.onchange = load;
    window._loadSelectedOperatorContextPolicy = load;
    await load();
}

async function saveArchiveReadingSetting() {
    const select = document.getElementById('archive-reading-operator-select');
    const globalSources = {};
    document.querySelectorAll('[data-context-global]').forEach(input => { globalSources[input.dataset.contextGlobal] = input.checked; });
    if (Object.keys(globalSources).length) {
        const response = await fetch('/operator/context-policy/global', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sources: globalSources, expected_revision: window._operatorContextGlobal?.revision }) });
        if (!response.ok) throw new Error('全局资料读取策略保存失败');
        window._operatorContextGlobal = await response.json();
    }
    if (select?.value) {
        const sources = {};
        document.querySelectorAll('[data-context-source]').forEach(input => { sources[input.dataset.contextSource] = input.value; });
        const response = await fetch(`/operator/context-policy/${encodeURIComponent(select.value)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sources, expected_revision: window._operatorContextSelected?.revision }) });
        if (!response.ok) throw new Error('干员资料读取策略保存失败');
        window._operatorContextSelected = await response.json();
    }
}

async function manageGroup() {
    if (!currentGroupId) return;
    let page = document.getElementById('page-group-manage');
    if (!page) {
        page = document.createElement('div');
        page.id = 'page-group-manage';
        page.className = 'page group-manage-page';
        page.innerHTML = `<div class="page-header"><button class="back-btn" onclick="goBack()"><span data-zoot-icon="previous"></span></button><h2>管理群</h2><button class="group-manage-save">保存</button></div><div class="group-manage-tools"><input class="group-manage-search" placeholder="搜索群成员或干员"><p>选择群成员，并为成员设置最多 16 个字符的群头衔。</p></div><div class="group-manage-members"></div>`;
        document.querySelector('.app-container')?.appendChild(page);
    }
    const response = await fetch(`/group/config/${encodeURIComponent(currentGroupId)}`);
    if (!response.ok) {
        showToast('群配置加载失败', 3000, 'error');
        return;
    }
    const config = await response.json();
    page._groupConfig = config;
    page._selectedMembers = new Set((config.members || []).map(String));
    page._memberTitles = { ...(config.member_titles || {}) };
    const render = keyword => {
        const query = keyword.trim().toLowerCase();
        const selected = page._selectedMembers;
        page.querySelector('.group-manage-members').innerHTML = Array.from(operatorMap.values())
            .filter(op => `${op.codename || ''} ${op.id}`.toLowerCase().includes(query))
            .map(op => {
                const id = String(op.id);
                return `<label class="group-manage-member"><input type="checkbox" data-member-id="${escapeHtml(id)}" ${selected.has(id) ? 'checked' : ''}><img src="${getOperatorAvatarUrl(id)}" onerror="this.src='/static/avatars/default.webp'"><span><strong>${escapeHtml(op.codename || id)}</strong><small>${escapeHtml(id)}</small></span><input class="group-member-title" data-title-id="${escapeHtml(id)}" maxlength="16" value="${escapeHtml(page._memberTitles[id] || '')}" placeholder="群头衔" ${selected.has(id) ? '' : 'disabled'}></label>`;
            }).join('');
    };
    page.querySelector('.group-manage-search').oninput = event => render(event.target.value);
    page.querySelector('.group-manage-members').onchange = event => {
        const checkbox = event.target.closest('input[type="checkbox"]');
        if (checkbox) {
            if (checkbox.checked) page._selectedMembers.add(checkbox.dataset.memberId);
            else page._selectedMembers.delete(checkbox.dataset.memberId);
            page.querySelector(`[data-title-id="${CSS.escape(checkbox.dataset.memberId)}"]`).disabled = !checkbox.checked;
        }
    };
    page.querySelector('.group-manage-members').oninput = event => {
        if (event.target.matches('[data-title-id]')) page._memberTitles[event.target.dataset.titleId] = event.target.value;
    };
    page.querySelector('.group-manage-save').onclick = async () => {
        const members = Array.from(page._selectedMembers);
        const memberTitles = {};
        members.forEach(id => {
            const title = String(page._memberTitles[id] || '').trim().slice(0, 16);
            if (title) memberTitles[id] = title;
        });
        const saveResponse = await fetch(`/group/config/${encodeURIComponent(currentGroupId)}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...config, members, member_titles: memberTitles }) });
        if (!saveResponse.ok) {
            showToast('群配置保存失败', 3000, 'error');
            return;
        }
        groups[currentGroupId] = { ...(groups[currentGroupId] || {}), ...config, members, member_titles: memberTitles };
        goBack();
    };
    render('');
    showPage('group-manage');
}
