// ========== Memory 2.0 记忆中心 ==========
function getMemoryCenterScope() {
    const operatorInput = document.getElementById('memory-center-operator');
    const personaInput = document.getElementById('memory-center-persona');
    const operatorId = (operatorInput?.value || window.currentOperatorId || '').trim();
    const personaId = (personaInput?.value || window.currentPersonaId || 'doctor').trim() || 'doctor';
    if (operatorInput && !operatorInput.value && operatorId) operatorInput.value = operatorId;
    if (personaInput && !personaInput.value) personaInput.value = personaId;
    return { operatorId, personaId };
}

function renderMemoryCenterEpisode(item) {
    const summary = escapeHtml(String(item.summary || ''));
    const topic = escapeHtml(String(item.topic_key || '未分类'));
    const date = item.last_seen ? new Date(item.last_seen * 1000).toLocaleString() : '';
    const statusLabel = {open: '持续整理', closed: '已结束整理', forgotten: '已遗忘'}[item.status] || item.status || '持续整理';
    return `<article class="memory-center-card" data-memory-id="${item.id}">
        <div class="memory-center-card-head"><span>${topic}</span><small>${escapeHtml(date)}</small></div>
        <div class="memory-center-card-body">${summary}</div>
        <div class="memory-center-card-meta">证据发生 ${Number(item.occurrence_count || 1)} 次 · 修订 ${Number(item.revision || 1)} · ${escapeHtml(statusLabel)}</div>
        <div class="memory-center-card-actions">
            <button onclick="governMemoryEpisode('${item.id}','EDIT')">编辑</button>
            <button onclick="governMemoryEpisode('${item.id}','PIN')">固定</button>
            <button onclick="governMemoryEpisode('${item.id}','CLOSE')">结束</button>
            <button class="danger" onclick="governMemoryEpisode('${item.id}','FORGET')">遗忘</button>
        </div>
    </article>`;
}

let memoryMigrationPollTimer = null;

function memoryMigrationMetrics(prediction) {
    const actions = prediction.actions || {};
    return [['旧库条目', prediction.source_total || 0], ['预计规范记忆', prediction.estimated_canonical || 0], ['预计证据记录', prediction.estimated_occurrences || 0], ['预计修订', prediction.estimated_revisions || 0], ['预计重定向', prediction.estimated_redirects || 0], ['预计减少', `${prediction.estimated_reduction || 0}（${(Number(prediction.estimated_reduction_ratio || 0) * 100).toFixed(1)}%）`], ['精确重复', prediction.exact_duplicate_rows || 0], ['语义续接', prediction.semantic_duplicate_rows || 0], ['高风险冲突', prediction.high_risk_conflicts || 0], ['待补 embedding', prediction.missing_embeddings || 0], ['预计 Prompt 降幅', `${prediction.estimated_prompt_token_reduction || 0} Token`], ['CREATE', actions.CREATE || 0], ['REINFORCE', actions.REINFORCE || 0], ['EXTEND', actions.EXTEND || 0], ['CONFLICT', actions.CONFLICT || 0]];
}

function renderMemoryMigrationPanel(payload) {
    const panel = document.getElementById('memory-migration-panel'); if (!panel) return;
    const run = payload.run || {}; const prediction = payload.prediction || payload;
    run.progress_done = run.progress_current || 0;
    const runId = String(run.id || prediction.run_id || ''); const state = run.state || 'analyzed';
    const revision = Number(run.analysis_revision || prediction.analysis_revision || 1); const watermark = String(run.source_watermark || prediction.source_watermark || '');
    const scopes = Object.entries(prediction.by_scope || {}); const progress = Number(run.progress_total || 0) ? Math.min(100, Math.round(Number(run.progress_current || 0) / Number(run.progress_total) * 100)) : 0;
    window.currentMemoryMigration = {runId, revision, watermark, prediction, state}; panel.classList.remove('hidden');
    panel.innerHTML = `<div class="memory-migration-head"><div><strong>Memory 2.0 迁移向导</strong><span>分析 #${escapeHtml(runId)} · revision ${revision}</span></div><button onclick="closeMemoryMigrationPanel()">关闭</button></div><div class="memory-migration-state"><span class="state-${escapeHtml(state)}">${escapeHtml(state)}</span><div class="memory-migration-progress"><i style="width:${progress}%"></i></div><small>${Number(run.progress_done || 0)} / ${Number(run.progress_total || prediction.source_total || 0)}</small></div><div class="memory-migration-metrics">${memoryMigrationMetrics(prediction).map(([label,value]) => `<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><div class="memory-migration-warning">${(prediction.warnings || ['效用与 Token 降幅为估算，最终以迁移结果为准。']).map(escapeHtml).join('<br>')}</div><fieldset class="memory-migration-scopes"><legend>迁移范围：人格 × 干员</legend>${scopes.length ? scopes.map(([scope,counts]) => `<label><input type="checkbox" name="memory-migration-scope" value="${escapeHtml(scope)}" checked><span>${escapeHtml(scope.replace('|',' × '))}</span><small>${Object.entries(counts).map(([key,value]) => `${key} ${value}`).join(' · ')}</small></label>`).join('') : '<span>当前范围没有旧记忆条目</span>'}</fieldset>${payload.actual && Object.keys(payload.actual).length ? `<details class="memory-migration-diff" open><summary>预测与实际差异</summary><pre>${escapeHtml(JSON.stringify(payload.differences || {}, null, 2))}</pre></details>` : ''}<div class="memory-migration-actions">${memoryMigrationActions(state, prediction)}</div>`;
}

function memoryMigrationActions(state, prediction) {
    const save = '<button onclick="saveMemoryMigrationReport()">保存分析报告</button>';
    if (state === 'analyzed') return save + `<button onclick="reviewMemoryMigrationWithAI()" ${Number(prediction.ai_review?.candidate_count || 0) ? '' : 'disabled'}>使用 AI 分析灰区（约 ${Number(prediction.ai_review?.estimated_input_tokens || 0) + Number(prediction.ai_review?.estimated_output_tokens || 0)} Token）</button><button class="primary" onclick="confirmMemoryMigration()">确认并开始影子迁移</button>`;
    if (state === 'queued' || state === 'running') return save + '<button onclick="controlMemoryMigration(\'pause\')">暂停</button><button class="danger" onclick="controlMemoryMigration(\'cancel\')">取消</button>';
    if (state === 'paused') return save + '<button class="primary" onclick="controlMemoryMigration(\'resume\')">继续</button><button class="danger" onclick="controlMemoryMigration(\'cancel\')">取消</button>';
    if (state === 'shadow_ready') return save + '<button onclick="discardMemoryMigrationShadow()">丢弃影子结果</button><button class="primary" onclick="cutoverMemoryMigration()">正式启用 Memory 2.0</button>';
    if (state === 'cancelled') return save + '<button onclick="discardMemoryMigrationShadow()">丢弃本次结果</button><button onclick="analyzeMemoryLibrary()">重新分析</button>';
    if (state === 'discarded') return save + '<button onclick="analyzeMemoryLibrary()">重新分析</button>'; return save;
}

function saveMemoryMigrationReport() { const state=window.currentMemoryMigration; if(!state)return; const blob=new Blob([JSON.stringify({run_id:state.runId,analysis_revision:state.revision,source_watermark:state.watermark,prediction:state.prediction},null,2)],{type:'application/json;charset=utf-8'}); const link=document.createElement('a'); link.href=URL.createObjectURL(blob); link.download=`zoot-memory-analysis-${state.runId}.json`; link.click(); setTimeout(()=>URL.revokeObjectURL(link.href),1000); }

async function analyzeMemoryLibrary() {
    const panel = document.getElementById('memory-migration-panel'); if (!panel) return;
    panel.classList.remove('hidden'); panel.innerHTML = '<div class="memory-migration-loading">正在本地扫描旧库、重复项、索引与 embedding 状态…此步骤不调用 LLM。</div>';
    const {operatorId, personaId} = getMemoryCenterScope();
    try { const response = await fetch('/memory/v2/migrations/analyze', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({operator_ids:operatorId ? [operatorId] : [], persona_ids:personaId ? [personaId] : []})}); if (!response.ok) throw new Error(await response.text()); renderMemoryMigrationPanel(await response.json()); }
    catch (error) { panel.innerHTML = `<div class="memory-migration-warning">分析失败：${escapeHtml(error.message || String(error))}</div>`; }
}

function selectedMemoryMigrationScopes() { return [...document.querySelectorAll('input[name="memory-migration-scope"]:checked')].map(node => node.value); }

async function reviewMemoryMigrationWithAI() {
    const state = window.currentMemoryMigration; if (!state) return; const ai = state.prediction.ai_review || {};
    if (!window.confirm(`将调用低成本模型批量裁决 ${Number(ai.candidate_count || 0)} 个灰区候选，预计 ${Number(ai.estimated_input_tokens || 0) + Number(ai.estimated_output_tokens || 0)} Token。继续吗？`)) return;
    const response = await fetch(`/memory/v2/migrations/${encodeURIComponent(state.runId)}/ai-review`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({confirmed:true})}); if (!response.ok) return showToast('AI 灰区分析失败', 3000, 'error'); await refreshMemoryMigration(state.runId);
}

async function confirmMemoryMigration() {
    const state = window.currentMemoryMigration; if (!state) return; const scopes = selectedMemoryMigrationScopes();
    if (!scopes.length && Object.keys(state.prediction.by_scope || {}).length) return showToast('请至少选择一个迁移范围', 2500, 'error');
    if (!window.confirm('开始影子迁移？正式记忆和旧库不会被修改，完成后仍需再次确认切换。')) return;
    const response = await fetch(`/memory/v2/migrations/${encodeURIComponent(state.runId)}/confirm`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({analysis_revision:state.revision, source_watermark:state.watermark, selected_scopes:scopes, confirmed:true})});
    if (response.status === 409) return showToast('源记忆库已变化，请重新分析', 3500, 'error'); if (!response.ok) return showToast('影子迁移启动失败', 3000, 'error'); await refreshMemoryMigration(state.runId); startMemoryMigrationPolling(state.runId);
}

async function refreshMemoryMigration(runId) { const response = await fetch(`/memory/v2/migrations/${encodeURIComponent(runId)}/report`); if (!response.ok) throw new Error(await response.text()); const payload = await response.json(); renderMemoryMigrationPanel(payload); if (!['queued','running'].includes(payload.run?.state)) stopMemoryMigrationPolling(); return payload; }
function startMemoryMigrationPolling(runId) { stopMemoryMigrationPolling(); memoryMigrationPollTimer = setInterval(() => refreshMemoryMigration(runId).catch(console.error), 1000); }
function stopMemoryMigrationPolling() { if (memoryMigrationPollTimer) clearInterval(memoryMigrationPollTimer); memoryMigrationPollTimer = null; }
function closeMemoryMigrationPanel() { stopMemoryMigrationPolling(); document.getElementById('memory-migration-panel')?.classList.add('hidden'); }

async function controlMemoryMigration(action) { const state = window.currentMemoryMigration; if (!state) return; const response = await fetch(`/memory/v2/migrations/${encodeURIComponent(state.runId)}/${action}`, {method:'POST'}); if (!response.ok) return showToast('迁移控制失败', 2500, 'error'); await refreshMemoryMigration(state.runId); if (action === 'resume') startMemoryMigrationPolling(state.runId); }
async function discardMemoryMigrationShadow() { const state = window.currentMemoryMigration; if (!state || !window.confirm('丢弃本次影子迁移结果？旧库和正式 Memory 2.0 不受影响。')) return; const response = await fetch(`/memory/v2/migrations/${encodeURIComponent(state.runId)}/discard-shadow`, {method:'POST'}); if (!response.ok) return showToast('丢弃失败', 2500, 'error'); await refreshMemoryMigration(state.runId); }
async function cutoverMemoryMigration() { const state = window.currentMemoryMigration; if (!state) return; if (!window.confirm('正式启用 Memory 2.0？系统会保留旧库并允许切回 legacy，但之后的 Prompt 将以新记忆为主。')) return; if (!window.confirm('请再次确认：切换读取模式并应用本次迁移结果。')) return; const response = await fetch(`/memory/v2/migrations/${encodeURIComponent(state.runId)}/cutover`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({analysis_revision:state.revision, source_watermark:state.watermark, confirmed:true})}); if (response.status === 409) return showToast('源记忆库已变化，禁止使用过期报告切换', 3500, 'error'); if (!response.ok) return showToast('正式切换失败', 3000, 'error'); await refreshMemoryMigration(state.runId); await loadMemoryCenter(); showToast('Memory 2.0 已正式启用', 3000, 'success'); }

function renderMemoryIndustrialState(health={},budget={},scope=null){const status=document.getElementById('memory-kernel-status');const matrix=document.getElementById('memory-industrial-matrix');const attention=Number(health.quality?.pending_event_count||0)+Number(health.quality?.pending_review_count||0)+Number(health.quality?.unindexed_episode_count||0);if(status){status.dataset.status=Object.keys(health).length?(attention?'attention':'ok'):'unavailable';status.querySelector('strong').textContent=`MEMORY KERNEL v${Number(health.schema_version||0)}`;status.querySelector('span').textContent=Object.keys(health).length?`${budget.mode||'本地模式'} · ${attention?`${attention} 项待处理`:'记忆链路正常'}`:'记忆内核状态暂不可用';}if(!matrix)return;const cells=[['EVT','原始事件',health.counts?.memory_events],['EPD','主题情节',scope?.counts?.episodes??health.counts?.memory_episodes],['FCT','时态事实',scope?.counts?.facts??health.counts?.memory_facts],['IDX','待建索引',health.quality?.unindexed_episode_count],['RVW','待裁决',health.quality?.pending_review_count],['RPL','角色扮演',scope?.counts?.roleplay_episodes]];matrix.innerHTML=cells.map(([code,label,value])=>`<article class="industrial-status-cell" data-state="${value===undefined||value===null?'unavailable':Number(value)>0&&['IDX','RVW'].includes(code)?'attention':'ok'}"><b>${code}</b><span>${escapeHtml(label)}</span><strong>${value===undefined||value===null?'N/A':Number(value)}</strong></article>`).join('');}

async function loadMemoryCenter() {
    const healthNode = document.getElementById('memory-center-health');
    const metricsNode = document.getElementById('memory-center-metrics');
    const scopeHealthNode = document.getElementById('memory-center-scope-health');
    const listNode = document.getElementById('memory-center-list');
    const reviewNode = document.getElementById('memory-review-list');
    const roleplayNode = document.getElementById('memory-roleplay-list');
    if (!healthNode || !metricsNode || !listNode || !reviewNode) return;
    const { operatorId, personaId } = getMemoryCenterScope();
    healthNode.textContent = '正在读取记忆状态…';
    try {
        const reviewQuery = new URLSearchParams({state: 'pending', limit: '50'});
        if (operatorId) {
            reviewQuery.set('operator_id', operatorId);
            reviewQuery.set('persona_id', personaId);
            reviewQuery.set('conversation_id', operatorId);
        }
        const [healthResult, budgetResult, reviewResult] = await Promise.allSettled([
            fetch('/memory/v2/health'),
            fetch(`/memory/v2/budget?persona_id=${encodeURIComponent(personaId)}&days=7`),
            fetch(`/memory/v2/reviews?${reviewQuery}`)
        ]);
        const healthRes=healthResult.status==='fulfilled'?healthResult.value:null;
        const budgetRes=budgetResult.status==='fulfilled'?budgetResult.value:null;
        const reviewRes=reviewResult.status==='fulfilled'?reviewResult.value:null;
        const health=healthRes?.ok?await healthRes.json():{};
        const budget=budgetRes?.ok?await budgetRes.json():{mode:'unavailable',ratio:0};
        const reviews=reviewRes?.ok?await reviewRes.json():{items:[]};
        if(!healthRes?.ok&&!budgetRes?.ok&&!reviewRes?.ok)throw new Error('Memory 2.0 状态接口不可用');
        const modeLabel = { full: '完整整理', delayed: '延迟整理', deterministic: '本地确定性模式' }[budget.mode] || budget.mode;
        const attentionCount = Number(health.quality?.pending_event_count || 0)
            + Number(health.quality?.pending_review_count || 0)
            + Number(health.quality?.unindexed_episode_count || 0);
        const healthAvailable=Object.keys(health).length>0;
        healthNode.innerHTML=healthAvailable?`<strong>Memory Kernel v${Number(health.schema_version||0)}</strong><span>当前：${escapeHtml(modeLabel)} · ${attentionCount?`${attentionCount} 项待处理`:'链路正常'}</span>`:'<strong>Memory Kernel 状态暂不可用</strong><span>其他已成功读取的记忆数据仍会保留显示。</span>';
        renderMemoryIndustrialState(health,budget);
        metricsNode.innerHTML = [
            ['原始事件', health.counts?.memory_events || 0],
            ['主题记忆', health.counts?.memory_episodes || 0],
            ['时态事实', health.counts?.memory_facts || 0],
            ['待裁决', health.quality?.pending_review_count || 0],
            ['精确重复率', `${(Number(health.quality?.exact_duplicate_ratio || 0) * 100).toFixed(1)}%`],
            ['待建索引', health.quality?.unindexed_episode_count || 0],
            ['记忆/对话', `${(Number(budget.ratio || 0) * 100).toFixed(1)}%`]
        ].map(([label, value]) => `<div><span>${label}</span><strong>${value}</strong></div>`).join('');

        if (!operatorId) {
            listNode.innerHTML = '<div class="memory-center-empty">填写干员英文 ID 后可查看其主题记忆。</div>';
            if (roleplayNode) roleplayNode.innerHTML = '<div class="memory-center-empty">填写干员英文 ID 后读取角色扮演长记忆。</div>';
            scopeHealthNode?.classList.add('hidden');
        } else {
            const params = new URLSearchParams({
                operator_id: operatorId,
                persona_id: personaId,
                conversation_id: operatorId,
                limit: '100'
            });
            const [episodeRes, scopeRes] = await Promise.all([
                fetch(`/memory/v2/episodes?${params}`),
                fetch(`/memory/v2/scope-overview?${params}`)
            ]);
            if (!episodeRes.ok || !scopeRes.ok) throw new Error('当前记忆范围加载失败');
            const data = await episodeRes.json();
            const scope = await scopeRes.json();
            listNode.innerHTML = data.items?.length
                ? data.items.map(renderMemoryCenterEpisode).join('')
                : '<div class="memory-center-empty">当前范围尚无主题记忆。旧数据迁移后会在这里显示。</div>';
            if (scopeHealthNode) {
                const scopeItems = [
                    ['可检索主题', scope.counts?.episodes || 0],
                    ['当前事实', scope.counts?.facts || 0],
                    ['角色反思', scope.counts?.reflections || 0],
                    ['固定档案块', scope.counts?.blocks || 0],
                    ['已遗忘主题', scope.counts?.forgotten_episodes || 0],
                    ['待重建摘要', scope.rebuild?.counts?.pending || 0]
                ];
                scopeHealthNode.innerHTML = scopeItems.map(([label, value]) => `<div><span>${label}</span><strong>${Number(value)}</strong></div>`).join('');
                scopeHealthNode.classList.remove('hidden');
            }
            renderMemoryIndustrialState(health,budget,scope);
            if(roleplayNode){const roleplayItems=Array.isArray(scope.roleplay_memories)?scope.roleplay_memories:[];roleplayNode.innerHTML=roleplayItems.length?roleplayItems.map(renderMemoryCenterEpisode).join(''):'<div class="memory-center-empty">当前范围尚无独立角色扮演长记忆；普通主题记忆仍会继续参与召回。</div>';}
        }
        reviewNode.innerHTML = !reviewRes?.ok
            ? '<div class="memory-center-empty">待裁决记录暂不可用，其他记忆状态不受影响。</div>'
            : reviews.items?.length
            ? reviews.items.map(item => `<article class="memory-center-card review">
                <div class="memory-center-card-body">${escapeHtml(item.reason || '需要用户裁决')}</div>
                <div class="memory-center-card-meta">事件 ${escapeHtml(item.event_id || '')}</div>
                <div class="memory-center-card-actions">
                    <button onclick="resolveMemoryReview('${item.id}','IGNORE')">忽略</button>
                    <button onclick="resolveMemoryReview('${item.id}','CREATE')">建立新记忆</button>
                </div>
            </article>`).join('')
            : '<div class="memory-center-empty">没有待裁决记忆。</div>';
    } catch (error) {
        console.error('加载记忆中心失败:', error);
        healthNode.textContent = `加载失败：${error.message || error}`;
        scopeHealthNode?.classList.add('hidden');
        listNode.innerHTML = '';
        reviewNode.innerHTML = '';
        if(roleplayNode)roleplayNode.innerHTML='';
        renderMemoryIndustrialState();
    }
}

async function governMemoryEpisode(episodeId, action) {
    let content = '';
    if (action === 'EDIT') {
        content = window.prompt('输入修订后的记忆内容：') || '';
        if (!content.trim()) return;
    }
    if (action === 'FORGET' && !window.confirm('确认让该记忆退出后续检索吗？原始证据仍会保留。')) return;
    const response = await fetch(`/memory/v2/episodes/${encodeURIComponent(episodeId)}/action`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, content, reason: '用户在记忆中心操作' })
    });
    if (!response.ok) {
        const detail = await response.text();
        throw new Error(detail || '记忆操作失败');
    }
    if (typeof showTemporaryToast === 'function') showTemporaryToast('记忆已更新');
    await loadMemoryCenter();
}

async function resolveMemoryReview(reviewId, action) {
    const response = await fetch(`/memory/v2/reviews/${encodeURIComponent(reviewId)}/resolve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, reason: '用户在记忆中心裁决' })
    });
    if (!response.ok) throw new Error(await response.text());
    await loadMemoryCenter();
}

async function previewMemoryContext() {
    const preview = document.getElementById('memory-context-preview');
    const query = document.getElementById('memory-context-query')?.value || '';
    const { operatorId, personaId } = getMemoryCenterScope();
    if (!preview || !operatorId) {
        if (typeof showTemporaryToast === 'function') showTemporaryToast('请先填写干员英文 ID');
        return;
    }
    preview.classList.remove('hidden');
    preview.textContent = '正在组装上下文…';
    try {
        const response = await fetch('/memory/v2/context/preview', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                query, operator_id: operatorId, persona_id: personaId,
                conversation_id: operatorId, purpose: 'chat', prompt_token_budget: 4000
            })
        });
        if (!response.ok) throw new Error(await response.text());
        const result = await response.json();
        preview.textContent = result.context_text || '没有找到会被注入的相关记忆。';
    } catch (error) {
        preview.textContent = `预览失败：${error.message || error}`;
    }
}

