    async function focusTodo(id){if(typeof showPage==='function')await showPage('tasks');if(typeof loadTodoItems==='function')await loadTodoItems();setTimeout(()=>{const card=document.querySelector(`.todo-card[data-id="${CSS.escape(String(id))}"]`);if(!card)return toast('该事务已删除或当前不可见','error');card.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});card.classList.add('todo-focus-highlight');setTimeout(()=>card.classList.remove('todo-focus-highlight'),2000);},120);}
