                root.querySelector('#story-scene-note-form').onsubmit=async event=>{event.preventDefault();const payload=Object.fromEntries(new FormData(event.currentTarget));payload.duration_turns=Number(payload.duration_turns||4);payload.protect_user_agency=true;await api(`/stories/sessions/${session.session_id}/scene-notes`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});toast('Scene Note 已应用');event.currentTarget.reset();};
