            const cards = available.triggers.map(item => `<button class="story-template" data-trigger="${esc(item.trigger_id)}"><strong>${esc(item.label)}</strong><small>${esc(item.template_name)} · ${esc(item.mode)}</small></button>`).join('');
            const root = sheet('可用长剧情', `<div class="story-templates">${cards || '<div class="story-empty">当前没有满足条件的剧情触发点</div>'}</div><div class="story-sheet-links"><button data-page="story-editor">创建故事框架</button><button data-page="story-management">管理全部长剧情</button></div>`);
